--anti-dump / anti-memory-scan protection
pcall(function()
    ffi.cdef[[
        typedef unsigned long  DWORD;
        typedef unsigned short WORD;
        typedef unsigned char  BYTE;
        typedef int            BOOL;
        typedef void*          HANDLE;
        typedef void*          LPVOID;
        typedef const void*    LPCVOID;
        typedef size_t         SIZE_T;
        typedef const char*    LPCSTR;

        typedef struct {
            LPVOID BaseAddress;
            LPVOID AllocationBase;
            DWORD  AllocationProtect;
            SIZE_T RegionSize;
            DWORD  State;
            DWORD  Protect;
            DWORD  Type;
        } MEMORY_BASIC_INFORMATION;

        typedef struct {
            WORD e_magic;
            WORD _pad1[29];
            DWORD e_lfanew;
        } IMAGE_DOS_HEADER;

        typedef struct {
            WORD  Machine;
            WORD  NumberOfSections;
            DWORD TimeDateStamp;
            DWORD PointerToSymbolTable;
            DWORD NumberOfSymbols;
            WORD  SizeOfOptionalHeader;
            WORD  Characteristics;
        } IMAGE_FILE_HEADER;

        typedef struct {
            DWORD VirtualAddress;
            DWORD Size;
        } IMAGE_DATA_DIRECTORY;

        typedef struct {
            WORD  Magic;
            BYTE  MajorLinkerVersion; BYTE MinorLinkerVersion;
            DWORD SizeOfCode; DWORD SizeOfInitializedData;
            DWORD SizeOfUninitializedData; DWORD AddressOfEntryPoint;
            DWORD BaseOfCode; DWORD BaseOfData; DWORD ImageBase;
            DWORD SectionAlignment; DWORD FileAlignment;
            WORD  MajorOperatingSystemVersion; WORD MinorOperatingSystemVersion;
            WORD  MajorImageVersion; WORD MinorImageVersion;
            WORD  MajorSubsystemVersion; WORD MinorSubsystemVersion;
            DWORD Win32VersionValue; DWORD SizeOfImage; DWORD SizeOfHeaders;
            DWORD CheckSum; WORD Subsystem; WORD DllCharacteristics;
            DWORD SizeOfStackReserve; DWORD SizeOfStackCommit;
            DWORD SizeOfHeapReserve; DWORD SizeOfHeapCommit;
            DWORD LoaderFlags; DWORD NumberOfRvaAndSizes;
            IMAGE_DATA_DIRECTORY DataDirectory[16];
        } IMAGE_OPTIONAL_HEADER32;

        typedef struct {
            DWORD Signature;
            IMAGE_FILE_HEADER FileHeader;
            IMAGE_OPTIONAL_HEADER32 OptionalHeader;
        } IMAGE_NT_HEADERS32;

        typedef struct {
            BYTE  Name[8];
            union { DWORD PhysicalAddress; DWORD VirtualSize; } Misc;
            DWORD VirtualAddress;
            DWORD SizeOfRawData;
            DWORD PointerToRawData;
            DWORD PointerToRelocations;
            DWORD PointerToLinenumbers;
            WORD  NumberOfRelocations;
            WORD  NumberOfLinenumbers;
            DWORD Characteristics;
        } IMAGE_SECTION_HEADER;

        typedef struct {
            DWORD   dwSize;
            DWORD   th32ModuleID;
            DWORD   th32ProcessID;
            DWORD   GlblcntUsage;
            DWORD   ProccntUsage;
            BYTE*   modBaseAddr;
            DWORD   modBaseSize;
            HANDLE  hModule;
            char    szModule[256];
            char    szExePath[260];
        } MODULEENTRY32;

        SIZE_T VirtualQuery(LPCVOID lpAddress, MEMORY_BASIC_INFORMATION* lpBuffer, SIZE_T dwLength);
        BOOL   VirtualProtect(LPVOID lpAddress, SIZE_T dwSize, DWORD flNewProtect, DWORD* lpflOldProtect);

        HANDLE CreateToolhelp32Snapshot(DWORD dwFlags, DWORD th32ProcessID);
        BOOL   Module32First(HANDLE hSnapshot, MODULEENTRY32* lpme);
        BOOL   Module32Next(HANDLE hSnapshot, MODULEENTRY32* lpme);
        BOOL   CloseHandle(HANDLE hObject);
        DWORD  GetCurrentProcessId();

        void*  memset(void* dest, int c, size_t count);
    ]]
end)

local MEM_COMMIT     = 0x1000
local MEM_PRIVATE    = 0x20000
local PAGE_READWRITE = 0x04
local PAGE_NOACCESS  = 0x01
local TH32CS_SNAPMODULE = 0x00000008

local IMAGE_SCN_CNT_CODE = 0x20
local IMAGE_SCN_MEM_EXECUTE = 0x20000000

local scan_tick    = 0
local nuked_bases  = {}

local function get_module_ranges()
    local modules = {}
    local pid = ffi.C.GetCurrentProcessId()
    local snap = ffi.C.CreateToolhelp32Snapshot(TH32CS_SNAPMODULE, pid)
    if snap == ffi.cast("HANDLE", -1) then return modules end

    local me = ffi.new("MODULEENTRY32")
    me.dwSize = ffi.sizeof("MODULEENTRY32")

    if ffi.C.Module32First(snap, me) ~= 0 then
        repeat
            table.insert(modules, {
                base = tonumber(ffi.cast("uintptr_t", me.modBaseAddr)),
                size = tonumber(me.modBaseSize),
            })
        until ffi.C.Module32Next(snap, me) == 0
    end
    ffi.C.CloseHandle(snap)
    return modules
end

local function addr_in_modules(addr_num, modules)
    for _, m in ipairs(modules) do
        if addr_num >= m.base and addr_num < m.base + m.size then
            return true
        end
    end
    return false
end

local function neutralize_pe(alloc_base)
    local old_prot = ffi.new("DWORD[1]")
    local mbi_n = ffi.new("MEMORY_BASIC_INFORMATION")
    local mbi_size_n = ffi.sizeof("MEMORY_BASIC_INFORMATION")
    local walk = ffi.cast("uint8_t*", alloc_base)
    local total = 0
    local ok_count = 0

    while total < 0x200000 do
        local result = ffi.C.VirtualQuery(walk, mbi_n, mbi_size_n)
        if result == 0 then break end
        if mbi_n.AllocationBase ~= alloc_base then break end

        local rsize = tonumber(mbi_n.RegionSize)

        if tonumber(mbi_n.State) == MEM_COMMIT then
            local protect = tonumber(mbi_n.Protect)

            if protect > 1 and bit.band(protect, 0x100) == 0 then
                local is_exec = (protect == 0x10)
                             or (protect == 0x20)
                             or (protect == 0x40)
                             or (protect == 0x80)

                local vp_ok = ffi.C.VirtualProtect(
                    ffi.cast("LPVOID", walk), rsize,
                    PAGE_READWRITE, old_prot)

                if vp_ok ~= 0 then
                    if is_exec then
                        ffi.C.memset(ffi.cast("void*", walk), 0xC3, rsize)
                    else
                        ffi.C.memset(ffi.cast("void*", walk), 0, rsize)
                    end

                    ffi.C.VirtualProtect(
                        ffi.cast("LPVOID", walk), rsize,
                        PAGE_NOACCESS, old_prot)

                    ok_count = ok_count + 1
                end
            end
        end

        walk = walk + rsize
        total = total + rsize
    end

    return ok_count > 0, ok_count
end

local function scan_and_kill()
    local modules = get_module_ranges()
    local mbi = ffi.new("MEMORY_BASIC_INFORMATION")
    local mbi_size = ffi.sizeof("MEMORY_BASIC_INFORMATION")
    local addr = ffi.cast("const uint8_t*", 0x10000)
    local checked = {}
    local threat = false

    while true do
        local result = ffi.C.VirtualQuery(addr, mbi, mbi_size)
        if result == 0 then break end

        local region_size = tonumber(mbi.RegionSize)
        local state = tonumber(mbi.State)
        local mtype = tonumber(mbi.Type)

        if state == MEM_COMMIT and mtype == MEM_PRIVATE then
            local alloc_base = mbi.AllocationBase
            local alloc_key = tonumber(ffi.cast("uintptr_t", alloc_base))

            if alloc_key > 0x10000
               and not checked[alloc_key]
               and not nuked_bases[alloc_key] then

                checked[alloc_key] = true

                if not addr_in_modules(alloc_key, modules) then
                    local has_pe = false
                    pcall(function()
                        local check_mbi = ffi.new("MEMORY_BASIC_INFORMATION")
                        ffi.C.VirtualQuery(alloc_base, check_mbi, mbi_size)
                        local prot = tonumber(check_mbi.Protect)

                        if prot > 1 and bit.band(prot, 0x100) == 0 then
                            local dos = ffi.cast("IMAGE_DOS_HEADER*", alloc_base)
                            if dos.e_magic == 0x5A4D then
                                local lfanew = tonumber(dos.e_lfanew)
                                if lfanew > 0 and lfanew < 0x1000 then
                                    local nt = ffi.cast("IMAGE_NT_HEADERS32*",
                                        ffi.cast("uint8_t*", alloc_base) + lfanew)
                                    if nt.Signature == 0x00004550 then
                                        has_pe = true
                                    end
                                end
                            end
                        end
                    end)

                    if has_pe then
                        nuked_bases[alloc_key] = true

                        local alloc_size = 0
                        local sz_mbi = ffi.new("MEMORY_BASIC_INFORMATION")
                        local sz_walk = ffi.cast("const uint8_t*", alloc_base)
                        while alloc_size < 0x200000 do
                            local sr = ffi.C.VirtualQuery(sz_walk, sz_mbi, mbi_size)
                            if sr == 0 then break end
                            if sz_mbi.AllocationBase ~= alloc_base then break end
                            alloc_size = alloc_size + tonumber(sz_mbi.RegionSize)
                            sz_walk = sz_walk + tonumber(sz_mbi.RegionSize)
                        end

                        if alloc_size >= 0x2000 then
                            pcall(neutralize_pe, alloc_base)
                        end

                        threat = true
                    end
                end
            end
        end

        addr = addr + region_size
        if tonumber(ffi.cast("uintptr_t", addr)) > 0x7FFE0000 then break end
    end

    return threat
end

pcall(scan_and_kill)


local clipboard = require("neverlose/clipboard")

local base64 = require("neverlose/base64")

local HSP = "\u{200A}"

local storage_codec
do
    local WINDOW_SIZE = 4095
    local MIN_MATCH = 3
    local MAX_MATCH = 18
    local COMPRESSED_MARKER = "!"
    local U32_DIVISOR_1 = 16777216
    local U32_DIVISOR_2 = 65536
    local U32_DIVISOR_3 = 256

    storage_codec = {
    }

    local function encode_base64(payload)
        local ok, encoded = pcall(base64.encode, payload)
        if not ok or type(encoded) ~= "string" or encoded == "" then
            return nil
        end

        return encoded
    end

    local function decode_base64(payload)
        local ok, decoded = pcall(base64.decode, payload)
        if not ok or type(decoded) ~= "string" or decoded == "" then
            return nil
        end

        return decoded
    end

    local function decode_json_payload(payload)
        local ok, data = pcall(json.parse, payload)
        if not ok or type(data) ~= "table" then
            return nil
        end

        return data
    end

    local function decode_storage_payload(payload)
        return decode_json_payload(payload)
    end

    local function pack_u32(value)
        return string.char(
            math.floor(value / U32_DIVISOR_1) % 256,
            math.floor(value / U32_DIVISOR_2) % 256,
            math.floor(value / U32_DIVISOR_3) % 256,
            value % 256
        )
    end

    local function unpack_u32(blob)
        if type(blob) ~= "string" or #blob < 4 then
            return nil
        end

        local b1, b2, b3, b4 = blob:byte(1, 4)
        if b1 == nil or b2 == nil or b3 == nil or b4 == nil then
            return nil
        end

        return ((b1 * 256 + b2) * 256 + b3) * 256 + b4
    end

    local function find_best_match(text, position, text_length)
        local search_start = position - WINDOW_SIZE
        if search_start < 1 then
            search_start = 1
        end

        local limit = text_length - position + 1
        if limit > MAX_MATCH then
            limit = MAX_MATCH
        end

        local best_distance = 0
        local best_length = 0

        for candidate = position - 1, search_start, -1 do
            local current_length = 0

            while current_length < limit do
                local source_byte = text:byte(candidate + current_length)
                local target_byte = text:byte(position + current_length)
                if source_byte ~= target_byte then
                    break
                end

                current_length = current_length + 1
            end

            if current_length >= MIN_MATCH and current_length > best_length then
                best_distance = position - candidate
                best_length = current_length

                if current_length == limit then
                    break
                end
            end
        end

        return best_distance, best_length
    end

    local function compress_lzss(text)
        if type(text) ~= "string" then
            return nil
        end

        if text == "" then
            return ""
        end

        local output = {
        }
        local position = 1
        local text_length = #text

        while position <= text_length do
            local flag_index = #output + 1
            local flags = 0
            output[flag_index] = "\0"

            for bit = 0, 7 do
                if position > text_length then
                    break
                end

                local distance, match_length = find_best_match(
                    text,
                    position,
                    text_length
                )

                if match_length >= MIN_MATCH then
                    local stored_distance = distance - 1
                    local high = math.floor(stored_distance / 16)
                    local low = stored_distance % 16

                    output[#output + 1] = string.char(
                        high,
                        low * 16 + (match_length - MIN_MATCH)
                    )

                    position = position + match_length
                else
                    flags = flags + 2 ^ bit
                    output[#output + 1] = string.char(text:byte(position))
                    position = position + 1
                end
            end

            output[flag_index] = string.char(flags)
        end

        return table.concat(output)
    end

    local function flag_has_bit(flags, bit)
        return math.floor(flags / (2 ^ bit)) % 2 == 1
    end

    local function decompress_lzss(text)
        if type(text) ~= "string" then
            return nil
        end

        if text == "" then
            return ""
        end

        local output = {
        }
        local output_length = 0
        local position = 1
        local text_length = #text

        while position <= text_length do
            local flags = text:byte(position)
            if flags == nil then
                return nil
            end

            position = position + 1

            for bit = 0, 7 do
                if position > text_length then
                    break
                end

                if flag_has_bit(flags, bit) then
                    output_length = output_length + 1
                    output[output_length] = text:sub(position, position)
                    position = position + 1
                else
                    local first = text:byte(position)
                    local second = text:byte(position + 1)
                    if first == nil or second == nil then
                        return nil
                    end

                    position = position + 2

                    local distance = first * 16 + math.floor(second / 16) + 1
                    local match_length = second % 16 + MIN_MATCH
                    local source_index = output_length - distance + 1

                    if source_index < 1 then
                        return nil
                    end

                    for offset = 0, match_length - 1 do
                        local value = output[source_index + offset]
                        if value == nil then
                            return nil
                        end

                        output_length = output_length + 1
                        output[output_length] = value
                    end
                end
            end
        end

        return table.concat(output, "", 1, output_length)
    end

    local function decode_compressed_payload(payload)
        local decoded = decode_base64(payload)
        if decoded == nil or #decoded < 5 then
            return nil
        end

        local expected_length = unpack_u32(decoded)
        if type(expected_length) ~= "number" then
            return nil
        end

        local decompressed = decompress_lzss(decoded:sub(5))
        if type(decompressed) ~= "string" then
            return nil
        end

        if #decompressed ~= expected_length then
            return nil
        end

        return decode_storage_payload(decompressed)
    end

    function storage_codec.encode(data)
        if type(data) ~= "table" then
            return nil
        end

        local ok_json, raw = pcall(json.stringify, data)
        if not ok_json or type(raw) ~= "string" or raw == "" then
            return nil
        end

        local raw_encoded = encode_base64(raw)
        if raw_encoded == nil then
            return nil
        end

        local compressed = compress_lzss(raw)
        if type(compressed) == "string" and compressed ~= "" then
            local compressed_payload = pack_u32(#raw) .. compressed
            local compressed_encoded = encode_base64(compressed_payload)

            if compressed_encoded ~= nil then
                if (#compressed_encoded + 1) < #raw_encoded then
                    return COMPRESSED_MARKER .. compressed_encoded
                end
            end
        end

        return raw_encoded
    end

    function storage_codec.decode(payload)
        if type(payload) ~= "string" or payload == "" then
            return nil
        end

        if payload:sub(1, 1) == COMPRESSED_MARKER then
            return decode_compressed_payload(payload:sub(2))
        end

        local decoded = decode_base64(payload)
        if decoded == nil then
            return nil
        end

        return decode_storage_payload(decoded)
    end
end

local animations
do
    animations = {
    }

    local anim = color()
    local intro_anim = color()

    local MIN_V = 0.4
    local MAX_V = 1.0
    local PERIOD = 3.0
    local TWO_PI = math.pi * 2
    local INTRO_LEAD_PADDING = 4.0
    local INTRO_GLOW_RADIUS = 2.35

    local utf8_cache = {
    }
    local parts_cache = {
    }

    local function clamp_unit(value)
        if value < 0 then
            return 0
        end

        if value > 1 then
            return 1
        end

        return value
    end

    local function lerp_color_hex(from, to, weight)
        local t = clamp_unit(weight)

        intro_anim.r = math.floor(from.r + (to.r - from.r) * t + 0.5)
        intro_anim.g = math.floor(from.g + (to.g - from.g) * t + 0.5)
        intro_anim.b = math.floor(from.b + (to.b - from.b) * t + 0.5)
        intro_anim.a = math.floor(from.a + (to.a - from.a) * t + 0.5)

        return intro_anim:to_hex()
    end

    local function get_utf8_chars(text)
        local cached = utf8_cache[text]
        if cached then
            return cached
        end

        local chars = {
        }
        for uchar in text:gmatch("[%z\1-\127\194-\244][\128-\191]*") do
            chars[#chars + 1] = uchar
        end

        utf8_cache[text] = chars
        return chars
    end

    local function set_wave_color(target, h, s, base_phase, inv_len, index)
        local phase = base_phase + (index - 1) * inv_len * math.pi
        local f = (math.sin(phase) + 1) * 0.5
        local v = MIN_V + (MAX_V - MIN_V) * f

        return target:as_hsv(h, s, v, 1.0)
    end

    function animations.wave(text, col)
        if text == nil then
            return ""
        end

        if text == "" then
            return ""
        end

        local h, s = col:to_hsv()
        local chars = get_utf8_chars(text)
        local len = #chars

        local parts = parts_cache
        local t = globals.realtime
        local base_phase = (t / PERIOD) * TWO_PI
        local inv_len = 1 / len

        for i = 1, len do
            parts[i] = "\a"
                .. set_wave_color(anim, h, s, base_phase, inv_len, i):to_hex()
                .. chars[i]
        end

        for i = len + 1, #parts do
            parts[i] = nil
        end

        return table.concat(parts, "", 1, len)
    end

    function animations.sidebar_intro(text, base_col, accent_col, progress)
        if text == nil then
            return ""
        end

        if text == "" then
            return ""
        end

        local chars = get_utf8_chars(text)
        local len = #chars
        if len == 0 then
            return ""
        end

        local inactive = base_col or accent_col
        local active = accent_col or base_col
        if inactive == nil or active == nil then
            return text
        end

        local head = clamp_unit(progress) * (len + INTRO_LEAD_PADDING) - INTRO_LEAD_PADDING
        local glow_center = head + 0.35
        local parts = parts_cache
        local h, s = active:to_hsv()
        local base_phase = (globals.realtime / PERIOD) * TWO_PI
        local inv_len = 1 / len

        for i = 1, len do
            local reveal = head - i + 1
            if reveal <= -1 then
                parts[i] = HSP
            else
                local reveal_t = clamp_unit(reveal + 1)
                local glow_t = 1.0 - math.min(
                    1.0,
                    math.abs(i - glow_center) / INTRO_GLOW_RADIUS
                )
                local color_t = clamp_unit(
                    math.max(
                        0.35 + reveal_t * 0.45 + glow_t * 0.35,
                        progress
                    )
                )

                parts[i] = "\a"
                    .. lerp_color_hex(
                        inactive,
                        set_wave_color(anim, h, s, base_phase, inv_len, i),
                        color_t
                    )
                    .. chars[i]
            end
        end

        for i = len + 1, #parts do
            parts[i] = nil
        end

        return table.concat(parts, "", 1, len)
    end
end


local sidebar
do
    local DEFAULT_NAME = "aesthetic  ₊✩°｡⋆˚⁺"
    local current_name = DEFAULT_NAME
    local ICON_CHAR = "\u{00E6}"

    sidebar = {
    }

    local cache = {
        last_t = -1,
        last_color_hex = nil,
        last_inactive_color_hex = nil,
        last_name = nil,
        waved = "",
        intro_started_at = nil,
        intro_finished = false,
    }

    local UPDATE_RATE = 1 / 30
    local INTRO_DURATION = 1.85

    local function on_render()
        if ui.get_alpha() <= 0 then
            return
        end

        local now = globals.realtime
        local style = ui.get_style()
        local col = style["Link Active"]
        local inactive_col = style["Small Text"] or col

        local color_hex = col:to_hex()
        local inactive_color_hex = inactive_col:to_hex()

        if cache.intro_started_at == nil then
            cache.intro_started_at = now
        end

        local intro_progress = 1
        if cache.intro_finished ~= true then
            intro_progress = (now - cache.intro_started_at) / INTRO_DURATION
            if intro_progress >= 1 then
                intro_progress = 1
                cache.intro_finished = true
            end
        end

        local needs_update = false
        if cache.waved == "" then
            needs_update = true
        end

        if cache.last_name ~= current_name then
            needs_update = true
        end

        if cache.last_color_hex ~= color_hex then
            needs_update = true
        end

        if cache.last_inactive_color_hex ~= inactive_color_hex then
            needs_update = true
        end

        if (now - cache.last_t) >= UPDATE_RATE then
            needs_update = true
        end

        if cache.intro_finished ~= true then
            needs_update = true
        end

        if needs_update then
            if cache.intro_finished ~= true then
                cache.waved = animations.sidebar_intro(
                    current_name,
                    inactive_col,
                    col,
                    intro_progress
                )
            else
                cache.waved = animations.wave(current_name, col)
            end

            cache.last_t = now
            cache.last_color_hex = color_hex
            cache.last_inactive_color_hex = inactive_color_hex
            cache.last_name = current_name
        end

        ui.sidebar(cache.waved, ICON_CHAR)
    end

    function sidebar.get_name()
        return current_name
    end

    function sidebar.set_name(value)
        if type(value) ~= "string" then
            current_name = DEFAULT_NAME
            return
        end

        current_name = value
    end

    events.render(on_render, true)
end

