        [800] = "800 Extra Bold",
        [900] = "900 Black",
    }

    gdi_font_api.weight_items = WEIGHT_ITEMS
    gdi_font_api.default_weight_item = DEFAULT_SETTINGS.weight_name

    local renderer_mt = {
    }
    renderer_mt.__index = renderer_mt

    local function ensure_gdi()
        if ffi == nil then
            ffi = require("ffi")
        end

        if gdi == nil then
            gdi = ffi.load("gdi32")
        end

        if gdi_types_ready ~= true then
            pcall(ffi.cdef, [[
                typedef void* HANDLE;
                typedef HANDLE HGDIOBJ;
                typedef HANDLE HBITMAP;
                typedef HANDLE HDC;
                typedef HANDLE HFONT;
                typedef unsigned char BYTE;
                typedef unsigned short WORD;
                typedef unsigned int UINT;
                typedef unsigned long DWORD;
                typedef long LONG;
                typedef int BOOL;
                typedef const wchar_t* LPCWSTR;

                typedef struct tagSIZE {
                    LONG cx;
                    LONG cy;
                } SIZE;

                typedef struct tagTEXTMETRICW {
                    LONG tmHeight;
                    LONG tmAscent;
                    LONG tmDescent;
                    LONG tmInternalLeading;
                    LONG tmExternalLeading;
                    LONG tmAveCharWidth;
                    LONG tmMaxCharWidth;
                    LONG tmWeight;
                    LONG tmOverhang;
                    LONG tmDigitizedAspectX;
                    LONG tmDigitizedAspectY;
                    wchar_t tmFirstChar;
                    wchar_t tmLastChar;
                    wchar_t tmDefaultChar;
                    wchar_t tmBreakChar;
                    BYTE tmItalic;
                    BYTE tmUnderlined;
                    BYTE tmStruckOut;
                    BYTE tmPitchAndFamily;
                    BYTE tmCharSet;
                } TEXTMETRICW;

                typedef struct tagBITMAPINFOHEADER {
                    DWORD biSize;
                    LONG biWidth;
                    LONG biHeight;
                    WORD biPlanes;
                    WORD biBitCount;
                    DWORD biCompression;
                    DWORD biSizeImage;
                    LONG biXPelsPerMeter;
                    LONG biYPelsPerMeter;
                    DWORD biClrUsed;
                    DWORD biClrImportant;
                } BITMAPINFOHEADER;

                typedef struct tagRGBQUAD {
                    BYTE rgbBlue;
                    BYTE rgbGreen;
                    BYTE rgbRed;
                    BYTE rgbReserved;
                } RGBQUAD;

                typedef struct tagBITMAPINFO {
                    BITMAPINFOHEADER bmiHeader;
                    RGBQUAD bmiColors[1];
                } BITMAPINFO;

                typedef struct tagLOGFONTW {
                    LONG lfHeight;
                    LONG lfWidth;
                    LONG lfEscapement;
                    LONG lfOrientation;
                    LONG lfWeight;
                    BYTE lfItalic;
                    BYTE lfUnderline;
                    BYTE lfStrikeOut;
                    BYTE lfCharSet;
                    BYTE lfOutPrecision;
                    BYTE lfClipPrecision;
                    BYTE lfQuality;
                    BYTE lfPitchAndFamily;
                    wchar_t lfFaceName[32];
                } LOGFONTW;

                HDC CreateCompatibleDC(HDC hdc);
                BOOL DeleteDC(HDC hdc);
                BOOL DeleteObject(HGDIOBJ hObject);
                HGDIOBJ SelectObject(HDC hdc, HGDIOBJ h);
                DWORD SetTextColor(HDC hdc, DWORD colorref);
                int SetBkMode(HDC hdc, int mode);
                BOOL GetTextExtentPoint32W(HDC hdc, LPCWSTR lpString, int c, SIZE* psizl);
                BOOL GetTextMetricsW(HDC hdc, TEXTMETRICW* lptm);
                BOOL TextOutW(HDC hdc, int x, int y, LPCWSTR lpString, int c);
                HFONT CreateFontIndirectW(const LOGFONTW* lplf);
                HBITMAP CreateDIBSection(HDC hdc, const BITMAPINFO* pbmi, UINT usage, void** ppvBits, HANDLE hSection, DWORD offset);
                BOOL GdiFlush(void);
            ]])
            gdi_types_ready = true
        end

        return ffi, gdi
    end

    local function clamp_number(value, min_value, max_value)
        if value < min_value then
            return min_value
        end

        if value > max_value then
            return max_value
        end

        return value
    end

    local function trim_string(value)
        if type(value) ~= "string" then
            return ""
        end

        return value:match("^%s*(.-)%s*$")
    end

    local function round_to_integer(value)
        if value >= 0 then
            return math.floor(value + 0.5)
        end

        return math.ceil(value - 0.5)
    end

    local function append_utf16_codepoint(buffer, unit_index, codepoint)
        if codepoint <= 0xFFFF then
            buffer[unit_index] = codepoint
            return unit_index + 1
        end

        codepoint = codepoint - 0x10000
        buffer[unit_index] = 0xD800 + math.floor(codepoint / 0x400)
        buffer[unit_index + 1] = 0xDC00 + (codepoint % 0x400)
        return unit_index + 2
    end

    local function is_utf8_tail(byte)
        return byte ~= nil and byte >= 0x80 and byte < 0xC0
    end

    local function to_wide_utf8(text)
        local ffi = ensure_gdi()
        local byte_count = #text
        local buffer = ffi.new("wchar_t[?]", byte_count + 1)
        local unit_index = 0
        local i = 1

        while i <= byte_count do
            local b1 = text:byte(i)
            local codepoint = 0x3F
            local consumed = 1

            if b1 < 0x80 then
                codepoint = b1
            elseif b1 >= 0xC2 and b1 < 0xE0 then
                local b2 = text:byte(i + 1)
                if is_utf8_tail(b2) then
                    codepoint = (b1 - 0xC0) * 0x40 + (b2 - 0x80)
                    consumed = 2
                end
            elseif b1 >= 0xE0 and b1 < 0xF0 then
                local b2 = text:byte(i + 1)
                local b3 = text:byte(i + 2)
                local valid_b2 = is_utf8_tail(b2)
                    and not (b1 == 0xE0 and b2 < 0xA0)
                    and not (b1 == 0xED and b2 >= 0xA0)

                if valid_b2 and is_utf8_tail(b3) then
                    codepoint = (b1 - 0xE0) * 0x1000
                        + (b2 - 0x80) * 0x40
                        + (b3 - 0x80)
                    consumed = 3
                end
            elseif b1 >= 0xF0 and b1 < 0xF5 then
                local b2 = text:byte(i + 1)
                local b3 = text:byte(i + 2)
                local b4 = text:byte(i + 3)
                local valid_b2 = is_utf8_tail(b2)
                    and not (b1 == 0xF0 and b2 < 0x90)
                    and not (b1 == 0xF4 and b2 >= 0x90)

                if valid_b2 and is_utf8_tail(b3) and is_utf8_tail(b4) then
                    codepoint = (b1 - 0xF0) * 0x40000
                        + (b2 - 0x80) * 0x1000
                        + (b3 - 0x80) * 0x40
                        + (b4 - 0x80)
                    consumed = 4
                end
            end

            unit_index = append_utf16_codepoint(buffer, unit_index, codepoint)
            i = i + consumed
        end

        return buffer, unit_index
    end

    local function create_bitmap_info(width, height)
        local ffi = ensure_gdi()
        local bitmap_info = ffi.new("BITMAPINFO[1]")
        bitmap_info[0].bmiHeader.biSize = ffi.sizeof("BITMAPINFOHEADER")
        bitmap_info[0].bmiHeader.biWidth = width
        bitmap_info[0].bmiHeader.biHeight = -height
        bitmap_info[0].bmiHeader.biPlanes = 1
        bitmap_info[0].bmiHeader.biBitCount = 32
        bitmap_info[0].bmiHeader.biCompression = 0
        bitmap_info[0].bmiHeader.biSizeImage = width * height * 4
        return bitmap_info
    end

    local function convert_bgra_to_rgba(bits_ptr, width, height)
        local ffi = ensure_gdi()
        local input = ffi.cast("uint8_t*", bits_ptr)
        local pixel_count = width * height
        local output = ffi.new("uint8_t[?]", pixel_count * 4)

        for i = 0, pixel_count - 1 do
            local src = i * 4
            local dst = i * 4
            output[dst] = 255
            output[dst + 1] = 255
            output[dst + 2] = 255
            output[dst + 3] = input[src + 1]
        end

        return ffi.string(output, pixel_count * 4)
    end

    local function get_utf8_glyph_end(text, index)
        local b1 = text:byte(index)
        if b1 == nil then
            return index
        end

        if b1 < 0x80 then
            return index
        end

        if b1 >= 0xC2 and b1 < 0xE0 then
            local b2 = text:byte(index + 1)
            if is_utf8_tail(b2) then
                return index + 1
            end

            return index
        end

        if b1 >= 0xE0 and b1 < 0xF0 then
            local b2 = text:byte(index + 1)
            local b3 = text:byte(index + 2)
            local valid_b2 = is_utf8_tail(b2)
                and not (b1 == 0xE0 and b2 < 0xA0)
                and not (b1 == 0xED and b2 >= 0xA0)

            if valid_b2 and is_utf8_tail(b3) then
                return index + 2
            end

            return index
        end

        if b1 >= 0xF0 and b1 < 0xF5 then
            local b2 = text:byte(index + 1)
            local b3 = text:byte(index + 2)
            local b4 = text:byte(index + 3)
            local valid_b2 = is_utf8_tail(b2)
                and not (b1 == 0xF0 and b2 < 0x90)
                and not (b1 == 0xF4 and b2 >= 0x90)

            if valid_b2 and is_utf8_tail(b3) and is_utf8_tail(b4) then
                return index + 3
            end
        end

        return index
    end

    local function normalize_weight_value(value)
        local numeric = DEFAULT_SETTINGS.weight
        if type(value) == "number" then
            numeric = value
        end

        numeric = clamp_number(round_to_integer(numeric), 100, 900)
        return clamp_number(round_to_integer(numeric / 100) * 100, 100, 900)
    end

    local function get_weight_name(value)
        return WEIGHT_NAMES[normalize_weight_value(value)] or DEFAULT_SETTINGS.weight_name
    end

    local function get_weight_value(name)
        return WEIGHT_VALUES[name] or DEFAULT_SETTINGS.weight
    end

    local function normalize_settings(settings)
        local normalized = {
            face = DEFAULT_SETTINGS.face,
            size = DEFAULT_SETTINGS.size,
            spacing = DEFAULT_SETTINGS.spacing,
            weight = DEFAULT_SETTINGS.weight,
            italic = DEFAULT_SETTINGS.italic,
            underline = DEFAULT_SETTINGS.underline,
            strike_out = DEFAULT_SETTINGS.strike_out,
            shadow = DEFAULT_SETTINGS.shadow,
            outline = DEFAULT_SETTINGS.outline,
            quality = DEFAULT_SETTINGS.quality,
        }

        if type(settings) == "table" then
            local face = trim_string(settings.face)
            if face ~= "" then
                normalized.face = face
            end

            if type(settings.size) == "number" then
                normalized.size = clamp_number(round_to_integer(settings.size), 1, 128)
            end

            if type(settings.spacing) == "number" then
                normalized.spacing = clamp_number(
                    round_to_integer(settings.spacing),
                    FONT_SPACING_MIN,
                    FONT_SPACING_MAX
                )
            end

            if type(settings.weight_name) == "string" and WEIGHT_VALUES[settings.weight_name] ~= nil then
                normalized.weight = get_weight_value(settings.weight_name)
            elseif type(settings.weight) == "number" then
                normalized.weight = normalize_weight_value(settings.weight)
            end

            if type(settings.italic) == "boolean" then
                normalized.italic = settings.italic
            end

            if type(settings.underline) == "boolean" then
                normalized.underline = settings.underline
            end

            if type(settings.strike_out) == "boolean" then
                normalized.strike_out = settings.strike_out
            end

            if type(settings.shadow) == "boolean" then
                normalized.shadow = settings.shadow
            end

            if type(settings.outline) == "boolean" then
                normalized.outline = settings.outline
            end

            if type(settings.quality) == "number" then
                normalized.quality = clamp_number(round_to_integer(settings.quality), 0, 255)
            end
        end

        normalized.weight_name = get_weight_name(normalized.weight)
        return normalized
    end

    local function clone_settings(settings)
        local normalized = normalize_settings(settings)
        return {
            face = normalized.face,
            size = normalized.size,
            spacing = normalized.spacing,
            weight = normalized.weight,
            weight_name = normalized.weight_name,
            italic = normalized.italic,
            underline = normalized.underline,
            strike_out = normalized.strike_out,
            shadow = normalized.shadow,
            outline = normalized.outline,
            quality = normalized.quality,
        }
    end

    local function build_settings_signature(settings)
        local normalized = normalize_settings(settings)
        return table.concat({
            normalized.face,
            tostring(normalized.size),
            tostring(normalized.spacing),
            tostring(normalized.weight),
            normalized.italic and "1" or "0",
            normalized.underline and "1" or "0",
            normalized.strike_out and "1" or "0",
            normalized.shadow and "1" or "0",
            normalized.outline and "1" or "0",
            tostring(normalized.quality),
        }, "|")
    end

    local function clear_text_resources(renderer)
        for glyph in pairs(renderer.text_cache) do
            renderer.text_cache[glyph] = nil
        end

        renderer.font_handle = nil
        renderer.cached_glyph_count = 0
    end

    local function create_font_handle(renderer)
        local ffi, gdi = ensure_gdi()
        local font_info = ffi.new("LOGFONTW[1]")
        local settings = renderer.settings
        local wide_face_name, wide_face_length = to_wide_utf8(settings.face or "")
        local face_units = math.min(FONT_FACE_MAX_UNITS, wide_face_length)

        font_info[0].lfHeight = -settings.size
        font_info[0].lfWeight = settings.weight
        font_info[0].lfItalic = settings.italic and 1 or 0
        font_info[0].lfUnderline = settings.underline and 1 or 0
        font_info[0].lfStrikeOut = settings.strike_out and 1 or 0
        font_info[0].lfCharSet = FONT_CHAR_SET
        font_info[0].lfQuality = settings.quality

        if face_units > 0 then
            ffi.copy(
                font_info[0].lfFaceName,
                wide_face_name,
                face_units * ffi.sizeof("wchar_t")
            )
        end

        local font_handle = gdi.CreateFontIndirectW(font_info)
        if font_handle == nil or font_handle == ffi.NULL then
            return nil
        end

        return ffi.gc(font_handle, gdi.DeleteObject)
    end

    local function ensure_font_handle(renderer)
        if renderer.font_handle == nil then
            renderer.font_handle = create_font_handle(renderer)
        end

        return renderer.font_handle
    end

    local function render_glyph_to_entry(renderer, glyph)
        local ffi, gdi = ensure_gdi()
        local font_handle = ensure_font_handle(renderer)
        if font_handle == nil then
            return nil
        end

        local wide_text, wide_length = to_wide_utf8(glyph)
        local dc = gdi.CreateCompatibleDC(nil)
        if dc == nil or dc == ffi.NULL then
            return nil
        end

        local old_font = gdi.SelectObject(dc, font_handle)
        local text_size = ffi.new("SIZE[1]")
        local text_metrics = ffi.new("TEXTMETRICW[1]")
        local has_extent = gdi.GetTextExtentPoint32W(dc, wide_text, wide_length, text_size) ~= 0
        local has_metrics = gdi.GetTextMetricsW(dc, text_metrics) ~= 0
        local layout_width = has_extent and math.max(1, text_size[0].cx) or 1
        local layout_height = has_metrics and math.max(1, text_metrics[0].tmHeight) or 1
        local draw_width = layout_width + TEXT_PAD_X * 2
        local draw_height = layout_height + TEXT_PAD_Y * 2
        local bitmap_info = create_bitmap_info(draw_width, draw_height)
        local bits = ffi.new("void*[1]")
        local bitmap = gdi.CreateDIBSection(dc, bitmap_info, 0, bits, nil, 0)

        if bitmap == nil or bitmap == ffi.NULL or bits[0] == nil or bits[0] == ffi.NULL then
            gdi.SelectObject(dc, old_font)
            gdi.DeleteDC(dc)
            return nil
        end

        local old_bitmap = gdi.SelectObject(dc, bitmap)
        gdi.SetBkMode(dc, 1)
        gdi.SetTextColor(dc, 0x00FFFFFF)
        ffi.fill(bits[0], draw_width * draw_height * 4, 0)
        gdi.TextOutW(dc, TEXT_PAD_X, TEXT_PAD_Y, wide_text, wide_length)
        gdi.GdiFlush()

        local texture = render.load_image_rgba(
            convert_bgra_to_rgba(bits[0], draw_width, draw_height),
            vector(draw_width, draw_height, 0)
        )

        gdi.SelectObject(dc, old_bitmap)
        gdi.SelectObject(dc, old_font)
        gdi.DeleteObject(bitmap)
        gdi.DeleteDC(dc)

        if texture == nil then
            return nil
        end

        return {
            texture = texture,
            draw_size = vector(draw_width, draw_height, 0),
            layout_size = vector(layout_width, layout_height, 0),
            last_used_frame = renderer.frame_id,
            pad_x = TEXT_PAD_X,
            pad_y = TEXT_PAD_Y,
        }
    end

    local function get_cached_glyph_entry(renderer, glyph)
        local entry = renderer.text_cache[glyph]
        if entry == nil then
            if renderer.cached_glyph_count >= GLYPH_CACHE_HARD_LIMIT then
                clear_text_resources(renderer)
            end

            entry = render_glyph_to_entry(renderer, glyph)
            if entry == nil then
                return nil
            end

            renderer.text_cache[glyph] = entry
            renderer.cached_glyph_count = renderer.cached_glyph_count + 1
        end

        entry.last_used_frame = renderer.frame_id
        return entry
    end

    local function draw_entry(renderer, entry, draw_position, clr, scale)
        local scaled_size = vector(
            math.max(1, entry.draw_size.x * scale),
            math.max(1, entry.draw_size.y * scale),
            0
        )
        local settings = renderer.settings
        local base_alpha = clr.a or 255

        if settings.outline == true then
            local outline_color = color(1, 1, 1, base_alpha)
            render.texture(entry.texture, draw_position + vector(-1, 0, 0), scaled_size, outline_color)
            render.texture(entry.texture, draw_position + vector(1, 0, 0), scaled_size, outline_color)
            render.texture(entry.texture, draw_position + vector(0, -1, 0), scaled_size, outline_color)
            render.texture(entry.texture, draw_position + vector(0, 1, 0), scaled_size, outline_color)
        end

        if settings.shadow == true then
            local shadow_alpha = renderer.shadow_alpha
            if shadow_alpha <= 0 then
                shadow_alpha = SHADOW_ALPHA
            end

            local shadow_color = color(1, 1, 1, math.min(base_alpha, shadow_alpha))
            render.texture(entry.texture, draw_position + vector(1, 1, 0), scaled_size, shadow_color)
        end

        render.texture(entry.texture, draw_position, scaled_size, clr)
    end

    local function render_fallback_text(renderer, position, clr, flags, text)
        local settings = renderer.settings
        local base_alpha = clr.a or 255

        if settings.outline == true then
            local outline_color = color(0, 0, 0, base_alpha)
            render.text(renderer.fallback_font, position + vector(-1, 0, 0), outline_color, flags, text)
            render.text(renderer.fallback_font, position + vector(1, 0, 0), outline_color, flags, text)
            render.text(renderer.fallback_font, position + vector(0, -1, 0), outline_color, flags, text)
            render.text(renderer.fallback_font, position + vector(0, 1, 0), outline_color, flags, text)
        end

        if settings.shadow == true then
            local shadow_alpha = renderer.shadow_alpha
            if shadow_alpha <= 0 then
                shadow_alpha = SHADOW_ALPHA
            end

            render.text(
                renderer.fallback_font,
                position + vector(1, 1, 0),
                color(0, 0, 0, math.min(base_alpha, shadow_alpha)),
                flags,
                text
            )
        end

        render.text(renderer.fallback_font, position, clr, flags, text)
    end

    function renderer_mt:set_settings(settings)
        local normalized = normalize_settings(settings)
        local signature = build_settings_signature(normalized)
        if self.signature == signature then
            return false
        end

        self.settings = normalized
        self.signature = signature
        clear_text_resources(self)
        return true
    end

    function renderer_mt:get_settings()
        return clone_settings(self.settings)
    end

    function renderer_mt:get_signature()
        return self.signature
    end

    function renderer_mt:get_spacing()
        return self.settings.spacing or 0
    end

    function renderer_mt:set_frame_id(frame_id)
        if type(frame_id) == "number" then
            self.frame_id = frame_id
        else
            self.frame_id = self.frame_id + 1
        end

        self:purge_cache()
    end

    function renderer_mt:purge_cache()
        if self.frame_id % CACHE_GC_INTERVAL ~= 0 then
            return
        end

        for glyph, entry in pairs(self.text_cache) do
            if self.frame_id - (entry.last_used_frame or 0) > CACHE_TTL_FRAMES then
                self.text_cache[glyph] = nil
            end
        end
    end

    function renderer_mt:measure_layout(text)
        if type(text) ~= "string" then
            text = tostring(text or "")
        end

        local byte_count = #text
        if byte_count == 0 then
            return render.measure_text(self.fallback_font, nil, text)
        end

        local total_width = 0
        local max_height = 0
        local spacing = self:get_spacing()
        local has_glyph = false
        local i = 1

        while i <= byte_count do
            local glyph_end = get_utf8_glyph_end(text, i)
            local glyph = text:sub(i, glyph_end)
            local entry = get_cached_glyph_entry(self, glyph)
            if entry == nil then
                return render.measure_text(self.fallback_font, nil, text)
            end

            if has_glyph == true then
                total_width = total_width + spacing
            end

            total_width = total_width + entry.layout_size.x
            max_height = math.max(max_height, entry.layout_size.y)
            has_glyph = true
            i = glyph_end + 1
        end

        return vector(math.max(1, total_width), max_height, 0)
    end

    function renderer_mt:measure_draw(text)
        if type(text) ~= "string" then
            text = tostring(text or "")
        end

        local byte_count = #text
        if byte_count == 0 then
            return self:measure_layout(text)
        end

        local total_width = 0
        local max_height = 0
        local spacing = self:get_spacing()
        local has_glyph = false
        local i = 1

        while i <= byte_count do
            local glyph_end = get_utf8_glyph_end(text, i)
            local glyph = text:sub(i, glyph_end)
            local entry = get_cached_glyph_entry(self, glyph)
            if entry == nil then
                return self:measure_layout(text)
            end

            if has_glyph == true then
                total_width = total_width + spacing
            end

            total_width = total_width + entry.layout_size.x
            max_height = math.max(max_height, entry.draw_size.y)
            has_glyph = true
            i = glyph_end + 1
        end

        return vector(math.max(1, total_width + TEXT_PAD_X * 2), max_height, 0)
    end

    function renderer_mt:measure_glyph_width(glyph)
        local entry = get_cached_glyph_entry(self, glyph)
        if entry == nil then
            return render.measure_text(self.fallback_font, nil, glyph).x
        end

        return entry.layout_size.x
    end

    function renderer_mt:draw_text(position, clr, text, scale)
        if type(text) ~= "string" then
            text = tostring(text or "")
        end

        local draw_scale = scale or 1.0
        if draw_scale <= 0.0 then
            return
        end

        local draw_size = self:measure_draw(text)
        local centered_offset = vector(
            (draw_size.x - draw_size.x * draw_scale) * 0.5,
            (draw_size.y - draw_size.y * draw_scale) * 0.5,
            0
        )
        local cursor_x = position.x + centered_offset.x
        local cursor_y = position.y + centered_offset.y
        local spacing = self:get_spacing()
        local has_glyph = false
        local i = 1
        local byte_count = #text

        while i <= byte_count do
            local glyph_end = get_utf8_glyph_end(text, i)
            local glyph = text:sub(i, glyph_end)
            local entry = get_cached_glyph_entry(self, glyph)
            if entry == nil then
                local shadow_alpha = math.min(clr.a or 255, self.shadow_alpha)
                render.text(self.fallback_font, position + vector(1, 1, 0), color(0, 0, 0, shadow_alpha), "", text)
                render.text(self.fallback_font, position, clr, "", text)
                return
            end

            if has_glyph == true then
                cursor_x = cursor_x + spacing * draw_scale
            end

            draw_entry(
                self,
                entry,
                vector(cursor_x - entry.pad_x * draw_scale, cursor_y, 0),
                clr,
                draw_scale
            )
            cursor_x = cursor_x + entry.layout_size.x * draw_scale
            has_glyph = true
            i = glyph_end + 1
        end
    end

    function renderer_mt:draw_glyph(position, clr, glyph, scale)
        local draw_scale = scale or 1.0
        if draw_scale <= 0.0 then
            return
        end

        local entry = get_cached_glyph_entry(self, glyph)
        if entry == nil then
            local shadow_alpha = math.min(clr.a or 255, self.shadow_alpha)
            render.text(self.fallback_font, position + vector(1, 1, 0), color(0, 0, 0, shadow_alpha), nil, glyph)
            render.text(self.fallback_font, position, clr, nil, glyph)
            return
        end

        draw_entry(
            self,
            entry,
            vector(
                position.x - entry.pad_x * draw_scale,
                position.y - entry.pad_y * draw_scale,
                0
            ),
            clr,
            draw_scale
        )
    end

    function gdi_font_api.get_default_settings()
        return clone_settings(DEFAULT_SETTINGS)
    end

    function gdi_font_api.clone_settings(settings)
        return clone_settings(settings)
    end

    function gdi_font_api.normalize_settings(settings)
        return normalize_settings(settings)
    end

    function gdi_font_api.get_weight_value(name)
        return get_weight_value(name)
    end

    function gdi_font_api.get_weight_name(value)
        return get_weight_name(value)
    end

    function gdi_font_api.get_settings_signature(settings)
        return build_settings_signature(settings)
    end

    function gdi_font_api.new_renderer(settings, fallback_font, shadow_alpha)
        local normalized = normalize_settings(settings)
        return setmetatable({
            settings = normalized,
            signature = build_settings_signature(normalized),
            fallback_font = type(fallback_font) == "number" and fallback_font or DEFAULT_FALLBACK_FONT,
            shadow_alpha = type(shadow_alpha) == "number" and shadow_alpha or SHADOW_ALPHA,
            frame_id = 0,
            font_handle = nil,
            text_cache = {
            },
            cached_glyph_count = 0,
        }, renderer_mt)
    end
end

