    local function normalize_color_codes(text)
        if type(text) ~= "string" then
            return ""
        end

        return text:gsub("\\a", "\a")
    end

    local function trim_string(value)
        if type(value) ~= "string" then
            return ""
        end

        return value:match("^%s*(.-)%s*$")
    end

    local function clamp_number(value, min_value, max_value)
        if value < min_value then
            return min_value
        end

        if value > max_value then
            return max_value
        end

        return value
    end

    clamp_font_index = function(value)
        if type(value) ~= "number" then
            return DEFAULT_FONT
        end

        local rounded = math.floor(value + 0.5)
        return clamp_number(rounded, FONT_MIN, FONT_MAX)
    end

    format_font_slider_value = function(value)
        local font_index = clamp_font_index(value)
        return FONT_LABELS[font_index] or FONT_LABELS[DEFAULT_FONT]
    end

    local function split_utf8(text)
        local chars = {
        }

        local index = 1
        while index <= #text do
            local byte = string.byte(text, index)
            local char_length = 1
            if byte >= 240 then
                char_length = 4
            elseif byte >= 224 then
                char_length = 3
            elseif byte >= 192 then
                char_length = 2
            end

            chars[#chars + 1] = text:sub(index, index + char_length - 1)
            index = index + char_length
        end

        return chars
    end

    local function rgba_to_hex(r, g, b, a)
        local r8 = clamp_number(math.floor(r + 0.5), 0, 255)
        local g8 = clamp_number(math.floor(g + 0.5), 0, 255)
        local b8 = clamp_number(math.floor(b + 0.5), 0, 255)
        local a8 = clamp_number(math.floor(a + 0.5), 0, 255)
        return string.format("%02X%02X%02X%02X", r8, g8, b8, a8)
    end

    local function normalize_hex_color(value)
        if type(value) ~= "string" then
            return nil
        end

        local hex = trim_string(value)
        if hex == "" then
            return nil
        end

        if hex:sub(1, 1) == "#" then
            hex = hex:sub(2)
        end

        if hex:sub(1, 2) == "\a" then
            hex = hex:sub(3)
        end

        if #hex == 6 then
            hex = hex .. "FF"
        end

        if #hex ~= 8 then
            return nil
        end

        if hex:find("[^%x]") ~= nil then
            return nil
        end

        return hex:upper()
    end

    local function hex_to_color(value)
        local hex = normalize_hex_color(value)
        if hex == nil then
            return nil
        end

        local r = tonumber(hex:sub(1, 2), 16)
        local g = tonumber(hex:sub(3, 4), 16)
        local b = tonumber(hex:sub(5, 6), 16)
        local a = tonumber(hex:sub(7, 8), 16)
        if r == nil or g == nil or b == nil or a == nil then
            return nil
        end

        return color(r, g, b, a)
    end

    local function get_default_position_for_screen(screen)
