    local function get_legacy_render_text(text, base_color)
        local tag_pos = text:find("\a", 1, true)
        if tag_pos ~= nil then
            local prefix = text:sub(1, tag_pos - 1)
            local suffix = text:sub(tag_pos)

            if prefix == "" then
                return text
            end

            local waved_prefix = animations.wave(prefix, base_color)
            return waved_prefix .. suffix
        end

        return animations.wave(text, base_color)
    end

    local function build_hsv_wave_text(
        chars,
        base_color,
        min_brightness,
        max_brightness,
        speed,
        wave_count,
        parts
    )
        local chars_count = #chars
        if chars_count == 0 then
            return ""
        end

        local minimum = clamp_number(min_brightness, 0.0, 1.0)
        local maximum = clamp_number(max_brightness, 0.0, 1.0)
        if maximum < minimum then
            local temp = minimum
            minimum = maximum
            maximum = temp
        end

        local speed_value = speed
        if type(speed_value) ~= "number" or speed_value <= 0 then
            speed_value = 3.0
        end

        local waves_value = wave_count
        if type(waves_value) ~= "number" or waves_value <= 0 then
            waves_value = 1.0
        end

        local h, s = base_color:to_hsv()
        local time_phase = globals.realtime * speed_value
        local wave_color = color()
        local previous_length = #parts

        for i = 1, chars_count do
            local phase = time_phase + ((i - 1) / chars_count) * waves_value * math.pi
            local wave = (math.sin(phase) + 1.0) * 0.5
            local brightness = minimum + (maximum - minimum) * wave
            wave_color:as_hsv(h, s, brightness, 1.0)
            parts[i] = "\a" .. wave_color:to_hex() .. chars[i]
        end

        for i = chars_count + 1, previous_length do
            parts[i] = nil
        end

        return table.concat(parts, "", 1, chars_count)
    end

    local function build_brightness_wave_text(
        chars,
        base_color,
        min_brightness,
        max_brightness,
        speed,
        wave_count,
        parts
    )
        local chars_count = #chars
        if chars_count == 0 then
            return ""
        end

        local minimum = clamp_number(min_brightness, 0.0, 1.0)
        local maximum = clamp_number(max_brightness, 0.0, 1.0)
        if maximum < minimum then
            local temp = minimum
            minimum = maximum
            maximum = temp
        end

        local speed_value = speed
        if type(speed_value) ~= "number" or speed_value <= 0 then
            speed_value = 2.0
        end

        local waves_value = wave_count
        if type(waves_value) ~= "number" or waves_value <= 0 then
            waves_value = 1.0
        end

        local time_phase = globals.realtime * speed_value
        local alpha = base_color.a or 255
        local previous_length = #parts
        for i = 1, chars_count do
            local phase = time_phase + (i / chars_count) * waves_value * math.pi
            local wave = (math.sin(phase) + 1.0) * 0.5
            local brightness = minimum + (maximum - minimum) * wave
            local value = math.floor(brightness * 255 + 0.5)
            local hex = rgba_to_hex(value, value, value, alpha)
            parts[i] = "\a" .. hex .. chars[i]
        end

        for i = chars_count + 1, previous_length do
            parts[i] = nil
        end

        return table.concat(parts, "", 1, chars_count)
    end

    local function build_char_gradient_text(chars, from_color, to_color, parts)
        local chars_count = #chars
        if chars_count == 0 then
            return ""
        end

        local from_r = from_color.r or 255
        local from_g = from_color.g or 255
        local from_b = from_color.b or 255
        local from_a = from_color.a or 255
        local to_r = to_color.r or 255
        local to_g = to_color.g or 255
        local to_b = to_color.b or 255
        local to_a = to_color.a or 255

        local denominator = chars_count - 1
        if denominator < 1 then
            denominator = 1
        end

        local previous_length = #parts
        for i = 1, chars_count do
            local ratio = (i - 1) / denominator
            local r = from_r + (to_r - from_r) * ratio
            local g = from_g + (to_g - from_g) * ratio
            local b = from_b + (to_b - from_b) * ratio
            local a = from_a + (to_a - from_a) * ratio
            local hex = rgba_to_hex(r, g, b, a)
            parts[i] = "\a" .. hex .. chars[i]
        end

        for i = chars_count + 1, previous_length do
            parts[i] = nil
        end

        return table.concat(parts, "", 1, chars_count)
    end

    local function build_gradient_wave_text(
        chars,
        from_color,
        to_color,
        speed,
        wave_count,
        parts
    )
        local chars_count = #chars
        if chars_count == 0 then
            return ""
        end

        local speed_value = speed
        if type(speed_value) ~= "number" or speed_value <= 0 then
            speed_value = 2.0
        end

        local waves_value = wave_count
        if type(waves_value) ~= "number" or waves_value <= 0 then
            waves_value = 1.0
        end

        local from_r = from_color.r or 255
        local from_g = from_color.g or 255
        local from_b = from_color.b or 255
        local from_a = from_color.a or 255
        local to_r = to_color.r or 255
        local to_g = to_color.g or 255
        local to_b = to_color.b or 255
        local to_a = to_color.a or 255

        local time_phase = globals.realtime * speed_value
        local previous_length = #parts
        for i = 1, chars_count do
            local phase = time_phase + ((i - 1) / chars_count) * waves_value * math.pi * 2
            local ratio = (math.sin(phase) + 1.0) * 0.5
            local r = from_r + (to_r - from_r) * ratio
            local g = from_g + (to_g - from_g) * ratio
            local b = from_b + (to_b - from_b) * ratio
            local a = from_a + (to_a - from_a) * ratio
            local hex = rgba_to_hex(r, g, b, a)
            parts[i] = "\a" .. hex .. chars[i]
        end

        for i = chars_count + 1, previous_length do
            parts[i] = nil
        end

        return table.concat(parts, "", 1, chars_count)
    end

    local function build_rainbow_text(
        chars,
        animated,
        speed,
        wave_count,
        saturation,
        value_level,
        parts
    )
        local chars_count = #chars
        if chars_count == 0 then
            return ""
        end

        local speed_value = speed
        if type(speed_value) ~= "number" or speed_value <= 0 then
            speed_value = 2.0
        end

        local waves_value = wave_count
        if type(waves_value) ~= "number" or waves_value <= 0 then
            waves_value = 1.0
        end

        local saturation_value = saturation
        if type(saturation_value) ~= "number" then
            saturation_value = 1.0
        end
        saturation_value = clamp_number(saturation_value, 0.0, 1.0)

        local value_value = value_level
        if type(value_value) ~= "number" then
            value_value = 1.0
        end
        value_value = clamp_number(value_value, 0.0, 1.0)
        local hue_offset = 0.0
        if animated == true then
            hue_offset = globals.realtime * speed_value
        end

        local rainbow_color = color()
        local previous_length = #parts
        for i = 1, chars_count do
            local hue = (hue_offset + ((i - 1) / chars_count) * waves_value) % 1.0
            rainbow_color:as_hsv(hue, saturation_value, value_value, 1.0)
            parts[i] = "\a" .. rainbow_color:to_hex() .. chars[i]
        end

        for i = chars_count + 1, previous_length do
            parts[i] = nil
        end

        return table.concat(parts, "", 1, chars_count)
    end

    local function normalize_segment_mode(value)
        if type(value) ~= "string" then
            return "static"
        end

        local mode = value:lower()
        if mode == "none" then
            return "static"
        end
        if mode == "color" then
            return "static"
        end
        if mode == "hsv_wave" then
            return "wave"
        end
        if mode == "grey_wave" then
            return "brightness_wave"
        end
        if mode == "gray_wave" then
            return "brightness_wave"
        end
        if mode == "char_gradient" then
            return "gradient"
        end
        if mode == "rainbow_static" then
            return "rainbow"
        end
        if mode == "rainbow_animated" then
            return "rainbow_wave"
        end
        if mode == "wave" then
            return mode
        end
        if mode == "pulse" then
            return mode
        end
        if mode == "centered" then
            return mode
        end
        if mode == "brightness_wave" then
            return mode
        end
        if mode == "brightness_pulse" then
            return "pulse"
        end
        if mode == "brightness_centered" then
            return mode
        end
        if mode == "gradient" then
            return mode
        end
        if mode == "gradient_wave" then
            return mode
        end
        if mode == "gradient_pulse" then
            return mode
        end
        if mode == "gradient_centered" then
            return mode
        end
        if mode == "rainbow" then
            return mode
        end
        if mode == "rainbow_wave" then
            return mode
        end
        if mode == "rainbow_pulse" then
            return mode
        end
        if mode == "rainbow_centered" then
            return mode
        end

        return "static"
    end

    local function get_segment_style_from_mode(mode)
        local normalized = normalize_segment_mode(mode)
        if normalized:find("^gradient") == 1 then
            return "gradient"
        end

        if normalized:find("^rainbow") == 1 then
            return "rainbow"
        end

        return "solid"
    end

    local function get_segment_animation_from_mode(mode)
        local normalized = normalize_segment_mode(mode)
        if normalized == "static"
            or normalized == "gradient"
            or normalized == "rainbow" then
            return "off"
        end

        if normalized:find("_pulse$") ~= nil
            or normalized == "pulse"
            or normalized == "brightness_pulse" then
            return "pulse"
        end

        if normalized:find("_centered$") ~= nil
            or normalized == "centered"
            or normalized == "brightness_centered" then
            return "centered"
        end

        return "wave"
    end

    local function normalize_segment_style(value)
        if type(value) ~= "string" then
            return nil
        end

        local style = value:lower()
        if style == "solid"
            or style == "static"
            or style == "color" then
            return "solid"
        end
        if style == "gradient" then
            return "gradient"
        end
        if style == "rainbow" then
            return "rainbow"
        end

        return nil
    end

    local function normalize_segment_animation(value)
        if type(value) ~= "string" then
            return nil
        end

        local animation = value:lower()
        if animation == "off"
            or animation == "none" then
            return "off"
        end
        if animation == "wave" then
            return "wave"
        end
        if animation == "sweep" then
            return "sweep"
        end
        if animation == "pulse" then
            return "pulse"
        end
        if animation == "breath"
            or animation == "breathe" then
            return "breath"
        end
        if animation == "centered"
            or animation == "center"
            or animation == "centre" then
            return "centered"
        end
        if animation == "shift" then
            return "shift"
        end

        return nil
    end

    local function normalize_segment_channel(value)
        if type(value) ~= "string" then
            return nil
        end

        local channel = value:lower()
        if channel == "color"
            or channel == "colour" then
            return "color"
        end
        if channel == "alpha"
            or channel == "opacity"
            or channel == "brightness"
            or channel == "monochrome"
            or channel == "mono" then
            return "alpha"
        end

        return nil
    end

    local function normalize_segment_repeat(value)
        if type(value) ~= "string" then
            return nil
        end

        local repeat_mode = value:lower()
        if repeat_mode == "loop" then
            return "loop"
        end
        if repeat_mode == "pingpong"
            or repeat_mode == "ping-pong"
            or repeat_mode == "bounce" then
            return "pingpong"
        end

        return nil
    end

    local function normalize_segment_direction(value)
        if type(value) ~= "string" then
            return nil
        end

        local direction = value:lower()
        if direction == "forward"
            or direction == "normal"
            or direction == "left_to_right"
            or direction == "ltr"
            or direction == "center_out"
            or direction == "outward" then
            return "forward"
        end
        if direction == "reverse"
            or direction == "backward"
            or direction == "right_to_left"
            or direction == "rtl"
            or direction == "outside_in"
            or direction == "inward" then
            return "reverse"
        end

        return nil
    end

    local function normalize_segment_shape(value)
        if type(value) ~= "string" then
            return nil
        end

        local shape = value:lower()
        if shape == "soft"
            or shape == "smooth" then
            return "soft"
        end
        if shape == "sharp"
            or shape == "hard" then
            return "sharp"
        end

        return nil
    end

    local function normalize_segment_glyph_animation(value)
        if type(value) ~= "string" then
            return nil
        end

        local animation = value:lower()
        if animation == "off"
            or animation == "none" then
            return "off"
        end
        if animation == "wave"
            or animation == "ripple" then
            return "wave"
        end
        if animation == "orbit"
            or animation == "orbital" then
            return "orbit"
        end
        if animation == "scatter"
            or animation == "split" then
            return "scatter"
        end
        if animation == "heart"
            or animation == "love" then
            return "heart"
        end

        return nil
    end

    local function is_legacy_segment_glyph_glitch(value)
        return type(value) == "string"
            and value:lower() == "glitch"
    end

    local function read_boolean(value, fallback)
        if type(value) == "boolean" then
            return value
        end

        if type(value) == "number" then
            return value ~= 0
        end

        if type(value) == "string" then
            local lowered = value:lower()
            if lowered == "true"
                or lowered == "yes"
                or lowered == "on"
                or lowered == "1" then
                return true
            end
            if lowered == "false"
                or lowered == "no"
                or lowered == "off"
                or lowered == "0" then
                return false
            end
        end

        return fallback
    end

    local function get_segment_style_key(value)
        if type(value) == "table" then
            local style = normalize_segment_style(value.style)
            if style ~= nil then
                return style
            end

            return get_segment_style_from_mode(value.mode)
        end

        return get_segment_style_from_mode(value)
    end

    local function get_segment_animation_key(value)
        if type(value) == "table" then
            local animation = normalize_segment_animation(value.animation)
            if animation ~= nil then
                return animation
            end

            return get_segment_animation_from_mode(value.mode)
        end

        return get_segment_animation_from_mode(value)
    end

    local function get_segment_animation_channel(value)
        if type(value) == "table" then
            local channel = normalize_segment_channel(value.channel)
            if channel ~= nil then
                return channel
            end

            local normalized = normalize_segment_mode(value.mode)
            if normalized == "pulse"
                or normalized == "gradient_pulse"
                or normalized == "rainbow_pulse"
                or normalized == "brightness_wave"
                or normalized == "brightness_centered" then
                return "alpha"
            end
        end

        return "color"
    end

    local function get_segment_animation_repeat(value)
        if type(value) == "table" then
            local repeat_mode = normalize_segment_repeat(
                value.repeat_mode or value.playback or value["repeat"]
            )
            if repeat_mode ~= nil then
                return repeat_mode
            end
        end

        return "loop"
    end

    local function get_segment_animation_direction(value)
        if type(value) == "table" then
            local direction = normalize_segment_direction(value.direction)
            if direction ~= nil then
                return direction
            end
        end

        return "forward"
    end

    local function get_segment_animation_reverse(value)
        if type(value) == "table" then
            return read_boolean(value.reverse, false)
        end

        return false
    end

    local function get_segment_animation_shape(value)
        if type(value) == "table" then
            local shape = normalize_segment_shape(value.shape)
            if shape ~= nil then
                return shape
            end
        end

        return "soft"
    end

    local function get_segment_glyph_animation_key(value)
        if type(value) == "table" then
            local animation = normalize_segment_glyph_animation(
                value.glyph_animation
                or value.glyph_anim
                or value.glyph_motion
                or value.glyph_fx
            )
            if animation ~= nil then
                return animation
            end
        end

        return "off"
    end

    local function get_segment_glyph_glitch_enabled(value)
        if type(value) == "table" then
            if read_boolean(
                value.glyph_glitch
                    or value.glyph_scramble
                    or value.glyph_random,
                false
            ) == true then
                return true
            end

            return is_legacy_segment_glyph_glitch(
                value.glyph_animation
                or value.glyph_anim
                or value.glyph_motion
                or value.glyph_fx
            )
        end

        return false
    end

    local function is_segment_animated_mode(mode)
        return get_segment_animation_from_mode(mode) ~= "off"
    end

    local function is_segment_rainbow_mode(mode)
        return get_segment_style_key(mode) == "rainbow"
    end

    local function is_segment_gradient_mode(mode)
        return get_segment_style_key(mode) == "gradient"
    end

    local function read_number(value, fallback, min_value, max_value)
        local number_value = value
        if type(number_value) ~= "number" then
            number_value = fallback
        end

        return clamp_number(number_value, min_value, max_value)
    end

    local function get_wrapped_progress(value)
        local wrapped = value % 1.0
        if wrapped < 0 then
            wrapped = wrapped + 1.0
        end

        return wrapped
    end

    local function get_animation_time_progress(phase, repeat_mode, reverse)
        local progress = get_wrapped_progress(phase / (math.pi * 2))
        if repeat_mode == "pingpong" then
            if progress > 0.5 then
                progress = 1.0 - progress
            end
            progress = progress * 2.0
        end

        if reverse == true then
            progress = 1.0 - progress
        end

        return progress
    end

    local function apply_animation_shape(sample, shape)
        local clamped = clamp_number(sample, 0.0, 1.0)
        if shape == "sharp" then
            return clamped * clamped
        end

        return clamped * clamped * (3.0 - 2.0 * clamped)
    end

    local function get_directed_position(position_ratio, direction)
        if direction == "reverse" then
            return 1.0 - position_ratio
        end

        return position_ratio
    end

    local function get_centered_animation_sample(position_ratio, progress, animation_span, direction)
        local span_value = read_number(animation_span, 1.0, 0.1, 10.0)
        local distance = math.abs(position_ratio - 0.5) * 2.0
        local width = 1.0 / span_value
        local travel = progress * (1.0 + width)
        if direction == "reverse" then
            travel = (1.0 + width) - travel
        end

        return 1.0 - clamp_number(
            math.abs(distance - travel) / width,
            0.0,
            1.0
        )
    end

    local function get_sweep_animation_sample(position_ratio, progress, animation_span, direction, wrap)
        local span_value = read_number(animation_span, 1.0, 0.1, 10.0)
        local width = 1.0 / span_value
        if wrap == true then
            local center = progress
            if direction == "reverse" then
                center = 1.0 - center
            end

            local distance = math.abs(position_ratio - center)
            distance = math.min(distance, 1.0 - distance)
            return 1.0 - clamp_number(distance / width, 0.0, 1.0)
        end

        local center = -width + progress * (1.0 + width * 2.0)
        local directed_position = get_directed_position(position_ratio, direction)
        return 1.0 - clamp_number(
            math.abs(directed_position - center) / width,
            0.0,
            1.0
        )
    end

    local function get_wave_animation_sample(position_ratio, progress, animation_span, direction)
        local span_value = read_number(animation_span, 1.0, 0.1, 10.0)
        local directed_position = get_directed_position(position_ratio, direction)
        local offset = directed_position * span_value * math.pi
        return (math.sin(progress * math.pi * 2.0 + offset) + 1.0) * 0.5
    end

    local function get_global_animation_sample(progress, animation_type)
        local sample = (math.sin(progress * math.pi * 2.0 - math.pi * 0.5) + 1.0) * 0.5
        if animation_type == "pulse" then
            return sample * sample
        end

        return sample
    end

    local function get_shift_offset(progress, animation_span, direction)
        local span_value = read_number(animation_span, 1.0, 0.1, 10.0)
        local offset = progress * span_value
        if direction == "reverse" then
            offset = -offset
        end

        return offset
    end

    local function get_animation_sample(
        animation_type,
        position_ratio,
        progress,
        animation_span,
        direction,
        shape
    )
        if animation_type == "pulse"
            or animation_type == "breath" then
            return apply_animation_shape(
                get_global_animation_sample(progress, animation_type),
                shape
            )
        end

        if animation_type == "centered" then
            return apply_animation_shape(get_centered_animation_sample(
                position_ratio,
                progress,
                animation_span,
                direction
            ), shape)
        end

        if animation_type == "sweep" then
            return apply_animation_shape(get_sweep_animation_sample(
                position_ratio,
                progress,
                animation_span,
                direction,
                false
            ), shape)
        end

        if animation_type == "shift" then
            return apply_animation_shape(get_sweep_animation_sample(
                position_ratio,
                progress,
                animation_span,
                direction,
                true
            ), shape)
        end

        return apply_animation_shape(get_wave_animation_sample(
            position_ratio,
            progress,
            animation_span,
            direction
        ), shape)
    end

    local function parse_profile_segment(raw_segment)
        if type(raw_segment) ~= "table" then
            return nil
        end

        local text_value = raw_segment.text
        if text_value == nil then
            return nil
        end

        if type(text_value) ~= "string" then
            text_value = tostring(text_value)
        end

        local text_upper = text_value:upper()
        local chars = split_utf8(text_value)
        local chars_upper = split_utf8(text_upper)
        local color_hex = normalize_hex_color(raw_segment.color)
        local normalized_mode = normalize_segment_mode(raw_segment.mode or raw_segment.effect)
        local segment_style = get_segment_style_key({
            style = raw_segment.style,
            mode = normalized_mode,
        })
        local segment_animation = get_segment_animation_key({
            animation = raw_segment.animation or raw_segment.anim,
            mode = normalized_mode,
        })
        local segment_channel = get_segment_animation_channel({
            channel = raw_segment.channel,
            mode = normalized_mode,
        })
        local segment = {
            text = text_value,
            text_upper = text_upper,
            chars = chars,
            chars_upper = chars_upper,
            mode = normalized_mode,
            style = segment_style,
            animation = segment_animation,
            channel = segment_channel,
            repeat_mode = get_segment_animation_repeat({
                repeat_mode = raw_segment.repeat_mode,
                playback = raw_segment.playback or raw_segment["repeat"],
            }),
            direction = get_segment_animation_direction({
                direction = raw_segment.direction,
            }),
            reverse = get_segment_animation_reverse({
                reverse = raw_segment.reverse or raw_segment.invert,
            }),
            shape = get_segment_animation_shape({
                shape = raw_segment.shape or raw_segment.sharpness,
            }),
            color_hex = color_hex,
            color_obj = hex_to_color(color_hex),
            wave_min = read_number(raw_segment.min, 0.3, 0.0, 1.0),
            wave_max = read_number(raw_segment.max, 1.0, 0.0, 1.0),
            wave_speed = read_number(raw_segment.speed, 2.0, 0.01, 20.0),
            wave_count = read_number(raw_segment.waves, 1.0, 0.1, 10.0),
            animation_span = read_number(
                raw_segment.animation_span or raw_segment.anim_span or raw_segment.span or raw_segment.waves,
                1.0,
                0.1,
                10.0
            ),
            saturation = read_number(raw_segment.saturation or raw_segment.sat, 1.0, 0.0, 1.0),
            value_level = read_number(raw_segment.value or raw_segment.val, 1.0, 0.0, 1.0),
            from_hex = normalize_hex_color(raw_segment.from),
            to_hex = normalize_hex_color(raw_segment.to),
            glyph_animation = get_segment_glyph_animation_key({
                glyph_animation = raw_segment.glyph_animation
                    or raw_segment.glyph_anim
                    or raw_segment.glyph_motion
                    or raw_segment.glyph_fx,
            }),
            glyph_glitch = get_segment_glyph_glitch_enabled(raw_segment),
            glyph_amount = read_number(
                raw_segment.glyph_amount
                    or raw_segment.glyph_amp
                    or raw_segment.glyph_strength
                    or raw_segment.glyph_size,
                4.0,
                0.0,
                24.0
            ),
            glyph_speed = read_number(
                raw_segment.glyph_speed
                    or raw_segment.glyph_rate,
                3.0,
                0.01,
                20.0
            ),
            glyph_span = read_number(
                raw_segment.glyph_span
                    or raw_segment.glyph_waves
                    or raw_segment.glyph_density,
                1.0,
                0.1,
                10.0
            ),
            render_parts = {
            },
        }

        if segment.wave_max < segment.wave_min then
            local temp = segment.wave_min
            segment.wave_min = segment.wave_max
            segment.wave_max = temp
        end

        segment.from_color_obj = hex_to_color(segment.from_hex)
        segment.to_color_obj = hex_to_color(segment.to_hex)
        segment.has_color_animation = get_segment_animation_key(segment) ~= "off"
        segment.has_glyph_animation = get_segment_glyph_animation_key(segment) ~= "off"
            or get_segment_glyph_glitch_enabled(segment) == true
        segment.is_animated = segment.has_color_animation == true
            or segment.has_glyph_animation == true
        return segment
    end

    parse_profile_from_input = function(raw_input)
        if type(raw_input) ~= "string" then
            return nil
        end

        local trimmed = trim_string(raw_input)
        if trimmed == "" then
            return nil
        end

        local prefix_length = nil
        local lowered = trimmed:lower()
        if lowered:sub(1, #API_PREFIX_LONG) == API_PREFIX_LONG then
            prefix_length = #API_PREFIX_LONG
        elseif lowered:sub(1, #API_PREFIX_SHORT) == API_PREFIX_SHORT then
            prefix_length = #API_PREFIX_SHORT
        else
            return nil
        end

        local payload = trim_string(trimmed:sub(prefix_length + 1))
        if payload == "" then
            return nil
        end

        local ok_profile, raw_profile = pcall(json.parse, payload)
        if not ok_profile or type(raw_profile) ~= "table" then
            return nil
        end

        local profile = {
            font = nil,
            custom_font = nil,
            segments = {
            },
        }

        if type(raw_profile.font) == "number" then
            profile.font = clamp_font_index(raw_profile.font)
        end

        if type(raw_profile.custom_font) == "table" then
            profile.custom_font = clone_custom_font_settings(raw_profile.custom_font)
        end

        local raw_segments = raw_profile.segments
        if type(raw_segments) == "table" then
            for i = 1, #raw_segments do
                local parsed_segment = parse_profile_segment(raw_segments[i])
                if parsed_segment ~= nil then
                    profile.segments[#profile.segments + 1] = parsed_segment
                end
            end
        end

        if #profile.segments == 0 then
            local fallback_segment = parse_profile_segment({
                text = raw_profile.text,
                style = raw_profile.style,
                animation = raw_profile.animation or raw_profile.anim,
                channel = raw_profile.channel,
                playback = raw_profile.playback or raw_profile["repeat"],
                direction = raw_profile.direction,
                reverse = raw_profile.reverse or raw_profile.invert,
                shape = raw_profile.shape or raw_profile.sharpness,
                mode = raw_profile.mode,
                effect = raw_profile.effect,
                color = raw_profile.color,
                min = raw_profile.min,
                max = raw_profile.max,
                speed = raw_profile.speed,
                waves = raw_profile.waves,
                saturation = raw_profile.saturation or raw_profile.sat,
                value = raw_profile.value or raw_profile.val,
                from = raw_profile.from,
                to = raw_profile.to,
            })
            if fallback_segment ~= nil then
                profile.segments[1] = fallback_segment
            end
        end

        if #profile.segments == 0 then
            return nil
        end

        local has_animated = false
        local has_color_animation = false
        local has_glyph_animation = false
        for i = 1, #profile.segments do
            if profile.segments[i].is_animated == true then
                has_animated = true
            end
            if profile.segments[i].has_color_animation == true then
                has_color_animation = true
            end
            if profile.segments[i].has_glyph_animation == true then
                has_glyph_animation = true
            end
        end
        profile.has_animated = has_animated
        profile.has_color_animation = has_color_animation
        profile.has_glyph_animation = has_glyph_animation

        return profile
    end

    local function build_profile_render_text(profile, style_color, uppercase_mode)
        local render_parts = {
        }
        local measure_parts = {
        }
        local fallback_hex = style_color:to_hex()
        local phase_cache = {
        }
        local solid_wave_color = color()
        local rainbow_color = color()

        for i = 1, #profile.segments do
            local segment = profile.segments[i]
            local segment_text = segment.text
            local segment_chars = segment.chars
            if uppercase_mode then
                segment_text = segment.text_upper
                segment_chars = segment.chars_upper
            end

            measure_parts[#measure_parts + 1] = segment_text

            local segment_render = ""
            local segment_style = get_segment_style_key(segment)
            local animation_type = get_segment_animation_key(segment)
            local animation_channel = get_segment_animation_channel(segment)
            local animation_repeat = get_segment_animation_repeat(segment)
            local animation_direction = get_segment_animation_direction(segment)
            local animation_reverse = get_segment_animation_reverse(segment)
            local animation_shape = get_segment_animation_shape(segment)
            local phase = nil
            if animation_type ~= "off" then
                phase = phase_cache[segment.wave_speed]
                if phase == nil then
                    phase = globals.realtime * read_number(segment.wave_speed, 2.0, 0.01, 20.0)
                    phase_cache[segment.wave_speed] = phase
                end
            end
            local progress = 0.0
            if phase ~= nil then
                progress = get_animation_time_progress(
                    phase,
                    animation_repeat,
                    animation_reverse
                )
            end
            local minimum = read_number(segment.wave_min, 0.3, 0.0, 1.0)
            local maximum = read_number(segment.wave_max, 1.0, 0.0, 1.0)
            if maximum < minimum then
                local temp = minimum
                minimum = maximum
                maximum = temp
            end

            if segment_style == "solid" and animation_type ~= "off" then
                local base_color = segment.color_obj
                if base_color == nil then
                    base_color = style_color
                end

                local chars_count = #segment_chars
                local previous_length = #segment.render_parts
                local hue, saturation, value_level = base_color:to_hsv()
                local red = base_color.r or 255
                local green = base_color.g or 255
                local blue = base_color.b or 255
                local alpha = base_color.a or 255
                if type(value_level) ~= "number" then
                    value_level = 1.0
                end
                local shift_offset = 0.0
                if animation_type == "shift" then
                    shift_offset = get_shift_offset(
                        progress,
                        segment.animation_span,
                        animation_direction
                    )
                end

                for char_index = 1, chars_count do
                    local position_ratio = 0
                    if chars_count > 1 then
                        position_ratio = (char_index - 1) / (chars_count - 1)
                    end

                    local sample = get_animation_sample(
                        animation_type,
                        position_ratio,
                        progress,
                        segment.animation_span,
                        animation_direction,
                        animation_shape
                    )
                    local strength = minimum + (maximum - minimum) * sample

                    if animation_channel == "alpha" then
                        local hex = rgba_to_hex(red, green, blue, alpha * strength)
                        segment.render_parts[char_index] = "\a" .. hex .. segment_chars[char_index]
                    elseif animation_type == "shift" then
                        solid_wave_color:as_hsv(
                            get_wrapped_progress(hue + shift_offset * 0.1),
                            saturation,
                            value_level,
                            alpha / 255
                        )
                        segment.render_parts[char_index] = "\a" .. solid_wave_color:to_hex() .. segment_chars[char_index]
                    else
                        solid_wave_color:as_hsv(hue, saturation, strength, alpha / 255)
                        segment.render_parts[char_index] = "\a" .. solid_wave_color:to_hex() .. segment_chars[char_index]
                    end
                end

                for char_index = chars_count + 1, previous_length do
                    segment.render_parts[char_index] = nil
                end

                segment_render = table.concat(segment.render_parts, "", 1, chars_count)
            elseif segment_style == "gradient" then
                local from_color = segment.from_color_obj
                if from_color == nil then
                    from_color = segment.color_obj
                end
                if from_color == nil then
                    from_color = style_color
                end

                local to_color = segment.to_color_obj
                if to_color == nil then
                    to_color = segment.color_obj
                end
                if to_color == nil then
                    to_color = style_color
                end

                local chars_count = #segment_chars
                local previous_length = #segment.render_parts
                local from_r = from_color.r or 255
                local from_g = from_color.g or 255
                local from_b = from_color.b or 255
                local from_a = from_color.a or 255
                local to_r = to_color.r or 255
                local to_g = to_color.g or 255
                local to_b = to_color.b or 255
                local to_a = to_color.a or 255
                local shift_offset = 0.0
                if animation_type == "shift" then
                    shift_offset = get_shift_offset(
                        progress,
                        segment.animation_span,
                        animation_direction
                    )
                end

                for char_index = 1, chars_count do
                    local position_ratio = 0
                    if chars_count > 1 then
                        position_ratio = (char_index - 1) / (chars_count - 1)
                    end

                    local ratio = position_ratio
                    local alpha_scale = 1.0
                    if animation_type ~= "off" then
                        local sample = get_animation_sample(
                            animation_type,
                            position_ratio,
                            progress,
                            segment.animation_span,
                            animation_direction,
                            animation_shape
                        )
                        local strength = minimum + (maximum - minimum) * sample
                        if animation_channel == "alpha" then
                            alpha_scale = strength
                        elseif animation_type == "shift" then
                            ratio = get_wrapped_progress(position_ratio + shift_offset)
                        else
                            ratio = strength
                        end
                    end

                    local r = from_r + (to_r - from_r) * ratio
                    local g = from_g + (to_g - from_g) * ratio
                    local b = from_b + (to_b - from_b) * ratio
                    local a = (from_a + (to_a - from_a) * ratio) * alpha_scale
                    local hex = rgba_to_hex(r, g, b, a)
                    segment.render_parts[char_index] = "\a" .. hex .. segment_chars[char_index]
                end

                for char_index = chars_count + 1, previous_length do
                    segment.render_parts[char_index] = nil
                end

                segment_render = table.concat(segment.render_parts, "", 1, chars_count)
            elseif segment_style == "rainbow" then
                local chars_count = #segment_chars
                local previous_length = #segment.render_parts
                local spread_value = read_number(segment.wave_count, 1.0, 0.1, 10.0)
                local saturation_value = read_number(segment.saturation, 1.0, 0.0, 1.0)
                local value_value = read_number(segment.value_level, 1.0, 0.0, 1.0)
                local base_alpha = (style_color.a or 255) / 255
                if segment.color_obj ~= nil and type(segment.color_obj.a) == "number" then
                    base_alpha = clamp_number(segment.color_obj.a / 255, 0.0, 1.0)
                end
                local shift_offset = 0.0
                if animation_type == "shift" then
                    shift_offset = get_shift_offset(
                        progress,
                        segment.animation_span,
                        animation_direction
                    )
                end

                for char_index = 1, chars_count do
                    local position_ratio = 0
                    if chars_count > 1 then
                        position_ratio = (char_index - 1) / (chars_count - 1)
                    end

                    local hue = position_ratio * spread_value
                    local alpha_scale = base_alpha
                    if animation_type ~= "off" then
                        local sample = get_animation_sample(
                            animation_type,
                            position_ratio,
                            progress,
                            segment.animation_span,
                            animation_direction,
                            animation_shape
                        )
                        local strength = minimum + (maximum - minimum) * sample
                        if animation_channel == "alpha" then
                            alpha_scale = clamp_number(base_alpha * strength, 0.0, 1.0)
                        elseif animation_type == "shift" then
                            hue = hue + shift_offset
                        else
                            hue = hue + strength * 0.5
                        end
                    end

                    rainbow_color:as_hsv(
                        get_wrapped_progress(hue),
                        saturation_value,
                        value_value,
                        alpha_scale
                    )
                    segment.render_parts[char_index] = "\a" .. rainbow_color:to_hex() .. segment_chars[char_index]
                end

                for char_index = chars_count + 1, previous_length do
                    segment.render_parts[char_index] = nil
                end

                segment_render = table.concat(segment.render_parts, "", 1, chars_count)
            else
                local hex = segment.color_hex
                if hex == nil then
                    hex = fallback_hex
                end

                segment_render = "\a" .. hex .. segment_text
            end

            render_parts[#render_parts + 1] = segment_render
            segment.cached_render_text = segment_render
        end

        return table.concat(render_parts), table.concat(measure_parts)
    end

    local function get_utf8_render_glyph_end(text, index)
        local byte = string.byte(text, index)
        if byte == nil then
            return index
        end

        if byte >= 240 then
            return index + 3
        end

        if byte >= 224 then
            return index + 2
        end

        if byte >= 192 then
            return index + 1
        end

        return index
    end

    local function get_cached_glyph_width(font_index, glyph)
        if font_index == CUSTOM_FONT then
            return state.custom_font_renderer:measure_glyph_width(glyph)
        end

        local font_cache = glyph_width_cache[font_index]
        if font_cache == nil then
            font_cache = {
            }
            glyph_width_cache[font_index] = font_cache
        end

        local width = font_cache[glyph]
        if width ~= nil then
            return width
        end

        width = render.measure_text(font_index, nil, glyph).x
        font_cache[glyph] = width

        return width
    end

    local function get_cached_hex_color(hex)
        local normalized = normalize_hex_color(hex)
        if normalized == nil then
            normalized = "FFFFFFFF"
        end

        local cached = glyph_color_cache[normalized]
        if cached ~= nil then
            return cached
        end

        cached = hex_to_color(normalized)
        if cached == nil then
            cached = color(255, 255, 255, 255)
        end

        glyph_color_cache[normalized] = cached
        return cached
    end

    local function get_heart_layer_count(count)
        if count >= 82 then
            return 5
        end
        if count >= 64 then
            return 4
        end
        if count >= 46 then
            return 3
        end
        if count >= 30 then
            return 2
        end

        return 1
    end

    local function get_normalized_heart_point(progress)
        local angle = progress * math.pi * 2
        local sin_angle = math.sin(angle)
        local raw_x = 16.0 * sin_angle * sin_angle * sin_angle
        local raw_y = 13.0 * math.cos(angle)
            - 5.0 * math.cos(angle * 2.0)
            - 2.0 * math.cos(angle * 3.0)
            - math.cos(angle * 4.0)
        return raw_x / 16.0, -((raw_y + 2.0) / 16.0)
    end

    local function ensure_heart_contour_cache()
        if heart_contour_cache.total_length > 0.0 then
            return
        end

        local samples = heart_contour_cache.samples
        local previous_x, previous_y = get_normalized_heart_point(0.0)
        local total_length = 0.0

        samples[1] = {
            x = previous_x,
            y = previous_y,
            distance = 0.0,
        }

        for sample_index = 1, HEART_CONTOUR_SAMPLE_COUNT do
            local progress = sample_index / HEART_CONTOUR_SAMPLE_COUNT
            local sample_x, sample_y = get_normalized_heart_point(progress)
            local delta_x = sample_x - previous_x
            local delta_y = sample_y - previous_y
            total_length = total_length + math.sqrt(delta_x * delta_x + delta_y * delta_y)

            local sample = samples[sample_index + 1]
            if sample == nil then
                sample = {
                }
                samples[sample_index + 1] = sample
            end

            sample.x = sample_x
            sample.y = sample_y
            sample.distance = total_length
            previous_x = sample_x
            previous_y = sample_y
        end

        for sample_index = HEART_CONTOUR_SAMPLE_COUNT + 2, #samples do
            samples[sample_index] = nil
        end

        heart_contour_cache.total_length = total_length
    end

    local function get_even_heart_contour_point(progress)
        ensure_heart_contour_cache()

        local wrapped_progress = progress - math.floor(progress)
        if wrapped_progress <= 0.0 then
            local first_sample = heart_contour_cache.samples[1]
            return first_sample.x, first_sample.y
        end

        local samples = heart_contour_cache.samples
        local total_length = heart_contour_cache.total_length
        local target_distance = wrapped_progress * total_length
        local left = 2
        local right = #samples

        while left < right do
            local middle = math.floor((left + right) * 0.5)
            if samples[middle].distance < target_distance then
                left = middle + 1
            else
                right = middle
            end
        end

        local upper_sample = samples[left]
        local lower_sample = samples[left - 1]
        local span = upper_sample.distance - lower_sample.distance
        if span <= 0.0 then
            return upper_sample.x, upper_sample.y
        end

        local ratio = (target_distance - lower_sample.distance) / span
        return lower_sample.x + (upper_sample.x - lower_sample.x) * ratio,
            lower_sample.y + (upper_sample.y - lower_sample.y) * ratio
    end

    local function get_cached_heart_layout(count)
        local cached = heart_layout_cache[count]
        if cached ~= nil then
            return cached
        end

        local layout = {
        }
        heart_layout_cache[count] = layout
        if count <= 0 then
            return layout
        end

        local layer_count = get_heart_layer_count(count)
        if layer_count > count then
            layer_count = count
        end

        local total_weight = 0.0
        for layer_index = 1, layer_count do
            total_weight = total_weight + HEART_LAYER_WEIGHTS[layer_index]
        end

        local layer_counts = {
        }
        local layer_remainders = {
        }
        local allocated = 0

        for layer_index = 1, layer_count do
            local exact_count = count * HEART_LAYER_WEIGHTS[layer_index] / total_weight
            local whole_count = math.floor(exact_count)
            if whole_count < 1 then
                whole_count = 1
            end

            layer_counts[layer_index] = whole_count
            layer_remainders[layer_index] = exact_count - whole_count
            allocated = allocated + whole_count
        end

        while allocated > count do
            for layer_index = layer_count, 1, -1 do
                if allocated <= count then
                    break
                end
                if layer_counts[layer_index] > 1 then
                    layer_counts[layer_index] = layer_counts[layer_index] - 1
                    allocated = allocated - 1
                end
            end
        end

        while allocated < count do
            local best_layer = 1
            local best_remainder = layer_remainders[1] or 0.0

            for layer_index = 2, layer_count do
                local remainder = layer_remainders[layer_index] or 0.0
                if remainder > best_remainder then
                    best_layer = layer_index
                    best_remainder = remainder
                end
            end

            layer_counts[best_layer] = layer_counts[best_layer] + 1
            layer_remainders[best_layer] = (layer_remainders[best_layer] or 0.0) - 1.0
            allocated = allocated + 1
        end

        local point_index = 0

        for layer_index = 1, layer_count do
            local point_count = layer_counts[layer_index]
            local layer_scale = HEART_LAYER_SCALES[layer_index]
            local point_offset = HEART_LAYER_POINT_OFFSETS[layer_index] or 0.0

            for layer_point = 1, point_count do
                local point_ratio = (layer_point - 0.5 + point_offset) / point_count
                local point_x, point_y = get_even_heart_contour_point(point_ratio)

                point_index = point_index + 1
                layout[point_index] = {
                    x = point_x * layer_scale,
                    y = point_y * layer_scale,
                }
            end
        end

        return layout
    end

    local function apply_heart_layout_to_segment(
        entries,
        start_index,
        end_index,
        segment_start_x,
        segment_end_x,
        amount
    )
        if end_index < start_index then
            return
        end

        local count = end_index - start_index + 1
        local layout = get_cached_heart_layout(count)
        local base_scale = amount * (3.25 + math.min(count, 24) * 0.11)
        local scale_x = base_scale * 0.95
        local scale_y = base_scale * 1.08
        local segment_center_x = segment_start_x + (segment_end_x - segment_start_x) * 0.5

        for index = 1, count do
            local entry = entries[start_index + index - 1]
            local point = layout[index]
            if point == nil then
                point = {
                    x = 0.0,
                    y = 0.0,
                }
            end

            entry.heart_anchor_x = segment_center_x - entry.base_x - entry.width * 0.5
            entry.heart_target_x = point.x * scale_x
            entry.heart_target_y = point.y * scale_y
        end
    end

    local function rebuild_cached_glyph_entries(profile, font_index, uppercase_mode)
        local entries = profile_render_cache.glyph_entries
        local entry_count = 0
        local cursor_x = 0
        local glyph_spacing = 0
        if font_index == CUSTOM_FONT then
            glyph_spacing = state.custom_font_renderer:get_spacing()
        end

        for segment_index = 1, #profile.segments do
            local segment = profile.segments[segment_index]
            local segment_chars = segment.chars
            if uppercase_mode then
                segment_chars = segment.chars_upper
            end

            local segment_render = segment.cached_render_text
            if type(segment_render) ~= "string" then
                segment_render = ""
            end

            local glyph_motion = get_segment_glyph_animation_key(segment)
            local glyph_glitch = get_segment_glyph_glitch_enabled(segment)
            local glyph_amount = read_number(segment.glyph_amount, 4.0, 0.0, 24.0)
            local glyph_speed = read_number(segment.glyph_speed, 3.0, 0.01, 20.0)
            local glyph_span = read_number(segment.glyph_span, 1.0, 0.1, 10.0)
            local current_hex = "FFFFFFFF"
            local render_index = 1
            local chars_count = #segment_chars
            local segment_entry_start = entry_count + 1
            local segment_start_x = cursor_x

            for char_index = 1, chars_count do
                while render_index <= #segment_render do
                    if string.byte(segment_render, render_index) ~= 7 then
                        break
                    end

                    local normalized_hex = normalize_hex_color(
                        segment_render:sub(render_index + 1, render_index + 8)
                    )
                    if normalized_hex == nil then
                        break
                    end

                    current_hex = normalized_hex
                    render_index = render_index + 9
                end

                local glyph_end = get_utf8_render_glyph_end(segment_render, render_index)
                local glyph_text = segment_render:sub(render_index, glyph_end)
                if glyph_text == "" then
                    glyph_text = segment_chars[char_index]
                end

                entry_count = entry_count + 1

                local entry = entries[entry_count]
                if entry == nil then
                    entry = {
                    }
                    entries[entry_count] = entry
                end

                entry.text = glyph_text
                entry.color = get_cached_hex_color(current_hex)
                entry.width = get_cached_glyph_width(font_index, segment_chars[char_index])
                entry.base_x = cursor_x
                entry.motion = glyph_motion
                entry.glitch = glyph_glitch
                entry.motion_amount = glyph_amount
                entry.motion_speed = glyph_speed
                entry.motion_span = glyph_span
                entry.motion_index = char_index
                entry.motion_count = chars_count
                entry.heart_anchor_x = 0.0
                entry.heart_target_x = 0.0
                entry.heart_target_y = 0.0

                cursor_x = cursor_x + entry.width
                if char_index < chars_count then
                    cursor_x = cursor_x + glyph_spacing
                end
                render_index = glyph_end + 1
            end

            if glyph_motion == "heart" then
                apply_heart_layout_to_segment(
                    entries,
                    segment_entry_start,
                    entry_count,
                    segment_start_x,
                    cursor_x,
                    glyph_amount
                )
            end
        end

        for i = entry_count + 1, #entries do
            entries[i] = nil
        end

        profile_render_cache.glyph_entry_count = entry_count
        profile_render_cache.glyph_base_width = cursor_x
    end

    local function rebuild_static_glyph_entries(render_text, plain_text, font_index)
        local entries = profile_render_cache.glyph_entries
        local glyph_chars = split_utf8(plain_text)
        local entry_count = 0
        local cursor_x = 0
        local glyph_spacing = 0
        if font_index == CUSTOM_FONT then
            glyph_spacing = state.custom_font_renderer:get_spacing()
        end
        local current_hex = "FFFFFFFF"
        local render_index = 1

        for char_index = 1, #glyph_chars do
            while render_index <= #render_text do
                if string.byte(render_text, render_index) ~= 7 then
                    break
                end

                local normalized_hex = normalize_hex_color(
                    render_text:sub(render_index + 1, render_index + 8)
                )
                if normalized_hex == nil then
                    break
                end

                current_hex = normalized_hex
                render_index = render_index + 9
            end

            local glyph_end = get_utf8_render_glyph_end(render_text, render_index)
            local glyph_text = render_text:sub(render_index, glyph_end)
            if glyph_text == "" then
                glyph_text = glyph_chars[char_index]
            end

            entry_count = entry_count + 1

            local entry = entries[entry_count]
            if entry == nil then
                entry = {
                }
                entries[entry_count] = entry
            end

            entry.text = glyph_text
            entry.color = get_cached_hex_color(current_hex)
            entry.width = get_cached_glyph_width(font_index, glyph_chars[char_index])
            entry.base_x = cursor_x
            entry.motion = "off"
            entry.glitch = false
            entry.motion_amount = 0.0
            entry.motion_speed = 0.0
            entry.motion_span = 0.0
            entry.motion_index = char_index
            entry.motion_count = #glyph_chars
            entry.heart_anchor_x = 0.0
            entry.heart_target_x = 0.0
            entry.heart_target_y = 0.0

            cursor_x = cursor_x + entry.width
            if char_index < #glyph_chars then
                cursor_x = cursor_x + glyph_spacing
            end
            render_index = glyph_end + 1
        end

        for i = entry_count + 1, #entries do
            entries[i] = nil
        end

        profile_render_cache.glyph_entry_count = entry_count
        profile_render_cache.glyph_base_width = cursor_x
    end

    local function can_use_custom_text_runs(custom_font_settings)
        return type(custom_font_settings) == "table"
            and custom_font_settings.spacing == 0
    end

    local function can_use_custom_profile_text_runs(profile, custom_font_settings)
        if can_use_custom_text_runs(custom_font_settings) ~= true then
            return false
        end

        if type(profile) ~= "table"
            or type(profile.segments) ~= "table"
            or #profile.segments == 0 then
            return false
        end

        for i = 1, #profile.segments do
            local segment = profile.segments[i]
            if type(segment) ~= "table" then
                return false
            end

            if segment.style ~= "solid" then
                return false
            end

            if type(segment.text) ~= "string"
                or string.find(segment.text, "\a", 1, true) ~= nil then
                return false
            end

            if segment.has_color_animation == true then
                return false
            end

            if segment.has_glyph_animation == true then
                return false
            end
        end

        return true
    end

    local function unpack_simple_render_text(render_text, fallback_text)
        if type(render_text) ~= "string" or render_text == "" then
            return nil, nil
        end

        local color_hex = "FFFFFFFF"
        local plain_text = render_text

        if string.byte(render_text, 1) == 7 then
            local normalized_hex = normalize_hex_color(render_text:sub(2, 9))
            if normalized_hex == nil then
                return nil, nil
            end

            color_hex = normalized_hex
            plain_text = render_text:sub(10)
        end

        if plain_text == "" and type(fallback_text) == "string" then
            plain_text = fallback_text
        end

        if type(plain_text) ~= "string"
            or plain_text == ""
            or string.find(plain_text, "\a", 1, true) ~= nil then
            return nil, nil
        end

        return color_hex, plain_text
    end

    local function rebuild_custom_text_run_entries(profile, uppercase_mode, font_index)
        local entries = profile_render_cache.glyph_entries
        local entry_count = 0
        local cursor_x = 0

        for segment_index = 1, #profile.segments do
            local segment = profile.segments[segment_index]
            local segment_render = segment.cached_render_text
            local fallback_text = uppercase_mode == true
                and segment.text_upper
                or segment.text
            local color_hex, run_text = unpack_simple_render_text(
                segment_render,
                fallback_text
            )

            if run_text ~= nil then
                local entry = entries[entry_count + 1]
                if entry == nil then
                    entry = {
                    }
                    entries[entry_count + 1] = entry
                end

                entry_count = entry_count + 1
                entry.text = run_text
                entry.color = get_cached_hex_color(color_hex)
                entry.width = get_cached_glyph_width(font_index, run_text)
                entry.base_x = cursor_x
                entry.motion = "off"
                entry.glitch = false
                entry.motion_amount = 0.0
                entry.motion_speed = 0.0
                entry.motion_span = 0.0
                entry.motion_index = 1
                entry.motion_count = 1
                entry.heart_anchor_x = 0.0
                entry.heart_target_x = 0.0
                entry.heart_target_y = 0.0

                cursor_x = cursor_x + entry.width
            end
        end

        for i = entry_count + 1, #entries do
            entries[i] = nil
        end

        profile_render_cache.glyph_entry_count = entry_count
        profile_render_cache.glyph_base_width = cursor_x
    end

    local function rebuild_custom_legacy_text_run_entries(render_text, plain_text, font_index)
        local color_hex, run_text = unpack_simple_render_text(render_text, plain_text)
        if run_text == nil then
            rebuild_static_glyph_entries(render_text, plain_text, font_index)
            return
        end

        local entries = profile_render_cache.glyph_entries
        local entry = entries[1]
        if entry == nil then
            entry = {
            }
            entries[1] = entry
        end

        entry.text = run_text
        entry.color = get_cached_hex_color(color_hex)
        entry.width = get_cached_glyph_width(font_index, run_text)
        entry.base_x = 0
        entry.motion = "off"
        entry.glitch = false
        entry.motion_amount = 0.0
        entry.motion_speed = 0.0
        entry.motion_span = 0.0
        entry.motion_index = 1
        entry.motion_count = 1
        entry.heart_anchor_x = 0.0
        entry.heart_target_x = 0.0
        entry.heart_target_y = 0.0

        for i = 2, #entries do
            entries[i] = nil
        end

        profile_render_cache.glyph_entry_count = 1
        profile_render_cache.glyph_base_width = entry.width
    end

    local function get_glyph_motion_padding(segment)
        local motion = get_segment_glyph_animation_key(segment)
        local glitch = get_segment_glyph_glitch_enabled(segment)
        if motion == "off"
            and glitch ~= true then
            return 0, 0
        end

        local amount = read_number(segment.glyph_amount, 4.0, 0.0, 24.0)
        if glitch == true then
            return 0, 0
        end

        if motion == "orbit" then
            return amount * 0.8, amount * 0.7
        end

        if motion == "scatter" then
            return amount * 1.2, amount * 0.4
        end

        if motion == "heart" then
            local count = 0
            if type(segment.chars) == "table" then
                count = #segment.chars
            end

            local base_scale = amount * (3.25 + math.min(count, 24) * 0.11)
            return base_scale * 1.15, base_scale * 1.25
        end

        return amount * 0.2, amount
    end

    local function get_profile_glyph_padding(profile)
        local padding_x = 0
        local padding_y = 0

        if type(profile) ~= "table" or type(profile.segments) ~= "table" then
            return padding_x, padding_y
        end

        for i = 1, #profile.segments do
            local segment = profile.segments[i]
            local segment_padding_x, segment_padding_y = get_glyph_motion_padding(segment)
            if segment_padding_x > padding_x then
                padding_x = segment_padding_x
            end
            if segment_padding_y > padding_y then
                padding_y = segment_padding_y
            end
        end

        return math.ceil(padding_x + 1), math.ceil(padding_y + 1)
    end

    local function get_glyph_motion_offset(entry, realtime)
        local motion = entry.motion
        if motion == "off" then
            return 0.0, 0.0
        end

        local amount = entry.motion_amount
        if amount <= 0 then
            return 0.0, 0.0
        end

        local position_ratio = 0.0
        if entry.motion_count > 1 then
            position_ratio = (entry.motion_index - 1) / (entry.motion_count - 1)
        end

        local phase = realtime * entry.motion_speed * math.pi * 2
        local offset_phase = phase + position_ratio * entry.motion_span * math.pi * 2

        if motion == "wave" then
            return 0.0, math.sin(offset_phase) * amount
        end

        if motion == "orbit" then
            return math.cos(offset_phase) * amount * 0.8,
                math.sin(offset_phase) * amount * 0.65
        end

        if motion == "scatter" then
            local center_bias = position_ratio - 0.5
            local direction = center_bias >= 0 and 1 or -1
            local travel = (math.sin(offset_phase - math.pi * 0.5) + 1.0) * 0.5
            return direction * travel * amount * (0.55 + math.abs(center_bias) * 0.9),
                math.cos(offset_phase * 0.5) * amount * 0.35
        end

        if motion == "heart" then
            local pulse = 0.86 + ((math.sin(phase * 1.1 - math.pi * 0.5) + 1.0) * 0.5) * 0.24
            local sway_x = math.sin(offset_phase * 0.45) * amount * 0.06
            local sway_y = math.cos(offset_phase * 0.45) * amount * 0.08
            return (entry.heart_anchor_x or 0.0) + (entry.heart_target_x or 0.0) * pulse + sway_x,
                (entry.heart_target_y or 0.0) * pulse + sway_y
        end

        return 0.0, 0.0
    end

    local function get_glitch_glyph_text(entry, font_index, realtime)
        if entry.text == " " then
            return entry.text, 0.0
        end

        local position_ratio = 0.0
        if entry.motion_count > 1 then
            position_ratio = (entry.motion_index - 1) / (entry.motion_count - 1)
        end

        local bucket = math.floor(realtime * entry.motion_speed * 18.0)
        local phase = realtime * entry.motion_speed * math.pi * 2
        local spread_phase = phase + position_ratio * entry.motion_span * math.pi * 2
        local sample = (math.sin(spread_phase) + 1.0) * 0.5
        local strength = clamp_number(entry.motion_amount / 24.0, 0.0, 1.0)
        local threshold = 0.2 + strength * 0.8
        if sample > threshold then
            return entry.text, 0.0
        end

        local seed = (entry.motion_index * 1103515245 + bucket * 12345) % 2147483647
        local glitch_text = GLITCH_GLYPHS[(seed % GLITCH_GLYPH_COUNT) + 1]
        local glitch_width = get_cached_glyph_width(font_index, glitch_text)
        return glitch_text, (entry.width - glitch_width) * 0.5
    end

    local function draw_cached_glyph_entries(font_index, position)
        local entry_count = profile_render_cache.glyph_entry_count
        if entry_count <= 0 then
            return
        end

        local base_x = position.x - profile_render_cache.glyph_base_width * 0.5
        local base_y = position.y - profile_render_cache.glyph_base_height * 0.5
        local realtime = globals.realtime

        for i = 1, entry_count do
            local entry = profile_render_cache.glyph_entries[i]
            local offset_x, offset_y = get_glyph_motion_offset(entry, realtime)
            local glyph_text = entry.text
            local glyph_adjust_x = 0.0
            if entry.glitch == true then
                glyph_text, glyph_adjust_x = get_glitch_glyph_text(entry, font_index, realtime)
            end

            local glyph_position = vector(
                base_x + entry.base_x + offset_x + glyph_adjust_x,
                base_y + offset_y,
                0
            )

            if font_index == CUSTOM_FONT then
                state.custom_font_renderer:draw_glyph(glyph_position, entry.color, glyph_text)
            else
                render.text(
                    font_index,
                    glyph_position,
                    entry.color,
                    nil,
                    glyph_text
                )
            end
        end
    end

    local function update_bounds()
        local half_width = math.max(1, state.text_size_x * 0.5)
        local half_height = math.max(1, state.text_size_y * 0.5)

        state.bounds_min_x = state.position_x - half_width - HOVER_PADDING
        state.bounds_min_y = state.position_y - half_height - HOVER_PADDING
        state.bounds_max_x = state.position_x + half_width + HOVER_PADDING
        state.bounds_max_y = state.position_y + half_height + HOVER_PADDING
    end

    local function is_mouse_inside_bounds(mouse)
        if mouse == nil then
            return false
        end

        if mouse.x < state.bounds_min_x then
            return false
        end

        if mouse.x > state.bounds_max_x then
            return false
        end

        if mouse.y < state.bounds_min_y then
            return false
        end

        if mouse.y > state.bounds_max_y then
            return false
        end

        return true
    end

    local function is_mouse_inside_menu(mouse)
        if mouse == nil then
            return false
        end

        local menu_position = ui.get_position()
        local menu_size = ui.get_size()
        if menu_position == nil or menu_size == nil then
            return false
        end

        if mouse.x < menu_position.x then
            return false
        end

        if mouse.x > menu_position.x + menu_size.x then
            return false
        end

        if mouse.y < menu_position.y then
            return false
        end

        if mouse.y > menu_position.y + menu_size.y then
            return false
        end

        return true
    end

    local function find_snap_target(x, y, screen)
        local center_x = screen.x * 0.5
        local center_y = screen.y * 0.5
        local snap_x = math.abs(x - center_x) <= SNAP_THRESHOLD
        local snap_y = math.abs(y - center_y) <= SNAP_THRESHOLD

        if snap_x == true then
            x = center_x
        end

        if snap_y == true then
            y = center_y
        end

        return x, y, snap_x, snap_y
    end

    local function clamp_position_to_screen(screen)
        local half_width = math.max(1, state.text_size_x * 0.5)
        local half_height = math.max(1, state.text_size_y * 0.5)

        state.position_x = clamp_number(state.position_x, half_width, screen.x - half_width)
        state.position_y = clamp_number(state.position_y, half_height, screen.y - half_height)
    end

    local function sync_config_refs()
        if config_refs.position_x ~= nil and type(state.position_x) == "number" then
            pcall(
                config_refs.position_x.set,
                config_refs.position_x,
                math.floor(state.position_x + 0.5)
            )
        end

        if config_refs.position_y ~= nil and type(state.position_y) == "number" then
            pcall(
                config_refs.position_y.set,
                config_refs.position_y,
                math.floor(state.position_y + 0.5)
            )
        end

        if config_refs.font ~= nil then
            pcall(
                config_refs.font.set,
                config_refs.font,
                get_active_font_index()
            )
        end
    end

    local function sync_text_config_ref()
        local next_value = current_name
        if type(state.api_profile) == "table" or get_active_font_index() ~= DEFAULT_FONT then
            local serialized = build_profile_input(build_current_profile_definition())
            if type(serialized) == "string" and serialized ~= "" then
                next_value = serialized
            end
        end

        if type(next_value) ~= "string" then
            next_value = ""
        end

        if next_value ~= current_name then
            apply_name_value(next_value)
        end

        if config_refs.text == nil then
            return
        end

        local ok_current, current_value = pcall(config_refs.text.get, config_refs.text)
        if ok_current and current_value == next_value then
            return
        end

        pending_text_config_value = next_value
        pcall(config_refs.text.set, config_refs.text, next_value)
    end

    local function render_snap_visuals(screen)
        local center_x = math.floor(screen.x * 0.5 + 0.5)
        local center_y = math.floor(screen.y * 0.5 + 0.5)
        local vertical_alpha = SNAP_LINE_ALPHA
        local horizontal_alpha = SNAP_LINE_ALPHA
        if state.active_snap_x == true then
            vertical_alpha = SNAP_LINE_ACTIVE_ALPHA
        end
        if state.active_snap_y == true then
            horizontal_alpha = SNAP_LINE_ACTIVE_ALPHA
        end

        render.line(
            vector(center_x, 0),
            vector(center_x, screen.y),
            color(255, 255, 255, vertical_alpha)
        )
        render.line(
            vector(0, center_y),
            vector(screen.x, center_y),
            color(255, 255, 255, horizontal_alpha)
        )
    end

    local function on_mouse_input()
        if ui.get_alpha() <= 0 then
            if state.dragging == true then
                state.dragging = false
                state.active_snap_x = false
                state.active_snap_y = false
                sync_config_refs()
            end

            state.hovered = false
            state.was_left_down = false
            state.was_right_down = false
            return
        end

        local mouse = ui.get_mouse_position()
        if mouse == nil then
            return
        end

        local left_down = common.is_button_down(VK_LBUTTON) == true
        local right_down = common.is_button_down(VK_RBUTTON) == true
        if is_mouse_inside_menu(mouse) then
            state.hovered = false
            state.active_snap_x = false
            state.active_snap_y = false

            if state.dragging == true and left_down ~= true then
                state.dragging = false
                sync_config_refs()
            end

            state.was_left_down = left_down
            state.was_right_down = right_down
            return
        end

        local is_hovered = is_mouse_inside_bounds(mouse)
        state.hovered = is_hovered

        if left_down and state.was_left_down ~= true then
            if is_hovered then
                state.dragging = true
                state.drag_offset_x = mouse.x - state.position_x
                state.drag_offset_y = mouse.y - state.position_y
            end
        end

        if state.dragging == true then
            if left_down == true then
                local screen = render.screen_size()
                ensure_position_initialized(screen)

                local next_x = mouse.x - state.drag_offset_x
                local next_y = mouse.y - state.drag_offset_y

                local snapped_x, snapped_y, snap_x, snap_y = find_snap_target(
                    next_x,
                    next_y,
                    screen
                )

                state.position_x = snapped_x
                state.position_y = snapped_y
                state.active_snap_x = snap_x
                state.active_snap_y = snap_y

                clamp_position_to_screen(screen)
            else
                state.dragging = false
                state.active_snap_x = false
                state.active_snap_y = false
                sync_config_refs()
            end
        end

        if right_down
            and state.was_right_down ~= true
            and state.hover_font_cycle_enabled == true then
            if is_hovered and state.dragging ~= true then
                local next_font = clamp_font_index(state.font_index + 1)
                if next_font == state.font_index then
                    if state.font_index >= FONT_MAX then
                        next_font = FONT_MIN
                    end
                end

                state.font_index = next_font

                if config_refs.font ~= nil then
                    pcall(
                        config_refs.font.set,
                        config_refs.font,
                        state.font_index
                    )
                end
            end
        end

        state.was_left_down = left_down
        state.was_right_down = right_down

        if state.hovered == true or state.dragging == true then
            return false
        end
    end

    local function on_render()
        if current_name == "" then
            return
        end

        local text = normalize_color_codes(current_name)
        if text == "" then
            return
        end

        local style = ui.get_style()
        local base_color = style["Link Active"]
        if base_color == nil then
            base_color = color(255, 255, 255, 255)
        end

        local configured_font_index = clamp_font_index(state.font_index)
        state.font_index = configured_font_index

        local font_index = configured_font_index
        local render_text = nil
        local measure_text_value = nil
        local use_glyph_render = false
        local use_text_runs = false
        local measure_padding_x = 0
        local measure_padding_y = 0
        local font_signature = get_font_signature(font_index, state.custom_font_settings)
        local profile = state.api_profile
        if profile ~= nil then
            if type(profile.font) == "number" then
                font_index = clamp_font_index(profile.font)
            end

            local custom_font_settings = get_profile_custom_font_settings(profile)
            font_signature = get_font_signature(font_index, custom_font_settings)
            if font_index == CUSTOM_FONT then
                prepare_custom_font_renderer(custom_font_settings)
                use_text_runs = can_use_custom_profile_text_runs(
                    profile,
                    custom_font_settings
                )
            end

            local uppercase_mode = font_index == 2

            local style_hex = base_color:to_hex()
            local now = globals.realtime
            use_glyph_render = profile.has_glyph_animation == true
                or font_index == CUSTOM_FONT
            if profile.has_glyph_animation == true then
                measure_padding_x, measure_padding_y = get_profile_glyph_padding(profile)
            end
            local should_rebuild = false
            if profile_render_cache.profile ~= profile then
                should_rebuild = true
            end
            if profile_render_cache.uppercase_mode ~= uppercase_mode then
                should_rebuild = true
            end
            if profile_render_cache.style_hex ~= style_hex then
                should_rebuild = true
            end
            if type(profile_render_cache.measure_text) ~= "string" then
                should_rebuild = true
            end
            if type(profile_render_cache.render_text) ~= "string" then
                should_rebuild = true
            end
            if profile_render_cache.use_glyph_render ~= use_glyph_render then
                should_rebuild = true
            end
            if profile_render_cache.use_text_runs ~= use_text_runs then
                should_rebuild = true
            end
            if profile_render_cache.font_signature ~= font_signature then
                should_rebuild = true
            end
            if profile.has_color_animation == true then
                if now >= profile_render_cache.next_animated_update then
                    should_rebuild = true
                end
            end

            if should_rebuild then
                render_text, measure_text_value = build_profile_render_text(
                    profile,
                    base_color,
                    uppercase_mode
                )
                profile_render_cache.profile = profile
                profile_render_cache.uppercase_mode = uppercase_mode
                profile_render_cache.style_hex = style_hex
                profile_render_cache.render_text = render_text
                profile_render_cache.measure_text = measure_text_value
                profile_render_cache.use_glyph_render = use_glyph_render
                profile_render_cache.use_text_runs = use_text_runs
                profile_render_cache.font_signature = font_signature

                if use_glyph_render == true then
                    if use_text_runs == true then
                        rebuild_custom_text_run_entries(profile, uppercase_mode, font_index)
                    else
                        rebuild_cached_glyph_entries(profile, font_index, uppercase_mode)
                    end
                else
                    profile_render_cache.glyph_entry_count = 0
                    profile_render_cache.glyph_base_width = 0
                    profile_render_cache.glyph_base_height = 0
                end

                if profile.has_color_animation == true then
                    profile_render_cache.next_animated_update = now + PROFILE_ANIM_UPDATE_INTERVAL
                else
                    profile_render_cache.next_animated_update = 0
                end
            else
                render_text = profile_render_cache.render_text
                measure_text_value = profile_render_cache.measure_text
            end
        else
            local source_text = text
            if font_index == 2 then
                source_text = source_text:upper()
            end

            if font_index == CUSTOM_FONT then
                prepare_custom_font_renderer(state.custom_font_settings)
                font_signature = get_font_signature(font_index, state.custom_font_settings)
                use_glyph_render = true
                use_text_runs = can_use_custom_text_runs(state.custom_font_settings)
            end

            render_text = get_legacy_render_text(source_text, base_color)
            measure_text_value = source_text

            if use_glyph_render == true then
                if use_text_runs == true then
                    rebuild_custom_legacy_text_run_entries(
                        render_text,
                        measure_text_value,
                        font_index
                    )
                else
                    rebuild_static_glyph_entries(render_text, measure_text_value, font_index)
                end
            else
                profile_render_cache.glyph_entry_count = 0
                profile_render_cache.glyph_base_width = 0
                profile_render_cache.glyph_base_height = 0
            end
        end

        if type(measure_text_value) ~= "string" or measure_text_value == "" then
            return
        end

        local cached_width = use_glyph_render == true
            and profile_render_cache.glyph_base_width
            or 0
        if state.last_measure_font_key ~= font_signature
            or state.last_measure_text ~= measure_text_value
            or state.last_measure_use_glyph_render ~= use_glyph_render
            or state.last_measure_cached_width ~= cached_width then
            local text_size = measure_font_text(font_index, measure_text_value)
            local measured_width = text_size.x
            if use_glyph_render == true and cached_width > 0 then
                measured_width = cached_width
            end

            state.text_size_x = measured_width + measure_padding_x * 2
            state.text_size_y = text_size.y + measure_padding_y * 2
            state.last_measure_font_key = font_signature
            state.last_measure_text = measure_text_value
            state.last_measure_padding_x = measure_padding_x
            state.last_measure_padding_y = measure_padding_y
            state.last_measure_use_glyph_render = use_glyph_render
            state.last_measure_cached_width = cached_width
            profile_render_cache.glyph_base_height = text_size.y
        elseif state.last_measure_padding_x ~= measure_padding_x
            or state.last_measure_padding_y ~= measure_padding_y then
            local text_size = measure_font_text(font_index, measure_text_value)
            local measured_width = text_size.x
            if use_glyph_render == true and cached_width > 0 then
                measured_width = cached_width
            end

            state.text_size_x = measured_width + measure_padding_x * 2
            state.text_size_y = text_size.y + measure_padding_y * 2
            state.last_measure_padding_x = measure_padding_x
            state.last_measure_padding_y = measure_padding_y
            state.last_measure_use_glyph_render = use_glyph_render
            state.last_measure_cached_width = cached_width
            profile_render_cache.glyph_base_height = text_size.y
        end

        local screen = render.screen_size()
        ensure_position_initialized(screen)
        clamp_position_to_screen(screen)
        update_bounds()

        if ui.get_alpha() > 0 then
            if state.dragging == true then
                render_snap_visuals(screen)
            end
        end

        local draw_position = vector(state.position_x, state.position_y)
        if use_glyph_render == true then
            draw_cached_glyph_entries(font_index, draw_position)
            return
        end

        render.text(
            font_index,
            draw_position,
            color(255, 255, 255, 255),
            "c",
            render_text
        )
    end

    update_callback_state = function()
        local enabled = current_name ~= ""
        if state.callbacks_registered == enabled then
            return
        end

        events.mouse_input(on_mouse_input, enabled)
        events.render(on_render, enabled)
        state.callbacks_registered = enabled

        if enabled == true then
            return
        end

        state.hovered = false
        state.dragging = false
        state.active_snap_x = false
        state.active_snap_y = false
        state.was_left_down = false
        state.was_right_down = false
    end

    function watermark.get_name()
        return current_name
    end

    function watermark.set_name(value)
        apply_name_value(value)
    end

    local function clone_profile_definition(profile_definition)
        local clone = {
            font = DEFAULT_FONT,
            custom_font = nil,
            segments = {
            },
        }

        if type(profile_definition) ~= "table" then
            return clone
        end

        if type(profile_definition.font) == "number" then
            clone.font = clamp_font_index(profile_definition.font)
        end

        if type(profile_definition.custom_font) == "table" then
            clone.custom_font = clone_custom_font_settings(profile_definition.custom_font)
        end

        local source_segments = profile_definition.segments
        if type(source_segments) ~= "table" then
            return clone
        end

        for i = 1, #source_segments do
            local source_segment = source_segments[i]
            if type(source_segment) == "table" then
                clone.segments[#clone.segments + 1] = {
                    text = tostring(source_segment.text or ""),
                    mode = normalize_segment_mode(source_segment.mode),
                    style = get_segment_style_key(source_segment),
                    animation = get_segment_animation_key(source_segment),
                    channel = get_segment_animation_channel(source_segment),
                    repeat_mode = get_segment_animation_repeat(source_segment),
                    direction = get_segment_animation_direction(source_segment),
                    reverse = get_segment_animation_reverse(source_segment),
                    shape = get_segment_animation_shape(source_segment),
                    color = normalize_hex_color(source_segment.color),
                    from = normalize_hex_color(source_segment.from),
                    to = normalize_hex_color(source_segment.to),
                    min = read_number(source_segment.min, 0.3, 0.0, 1.0),
                    max = read_number(source_segment.max, 1.0, 0.0, 1.0),
                    speed = read_number(source_segment.speed, 2.0, 0.01, 20.0),
                    waves = read_number(source_segment.waves, 1.0, 0.1, 10.0),
                    animation_span = read_number(source_segment.animation_span, 1.0, 0.1, 10.0),
                    saturation = read_number(source_segment.saturation, 1.0, 0.0, 1.0),
                    value = read_number(source_segment.value, 1.0, 0.0, 1.0),
                    glyph_animation = get_segment_glyph_animation_key(source_segment),
                    glyph_glitch = get_segment_glyph_glitch_enabled(source_segment),
                    glyph_amount = read_number(source_segment.glyph_amount, 4.0, 0.0, 24.0),
                    glyph_speed = read_number(source_segment.glyph_speed, 3.0, 0.01, 20.0),
                    glyph_span = read_number(source_segment.glyph_span, 1.0, 0.1, 10.0),
                }
            end
        end

        return clone
    end

    local function build_segment_definition(segment)
        if type(segment) ~= "table" then
            return nil
        end

        return {
            text = tostring(segment.text or ""),
            mode = normalize_segment_mode(segment.mode),
            style = get_segment_style_key(segment),
            animation = get_segment_animation_key(segment),
            channel = get_segment_animation_channel(segment),
            repeat_mode = get_segment_animation_repeat(segment),
            direction = get_segment_animation_direction(segment),
            reverse = get_segment_animation_reverse(segment),
            shape = get_segment_animation_shape(segment),
            color = normalize_hex_color(segment.color_hex),
            from = normalize_hex_color(segment.from_hex),
            to = normalize_hex_color(segment.to_hex),
            min = read_number(segment.wave_min, 0.3, 0.0, 1.0),
            max = read_number(segment.wave_max, 1.0, 0.0, 1.0),
            speed = read_number(segment.wave_speed, 2.0, 0.01, 20.0),
            waves = read_number(segment.wave_count, 1.0, 0.1, 10.0),
            animation_span = read_number(segment.animation_span, 1.0, 0.1, 10.0),
            saturation = read_number(segment.saturation, 1.0, 0.0, 1.0),
            value = read_number(segment.value_level, 1.0, 0.0, 1.0),
            glyph_animation = get_segment_glyph_animation_key(segment),
            glyph_glitch = get_segment_glyph_glitch_enabled(segment),
            glyph_amount = read_number(segment.glyph_amount, 4.0, 0.0, 24.0),
            glyph_speed = read_number(segment.glyph_speed, 3.0, 0.01, 20.0),
            glyph_span = read_number(segment.glyph_span, 1.0, 0.1, 10.0),
        }
    end

    build_current_profile_definition = function()
        local profile_definition = {
            font = clamp_font_index(state.font_index),
            custom_font = nil,
            segments = {
            },
        }

        if type(state.api_profile) == "table" then
            if type(state.api_profile.font) == "number" then
                profile_definition.font = clamp_font_index(state.api_profile.font)
            end

            if type(state.api_profile.custom_font) == "table" then
                profile_definition.custom_font = clone_custom_font_settings(state.api_profile.custom_font)
            end

            local source_segments = state.api_profile.segments
            if type(source_segments) == "table" then
                for i = 1, #source_segments do
                    local definition = build_segment_definition(source_segments[i])
                    if definition ~= nil then
                        profile_definition.segments[#profile_definition.segments + 1] = definition
                    end
                end
            end
        end

        if #profile_definition.segments == 0
            and current_name ~= "" then
            local fallback_text = normalize_color_codes(current_name)
            if fallback_text == "" then
                fallback_text = DEFAULT_NAME
            end

            profile_definition.segments[1] = {
                text = fallback_text,
                mode = "static",
                style = "solid",
                animation = "off",
                channel = "color",
                repeat_mode = "loop",
                direction = "forward",
                reverse = false,
                shape = "soft",
                color = nil,
                from = nil,
                to = nil,
                min = 0.3,
                max = 1.0,
                speed = 2.0,
                waves = 1.0,
                animation_span = 1.0,
                saturation = 1.0,
                value = 1.0,
                glyph_animation = "off",
                glyph_glitch = false,
                glyph_amount = 4.0,
                glyph_speed = 3.0,
                glyph_span = 1.0,
            }
        end

        if profile_definition.custom_font == nil
            and profile_definition.font == CUSTOM_FONT then
            profile_definition.custom_font = clone_custom_font_settings(state.custom_font_settings)
        end

        return profile_definition
    end

    build_profile_input = function(profile_definition)
        local normalized = clone_profile_definition(profile_definition)
        if #normalized.segments == 0 then
            return ""
        end

        local raw_profile = {
            font = clamp_font_index(normalized.font),
            segments = {
            },
        }

        if type(normalized.custom_font) == "table" then
            raw_profile.custom_font = {
                face = normalized.custom_font.face,
                size = normalized.custom_font.size,
                spacing = normalized.custom_font.spacing,
                weight = normalized.custom_font.weight,
                italic = normalized.custom_font.italic,
                underline = normalized.custom_font.underline,
                strike_out = normalized.custom_font.strike_out,
                shadow = normalized.custom_font.shadow,
                outline = normalized.custom_font.outline,
                quality = normalized.custom_font.quality,
            }
        end

        for i = 1, #normalized.segments do
            local segment = normalized.segments[i]
            local raw_segment = {
                text = tostring(segment.text or ""),
            }

            local style = get_segment_style_key(segment)
            local animation = get_segment_animation_key(segment)
            local channel = get_segment_animation_channel(segment)
            local repeat_mode = get_segment_animation_repeat(segment)
            local direction = get_segment_animation_direction(segment)
            local reverse = get_segment_animation_reverse(segment)
            local shape = get_segment_animation_shape(segment)

            raw_segment.style = style
            raw_segment.animation = animation
            raw_segment.channel = channel
            raw_segment.playback = repeat_mode
            raw_segment.direction = direction
            raw_segment.shape = shape
            if reverse == true then
                raw_segment.reverse = true
            end

            local mode = "static"
            if style == "gradient" then
                mode = "gradient"
                if animation == "wave" then
                    mode = "gradient_wave"
                elseif animation == "centered" then
                    mode = "gradient_centered"
                elseif animation == "pulse" and channel == "alpha" then
                    mode = "gradient_pulse"
                end
            elseif style == "rainbow" then
                mode = "rainbow"
                if animation == "wave" then
                    mode = "rainbow_wave"
                elseif animation == "centered" then
                    mode = "rainbow_centered"
                elseif animation == "pulse" and channel == "alpha" then
                    mode = "rainbow_pulse"
                end
            elseif animation == "wave" then
                mode = "wave"
            elseif animation == "centered" then
                mode = "centered"
            elseif animation == "pulse" and channel == "alpha" then
                mode = "pulse"
            end

            if mode ~= "static" then
                raw_segment.mode = mode
            end

            if segment.color ~= nil
                and (
                    style == "solid"
                    or style == "rainbow"
                ) then
                raw_segment.color = segment.color
            end

            if segment.from ~= nil then
                raw_segment.from = segment.from
            end

            if segment.to ~= nil then
                raw_segment.to = segment.to
            end

            if animation ~= "off" then
                raw_segment.speed = read_number(segment.speed, 2.0, 0.01, 20.0)
                raw_segment.min = read_number(segment.min, 0.3, 0.0, 1.0)
                raw_segment.max = read_number(segment.max, 1.0, 0.0, 1.0)
            end

            if animation == "wave"
                or animation == "sweep"
                or animation == "centered"
                or animation == "shift" then
                raw_segment.animation_span = read_number(segment.animation_span, 1.0, 0.1, 10.0)
            end

            if mode == "wave" then
                raw_segment.waves = read_number(segment.animation_span, 1.0, 0.1, 10.0)
            end

            if style == "rainbow" then
                raw_segment.waves = read_number(segment.waves, 1.0, 0.1, 10.0)
                raw_segment.saturation = read_number(segment.saturation, 1.0, 0.0, 1.0)
                raw_segment.value = read_number(segment.value, 1.0, 0.0, 1.0)
            end

            local glyph_animation = get_segment_glyph_animation_key(segment)
            if glyph_animation ~= "off" then
                raw_segment.glyph_animation = glyph_animation
            end

            if get_segment_glyph_glitch_enabled(segment) == true then
                raw_segment.glyph_glitch = true
            end

            if glyph_animation ~= "off"
                or get_segment_glyph_glitch_enabled(segment) == true then
                raw_segment.glyph_amount = read_number(segment.glyph_amount, 4.0, 0.0, 24.0)
                raw_segment.glyph_speed = read_number(segment.glyph_speed, 3.0, 0.01, 20.0)
                raw_segment.glyph_span = read_number(segment.glyph_span, 1.0, 0.1, 10.0)
            end

            raw_profile.segments[#raw_profile.segments + 1] = raw_segment
        end

        local ok_json, payload = pcall(json.stringify, raw_profile)
        if not ok_json or type(payload) ~= "string" or payload == "" then
            return nil
        end

        return API_PREFIX_LONG .. payload
    end

    function watermark.get_profile_definition()
        return clone_profile_definition(build_current_profile_definition())
    end

    function watermark.normalize_segment_mode(value)
        return normalize_segment_mode(value)
    end

    function watermark.get_segment_style_key(value)
        return get_segment_style_key(value)
    end

    function watermark.get_segment_animation_key(value)
        return get_segment_animation_key(value)
    end

    function watermark.get_segment_animation_channel(value)
        return get_segment_animation_channel(value)
    end

    function watermark.get_segment_animation_repeat(value)
        return get_segment_animation_repeat(value)
    end

    function watermark.get_segment_animation_direction(value)
        return get_segment_animation_direction(value)
    end

    function watermark.get_segment_animation_reverse(value)
        return get_segment_animation_reverse(value)
    end

    function watermark.get_segment_animation_shape(value)
        return get_segment_animation_shape(value)
    end

    function watermark.get_segment_glyph_animation_key(value)
        return get_segment_glyph_animation_key(value)
    end

    function watermark.get_segment_glyph_glitch_enabled(value)
        return get_segment_glyph_glitch_enabled(value)
    end

    function watermark.export_profile_string()
        return build_profile_input(build_current_profile_definition())
    end

    function watermark.import_profile_string(value)
        if type(value) ~= "string" then
            return false
        end

        if value == "" then
            watermark.set_name("")
            return true
        end

        if parse_profile_from_input(value) == nil then
            return false
        end

        watermark.set_name(value)
        return true
    end

    function watermark.apply_profile_definition(profile_definition)
        local serialized = build_profile_input(profile_definition)
        if serialized == nil then
            return nil
        end

        watermark.set_name(serialized)
        return serialized
    end

    function watermark.get_default_position()
        return get_default_position_for_screen(render.screen_size())
    end

    function watermark.get_position_x()
        local screen = render.screen_size()
        ensure_position_initialized(screen)
        return state.position_x
    end

    function watermark.get_position_y()
        local screen = render.screen_size()
        ensure_position_initialized(screen)
        return state.position_y
    end

    function watermark.get_font()
        return get_active_font_index()
    end

    function watermark.get_custom_font_settings(profile_definition)
        if type(profile_definition) == "table"
            and type(profile_definition.custom_font) == "table" then
            return clone_custom_font_settings(profile_definition.custom_font)
        end

        return clone_custom_font_settings(state.custom_font_settings)
    end

    function watermark.hex_to_color(value)
        return hex_to_color(value)
    end

    function watermark.color_to_hex(value)
        if value == nil then
            return nil
        end

        return rgba_to_hex(
            value.r or 255,
            value.g or 255,
            value.b or 255,
            value.a or 255
        )
    end

    function watermark.bind_config_refs(text_ref, position_x_ref, position_y_ref, font_ref)
        config_refs.text = text_ref
        config_refs.position_x = position_x_ref
        config_refs.position_y = position_y_ref
        config_refs.font = font_ref
    end

    function watermark.consume_bound_text_ref_value(value)
        if pending_text_config_value == nil then
            return false
        end

        if pending_text_config_value ~= value then
            pending_text_config_value = nil
            return false
        end

        pending_text_config_value = nil
        return true
    end

    function watermark.set_position_x(value)
        if type(value) ~= "number" then
            return
        end

        state.position_x = value
    end

    function watermark.set_position_y(value)
        if type(value) ~= "number" then
            return
        end

        state.position_y = value
    end

    function watermark.set_font(value)
        state.font_index = clamp_font_index(value)

        if type(state.api_profile) == "table" then
            state.api_profile.font = state.font_index
            if state.font_index == CUSTOM_FONT
                and type(state.api_profile.custom_font) ~= "table" then
                state.api_profile.custom_font = clone_custom_font_settings(state.custom_font_settings)
            end
        end

        sync_text_config_ref()
    end

    function watermark.set_hover_font_cycle_enabled(value)
        state.hover_font_cycle_enabled = value == true
    end

    update_callback_state()
end

local icons
do
    icons = {
    }

    local icon_cache = {
    }
    local space_cache = {
        [0] = "",
    }

    local function make_icon_padding(width)
        if type(width) ~= "number" then
            return ""
        end

        if width <= 0 then
            return ""
        end

        local full_width = math.floor(width)
        local has_half = width - full_width >= 0.5
        local cache_key = tostring(full_width) .. ":" .. tostring(has_half)
        local cached = space_cache[cache_key]
        if cached ~= nil then
            return cached
        end

        local padding = ""
        if full_width > 0 then
            padding = string.rep(" ", full_width)
        end

        if has_half then
            padding = padding .. HSP
        end

        space_cache[cache_key] = padding
        return padding
    end

    local function color_prefix(color)
        if color == nil then
            return ""
        end

        if color == "" then
            return ""
        end

        local a = color:sub(1, 2)
        if a == "\a" then
            return color
        end

        return "\a" .. color
    end

    function icons.get(name, left, right, color)
        if name == nil then
            return "\aDEFAULT"
        end

        if name == "" then
            return "\aDEFAULT"
        end

        local icon = icon_cache[name]
        if icon == nil then
            icon = ui.get_icon(name)
            icon_cache[name] = icon
        end

        if left == nil then
            left = 0
        end

        if right == nil then
            right = 0
        end

        local lsp = make_icon_padding(left)
        local rsp = make_icon_padding(right)

        return color_prefix(color) .. lsp .. icon .. rsp .. "\aDEFAULT"
    end
end

icons.menu_icon_animations = {
    items = {
    },
    active_items = {
    },
    animation_speed_ref = nil,
    callback_registered = false,
    active_item_types = {
        switch = true,
        combo = true,
        selectable = true,
        listable = true,
        slider = true,
    },
    disabled_combo_values = {
        Off = true,
        Disabled = true,
        None = true,
    },
}

function icons.menu_icon_animations.get_animation_speed()
    if icons.menu_icon_animations.animation_speed_ref == nil then
        local ok_ref, ref = pcall(ui.find, "Settings", "Animation Speed")
        if ok_ref and ref ~= nil then
            icons.menu_icon_animations.animation_speed_ref = ref
        else
            icons.menu_icon_animations.animation_speed_ref = false
        end
    end

    local ref = icons.menu_icon_animations.animation_speed_ref
    if ref == false then
        return 1
    end

    local ok_value, value = pcall(ref.get, ref)
    if ok_value and type(value) == "number" and value > 0 then
        return value
    end

    return 1
end

function icons.menu_icon_animations.parse_name(name)
    if type(name) ~= "string" then
        return nil
    end

    if name:sub(1, 2) ~= "\a" then
        return nil
    end

    local color_end = nil
    if name:sub(3, 3) == "{" then
        color_end = name:find("}", 4, true)
    else
        local color_token = name:match("^\a([A-Za-z0-9_]+)")
        if color_token ~= nil then
            color_end = 2 + #color_token
        end
    end

    if color_end == nil then
        return nil
    end

    local icon_end = name:find("\aDEFAULT", color_end + 1, true)
    if icon_end == nil then
        return nil
    end

    local icon_body = name:sub(color_end + 1, icon_end - 1)
    if icon_body == "" then
        return nil
    end

    return {
        icon_body = icon_body,
        tail = name:sub(icon_end + #"\aDEFAULT"),
    }
end

function icons.menu_icon_animations.get_icon_color_hex(progress)
    local inactive = ui.get_style("Small Text")
    local active = ui.get_style("Link Active")
    if inactive == nil or active == nil then
        return nil
    end

    return inactive:lerp(active, progress):to_hex()
end

function icons.menu_icon_animations.build_name(parts, progress)
    if parts == nil then
        return nil
    end

    local color_hex = icons.menu_icon_animations.get_icon_color_hex(progress)
    if type(color_hex) ~= "string" then
        return nil
    end

    return "\a" .. color_hex .. parts.icon_body .. "\aDEFAULT" .. parts.tail
end

function icons.menu_icon_animations.refresh_parts(state)
    local ok_name, current_name = pcall(state.item.name, state.item)
    if not ok_name or type(current_name) ~= "string" then
        return false
    end

    if current_name == state.last_applied_name then
        return state.parts ~= nil
    end

    state.parts = icons.menu_icon_animations.parse_name(current_name)
    return state.parts ~= nil
end

function icons.menu_icon_animations.apply_name(state, progress)
    if icons.menu_icon_animations.refresh_parts(state) ~= true then
        return false
    end

    local name = icons.menu_icon_animations.build_name(state.parts, progress)
    if type(name) ~= "string" then
        return false
    end

    state.last_applied_name = name
    pcall(state.item.name, state.item, name)
    return true
end

function icons.menu_icon_animations.resolve_active_value(item_type, value)
    if item_type == "combo" then
        return (
            type(value) == "string"
            and icons.menu_icon_animations.disabled_combo_values[value] ~= true
        )
    end

    if item_type == "selectable" or item_type == "listable" then
        return type(value) == "table" and next(value) ~= nil
    end

    if item_type == "slider" then
        return type(value) == "number" and value ~= 0
    end

    if type(value) == "boolean" then
        return value
    end

    if type(value) == "number" then
        return value ~= 0
    end

    if type(value) == "string" then
        return (
            value ~= ""
            and icons.menu_icon_animations.disabled_combo_values[value] ~= true
        )
    end

    if type(value) == "table" then
        return next(value) ~= nil
    end

    return false
end

function icons.menu_icon_animations.get_target_progress(state)
    local ok_value, value = pcall(state.item.get, state.item)
    if not ok_value then
        return 0
    end

    if icons.menu_icon_animations.resolve_active_value(state.item_type, value) == true then
        return 1
    end

    return 0
end

function icons.menu_icon_animations.update_render_state(enabled)
    if icons.menu_icon_animations.callback_registered == enabled then
        return
    end

    events.render(icons.menu_icon_animations.on_render, enabled)
    icons.menu_icon_animations.callback_registered = enabled
end

function icons.menu_icon_animations.mark_active(state)
    if state.is_animating == true then
        return
    end

    state.is_animating = true
    icons.menu_icon_animations.active_items[#icons.menu_icon_animations.active_items + 1] = state
    icons.menu_icon_animations.update_render_state(true)
end

function icons.menu_icon_animations.on_render()
    local speed = icons.menu_icon_animations.get_animation_speed()
    local step = math.min(1, globals.frametime * 14 * speed)
    local active_items = icons.menu_icon_animations.active_items

    for index = #active_items, 1, -1 do
        local state = active_items[index]
        if state == nil then
            table.remove(active_items, index)
        else
            state.progress = state.progress + (state.target - state.progress) * step
            if math.abs(state.target - state.progress) <= 0.001 then
                state.progress = state.target
            end

            icons.menu_icon_animations.apply_name(state, state.progress)

            if state.progress == state.target then
                state.is_animating = false
                table.remove(active_items, index)
            end
        end
    end

    if #active_items == 0 then
        icons.menu_icon_animations.update_render_state(false)
    end
end

function icons.menu_icon_animations.track_item(item, item_type)
    if item == nil or icons.menu_icon_animations.active_item_types[item_type] ~= true then
        return
    end

    if icons.menu_icon_animations.items[item] ~= nil then
        return
    end

    local ok_name, raw_name = pcall(item.name, item)
    if not ok_name or type(raw_name) ~= "string" then
        return
    end

    local parts = icons.menu_icon_animations.parse_name(raw_name)
    if parts == nil then
        return
    end

    local state = {
        item = item,
        item_type = item_type,
        parts = parts,
        progress = 0,
        target = 0,
        is_animating = false,
        last_applied_name = nil,
    }
    icons.menu_icon_animations.items[item] = state

    local function on_change()
        state.target = icons.menu_icon_animations.get_target_progress(state)

        if icons.menu_icon_animations.refresh_parts(state) ~= true then
            return
        end

        if state.progress == state.target then
            icons.menu_icon_animations.apply_name(state, state.progress)
            return
        end

        icons.menu_icon_animations.mark_active(state)
    end

    state.target = icons.menu_icon_animations.get_target_progress(state)
    state.progress = state.target
    icons.menu_icon_animations.apply_name(state, state.progress)
    pcall(item.set_callback, item, on_change)
end

