    local BINDS_KEY = "__aesthetic_binds"
    local RAW_KEY = "__aesthetic_raw"
    local STORAGE_PREFIX = "aesthetic-new:"
    local LEGACY_STORAGE_PREFIX = "aesthetic_cfg:"
    local DB_STORAGE_KEY = "aesthetic_cfg_store"
    local LEGACY_PURGED_KEY = "aesthetic_cfg_legacy_purged_v1"

    config = {
        _items = {
        },
    }

    if type(db) ~= "table" then
        db = {
        }
    end

    if db[LEGACY_PURGED_KEY] ~= true then
        local legacy_list = db.config_list
        if type(legacy_list) == "table" then
            for _, legacy_name in ipairs(legacy_list) do
                if type(legacy_name) == "string" and legacy_name ~= "" then
                    db[legacy_name] = nil
                end
            end
        end

        db.config_list = nil
        db.config_meta = nil
        db[LEGACY_PURGED_KEY] = true
    end

    local store = db[DB_STORAGE_KEY]
    if type(store) ~= "table" then
        store = {
        }
    end

    if type(store.configs) ~= "table" then
        store.configs = {
        }
    end

    if type(store.list) ~= "table" then
        store.list = {
        }
    end

    if type(store.meta) ~= "table" then
        store.meta = {
        }
    end

    local config_list_ref = nil
    local config_name_ref = nil

    local function persist_store()
        db[DB_STORAGE_KEY] = store
    end

    local function contains(list, value)
        for _, current in ipairs(list) do
            if current == value then
                return true
            end
        end

        return false
    end

    local function ensure_meta()
        return store.meta
    end

    local function ensure_list()
        local list = store.list
        if type(list) ~= "table" then
            list = {
            }
        end

        local valid = {
        }
        for _, name in ipairs(list) do
            local is_valid_name = type(name) == "string"
            local payload = store.configs[name]
            local has_payload = type(payload) == "string" and payload ~= ""
            if is_valid_name then
                if has_payload then
                    valid[#valid + 1] = name
                end
            end
        end

        return valid
    end

    local function set_current_config(name)
        if config_name_ref == nil then
            return
        end

        if config_list_ref == nil then
            return
        end

        config_name_ref:set(name)

        local list = config_list_ref:list()
        if type(list) ~= "table" then
            return
        end

        for index, value in ipairs(list) do
            if value == name then
                config_list_ref:set(index)
                return
            end
        end
    end

    local function get_color_value(item)
        local result = {
        }
        local modes = item:list()
        if type(modes) ~= "table" then
            local col = item:get()
            result.default = {
                {
                    r = col.r,
                    g = col.g,
                    b = col.b,
                    a = col.a,
                },
            }

            return result
        end

        if #modes == 0 then
            local col = item:get()
            result.default = {
                {
                    r = col.r,
                    g = col.g,
                    b = col.b,
                    a = col.a,
                },
            }

            return result
        end

        for _, mode in ipairs(modes) do
            local ok, colors = pcall(item.get, item, mode)
            if ok then
                if type(colors) == "table" then
                    result[mode] = {
                    }
                    for i, color_item in ipairs(colors) do
                        result[mode][i] = {
                            r = color_item.r,
                            g = color_item.g,
                            b = color_item.b,
                            a = color_item.a,
                        }
                    end
                end
            end
        end

        return result
    end

    local function set_color_value(item, value)
        if type(value) ~= "table" then
            return
        end

        for mode, list in pairs(value) do
            if type(list) == "table" then
                local converted = {
                }
                for i, color_item in ipairs(list) do
                    if type(color_item) == "table" then
                        converted[i] = color(
                            color_item.r or 0,
                            color_item.g or 0,
                            color_item.b or 0,
                            color_item.a or 255
                        )
                    end
                end
                item:set(mode, converted)
            end
        end
    end

    local function read_item_key(item)
        local ok, value = pcall(item.key, item)
        if not ok then
            return nil
        end

        if type(value) ~= "number" then
            return nil
        end

        if value == 0 then
            return nil
        end

        return value
    end

    local function append_bind_snapshot(snapshot, bind_list)
        if type(bind_list) ~= "table" then
            return
        end

        for _, bind_data in pairs(bind_list) do
            if type(bind_data) == "table" then
                local ref = bind_data.reference
                if ref ~= nil then
                    snapshot[ref] = {
                        mode = bind_data.mode,
                        value = bind_data.value,
                    }
                end
            end
        end
    end

    local function collect_bind_snapshot()
        local snapshot = {
        }

        local ok_list, bind_list = pcall(ui.get_binds)
        if ok_list then
            append_bind_snapshot(snapshot, bind_list)
        end

        local ok_all, bind_list_all = pcall(ui.get_binds, true)
        if ok_all then
            append_bind_snapshot(snapshot, bind_list_all)
        end

        return snapshot
    end

    local function get_item_bind(item, bind_snapshot)
        local key = read_item_key(item)

        local mode = nil
        local value = nil

        local bind_data = bind_snapshot[item]
        if type(bind_data) == "table" then
            mode = bind_data.mode
            value = bind_data.value
        end

        if key == nil then
            if mode == nil then
                if value == nil then
                    return nil
                end
            end
        end

        return {
            key = key,
            mode = mode,
            value = value,
        }
    end

    local function apply_item_bind(item, bind_data)
        if type(bind_data) ~= "table" then
            return
        end

        local key = bind_data.key
        if key == nil then
            if type(bind_data.value) == "number" then
                key = bind_data.value
            end
        end

        if key == nil then
            return
        end

        if bind_data.mode ~= nil then
            if pcall(item.key, item, key, bind_data.mode) then
                return
            end

            if pcall(item.key, item, bind_data.mode, key) then
                return
            end
        end

        pcall(item.key, item, key)
    end

    local handlers = {
        color_picker = {
            get = get_color_value,
            set = set_color_value,
        },
        hotkey = {
            get = function(item)
                local ok, value = pcall(item.key, item)
                if ok then
                    return value
                end

                return item:get()
            end,
            set = function(item, value)
                local ok = pcall(item.key, item, value)
                if ok then
                    return
                end

                item:set(value)
            end,
        },
        default = {
            get = function(item)
                return item:get()
            end,
            set = function(item, value)
                item:set(value)
            end,
        },
    }

    local function encode_packed_storage(data)
        return storage_codec.encode(data)
    end

    local function decode_packed_storage(payload)
        return storage_codec.decode(payload)
    end

    local function decode_plain_json_storage(payload)
        if type(payload) ~= "string" or payload == "" then
            return nil
        end

        local ok_json, data = pcall(json.parse, payload)
        if not ok_json or type(data) ~= "table" then
            return nil
        end

        return data
    end

    local function encode_storage(data)
        local packed = encode_packed_storage(data)
        if packed == nil then
            return nil
        end

        return STORAGE_PREFIX .. packed
    end

    local function decode_storage(payload)
        if type(payload) ~= "string" then
            return nil
        end

        if payload == "" then
            return nil
        end

        local clean = payload
        if payload:sub(1, #STORAGE_PREFIX) == STORAGE_PREFIX then
            clean = payload:sub(#STORAGE_PREFIX + 1)
            if clean == "" then
                return nil
            end

            return decode_packed_storage(clean)
        end

        if payload:sub(1, #LEGACY_STORAGE_PREFIX) == LEGACY_STORAGE_PREFIX then
            clean = payload:sub(#LEGACY_STORAGE_PREFIX + 1)
        end

        if clean == "" then
            return nil
        end

        local data = decode_packed_storage(clean)
        if data ~= nil then
            return data
        end

        return decode_plain_json_storage(clean)
    end

    local function serialize()
        local data = {
        }
        local binds = {
        }
        local raw_items = {
        }
        local bind_snapshot = collect_bind_snapshot()

        for _, item in ipairs(config._items) do
            local ok_value, value = pcall(item.get)
            if ok_value then
                data[item.id] = value
            end

            local ok_export, raw_value = pcall(item.ref.export, item.ref)
            if ok_export and raw_value ~= nil then
                raw_items[item.id] = raw_value
            end

            local bind_data = get_item_bind(item.ref, bind_snapshot)
            if bind_data ~= nil then
                binds[item.id] = bind_data
            end
        end

        if next(raw_items) ~= nil then
            data[RAW_KEY] = raw_items
        end

        if next(binds) ~= nil then
            data[BINDS_KEY] = binds
        end

        return data
    end

    function config.bind_controls(list_ref, name_ref)
        config_list_ref = list_ref
        config_name_ref = name_ref
    end

    local SOUND_DISABLED_ITEM_IDS = {
        angles_hotkeys_freestanding_switch = true,
        angles_hotkeys_manual_direction = true,
        main_rage_dormant_aimbot = true,
        main_misc_edge_stop = true,
        main_home_watermark_text = true,
        main_home_watermark_position_x = true,
        main_home_watermark_position_y = true,
        main_home_watermark_font = true,
    }

    local function item_has_bind(reference)
        if reference == nil then
            return false
        end

        local reference_id = nil
        local ok_reference_id, id_value = pcall(reference.id, reference)
        if ok_reference_id then
            reference_id = id_value
        end

        local ok_binds, binds = pcall(ui.get_binds, true)
        if not ok_binds or type(binds) ~= "table" then
            return false
        end

        for i = 1, #binds do
            local bind_data = binds[i]
            if type(bind_data) == "table" then
                local bind_reference = bind_data.reference
                if bind_reference ~= nil then
                    local is_same = bind_reference == reference
                    if not is_same and reference_id ~= nil then
                        local ok_bind_id, bind_id = pcall(bind_reference.id, bind_reference)
                        if ok_bind_id and bind_id == reference_id then
                            is_same = true
                        end
                    end

                    if is_same then
                        return true
                    end
                end
            end
        end

        return false
    end

    local function attach_interaction_sound(item, item_type, item_id)
        if type(item_id) == "string" and SOUND_DISABLED_ITEM_IDS[item_id] == true then
            return
        end

        local sound_path = sounds.press
        if item_type == "slider" then
            sound_path = sounds.scroll
        end

        local has_last_value = false
        local last_value = nil

        local function on_change()
            local ok_current, current_value = pcall(item.get, item)
            if not ok_current then
                sounds.play(sound_path)
                return
            end

            if not has_last_value then
                has_last_value = true
                last_value = current_value
                sounds.play(sound_path)
                return
            end

            if current_value == last_value then
                return
            end

            last_value = current_value

            if ui.get_alpha() <= 0 and item_has_bind(item) then
                return
            end

            sounds.play(sound_path)
        end

        pcall(item.set_callback, item, on_change)
    end

    function config.push(item, key_override)
        local item_type = item:type()
        local handler = handlers[item_type]
        if handler == nil then
            handler = handlers.default
        end

        icons.menu_icon_animations.track_item(item, item_type)

        local key = key_override
        if key == nil then
            local ok, name = pcall(item.name, item)
            if ok then
                if type(name) == "string" then
                    key = name
                end
            end
        end

        if key == "" then
            local ok, name = pcall(item.name, item)
            if ok then
                if type(name) == "string" then
                    key = name
                end
            end
        end

        attach_interaction_sound(item, item_type, key)

        if key == nil then
            return item
        end

        if key == "" then
            return item
        end

        config._items[#config._items + 1] = {
            id = key,
            ref = item,
            get = function()
                return handler.get(item)
            end,
            set = function(value)
                handler.set(item, value)
            end,
        }

        return item
    end

    function config.apply(data, options)
        if type(data) ~= "table" then
            return
        end

        local allow_raw = true
        local allow_binds = true
        if type(options) == "table" then
            if options.allow_raw == false then
                allow_raw = false
            end

            if options.allow_binds == false then
                allow_binds = false
            end
        end

        local binds = data[BINDS_KEY]
        local raw_items = data[RAW_KEY]
        local has_binds = allow_binds and type(binds) == "table"
        local has_raw_items = allow_raw and type(raw_items) == "table"

        for _, item in ipairs(config._items) do
            local imported = false
            if has_raw_items then
                local raw_value = raw_items[item.id]
                if raw_value ~= nil then
                    imported = pcall(item.ref.import, item.ref, raw_value)
                end
            end

            if not imported then
                local value = data[item.id]
                if value ~= nil then
                    pcall(item.set, value)
                end
            end

            if item.id == "angles_hotkeys_manual_left"
                or item.id == "angles_hotkeys_manual_forward"
                or item.id == "angles_hotkeys_manual_right" then
                local ok_key, key = pcall(item.ref.key, item.ref)
                if ok_key and type(key) == "number" and key ~= 0 then
                    if not pcall(item.ref.key, item.ref, key, 2) then
                        pcall(item.ref.key, item.ref, 2, key)
                    end
                end
            end

            if has_binds then
                local bind_data = binds[item.id]
                if bind_data ~= nil then
                    if item.id == "angles_hotkeys_manual_left"
                        or item.id == "angles_hotkeys_manual_forward"
                        or item.id == "angles_hotkeys_manual_right" then
                        if type(bind_data) == "table" then
                            bind_data.mode = 2
                        end
                    end
                    apply_item_bind(item.ref, bind_data)
                end
            end
        end
    end

    function config.update()
        store.list = ensure_list()
    end

    function config.save(name)
        if name == nil then
            name = ""
        end

        name = tostring(name)
        if name == "" then
            return prints.error("Config name cannot be empty!")
        end

        local payload = encode_storage(serialize())
        if payload == nil then
            return prints.error("Failed to encode config")
        end

        store.configs[name] = payload

        local meta = ensure_meta()
        if type(meta[name]) ~= "table" then
            meta[name] = {
            }
        end
        meta[name].created_ts = common.get_unixtime()

        local list = ensure_list()
        if not contains(list, name) then
            list[#list + 1] = name
        end
        store.list = list

        persist_store()

        set_current_config(name)
        prints.success("Saved: " .. name)
    end

    function config.load(name)
        if type(name) ~= "string" then
            return prints.error("Config not found: " .. tostring(name))
        end

        if name == "" then
            return prints.error("Config not found: " .. tostring(name))
        end

        local data = decode_storage(store.configs[name])
        if type(data) ~= "table" then
            return prints.error("Config not found: " .. tostring(name))
        end

        config.apply(data)
        prints.success("Loaded config: " .. name)
    end

    function config.remove(name)
        if type(name) ~= "string" then
            return prints.error("Config not found: " .. tostring(name))
        end

        if name == "" then
            return prints.error("Config not found: " .. tostring(name))
        end

        if store.configs[name] == nil then
            return prints.error("Config not found: " .. tostring(name))
        end

        store.configs[name] = nil

        local meta = ensure_meta()
        meta[name] = nil

        local list = ensure_list()
        local fallback = ""
        for i, value in ipairs(list) do
            if value == name then
                table.remove(list, i)
                fallback = list[i - 1]
                if type(fallback) ~= "string" then
                    fallback = list[1]
                end
                if type(fallback) ~= "string" then
                    fallback = ""
                end
                break
            end
        end
        store.list = list

        persist_store()

        set_current_config(fallback)
        prints.success("Removed config: " .. name)
    end

    function config.rename(old_name, new_name)
        if type(old_name) ~= "string" or old_name == "" then
            prints.error("Config not found: " .. tostring(old_name))
            return false
        end

        if type(new_name) ~= "string" or new_name == "" then
            prints.error("Config name cannot be empty!")
            return false
        end

        if old_name == new_name then
            return true
        end

        if type(store.configs[old_name]) ~= "string" then
            prints.error("Config not found: " .. tostring(old_name))
            return false
        end

        if type(store.configs[new_name]) == "string" then
            prints.error("Config already exists: " .. tostring(new_name))
            return false
        end

        store.configs[new_name] = store.configs[old_name]
        store.configs[old_name] = nil

        local meta = ensure_meta()
        if type(meta[old_name]) == "table" then
            meta[new_name] = meta[old_name]
            meta[old_name] = nil
        end

        local list = ensure_list()
        for index, value in ipairs(list) do
            if value == old_name then
                list[index] = new_name
                break
            end
        end
        store.list = list

        persist_store()

        set_current_config(new_name)
        prints.success("Renamed config: " .. old_name .. " -> " .. new_name)
        return true
    end

    function config.export()
        local packed = encode_storage(serialize())
        if packed == nil then
            return prints.error("Failed to encode config")
        end

        clipboard.set(packed)
        prints.success("Copied config to clipboard")
    end

    local function sanitize_import_text(raw)
        local clean = raw
            :gsub("\239\187\191", "")
            :gsub("\194\160", " ")
            :gsub("^%s+", "")
            :gsub("%s+$", "")

        return clean
    end

    local function decode_clipboard_storage(clean)
        local data = decode_storage(clean)
        if data ~= nil then
            return data
        end

        local normalized = clean
            :gsub("\0", "")
            :gsub("[\1-\8\11\12\14-\31]", "")
            :gsub("\226\128\139", "")
            :gsub("\226\128\140", "")
            :gsub("\226\128\141", "")
            :gsub("\226\128\142", "")
            :gsub("\226\128\143", "")

        if normalized ~= clean then
            data = decode_storage(normalized)
            if data ~= nil then
                return data
            end
        end

        local ascii_safe = normalized:gsub("[\128-\255]", "?")
        if ascii_safe ~= normalized then
            data = decode_storage(ascii_safe)
            if data ~= nil then
                return data
            end
        end

        return nil
    end

    local function parse_clipboard_data(show_errors)
        local raw = clipboard.get()
        if type(raw) ~= "string" then
            if show_errors then
                prints.error("Invalid or empty clipboard data")
            end

            return nil
        end

        if raw == "" then
            if show_errors then
                prints.error("Invalid or empty clipboard data")
            end

            return nil
        end

        local clean = sanitize_import_text(raw)
        if clean == "" then
            if show_errors then
                prints.error("Invalid or empty clipboard data")
            end

            return nil
        end

        local data = decode_clipboard_storage(clean)
        if data == nil then
            if show_errors then
                prints.error("Invalid or empty clipboard data")
            end

            return nil
        end

        return data
    end

    function config.read(name)
        if type(name) ~= "string" then
            return nil
        end

        if name == "" then
            return nil
        end

        return decode_storage(store.configs[name])
    end

    function config.get_list()
        return ensure_list()
    end

    function config.get_meta(name)
        if type(name) ~= "string" then
            return nil
        end

        local meta = ensure_meta()
        if type(meta[name]) ~= "table" then
            return nil
        end

        return meta[name]
    end

    local function get_scope_from_id(id)
        if type(id) ~= "string" then
            return nil
        end

        if id:find("^main_home_") then
            return "main_home"
        end

        if id:find("^angles_builder_") then
            return "angles_builder"
        end

        if id:find("^angles_hotkeys_") then
            return "angles_hotkeys"
        end

        if id:find("^angles_features_") then
            return "angles_features"
        end

        if id:find("^main_rage_") then
            return "main_rage"
        end

        if id:find("^main_visuals_") then
            return "main_visuals"
        end

        if id:find("^main_misc_") then
            return "main_misc"
        end

        return nil
    end

    local function copy_scoped_entries(source, target, selected_scopes)
        if type(source) ~= "table" then
            return false
        end

        local has_any = false
        for id, value in pairs(source) do
            local scope = get_scope_from_id(id)
            if scope ~= nil and selected_scopes[scope] then
                target[id] = value
                has_any = true
            end
        end

        return has_any
    end

    function config.filter_data(data, selected_scopes)
        if type(data) ~= "table" then
            return {
            }
        end

        if type(selected_scopes) ~= "table" then
            return data
        end

        local filtered = {
        }

        for id, value in pairs(data) do
            if id ~= RAW_KEY and id ~= BINDS_KEY then
                local scope = get_scope_from_id(id)
                if scope ~= nil and selected_scopes[scope] then
                    filtered[id] = value
                end
            end
        end

        if type(data[RAW_KEY]) == "table" then
            local filtered_raw = {
            }
            local has_raw = copy_scoped_entries(
                data[RAW_KEY],
                filtered_raw,
                selected_scopes
            )
            if has_raw then
                filtered[RAW_KEY] = filtered_raw
            end
        end

        if selected_scopes.global_binds then
            local binds = data[BINDS_KEY]
            if type(binds) == "table" then
                filtered[BINDS_KEY] = binds

                local source_raw = data[RAW_KEY]
                if type(source_raw) == "table" then
                    local target_raw = filtered[RAW_KEY]
                    if type(target_raw) ~= "table" then
                        target_raw = {
                        }
                        filtered[RAW_KEY] = target_raw
                    end

                    for id in pairs(binds) do
                        local raw_value = source_raw[id]
                        if raw_value ~= nil then
                            target_raw[id] = raw_value
                        end
                    end

                    if next(target_raw) == nil then
                        filtered[RAW_KEY] = nil
                    end
                end
            end
        end

        return filtered
    end

    function config.decode_clipboard()
        return parse_clipboard_data(true)
    end

    function config.import()
        local data = parse_clipboard_data(true)
        if data == nil then
            return
        end

        config.apply(data)
        prints.success("Config loaded from clipboard")
    end
end

local config_ui
do
    local gdi_font_api = storage_codec.gdi_font_api
    local CUSTOM_FONT = 5
