    local function on_watermark_console_input(text)
        if type(text) ~= "string" then
            return
        end

        local trimmed = text:match("^%s*(.-)%s*$")
        if trimmed == "watermark" then
            print_watermark_examples_to_console()
            return false
        end
    end

