    function watermark_builder:get_mode_label(segment)
        local segment_type = self:get_segment_type(segment)
        local animation = self:get_segment_animation_label(segment)
        local glyph_animation = self:get_segment_glyph_animation_label(segment)
        local label = segment_type

        if animation ~= "Off" then
            label = label .. " + " .. animation
            if self:get_segment_animation_effect_label(segment) == "Alpha" then
                label = label .. " Alpha"
            end
            if self:get_segment_animation_playback_label(segment) == "Ping-Pong" then
                label = label .. " Ping"
            end
            if self:get_segment_animation_reverse_label(segment) == "On" then
                label = label .. " Rev"
            end
        end

        if glyph_animation ~= "Off" then
            label = label .. " + " .. glyph_animation
        end
        if watermark.get_segment_glyph_glitch_enabled(segment) == true then
            label = label .. " + Glitch"
        end

        return label
    end

    function watermark_builder:get_segment_type(segment)
        local style = watermark.get_segment_style_key(segment)
        if style == "gradient" then
            return "Gradient"
        end

        if style == "rainbow" then
            return "Rainbow"
        end

        return "Solid"
    end

    function watermark_builder:get_segment_animation_label(segment)
        local animation = watermark.get_segment_animation_key(segment)
        if animation == "off" then
            return "Off"
        end
        if animation == "wave" then
            return "Wave"
        end
        if animation == "sweep" then
            return "Sweep"
        end
        if animation == "pulse" then
            return "Pulse"
        end
        if animation == "breath" then
            return "Breath"
        end
        if animation == "centered" then
            return "Centered"
        end

        return "Shift"
    end

    function watermark_builder:get_segment_animation_effect_label(segment)
        if watermark.get_segment_animation_channel(segment) == "alpha" then
            return "Alpha"
        end

        return "Color"
    end

    function watermark_builder:get_segment_animation_playback_label(segment)
        if watermark.get_segment_animation_repeat(segment) == "pingpong" then
            return "Ping-Pong"
        end

        return "Loop"
    end

    function watermark_builder:get_segment_animation_direction_label(segment)
        if watermark.get_segment_animation_direction(segment) == "reverse" then
            return "Reverse"
        end

        return "Forward"
    end

    function watermark_builder:get_segment_animation_reverse_label(segment)
        if watermark.get_segment_animation_reverse(segment) == true then
            return "On"
        end

        return "Off"
    end

    function watermark_builder:get_segment_animation_shape_label(segment)
        if watermark.get_segment_animation_shape(segment) == "sharp" then
            return "Sharp"
        end

        return "Soft"
    end

    function watermark_builder:get_segment_glyph_animation_label(segment)
        local animation = watermark.get_segment_glyph_animation_key(segment)
        if animation == "wave" then
            return "Wave"
        end
        if animation == "orbit" then
            return "Orbit"
        end
        if animation == "scatter" then
            return "Scatter"
        end
        if animation == "heart" then
            return "Heart"
        end

        return "Off"
    end

    function watermark_builder:get_segment_glyph_glitch_label(segment)
        if watermark.get_segment_glyph_glitch_enabled(segment) == true then
            return "On"
        end

        return "Off"
    end

    function watermark_builder:is_segment_animation_enabled(segment)
        return self:get_segment_animation_label(segment) ~= "Off"
    end

    function watermark_builder:uses_segment_animation_span(segment)
        local animation = self:get_segment_animation_label(segment)
        return animation == "Wave"
            or animation == "Sweep"
            or animation == "Centered"
            or animation == "Shift"
    end

    function watermark_builder:apply_segment_mode(segment, segment_type, animation_label, effect_label)
        if type(segment) ~= "table" then
            return
        end

        if segment_type == "Gradient" then
            segment.style = "gradient"
        elseif segment_type == "Rainbow" then
            segment.style = "rainbow"
        else
            segment.style = "solid"
        end

        if animation_label == "Wave" then
            segment.animation = "wave"
        elseif animation_label == "Sweep" then
            segment.animation = "sweep"
        elseif animation_label == "Pulse" then
            segment.animation = "pulse"
        elseif animation_label == "Breath" then
            segment.animation = "breath"
        elseif animation_label == "Centered" then
            segment.animation = "centered"
        elseif animation_label == "Shift" then
            segment.animation = "shift"
        else
            segment.animation = "off"
        end

        if effect_label == "Alpha" then
            segment.channel = "alpha"
        else
            segment.channel = "color"
        end

        if segment.style == "gradient" then
            segment.mode = "gradient"
            if segment.animation == "wave" then
                segment.mode = "gradient_wave"
            elseif segment.animation == "centered" then
                segment.mode = "gradient_centered"
            elseif segment.animation == "pulse" and segment.channel == "alpha" then
                segment.mode = "gradient_pulse"
            end
        elseif segment.style == "rainbow" then
            segment.mode = "rainbow"
            if segment.animation == "wave" then
                segment.mode = "rainbow_wave"
            elseif segment.animation == "centered" then
                segment.mode = "rainbow_centered"
            elseif segment.animation == "pulse" and segment.channel == "alpha" then
                segment.mode = "rainbow_pulse"
            end
        else
            segment.mode = "static"
            if segment.animation == "wave" then
                segment.mode = "wave"
            elseif segment.animation == "centered" then
                segment.mode = "centered"
            elseif segment.animation == "pulse" and segment.channel == "alpha" then
                segment.mode = "pulse"
            end
        end
    end

    function watermark_builder:apply_segment_type_defaults(segment, segment_type)
        if type(segment) ~= "table" then
            return
        end

        if segment_type == "Gradient" then
            local fallback_color = segment.color
            if fallback_color == nil then
                fallback_color = watermark.color_to_hex(self:get_style_color())
            end

            if segment.from == nil and segment.to == nil then
                segment.to = fallback_color
            else
                if segment.from == nil and segment.color ~= nil then
                    segment.from = fallback_color
                end
                if segment.to == nil and segment.color ~= nil then
                    segment.to = fallback_color
                end
            end
            segment.color = nil
            return
        end

        if segment_type == "Solid" then
            if segment.color == nil then
                segment.color = segment.from or segment.to
            end
        end
    end

    function watermark_builder:get_color_source_label(color_hex)
        if color_hex == nil then
            return "Accent"
        end

        return "Custom"
    end

    function watermark_builder:get_gradient_source_label(segment)
        if type(segment) ~= "table" then
            return "Accent -> Custom"
        end

        local use_start_accent = segment.from == nil
        local use_end_accent = segment.to == nil
        if use_start_accent == true and use_end_accent == true then
            return "Accent -> Custom"
        end

        if use_start_accent == true then
            return "Accent -> Custom"
        end

        if use_end_accent == true then
            return "Custom -> Accent"
        end

        return "Custom -> Custom"
    end

    function watermark_builder:make_default_segment(text)
        return {
            text = text or "Text",
            mode = "static",
            style = "solid",
            animation = "off",
            channel = "color",
            repeat_mode = "loop",
            direction = "forward",
            reverse = false,
            shape = "soft",
            color = nil,
            from = nil,
            to = nil,
            min = 0.3,
            max = 1.0,
            speed = 2.0,
            waves = 1.0,
            animation_span = 1.0,
            saturation = 1.0,
            value = 1.0,
            glyph_animation = "off",
            glyph_glitch = false,
            glyph_amount = 4.0,
            glyph_speed = 3.0,
            glyph_span = 1.0,
        }
    end

    function watermark_builder:clone_segment(segment)
        local clone = self:make_default_segment("")
        if type(segment) ~= "table" then
            return clone
        end

        clone.text = tostring(segment.text or "")
        clone.mode = watermark.normalize_segment_mode(segment.mode)
        clone.style = watermark.get_segment_style_key(segment) or clone.style
        clone.animation = watermark.get_segment_animation_key(segment) or clone.animation
        clone.channel = watermark.get_segment_animation_channel(segment) or clone.channel
        clone.repeat_mode = watermark.get_segment_animation_repeat(segment) or clone.repeat_mode
        clone.direction = watermark.get_segment_animation_direction(segment) or clone.direction
        clone.reverse = watermark.get_segment_animation_reverse(segment)
        clone.shape = watermark.get_segment_animation_shape(segment) or clone.shape
        clone.color = watermark.color_to_hex(watermark.hex_to_color(segment.color))
        clone.from = watermark.color_to_hex(watermark.hex_to_color(segment.from))
        clone.to = watermark.color_to_hex(watermark.hex_to_color(segment.to))

        if type(segment.min) == "number" then
            clone.min = segment.min
        end
        if type(segment.max) == "number" then
            clone.max = segment.max
        end
        if type(segment.speed) == "number" then
            clone.speed = segment.speed
        end
        if type(segment.waves) == "number" then
            clone.waves = segment.waves
        end
        if type(segment.animation_span) == "number" then
            clone.animation_span = segment.animation_span
        end
        if type(segment.saturation) == "number" then
            clone.saturation = segment.saturation
        end
        if type(segment.value) == "number" then
            clone.value = segment.value
        end
        clone.glyph_animation = watermark.get_segment_glyph_animation_key(segment)
        clone.glyph_glitch = watermark.get_segment_glyph_glitch_enabled(segment)
        if type(segment.glyph_amount) == "number" then
            clone.glyph_amount = segment.glyph_amount
        end
        if type(segment.glyph_speed) == "number" then
            clone.glyph_speed = segment.glyph_speed
        end
        if type(segment.glyph_span) == "number" then
            clone.glyph_span = segment.glyph_span
        end

        return clone
    end

    function watermark_builder:get_style_color()
        local style = ui.get_style()
        if type(style) == "table" and style["Link Active"] ~= nil then
            return style["Link Active"]
        end

        return color(255, 255, 255, 255)
    end

    function watermark_builder:get_picker_color(hex_value)
        local parsed = watermark.hex_to_color(hex_value)
        if parsed ~= nil then
            return parsed
        end

        return self:get_style_color()
    end

    function watermark_builder:normalize_slider_number(value, fallback, min_value, max_value)
        local number_value = value
        if type(number_value) ~= "number" then
            number_value = fallback
        end

        if number_value < min_value then
            return min_value
        end

        if number_value > max_value then
            return max_value
        end

        return number_value
    end

    function watermark_builder:encode_unit_slider(value, fallback)
        local normalized = self:normalize_slider_number(value, fallback, 0.0, 1.0)
        return math.floor(normalized * 100 + 0.5)
    end

    function watermark_builder:decode_unit_slider(value, fallback)
        if type(value) ~= "number" then
            return fallback
        end

        return self:normalize_slider_number(value * 0.01, fallback, 0.0, 1.0)
    end

    function watermark_builder:encode_speed_slider(value)
        local normalized = self:normalize_slider_number(value, 2.0, 0.01, 20.0)
        return math.floor(normalized * 100 + 0.5)
    end

    function watermark_builder:decode_speed_slider(value)
        if type(value) ~= "number" then
            return 2.0
        end

        return self:normalize_slider_number(value * 0.01, 2.0, 0.01, 20.0)
    end

    function watermark_builder:encode_waves_slider(value)
        local normalized = self:normalize_slider_number(value, 1.0, 0.1, 10.0)
        return math.floor(normalized * 10 + 0.5)
    end

    function watermark_builder:decode_waves_slider(value)
        if type(value) ~= "number" then
            return 1.0
        end

        return self:normalize_slider_number(value * 0.1, 1.0, 0.1, 10.0)
    end

    function watermark_builder:encode_glyph_amount_slider(value)
        local normalized = self:normalize_slider_number(value, 4.0, 0.0, 24.0)
        return math.floor(normalized * 10 + 0.5)
    end

    function watermark_builder:decode_glyph_amount_slider(value)
        if type(value) ~= "number" then
            return 4.0
        end

        return self:normalize_slider_number(value * 0.1, 4.0, 0.0, 24.0)
    end

    function watermark_builder:get_custom_font_options_value(custom_font)
        local value = {
        }
        local count = 0

        if type(custom_font) ~= "table" then
            return value
        end

        if custom_font.italic == true then
            count = count + 1
            value[count] = 1
        end

        if custom_font.underline == true then
            count = count + 1
            value[count] = 2
        end

        if custom_font.strike_out == true then
            count = count + 1
            value[count] = 3
        end

        if custom_font.shadow == true then
            count = count + 1
            value[count] = 4
        end

        if custom_font.outline == true then
            count = count + 1
            value[count] = 5
        end

        return value
    end

    function watermark_builder:apply_custom_font_options_value(custom_font, value)
        local selected = {
        }

        if type(value) == "table" then
            for i = 1, #value do
                local item = value[i]
                if item == 1 or item == "Italic" then
                    selected[1] = true
                elseif item == 2 or item == "Underline" then
                    selected[2] = true
                elseif item == 3 or item == "Strike Out" then
                    selected[3] = true
                elseif item == 4 or item == "Shadow" then
                    selected[4] = true
                elseif item == 5 or item == "Outline" then
                    selected[5] = true
                elseif type(item) == "string" then
                    local lowered = item:lower()
                    if lowered == "italic" then
                        selected[1] = true
                    elseif lowered == "underline" then
                        selected[2] = true
                    elseif lowered == "strike out" then
                        selected[3] = true
                    elseif lowered == "shadow" then
                        selected[4] = true
                    elseif lowered == "outline" then
                        selected[5] = true
                    end
                end
            end
        end

        custom_font.italic = selected[1] == true
        custom_font.underline = selected[2] == true
        custom_font.strike_out = selected[3] == true
        custom_font.shadow = selected[4] == true
        custom_font.outline = selected[5] == true
    end

    function watermark_builder:ensure_profile()
        if type(self.state.profile) ~= "table" then
            self.state.profile = watermark.get_profile_definition()
        end

        local segments = self.state.profile.segments
        if type(segments) ~= "table" then
            segments = {
            }
            self.state.profile.segments = segments
        end

        if type(self.state.profile.font) ~= "number" then
            self.state.profile.font = watermark.get_font()
        end

        if type(self.state.profile.custom_font) ~= "table" then
            self.state.profile.custom_font = watermark.get_custom_font_settings(self.state.profile)
        else
            self.state.profile.custom_font = gdi_font_api.clone_settings(self.state.profile.custom_font)
        end

        if #segments == 0 then
            self.state.selected_segment_index = 0
            return
        end

        if self.state.selected_segment_index < 1 then
            self.state.selected_segment_index = 1
        end

        if self.state.selected_segment_index > #segments then
            self.state.selected_segment_index = #segments
        end
    end

    function watermark_builder:get_custom_font_profile()
        self:ensure_profile()
        self.state.profile.custom_font = gdi_font_api.clone_settings(self.state.profile.custom_font)
        return self.state.profile.custom_font
    end

    function watermark_builder:get_selected_segment()
        self:ensure_profile()
        if self.state.selected_segment_index < 1 then
            return nil
        end
        return self.state.profile.segments[self.state.selected_segment_index]
    end

    function watermark_builder:format_segment_label(index, segment)
        local text = "(empty)"
        if type(segment) == "table" and type(segment.text) == "string" and segment.text ~= "" then
            text = segment.text
        end

        local mode_icon = icons.get("tag", 1, 5, "{Link Active}")
        local segment_type = self:get_segment_type(segment)
        local animation_enabled = self:is_segment_animation_enabled(segment)
        if segment_type == "Gradient" or segment_type == "Rainbow" then
            mode_icon = icons.get("palette", 1, 5, "{Link Active}")
        elseif animation_enabled == true then
            mode_icon = icons.get("wave-sine", 1, 5, "{Link Active}")
        end

        return mode_icon .. tostring(index) .. ". " .. text .. " [" .. self:get_mode_label(segment) .. "]"
    end

    function watermark_builder:update_segment_button_state()
        self:ensure_profile()

        local count = #self.state.profile.segments
        local selected = self.state.selected_segment_index

        self.ref.segment_list:disabled(count == 0)
        self.ref.segment_duplicate:disabled(count == 0)
        self.ref.segment_remove:disabled(count == 0)
        self.ref.segment_up:disabled(count <= 1 or selected <= 1)
        self.ref.segment_down:disabled(count <= 1 or selected >= count)
    end

    function watermark_builder:get_value_signature(value)
        if value == nil then
            return "nil"
        end

        local value_type = type(value)
        if value_type == "string"
            or value_type == "number"
            or value_type == "boolean" then
            return value_type .. ":" .. tostring(value)
        end

        if value_type == "table" then
            if type(value.r) == "number"
                or type(value.g) == "number"
                or type(value.b) == "number" then
                return "color:" .. tostring(watermark.color_to_hex(value))
            end

            local parts = {
                "table",
            }
            for i = 1, #value do
                parts[#parts + 1] = self:get_value_signature(value[i])
            end

            return table.concat(parts, "|")
        end

        local ok_hex, hex_value = pcall(function()
            if value.to_hex ~= nil then
                return value:to_hex()
            end
        end)
        if ok_hex and type(hex_value) == "string" then
            return "color:" .. hex_value
        end

        return value_type .. ":" .. tostring(value)
    end

    function watermark_builder:consume_pending_item_value(item, value)
        if item == nil then
            return false
        end

        local ok_id, item_id = pcall(item.id, item)
        if not ok_id or type(item_id) ~= "number" then
            return false
        end

        local expected = self.state.pending_item_values[item_id]
        if expected == nil then
            return false
        end

        if expected ~= self:get_value_signature(value) then
            self.state.pending_item_values[item_id] = nil
            return false
        end

        self.state.pending_item_values[item_id] = nil
        return true
    end

    function watermark_builder:consume_pending_hidden_value(key, value)
        local expected = self.state.pending_hidden_ref_values[key]
        if expected == nil then
            return false
        end

        if expected ~= self:get_value_signature(value) then
            return false
        end

        self.state.pending_hidden_ref_values[key] = nil
        return true
    end

    function watermark_builder:set_item_value(item, value)
        if item == nil then
            return
        end

        local ok_id, item_id = pcall(item.id, item)
        if ok_id and type(item_id) == "number" then
            self.state.pending_item_values[item_id] = self:get_value_signature(value)
        end

        pcall(item.set, item, value)
    end

    function watermark_builder:set_hidden_value(key, item, value)
        self.state.pending_hidden_ref_values[key] = self:get_value_signature(value)
        pcall(item.set, item, value)
    end

    function watermark_builder:refresh_segment_list()
        self:ensure_profile()

        local items = {
        }
        local count = #self.state.profile.segments
        if count == 0 then
            items[1] = "(watermark disabled)"
        else
            for i = 1, count do
                items[i] = self:format_segment_label(i, self.state.profile.segments[i])
            end
        end

        self.state.sync = true
        self.ref.segment_list:update(items)
        self:set_item_value(
            self.ref.segment_list,
            count > 0 and self.state.selected_segment_index or 1
        )
        self.state.sync = false

        self:update_segment_button_state()
    end

    function watermark_builder:update_editor_visibility()
        local segment = self:get_selected_segment()
        local has_segment = segment ~= nil
        local is_open = self.state.is_open == true
        local show_editor_groups = is_open == true and has_segment == true
        local use_custom_font = show_editor_groups == true
            and self.state.profile.font == CUSTOM_FONT
        self.ref.general_group:visibility(show_editor_groups)
        self.ref.editor_group:visibility(show_editor_groups)
        self.ref.text_animation_group:visibility(show_editor_groups)
        self.ref.animation_group:visibility(show_editor_groups)
        self.ref.general_custom_font_label:visibility(use_custom_font)
        self.ref.general_custom_font_face:visibility(use_custom_font)
        self.ref.general_custom_font_size:visibility(use_custom_font)
        self.ref.general_custom_font_spacing:visibility(use_custom_font)
        self.ref.general_custom_font_weight:visibility(use_custom_font)
        self.ref.general_custom_font_options:visibility(use_custom_font)
        self.ref.general_custom_font_quality:visibility(use_custom_font)

        if is_open ~= true or segment == nil then
            return
        end

        local segment_type = self:get_segment_type(segment)
        local animation_label = self:get_segment_animation_label(segment)
        local animation_enabled = animation_label ~= "Off"
        local use_solid = segment_type == "Solid"
        local use_gradient = segment_type == "Gradient"
        local use_rainbow = segment_type == "Rainbow"
        local use_alpha = self:get_segment_animation_effect_label(segment) == "Alpha"
        local use_animation_span = self:uses_segment_animation_span(segment)
        local use_direction = animation_label == "Wave"
            or animation_label == "Sweep"
            or animation_label == "Centered"
            or animation_label == "Shift"
        local use_shape = animation_enabled == true
        local glyph_motion_enabled = self:get_segment_glyph_animation_label(segment) ~= "Off"
        local glyph_glitch_enabled = self:get_segment_glyph_glitch_label(segment) == "On"
        local glyph_enabled = glyph_motion_enabled == true
            or glyph_glitch_enabled == true

        self.ref.segment_color_source:visibility(use_solid)
        self.ref.segment_color:visibility(use_solid and segment.color ~= nil)
        self.ref.segment_gradient_source:visibility(use_gradient)
        self.ref.segment_from:visibility(use_gradient and segment.from ~= nil)
        self.ref.segment_to:visibility(use_gradient and segment.to ~= nil)
        self.ref.segment_color_spread:visibility(use_rainbow)
        self.ref.segment_saturation:visibility(use_rainbow)
        self.ref.segment_value:visibility(use_rainbow)

        self.ref.segment_animation:visibility(true)
        self.ref.segment_glyph_animation:visibility(true)
        self.ref.segment_glyph_glitch:visibility(true)
        self.ref.segment_glyph_amount:visibility(glyph_enabled == true)
        self.ref.segment_glyph_speed:visibility(glyph_enabled == true)
        self.ref.segment_glyph_span:visibility(glyph_enabled == true)
        self.ref.segment_animation_effect:visibility(animation_enabled == true)
        self.ref.segment_animation_playback:visibility(animation_enabled == true)
        self.ref.segment_animation_direction:visibility(animation_enabled == true and use_direction == true)
        self.ref.segment_animation_reverse:visibility(animation_enabled == true)
        self.ref.segment_animation_shape:visibility(animation_enabled == true and use_shape == true)
        self.ref.segment_min:visibility(animation_enabled == true)
        self.ref.segment_max:visibility(animation_enabled == true)
        self.ref.segment_speed:visibility(animation_enabled == true)
        self.ref.segment_animation_span:visibility(animation_enabled == true and use_animation_span == true)

        if use_alpha == true then
            self.ref.segment_min:name(
                icons.get("arrow-turn-down-right", 1.5, 6, "{Link Active}") .. "Min Alpha"
            )
            self.ref.segment_max:name(
                icons.get("arrow-turn-down-right", 1.5, 6, "{Link Active}") .. "Max Alpha"
            )
        else
            self.ref.segment_min:name(
                icons.get("arrow-turn-down-right", 1.5, 6, "{Link Active}") .. "Min Strength"
            )
            self.ref.segment_max:name(
                icons.get("arrow-turn-down-right", 1.5, 6, "{Link Active}") .. "Max Strength"
            )
        end

        if animation_label == "Wave" then
            self.ref.segment_animation_span:name(
                icons.get("wave-sine", 1, 5.5, "{Link Active}") .. "Spread"
            )
        elseif animation_label == "Sweep"
            or animation_label == "Centered" then
            self.ref.segment_animation_span:name(
                icons.get("wave-sine", 1, 5.5, "{Link Active}") .. "Width"
            )
        elseif animation_label == "Shift" then
            self.ref.segment_animation_span:name(
                icons.get("wave-sine", 1, 5.5, "{Link Active}") .. "Range"
            )
        else
            self.ref.segment_animation_span:name(
                icons.get("wave-sine", 1, 5.5, "{Link Active}") .. "Spread"
            )
        end
    end

    function watermark_builder:sync_general_controls()
        local custom_font = self:get_custom_font_profile()
        self.state.sync = true
        self:set_item_value(self.ref.general_font, self.state.profile.font)
        self:set_item_value(self.ref.general_custom_font_face, custom_font.face)
        self:set_item_value(self.ref.general_custom_font_size, custom_font.size)
        self:set_item_value(self.ref.general_custom_font_spacing, custom_font.spacing)
        self:set_item_value(
            self.ref.general_custom_font_weight,
            gdi_font_api.get_weight_name(custom_font.weight)
        )
        self:set_item_value(
            self.ref.general_custom_font_options,
            self:get_custom_font_options_value(custom_font)
        )
        self:set_item_value(self.ref.general_custom_font_quality, custom_font.quality)
        self.state.sync = false
        self:update_editor_visibility()
    end

    function watermark_builder:sync_editor_controls()
        local segment = self:get_selected_segment()
        if segment == nil then
            self:update_editor_visibility()
            return
        end

        local segment_type = self:get_segment_type(segment)
        if segment_type == "Gradient" then
            self:apply_segment_type_defaults(segment, segment_type)
        end

        local animation_label = self:get_segment_animation_label(segment)
        local animation_effect = self:get_segment_animation_effect_label(segment)

        self.state.sync = true
        self:set_item_value(self.ref.segment_text, segment.text)
        self:set_item_value(self.ref.segment_style, segment_type)
        self:set_item_value(self.ref.segment_animation, animation_label)
        self:set_item_value(
            self.ref.segment_glyph_animation,
            self:get_segment_glyph_animation_label(segment)
        )
        self:set_item_value(
            self.ref.segment_glyph_glitch,
            self:get_segment_glyph_glitch_label(segment) == "On"
        )
        self:set_item_value(
            self.ref.segment_glyph_amount,
            self:encode_glyph_amount_slider(segment.glyph_amount)
        )
        self:set_item_value(
            self.ref.segment_glyph_speed,
            self:encode_speed_slider(segment.glyph_speed)
        )
        self:set_item_value(
            self.ref.segment_glyph_span,
            self:encode_waves_slider(segment.glyph_span)
        )
        self:set_item_value(self.ref.segment_animation_effect, animation_effect)
        self:set_item_value(
            self.ref.segment_animation_playback,
            self:get_segment_animation_playback_label(segment)
        )
        self:set_item_value(
            self.ref.segment_animation_direction,
            self:get_segment_animation_direction_label(segment)
        )
        self:set_item_value(
            self.ref.segment_animation_reverse,
            self:get_segment_animation_reverse_label(segment)
        )
        self:set_item_value(
            self.ref.segment_animation_shape,
            self:get_segment_animation_shape_label(segment)
        )
        self:set_item_value(self.ref.segment_color_source, self:get_color_source_label(segment.color))
        self:set_item_value(self.ref.segment_gradient_source, self:get_gradient_source_label(segment))
        self:set_item_value(self.ref.segment_color, self:get_picker_color(segment.color))
        self:set_item_value(self.ref.segment_from, self:get_picker_color(segment.from))
        self:set_item_value(self.ref.segment_to, self:get_picker_color(segment.to))
        self:set_item_value(self.ref.segment_color_spread, self:encode_waves_slider(segment.waves))
        self:set_item_value(self.ref.segment_saturation, self:encode_unit_slider(segment.saturation, 1.0))
        self:set_item_value(self.ref.segment_value, self:encode_unit_slider(segment.value, 1.0))
        self:set_item_value(self.ref.segment_min, self:encode_unit_slider(segment.min, 0.3))
        self:set_item_value(self.ref.segment_max, self:encode_unit_slider(segment.max, 1.0))
        self:set_item_value(self.ref.segment_speed, self:encode_speed_slider(segment.speed))
        self:set_item_value(self.ref.segment_animation_span, self:encode_waves_slider(segment.animation_span))
        self.state.sync = false

        self:update_editor_visibility()
    end

    function watermark_builder:load_from_watermark()
        self.state.profile = watermark.get_profile_definition()
        self:ensure_profile()
        self:sync_general_controls()
        self:refresh_segment_list()
        self:sync_editor_controls()
    end

    function watermark_builder:store_profile()
        local serialized = watermark.apply_profile_definition(self.state.profile)
        if type(serialized) ~= "string" then
            return false
        end

        self:set_hidden_value("text", watermark_text, serialized)
        self:set_hidden_value("font", watermark_font, self.state.profile.font)

        return true
    end

    function watermark_builder:set_items_visibility(items, state)
        for i = 1, #items do
            items[i]:visibility(state)
        end
    end

    function watermark_builder:set_items_disabled(items, state)
        for i = 1, #items do
            pcall(items[i].disabled, items[i], state)
        end
    end

    function watermark_builder:capture_disabled_states(items)
        local states = {
        }

        for i = 1, #items do
            local ok_disabled, is_disabled = pcall(items[i].disabled, items[i])
            states[i] = ok_disabled and is_disabled == true
        end

        return states
    end

    function watermark_builder:restore_disabled_states(items, states)
        for i = 1, #items do
            pcall(items[i].disabled, items[i], states[i] == true)
        end
    end

    function watermark_builder:open()
        self:load_from_watermark()
        watermark.set_hover_font_cycle_enabled(false)
        self.state.preset_disabled_states = self:capture_disabled_states(
            self.ref.preset_interactive_items
        )

        for i = 1, #self.ref.preset_groups do
            self.ref.preset_groups[i]:visibility(false)
        end
        self:set_items_visibility(self.ref.preset_items, false)
        self:set_items_disabled(self.ref.preset_interactive_items, true)

        for i = 1, #self.ref.builder_groups do
            self.ref.builder_groups[i]:visibility(true)
        end
        self:set_items_visibility(self.ref.builder_items, true)
        self:set_items_disabled(self.ref.builder_interactive_items, false)
        self.state.is_open = true
        self:update_segment_button_state()
        self:update_editor_visibility()
    end

    function watermark_builder:close()
        self.state.is_open = false
        watermark.set_hover_font_cycle_enabled(true)
        for i = 1, #self.ref.builder_groups do
            self.ref.builder_groups[i]:visibility(false)
        end
        self:set_items_visibility(self.ref.builder_items, false)
        self:set_items_disabled(self.ref.builder_interactive_items, true)

        for i = 1, #self.ref.preset_groups do
            self.ref.preset_groups[i]:visibility(true)
        end
        self:set_items_visibility(self.ref.preset_items, true)
        self:restore_disabled_states(
            self.ref.preset_interactive_items,
            self.state.preset_disabled_states
        )

        local meta = config.get_meta(config_name:get())
        local has_meta = (
            type(meta) == "table"
            and type(meta.created_ts) == "number"
        )
        meta_group:visibility(has_meta)

        self.state.preset_disabled_states = {
        }
    end

