    watermark_builder.ref.copy_button = watermark_builder.ref.actions_group:button(
        icons.get("copy", 3, 3, "{Link Active}") .. "Copy   ",
        function()
            sounds.play(sounds.press)

            local serialized = watermark.export_profile_string()
            if type(serialized) ~= "string" or serialized == "" then
                return prints.error("Failed to export watermark code")
            end

            clipboard.set(serialized)
            prints.success("Copied watermark code to clipboard")
        end,
        true
    )
    watermark_builder.ref.paste_button = watermark_builder.ref.actions_group:button(
        icons.get("download", 3, 3, "{Link Active}") .. "Paste   ",
        function()
            sounds.play(sounds.press)

            local raw = clipboard.get()
            if type(raw) ~= "string" or raw == "" then
                return prints.error("Invalid or empty clipboard data")
            end

            if watermark.import_profile_string(raw) ~= true then
                return prints.error("Invalid watermark code")
            end

            local serialized = watermark.export_profile_string()
            if type(serialized) ~= "string" or serialized == "" then
                return prints.error("Failed to import watermark code")
            end

            watermark_builder.state.sync = true
            pcall(watermark_text.set, watermark_text, serialized)
            pcall(watermark_font.set, watermark_font, watermark.get_font())
            watermark_builder.state.sync = false

            watermark_builder:load_from_watermark()
            prints.success("Imported watermark code")
        end,
        true
    )

