            watermark_builder.state.selected_segment_index = #segments
            watermark_builder:refresh_segment_list()
            watermark_builder:sync_editor_controls()
            watermark_builder:store_profile()
        end,
        true
    )
    watermark_builder.ref.segment_duplicate = watermark_builder.ref.segments_group:button(
        icons.get("copy", 2.5, 2.5, "{Link Active}") .. "Duplicate",
        function()
            sounds.play(sounds.press)
            local segment = watermark_builder:get_selected_segment()
            if segment == nil then
                return
            end

            local segments = watermark_builder.state.profile.segments
            local index = watermark_builder.state.selected_segment_index + 1
            table.insert(segments, index, watermark_builder:clone_segment(segment))
            watermark_builder.state.selected_segment_index = index
            watermark_builder:refresh_segment_list()
            watermark_builder:sync_editor_controls()
            watermark_builder:store_profile()
        end,
        true
    )
    watermark_builder.ref.segment_remove = watermark_builder.ref.segments_group:button(
        icons.get("trash-xmark", 1, 2.5, "FF6B6BFF") .. "Remove",
        function()
            sounds.play(sounds.press)
            watermark_builder:ensure_profile()
            local segments = watermark_builder.state.profile.segments
            if #segments == 0 then
                return
            end

            table.remove(segments, watermark_builder.state.selected_segment_index)
            if #segments == 0 then
                watermark_builder.state.selected_segment_index = 0
            elseif watermark_builder.state.selected_segment_index > #segments then
                watermark_builder.state.selected_segment_index = #segments
            end

            watermark_builder:refresh_segment_list()
            watermark_builder:sync_editor_controls()
            watermark_builder:store_profile()
        end,
        true
    )
    watermark_builder.ref.segment_up = watermark_builder.ref.segments_group:button(
        icons.get("arrow-up", 2.5, 2.5, "{Link Active}") .. "Move Up",
        function()
            sounds.play(sounds.press)
            local index = watermark_builder.state.selected_segment_index
            if index <= 1 then
                return
            end

            local segments = watermark_builder.state.profile.segments
            segments[index], segments[index - 1] = segments[index - 1], segments[index]
            watermark_builder.state.selected_segment_index = index - 1
            watermark_builder:refresh_segment_list()
            watermark_builder:sync_editor_controls()
            watermark_builder:store_profile()
        end,
        true
    )
    watermark_builder.ref.segment_down = watermark_builder.ref.segments_group:button(
        icons.get("arrow-down", 2.5, 2.5, "{Link Active}") .. "Move Down",
        function()
            sounds.play(sounds.press)
            local segments = watermark_builder.state.profile.segments
            local index = watermark_builder.state.selected_segment_index
            if index >= #segments then
