            segments[index], segments[index + 1] = segments[index + 1], segments[index]
            watermark_builder.state.selected_segment_index = index + 1
            watermark_builder:refresh_segment_list()
            watermark_builder:sync_editor_controls()
            watermark_builder:store_profile()
        end,
        true
