            local default_position = watermark.get_default_position()
            local position_x = math.floor(default_position.x + 0.5)
            local position_y = math.floor(default_position.y + 0.5)

            pcall(watermark_position_x.set, watermark_position_x, position_x)
            pcall(watermark_position_y.set, watermark_position_y, position_y)
        end,
        true
    )

