    watermark_builder.ref.segment_color_source:tooltip("For Solid style: Accent uses the menu accent color, Custom uses the color picker below.")
    watermark_builder.ref.segment_gradient_source:tooltip(
        "For Gradient style: chooses which side uses accent and which side uses a custom color."
