    watermark_builder.ref.segment_color:tooltip("Custom solid color used when Color Source is set to Custom.")
    watermark_builder.ref.segment_from:tooltip("Gradient start color.")
    watermark_builder.ref.segment_to:tooltip(
        "Gradient end color.\n\nWhen a gradient uses color animation, this color is also used as the animated target color."
