    watermark_builder.ref.segment_color_spread:tooltip(
        "For Rainbow style: controls how many hue steps are visible across the segment at once."
    )
    watermark_builder.ref.segment_saturation:tooltip("For Rainbow style: controls color saturation.")
    watermark_builder.ref.segment_value:tooltip("For Rainbow style: controls brightness/value.")

    watermark_builder.ref.segment_glyph_animation:tooltip(
        "Selects the glyph motion type.\n\nOff = static glyph positions.\nWave = smooth vertical wave.\nOrbit = circular drift.\nScatter = center-out split motion.\nHeart = letters form a pulsing heart shape.\n\nOpen the gear for glitch and motion tuning."
    )
    watermark_builder.ref.segment_glyph_glitch:tooltip("Randomly swaps characters while keeping the segment width stable.")
    watermark_builder.ref.segment_glyph_amount:tooltip(
        "Maximum glyph offset in pixels.\n\nFor Glyph Glitch it controls how aggressively characters get replaced."
    )
    watermark_builder.ref.segment_glyph_speed:tooltip("How fast the glyph motion updates.")
    watermark_builder.ref.segment_glyph_span:tooltip("How wide the phase spread is across the glyphs.")
    watermark_builder.ref.segment_animation:tooltip(
        "Selects the color animation type.\n\nOff = static.\nWave = phased wave across letters.\nSweep = moving band.\nPulse = global pulse.\nBreath = softer global pulse.\nCentered = wave travels from the center to the edges.\nShift = slides the whole animated zone.\n\nOpen the gear for advanced color modifiers."
    )
    watermark_builder.ref.segment_animation_effect:tooltip(
        "Chooses what the animation affects.\n\nColor blends toward the animated color.\nAlpha animates transparency."
    )
    watermark_builder.ref.segment_animation_playback:tooltip(
        "Loop restarts from the beginning.\nPing-Pong plays forward and then backward without a hard reset."
    )
    watermark_builder.ref.segment_animation_direction:tooltip(
        "Changes the spatial direction of the animation.\n\nFor example, Sweep can move left to right or right to left."
    )
    watermark_builder.ref.segment_animation_reverse:tooltip(
        "Flips the time phase of the animation.\n\nUnlike Direction, this reverses the cycle itself instead of the spatial layout."
    )
    watermark_builder.ref.segment_animation_shape:tooltip(
        "Soft uses a smoother falloff.\nSharp makes the animation peak tighter and more aggressive."
    )
    watermark_builder.ref.segment_min:tooltip(
        "Lower bound of animation strength.\n\nFor Color it controls the minimum blend amount.\nFor Alpha it controls the minimum visible alpha."
