    watermark_builder.ref.segment_list:set_callback(function(item)
        if item == nil then
            return
        end

        local ok_value, value = pcall(item.get, item)
        if not ok_value or type(value) ~= "number" then
            return
        end

        if watermark_builder:consume_pending_item_value(item, value) then
            return
        end

        if watermark_builder.state.sync == true then
            return
        end

        watermark_builder.state.selected_segment_index = value
        watermark_builder:sync_editor_controls()
    end)

    watermark_builder.ref.general_font:set_callback(function(item)
        if item == nil then
            return
        end

        local ok_value, value = pcall(item.get, item)
        if not ok_value or type(value) ~= "number" then
            return
        end

        if watermark_builder:consume_pending_item_value(item, value) then
            return
        end

        if watermark_builder.state.sync == true then
            return
        end

        watermark_builder.state.profile.font = value
        if value == CUSTOM_FONT and type(watermark_builder.state.profile.custom_font) ~= "table" then
            watermark_builder.state.profile.custom_font = watermark.get_custom_font_settings()
        end
        watermark_builder:update_editor_visibility()
        watermark_builder:store_profile()
    end)

