    local pending_action = nil
    local pending_payload = nil
    local pending_name = nil

    local all_buttons = {
    }

    local confirm_btn = nil
    local cancel_btn = nil
    local remove_btn = nil
    local last_click = 0
    local last_clicked_config_name = nil

    local options_sync = false
    local previous_options_set = {
    }

    local function reset_config_list_click_state()
        last_click = 0
        last_clicked_config_name = nil
    end

    local function to_index_set(values)
        local set = {
        }

        if type(values) ~= "table" then
            return set
        end

        for _, value in ipairs(values) do
            if type(value) == "number" then
                set[value] = true
            end
        end

        return set
    end

    local function to_index_array(index_set)
        local values = {
        }

        for index = 1, #option_items do
            if index_set[index] then
                values[#values + 1] = index
            end
        end

        return values
    end

    local function are_all_children_selected(index_set, children)
        for _, child_index in ipairs(children) do
            if not index_set[child_index] then
                return false
            end
        end

        return true
    end

    local function are_children_changed(current_set, children)
        for _, child_index in ipairs(children) do
            local current_value = current_set[child_index] == true
            local previous_value = previous_options_set[child_index] == true
            if current_value ~= previous_value then
                return true
            end
        end

        return false
    end

    local function normalize_options_selection(values)
        local selected = to_index_set(values)

        for _, option_group in ipairs(option_groups) do
            local parent = option_group.parent
            local children = option_group.children
            local child_changed = are_children_changed(selected, children)

            local parent_selected = selected[parent] == true
            local parent_was_selected = previous_options_set[parent] == true
            local parent_turned_on = parent_selected and not parent_was_selected
            local parent_turned_off = parent_was_selected and not parent_selected

            if parent_turned_on and not child_changed then
                for _, child_index in ipairs(children) do
                    selected[child_index] = true
                end
            end

            if parent_turned_off and not child_changed then
                for _, child_index in ipairs(children) do
                    selected[child_index] = nil
                end
            end

            if are_all_children_selected(selected, children) then
                selected[parent] = true
            else
                selected[parent] = nil
            end
        end

        return selected
    end

    local function set_default_options()
        local default_set = {
        }

        for index = 1, #option_items do
            default_set[index] = true
        end

        local values = to_index_array(default_set)
        options_sync = true
        options_list:set(values)
        options_sync = false
        previous_options_set = default_set
    end

    local function clear_options_selection()
        options_sync = true
        options_list:set({
        })
        options_sync = false

        previous_options_set = {
        }
    end

    options_list:set_callback(function()
        if options_sync then
            return
        end

        local normalized_set = normalize_options_selection(options_list:get())
        local normalized_values = to_index_array(normalized_set)

        options_sync = true
        options_list:set(normalized_values)
        options_sync = false

        previous_options_set = normalized_set
    end)

    local function get_selected_scopes()
        local selected_set = to_index_set(options_list:get())
        local main_rage = selected_set[option_index.main_rage] == true
        local main_visuals = selected_set[option_index.main_visuals] == true
        local main_misc = selected_set[option_index.main_misc] == true
        local scopes = {
            angles_builder = selected_set[option_index.angles_builder] == true,
            angles_hotkeys = selected_set[option_index.angles_hotkeys] == true,
            angles_features = selected_set[option_index.angles_features] == true,
            main_home = main_rage or main_visuals or main_misc,
            main_rage = main_rage,
            main_visuals = main_visuals,
            main_misc = main_misc,
            global_binds = selected_set[option_index.global_binds] == true,
        }

        return scopes
    end

    local function config_exists(name)
        local list = config_list:list()
        if type(list) ~= "table" then
            return false
        end

        for _, value in ipairs(list) do
            if value == name then
                return true
            end
        end

        return false
    end

    local function format_elapsed(sec)
        if sec < 60 then
            return sec .. " Seconds"
        end

        if sec < 3600 then
            return math.floor(sec / 60) .. " Minutes"
        end

        if sec < 86400 then
            return math.floor(sec / 3600) .. " Hours"
        end

        return math.floor(sec / 86400) .. " Days"
    end

    local function update_meta(name)
        if watermark_builder.state.is_open == true then
            meta_group:visibility(false)
            return
        end

        local meta = config.get_meta(name)
        if type(meta) ~= "table" then
            meta_group:visibility(false)
            return
        end

        if type(meta.created_ts) ~= "number" then
            meta_group:visibility(false)
            return
        end

        local elapsed = common.get_unixtime() - meta.created_ts
        date_label:name(
            icons.get("clock", 0, 4, "{Link Active}") ..
            format_elapsed(elapsed) ..
            " ago"
        )
        meta_group:visibility(true)
    end

    local function refresh_list()
        reset_config_list_click_state()

        local list = config.get_list()
        if type(list) ~= "table" then
            list = {
            }
        end

        if #list == 0 then
            config_list:update({
                icons.get("eye-slash", 0, 4, "{Link Active}") .. "I don't see any presets(",
            })
            config_list:set(1)
            config_list:disabled(true)
            config_name:set("")
            update_meta("")
            if remove_btn ~= nil then
                remove_btn:disabled(true)
            end
            if confirm_btn ~= nil then
                confirm_btn:disabled(true)
            end
            if cancel_btn ~= nil then
                cancel_btn:disabled(true)
            end
            return
        end

        config_list:update(list)

        local current = config_name:get()
        local found = false
        for index, value in ipairs(list) do
            if value == current then
                config_list:set(index)
                found = true
                break
            end
        end

        if not found then
            config_list:set(1)
            config_name:set(list[1])
        end

        config_list:disabled(false)
        if remove_btn ~= nil then
            remove_btn:disabled(false)
        end
        if confirm_btn ~= nil then
            confirm_btn:disabled(false)
        end
        if cancel_btn ~= nil then
            cancel_btn:disabled(false)
        end
        update_meta(config_name:get())
    end

    local function start_action(action, payload, name)
        pending_action = action
        pending_payload = payload
        pending_name = name

        for _, button in ipairs(all_buttons) do
            button:disabled(true)
        end

        config_list:disabled(true)
        config_name:disabled(action == "load" or action == "import")

        if action == "load" or action == "import" then
            set_default_options()
            options_list:disabled(false)
        else
            clear_options_selection()
            options_list:disabled(true)
        end

        confirm_btn:disabled(false)
        cancel_btn:disabled(false)
        confirm_btn:visibility(true)
        cancel_btn:visibility(true)
    end

    local function cancel_action()
        pending_action = nil
        pending_payload = nil
        pending_name = nil

        for _, button in ipairs(all_buttons) do
            button:disabled(false)
        end

        confirm_btn:visibility(false)
        cancel_btn:visibility(false)
        config_name:disabled(false)
        clear_options_selection()
        options_list:disabled(true)

        refresh_list()
    end

    local function begin_load_selected_config()
        local name = config_name:get()
        if not config_exists(name) then
            return prints.error("Config not found: " .. tostring(name))
        end

        local data = config.read(name)
        if type(data) ~= "table" then
            return prints.error("Config not found: " .. tostring(name))
        end

        start_action("load", data, name)
    end

    config_list:set_callback(function()
        if config_list:disabled() then
            return
        end

        local idx = config_list:get()
        local name = config_list:list()[idx]
        if name == nil then
            return
        end

        config_name:set(name)
        sounds.play(sounds.press)

        local now = globals.realtime
        local is_same_config = name == last_clicked_config_name
        if is_same_config and now - last_click < 0.3 then
            reset_config_list_click_state()
            begin_load_selected_config()
            return
        end

        last_click = now
        last_clicked_config_name = name
    end)

    local save_btn = tab:button(
        icons.get("floppy-disk", 2.5, 2.5, "{Link Active}") .. "Save  ",
        function()
            sounds.play(sounds.press)
            local name = config_name:get()
            if name == "" then
                return prints.error("Config name cannot be empty!")
            end

            if config_exists(name) then
                start_action("save", nil, name)
                return
            end

            config.save(name)
            refresh_list()
        end,
        true
    ):tooltip("Saves or creates a preset")

    local export_btn = tab:button(
        icons.get("copy", 2.5, 2.5, "{Link Active}") .. "Copy  ",
        function()
            sounds.play(sounds.press)
            config.export()
        end,
        true
    ):tooltip("Copies the settings to the clipboard")

    local import_btn = tab:button(
        icons.get("download", 2.5, 2.5, "{Link Active}") .. "Paste  ",
        function()
            sounds.play(sounds.press)
            local data = config.decode_clipboard()
            if data == nil then
                return
            end

            start_action("import", data, nil)
        end,
        true
    ):tooltip("Load settings from the clipboard")

    remove_btn = tab:button(
        icons.get("trash-xmark", 0.5, 0.5, "FF6B6BFF"),
        function()
            sounds.play(sounds.press)
            local name = config_name:get()
            if not config_exists(name) then
                return prints.error("Config not found: " .. name)
            end

            start_action("remove", nil, name)
        end,
        true
    ):tooltip("Deletes the selected config")

    cancel_btn = tab:button(
        string.format(
            "%s\aDB6361FF%s    \a{Text Preview}%s%s",
            string.rep(" ", 9),
            ui.get_icon("xmark"),
            "Cancel",
            string.rep(" ", 9)
        ),
        function()
            sounds.play(sounds.back)
            cancel_action()
        end,
        true
    )

    confirm_btn = tab:button(
        string.format(
            "%s\a{Link Active}%s    \a{Text Preview}%s%s",
            string.rep(" ", 8),
            ui.get_icon("check"),
            "Confirm",
            string.rep(" ", 9)
        ),
        function()
            sounds.play(sounds.confirm)

            if pending_action == "save" then
                local name = config_name:get()
                local source_name = pending_name

                if source_name ~= nil and source_name ~= "" then
                    if source_name ~= name then
                        local ok_rename = config.rename(source_name, name)
                        if not ok_rename then
                            return
                        end
                    end
                end

                config.save(name)
                cancel_action()
                return
            end

            if pending_action == "remove" then
                local name = config_name:get()
                config.remove(name)
                cancel_action()
                return
            end

            if pending_action == "load" then
                local selected_scopes = get_selected_scopes()
                local data = config.filter_data(pending_payload, selected_scopes)
                local allow_binds = selected_scopes.global_binds == true
                config.apply(data, {
                    allow_raw = allow_binds,
                    allow_binds = allow_binds,
                })
                prints.success("Loaded config: " .. tostring(pending_name))
                cancel_action()
                return
            end

            if pending_action == "import" then
                local selected_scopes = get_selected_scopes()
                local data = config.filter_data(pending_payload, selected_scopes)
                local allow_binds = selected_scopes.global_binds == true
                config.apply(data, {
                    allow_raw = allow_binds,
                    allow_binds = allow_binds,
                })
                prints.success("Config loaded from clipboard")
                cancel_action()
            end
        end,
        true
    )

    confirm_btn:visibility(false)
    cancel_btn:visibility(false)
    watermark_builder.ref.preset_items = {
        config_list,
        config_name,
        date_label,
        watermark_builder_label,
        watermark_builder_open,
        options_list,
        save_btn,
        export_btn,
        import_btn,
        remove_btn,
    }
    watermark_builder.ref.preset_interactive_items = {
        config_list,
        config_name,
        watermark_builder_open,
        options_list,
        save_btn,
        export_btn,
        import_btn,
        remove_btn,
    }

    all_buttons = {
        save_btn,
        export_btn,
        import_btn,
        remove_btn,
        watermark_builder_open,
    }

    clear_options_selection()

    config.update()
    refresh_list()
    watermark_builder.state.preset_disabled_states = watermark_builder:capture_disabled_states(
        watermark_builder.ref.preset_interactive_items
    )
    watermark_builder:close()

    local last_update = 0
    local function on_render()
        local now = globals.realtime
        if now - last_update >= 1 then
            update_meta(config_name:get())
            last_update = now
        end
    end

    events.render(on_render, true)
end

