    fluctuate = nil,
    fix_recharge_delay = nil,
}
angles_builder.apply_fake_lag_limit_override = function()
    local fake_lag_limit_ref = nl.aa and nl.aa.fake_lag and nl.aa.fake_lag.limit
    if fake_lag_limit_ref == nil then
        return
    end

    local override_state = angles_builder.fake_lag_limit_override_state
    if override_state == nil then
        fake_lag_limit_ref:override()
        return
    end

    local override_value = override_state.fluctuate
    if override_state.fix_recharge_delay ~= nil then
        override_value = override_state.fix_recharge_delay
    end

    if override_value == nil then
        fake_lag_limit_ref:override()
        return
    end

    fake_lag_limit_ref:override(override_value)
end
