    local function builder_lc_key(team_index, condition_index, suffix)
        return builder_key(team_index, condition_index, "lc_" .. suffix)
    end

    local function make_condition_toggle_name(
        is_enabled,
        team_index,
        condition_index,
        id_prefix
    )
        local prefix = id_prefix
        if type(prefix) ~= "string" or prefix == "" then
            prefix = "team_toggle"
        end

        if is_enabled == true then
            return icons.get("check", 1, 1, "A0CE48FF")
                .. "##"
                .. prefix
                .. "_"
                .. team_index
                .. "_"
                .. condition_index
        end

        return icons.get("xmark", 1.5, 1.5, "CE4848FF")
            .. "##"
            .. prefix
            .. "_"
            .. team_index
            .. "_"
            .. condition_index
    end

    local function get_break_lc_tickbase_type_name(value)
        if value == 2 or value == "Ways" then
            return "Ways"
        end

        return "Default"
    end

    local function format_break_lc_tickbase_value(value)
        local number = math.floor(tonumber(value) or 2)
        if number < 2 then
            number = 2
        elseif number > 22 then
            number = 22
        end

        if number == 2 then
            return "Sharp"
        end

        if number == 22 then
            return "Smooth"
        end

        return tostring(number) .. " t"
    end

    local function create_break_lc_tickbase_refs(
        exploits_group,
        break_lc_mode_ref,
        team_index,
        condition_index
    )
        local refs = {
            break_lc_custom_tickbase_enabled_ref = nil,
            break_lc_tickbase_randomize_ref = nil,
            break_lc_tickbase_choke_ref = nil,
            break_lc_tickbase_type_ref = nil,
            break_lc_tickbase_random_min_ref = nil,
            break_lc_tickbase_random_max_ref = nil,
            break_lc_tickbase_sliders_ref = nil,
            break_lc_tickbase_slot_refs = {
            },
        }

        for slot_index = 1, 8 do
            refs["break_lc_tickbase_" .. slot_index .. "_ref"] = nil
        end

        if exploits_group == nil or break_lc_mode_ref == nil then
            return refs
        end

        refs.break_lc_custom_tickbase_enabled_ref = config.push(
            exploits_group:switch(
                "##builder_break_lc_custom_tickbase_"
                .. team_index
                .. "_"
                .. condition_index,
                false
            ),
            builder_key(team_index, condition_index, "break_lc_custom_tickbase_enabled")
        )
        refs.break_lc_custom_tickbase_enabled_ref:visibility(false)

        local gear = break_lc_mode_ref:create()
        if gear == nil then
            return refs
        end

        local custom_tickbase_label = gear:label(
            ui_symbols.prefix_dot .. "   Custom Tickbase"
        )
        local custom_tickbase_toggle = gear:button(
            make_condition_toggle_name(
                refs.break_lc_custom_tickbase_enabled_ref:get() == true,
                team_index,
                condition_index,
                "break_lc_tickbase"
            ),
            function()
                refs.break_lc_custom_tickbase_enabled_ref:set(
                    refs.break_lc_custom_tickbase_enabled_ref:get() ~= true
                )
            end,
            true
        )

        refs.break_lc_tickbase_randomize_ref = config.push(
            gear:switch(ui_symbols.prefix_dot .. "   Randomize", true),
            builder_key(team_index, condition_index, "break_lc_tickbase_randomize")
        )
        refs.break_lc_tickbase_randomize_ref:tooltip(
            "Randomizes the defensive interval for Break LC."
        )

        refs.break_lc_tickbase_choke_ref = config.push(
            gear:slider(
                ui_symbols.prefix_arrow .. "   Choke",
                2,
                22,
                16,
                nil,
                format_break_lc_tickbase_value
            ),
            builder_key(team_index, condition_index, "break_lc_tickbase_choke")
        )

        refs.break_lc_tickbase_type_ref = config.push(
            gear:combo(ui_symbols.prefix_dot .. "   Type", {
                "Default",
                "Ways",
            }),
            builder_key(team_index, condition_index, "break_lc_tickbase_type")
        )
        refs.break_lc_tickbase_type_ref:tooltip(
            "Default uses a range. Ways uses custom slot values."
        )

        refs.break_lc_tickbase_random_min_ref = config.push(
            gear:slider(
                ui_symbols.prefix_arrow .. "   [1]",
                2,
                22,
                16,
                nil,
                format_break_lc_tickbase_value
            ),
            builder_key(team_index, condition_index, "break_lc_tickbase_random_min")
        )

        refs.break_lc_tickbase_random_max_ref = config.push(
            gear:slider(
                ui_symbols.prefix_arrow .. "   [2]",
                2,
                22,
                16,
                nil,
                format_break_lc_tickbase_value
            ),
            builder_key(team_index, condition_index, "break_lc_tickbase_random_max")
        )

        refs.break_lc_tickbase_sliders_ref = config.push(
            gear:slider(ui_symbols.prefix_dot .. "   Sliders", 2, 8, 3),
            builder_key(team_index, condition_index, "break_lc_tickbase_sliders")
        )
        refs.break_lc_tickbase_sliders_ref:tooltip(
            "Amount of slot values used by Ways."
        )

        for slot_index = 1, 8 do
            local key = "break_lc_tickbase_" .. slot_index .. "_ref"
            local slot_ref = config.push(
                gear:slider(
                    ui_symbols.prefix_arrow .. "   " .. slot_index,
                    2,
                    22,
                    2,
                    nil,
                    format_break_lc_tickbase_value
                ),
                builder_key(team_index, condition_index, "break_lc_tickbase_" .. slot_index)
            )
            refs[key] = slot_ref
            refs.break_lc_tickbase_slot_refs[slot_index] = slot_ref
        end

        local reset_button = gear:button(
            icons.get("rotate-left", 1, 1, "{Link Active}") .. "Reset",
            function()
                refs.break_lc_tickbase_sliders_ref:set(3)
                for slot_index = 1, 8 do
                    local slot_ref = refs.break_lc_tickbase_slot_refs[slot_index]
                    if slot_ref ~= nil then
                        slot_ref:set(2)
                    end
                end
            end,
            true
        )

        local randomize_button = gear:button(
            icons.get("shuffle", 1, 1, "{Link Active}") .. "Randomize",
            function()
                local count = refs.break_lc_tickbase_sliders_ref:get()
                if type(count) ~= "number" then
                    count = 3
                end
                count = math.floor(count)
                if count < 2 then
                    count = 2
                elseif count > 8 then
                    count = 8
                end

                for slot_index = 1, count do
                    local slot_ref = refs.break_lc_tickbase_slot_refs[slot_index]
                    if slot_ref ~= nil then
                        slot_ref:set(math.random(2, 22))
                    end
                end
            end,
            true
        )

        local function sync_break_lc_tickbase_visibility()
            local enabled = refs.break_lc_custom_tickbase_enabled_ref:get() == true
            local randomize_enabled = refs.break_lc_tickbase_randomize_ref:get() == true
            local type_name = get_break_lc_tickbase_type_name(
                refs.break_lc_tickbase_type_ref:get()
            )
            local use_ways = randomize_enabled == true and type_name == "Ways"
            local slot_count = refs.break_lc_tickbase_sliders_ref:get()
            if type(slot_count) ~= "number" then
                slot_count = 3
            end
            slot_count = math.floor(slot_count)
            if slot_count < 2 then
                slot_count = 2
            elseif slot_count > 8 then
                slot_count = 8
            end

            custom_tickbase_label:disabled(false)
            custom_tickbase_toggle:name(
                make_condition_toggle_name(
                    enabled,
                    team_index,
                    condition_index,
                    "break_lc_tickbase"
                )
            )

            refs.break_lc_tickbase_randomize_ref:disabled(not enabled)
            refs.break_lc_tickbase_choke_ref:visibility(
                not randomize_enabled
            )
            refs.break_lc_tickbase_choke_ref:disabled(not enabled)
            refs.break_lc_tickbase_type_ref:visibility(randomize_enabled)
            refs.break_lc_tickbase_type_ref:disabled(not enabled)
            refs.break_lc_tickbase_random_min_ref:visibility(
                randomize_enabled and not use_ways
            )
            refs.break_lc_tickbase_random_min_ref:disabled(not enabled)
            refs.break_lc_tickbase_random_max_ref:visibility(
                randomize_enabled and not use_ways
            )
            refs.break_lc_tickbase_random_max_ref:disabled(not enabled)
            refs.break_lc_tickbase_sliders_ref:visibility(use_ways)
            refs.break_lc_tickbase_sliders_ref:disabled(not enabled)

            for slot_index = 1, 8 do
                local slot_ref = refs.break_lc_tickbase_slot_refs[slot_index]
                if slot_ref ~= nil then
                    slot_ref:visibility(use_ways and slot_index <= slot_count)
                    slot_ref:disabled(not enabled)
                end
            end

            reset_button:visibility(use_ways)
            reset_button:disabled(not enabled)
            randomize_button:visibility(use_ways)
            randomize_button:disabled(not enabled)
        end

        refs.break_lc_custom_tickbase_enabled_ref:set_callback(
            sync_break_lc_tickbase_visibility,
            true
        )
        refs.break_lc_tickbase_randomize_ref:set_callback(
            sync_break_lc_tickbase_visibility
        )
        refs.break_lc_tickbase_type_ref:set_callback(
            sync_break_lc_tickbase_visibility
        )
        refs.break_lc_tickbase_sliders_ref:set_callback(
            sync_break_lc_tickbase_visibility
        )

        return refs
    end

