    do
        local ffi_ok, ffi_lib = pcall(require, "ffi")
        if ffi_ok and ffi_lib ~= nil then
            pcall(ffi_lib.cdef, [[
        typedef struct {
          long left;
          long top;
          long right;
          long bottom;
        } RECT;
        void* SetCursor(void* hCursor);
        int SetCursorPos(int X, int Y);
        void* GetForegroundWindow(void);
        int GetWindowRect(void* hWnd, RECT* lpRect);
        int ClipCursor(const RECT* lpRect);
      ]])

            local ok_set_cursor = pcall(function()
                return ffi_lib.C.SetCursor
            end)
            local ok_set_cursor_pos = pcall(function()
                return ffi_lib.C.SetCursorPos
            end)
            local ok_get_foreground = pcall(function()
                return ffi_lib.C.GetForegroundWindow
            end)
            local ok_get_window_rect = pcall(function()
                return ffi_lib.C.GetWindowRect
            end)
            local ok_clip_cursor = pcall(function()
                return ffi_lib.C.ClipCursor
            end)

            mouse_override_state.ffi_ready = (
                ok_set_cursor
                and ok_set_cursor_pos
                and ok_get_foreground
                and ok_get_window_rect
                and ok_clip_cursor
            )

            if mouse_override_state.ffi_ready then
                mouse_override_state.ffi = ffi_lib
                mouse_override_state.null_cursor = ffi_lib.cast("void*", 0)
                mouse_override_state.clip_rect = ffi_lib.new("RECT[1]")
            end
        end
    end

