    local function get_condition_enabled_state(team_index, condition_index)
        local team_view = condition_views[team_index]
        if team_view == nil then
            return true
        end

        local condition_view = team_view[condition_index]
        if condition_view == nil then
            return true
        end

        local ref = condition_view.enabled_ref
        if ref == nil then
            return true
        end

        return ref:get() == true
    end

    local function set_condition_enabled_state(team_index, condition_index, state)
        local team_view = condition_views[team_index]
        if team_view == nil then
