    local function hide_condition_groups(view)
        set_condition_groups_visibility(view, false, false)
        set_condition_groups_visibility(view, false, true)
    end

    local function hide_all_condition_views()
        for team_index = 1, #condition_views do
            local team_view = condition_views[team_index]
            if team_view ~= nil then
                for condition_index = 1, #team_view do
                    local view = team_view[condition_index]
                    if view ~= nil then
                        hide_condition_groups(view)
                    end
                end
            end
        end
    end

    local function update_team_visibility(selected_index)
        for team_index = 1, #team_groups do
            local visible = (
                layout_state.is_builder_visible
                and layout_state.is_condition_menu_open ~= true
                and team_index == selected_index
            )
            team_groups[team_index]:visibility(visible)
            weapon_switch_groups[team_index]:visibility(visible)
        end
    end

