        STATE_REF_KEYS[#STATE_REF_KEYS + 1] = "left_yaw_crouch_" .. direction_key .. "_ref"
        STATE_REF_KEYS[#STATE_REF_KEYS + 1] = "right_yaw_crouch_" .. direction_key .. "_ref"
    end
    for tickbase_index = 1, 8 do
        STATE_REF_KEYS[#STATE_REF_KEYS + 1] = "break_lc_tickbase_" .. tickbase_index .. "_ref"
    end

    local function sanitize_clipboard_label(value)
        if type(value) ~= "string" then
            return "unknown"
        end

        local text = value:lower()
        text = text:gsub("%s+", "_")
        text = text:gsub("[^%w%-%_]", "")
        text = text:gsub("_+", "_")
        text = text:gsub("^_+", "")
        text = text:gsub("_+$", "")

        if text == "" then
            return "unknown"
        end

        return text
    end

    local function make_state_clipboard_header(team_index, condition_index)
        return CLIPBOARD_STATE_PREFIX
            .. sanitize_clipboard_label(mode_names[team_index])
            .. "_"
            .. sanitize_clipboard_label(condition_names[condition_index])
    end

    local function encode_state_clipboard_payload(payload)
        return storage_codec.encode(payload)
    end

    local function decode_state_clipboard_payload(raw)
        local payload = storage_codec.decode(raw)
        if payload ~= nil then
            return payload
        end

        local ok_json, legacy_payload = pcall(json.parse, raw)
        if not ok_json or type(legacy_payload) ~= "table" then
            return nil
        end

        return legacy_payload
    end

    local function encode_state_payload(payload, team_index, condition_index)
        local encoded = encode_state_clipboard_payload(payload)
        if encoded == nil then
            return nil
        end

        return make_state_clipboard_header(team_index, condition_index) .. ":" .. encoded
    end

    local function decode_state_payload(raw)
        if type(raw) ~= "string" or raw == "" then
            return nil
        end

        local split_index = raw:find(":", 1, true)
        if split_index == nil then
            return nil
        end

        local header = raw:sub(1, split_index - 1)
        if header:sub(1, #CLIPBOARD_STATE_PREFIX) ~= CLIPBOARD_STATE_PREFIX then
            return nil
        end

        local payload_raw = raw:sub(split_index + 1)
        if payload_raw == "" then
            return nil
        end

        return decode_state_clipboard_payload(payload_raw)
    end

    local function collect_state_payload_profile(team_index, condition_index, use_lc_profile)
        local team_view = condition_views[team_index]
        if team_view == nil then
            return nil
        end

        local view = team_view[condition_index]
        if view == nil then
            return nil
        end

        local payload = {
        }
        local has_values = false

        for index = 1, #STATE_REF_KEYS do
            local key = STATE_REF_KEYS[index]
            local ref = nil
            if use_lc_profile == true then
                if key == "enabled_ref" or key == "defensive_enabled_ref" then
                    ref = view[key]
                else
                    local lc_view = view.lc_runtime_view
                    if type(lc_view) == "table" then
                        ref = lc_view[key]
                    end
                end
            else
                ref = view[key]
            end
            if ref ~= nil and ref.get ~= nil then
                local ok_value, value = pcall(ref.get, ref)
                if ok_value then
                    payload[key] = clone_value(value)
                    has_values = true
                end
            end
        end

        if has_values ~= true then
            return nil
        end

        return payload
    end

    local function apply_state_payload_profile(
        team_index,
        condition_index,
        payload,
        use_lc_profile
    )
        if type(payload) ~= "table" then
            return
        end

        local team_view = condition_views[team_index]
        if team_view == nil then
            return
        end

        local view = team_view[condition_index]
        if view == nil then
            return
        end

        for index = 1, #STATE_REF_KEYS do
            local key = STATE_REF_KEYS[index]
            if payload[key] ~= nil then
                local ref = nil
                if use_lc_profile == true then
                    if key == "enabled_ref" or key == "defensive_enabled_ref" then
                        ref = view[key]
                    else
                        local lc_view = view.lc_runtime_view
                        if type(lc_view) == "table" then
                            ref = lc_view[key]
                        end
                    end
                else
                    ref = view[key]
                end
                if ref ~= nil and ref.set ~= nil then
                    pcall(ref.set, ref, clone_value(payload[key]))
                end
            end
        end
    end

    local function collect_state_payload(team_index, condition_index)
        local profiles = {
        }

        local builder_payload = collect_state_payload_profile(
            team_index,
            condition_index,
            false
        )
        if type(builder_payload) == "table" then
            profiles.builder = builder_payload
        end

        local defensive_payload = collect_state_payload_profile(
            team_index,
            condition_index,
            true
        )
        if type(defensive_payload) == "table" then
            profiles.defensive = defensive_payload
        end

        if next(profiles) == nil then
            return nil
        end

        local payload = {
            __aesthetic_profiles = profiles,
            __aesthetic_profiles_version = 1,
        }

        return payload
    end

    local function apply_state_payload(team_index, condition_index, payload)
        if type(payload) ~= "table" then
            return
        end

        local profiles = payload.__aesthetic_profiles
        if type(profiles) == "table" then
            if type(profiles.builder) == "table" then
                apply_state_payload_profile(
                    team_index,
                    condition_index,
                    profiles.builder,
                    false
                )
            end

            if type(profiles.defensive) == "table" then
                apply_state_payload_profile(
                    team_index,
                    condition_index,
                    profiles.defensive,
                    true
                )
            end

            return
        end

        apply_state_payload_profile(
            team_index,
            condition_index,
            payload,
            layout_state.is_defensive_builder_open == true
        )
    end

    local send_all_to_opposite_button = nil

    local function make_send_all_button_name()
        local source_team_index = mode_list:get()
        local target_team_index = get_opposite_team_index_from(source_team_index)
        local accent_color = mode_icon_colors[target_team_index]
        if type(accent_color) ~= "string" then
            accent_color = "{Link Active}"
        end

        return icons.get("arrows-repeat", 3, 4, accent_color)
            .. "Transfer all states to "
            .. "\a"
            .. accent_color
            .. "opposite team\aDEFAULT    "
    end

    local function update_send_all_button_name()
        if send_all_to_opposite_button == nil then
            return
        end

        send_all_to_opposite_button:name(make_send_all_button_name())
    end

    send_all_to_opposite_button = transfer_group:button(
        make_send_all_button_name(),
        function()
            sounds.play(sounds.press)

            local source_team_index = mode_list:get()
            if source_team_index ~= team.ct and source_team_index ~= team.t then
                prints.error("Invalid team selected")
                return
            end

            local target_team_index = get_opposite_team_index_from(source_team_index)

            for condition_index = 1, #condition_names do
                local source_payload = collect_state_payload(source_team_index, condition_index)
                if source_payload ~= nil then
                    apply_state_payload(target_team_index, condition_index, source_payload)
                end
            end

            update_send_all_button_name()
            prints.success("All states sent to opposite team")
        end,
        true
    )

    update_nav_buttons = function()
        if to_opposite_button ~= nil then
            to_opposite_button:name(make_send_button_name())
            to_opposite_button:tooltip(make_send_button_tooltip())
        end

        if copy_button ~= nil then
            copy_button:name(
                icons.get("copy", 1, 1, "{Link Active}") .. "##copy_condition_button"
            )
        end

        if paste_button ~= nil then
            paste_button:name(
                icons.get("paste", 1, 1, "{Link Active}") .. "##paste_condition_button"
            )
        end

        for condition_index = 1, #condition_nav_buttons do
            local button = condition_nav_buttons[condition_index]
            if button ~= nil then
                local is_current = condition_index == layout_state.active_condition_index
                local is_enabled = get_condition_enabled_state(
                    layout_state.active_team_index,
                    condition_index
                )
                button:visibility(true)
                button:name(make_nav_button_name(condition_index, is_current))
                button:disabled(not is_enabled)
                button:tooltip(
                    "Team: "
                    .. mode_names[layout_state.active_team_index]
                    .. "\nCondition: "
                    .. condition_names[condition_index]
                )
            end
        end
    end

    for condition_index = 1, #condition_names do
        condition_nav_buttons[condition_index] = portal_group:button(
            make_nav_button_name(condition_index, false),
            function()
                if layout_state.active_condition_index == condition_index and layout_state.is_condition_menu_open == true then
                    return
                end
                sounds.play(sounds.press)
                open_condition_settings(layout_state.active_team_index, condition_index)
                update_nav_buttons()
            end,
            true
        )
    end

    to_opposite_button = portal_group:button(
        make_send_button_name(),
        function()
            sounds.play(sounds.press)

            local source_payload = collect_state_payload(
                layout_state.active_team_index,
                layout_state.active_condition_index
            )
            if source_payload == nil then
                prints.error("Failed to collect current state data")
                return
            end

            local target_team_index = get_opposite_team_index()
            apply_state_payload(
                target_team_index,
                layout_state.active_condition_index,
                source_payload
            )
            update_nav_buttons()
            prints.success("Current state sent to opposite team")
        end,
