    copy_button = portal_group:button(
        icons.get("copy", 1, 1, "{Link Active}") .. "##copy_condition_button",
        function()
            local payload = collect_state_payload(
                layout_state.active_team_index,
                layout_state.active_condition_index
            )
            if payload == nil then
                prints.error("Failed to collect current state data")
                return
            end

            local encoded = encode_state_payload(
                payload,
                layout_state.active_team_index,
                layout_state.active_condition_index
            )
            if encoded == nil then
                prints.error("Failed to encode state data")
                return
