            clipboard.set(encoded)
            prints.confirm("State copied to clipboard")
        end,
        true
    )
    copy_button:tooltip(tooltip.copy)

    paste_button = portal_group:button(
        icons.get("paste", 1, 1, "{Link Active}") .. "##paste_condition_button",
        function()
            local raw = clipboard.get()
            local payload = decode_state_payload(raw)
            if payload == nil then
                prints.error("Invalid or empty clipboard state data")
                return
            end

            apply_state_payload(
                layout_state.active_team_index,
                layout_state.active_condition_index,
