    local function create_crouch_direction_override_refs(
        yaw_ref,
        min_value,
        max_value,
        key_resolver,
        side_key
    )
        if yaw_ref == nil or key_resolver == nil or type(side_key) ~= "string" then
            return nil, nil
        end

        local gear = yaw_ref:create()
        if gear == nil then
            return nil, nil
        end

        local directions_ref = config.push(
            gear:selectable(
                ui_symbols.prefix_dot .. "   Directions",
                CROUCH_MOVE_DIRECTION_NAMES
            ),
            key_resolver(side_key .. "_yaw_crouch_directions")
        )

        local direction_refs = {
        }
        for direction_index = 1, #CROUCH_MOVE_DIRECTION_OVERRIDES do
            local direction_data = CROUCH_MOVE_DIRECTION_OVERRIDES[direction_index]
            direction_refs[direction_data.name] = config.push(
                gear:slider(
                    ui_symbols.prefix_arrow .. "   " .. direction_data.name,
                    min_value,
                    max_value,
                    0
                ),
                key_resolver(side_key .. "_yaw_crouch_" .. direction_data.key)
            )
        end

        local function is_direction_enabled(direction_name)
            if directions_ref == nil then
                return false
            end

            local ok_named, named = pcall(directions_ref.get, directions_ref, direction_name)
            if ok_named and type(named) == "boolean" then
                return named
            end

            local ok_list, list = pcall(directions_ref.get, directions_ref)
            if not ok_list or type(list) ~= "table" then
                return false
            end

            for list_index = 1, #list do
                if list[list_index] == direction_name then
                    return true
                end
            end

            return false
        end

        local function update_direction_visibility()
            for direction_index = 1, #CROUCH_MOVE_DIRECTION_OVERRIDES do
                local direction_data = CROUCH_MOVE_DIRECTION_OVERRIDES[direction_index]
                local direction_ref = direction_refs[direction_data.name]
                if direction_ref ~= nil then
                    direction_ref:visibility(
                        is_direction_enabled(direction_data.name)
                    )
                end
            end
        end

        if directions_ref ~= nil then
            directions_ref:set_callback(update_direction_visibility, true)
        end

        return directions_ref, direction_refs
    end

    local function attach_crouch_direction_view_refs(view, side_key, directions_ref, direction_refs)
        if type(view) ~= "table" or type(side_key) ~= "string" then
            return
        end

        view[side_key .. "_yaw_crouch_dirs_ref"] = directions_ref
        view[side_key .. "_yaw_crouch_dir_refs"] = direction_refs

        for direction_index = 1, #CROUCH_MOVE_DIRECTION_OVERRIDES do
            local direction_data = CROUCH_MOVE_DIRECTION_OVERRIDES[direction_index]
            local direction_ref = nil
            if type(direction_refs) == "table" then
                direction_ref = direction_refs[direction_data.name]
            end
            view[side_key .. "_yaw_crouch_" .. direction_data.key .. "_ref"] = direction_ref
        end
    end

