    local function clamp_number(value, min_value, max_value)
        if value < min_value then
            return min_value
        end

        if value > max_value then
            return max_value
        end

        return value
    end

    local function get_jitter_state(team_index, condition_index)
        local team_state = jitter_runtime_state[team_index]
        if type(team_state) ~= "table" then
            team_state = {
            }
            jitter_runtime_state[team_index] = team_state
        end

        local condition_state = team_state[condition_index]
        if type(condition_state) ~= "table" then
            condition_state = {
                side = rage.antiaim:inverter() == true,
                next_switch_packet = runtime_state.sent_packets + 1,
                next_return_packet = runtime_state.sent_packets + 11,
                return_end_packet = 0,
                return_resume_side = rage.antiaim:inverter() == true,
                return_resume_delay = 1,
                return_offset = 0,
                switch_count = 0,
                trap_switches_left = 0,
                trap_next_check_packet = runtime_state.sent_packets + 1,
            }
            team_state[condition_index] = condition_state
        end

        return condition_state
    end

    local function get_body_yaw_state(team_index, condition_index)
        local team_state = body_yaw_runtime_state[team_index]
        if type(team_state) ~= "table" then
            team_state = {
            }
            body_yaw_runtime_state[team_index] = team_state
        end

        local condition_state = team_state[condition_index]
        if type(condition_state) ~= "table" then
            condition_state = {
                switch_state = false,
                switch_packets = 0,
                switch_last_flip = 0,
            }
            team_state[condition_index] = condition_state
        end

        return condition_state
    end

    local function find_closest_body_delay_index(delay)
        local closest_index = 1
        local closest_delta = math.huge

        for index = 1, #BODY_DELAY_DISCRETE_VALUES do
            local delta = math.abs(delay - BODY_DELAY_DISCRETE_VALUES[index])
            if delta < closest_delta then
                closest_delta = delta
                closest_index = index
            end
        end

        return closest_index
    end

    local function get_random_body_delay(base_delay, variability)
        local delay = clamp_number(math.floor(base_delay or 1), 1, 20)
        local var = clamp_number(variability or 0, 0, 100)
        if delay <= 1 or var <= 0 then
            return delay
        end

        local closest_index = find_closest_body_delay_index(delay)
        local values_count = #BODY_DELAY_DISCRETE_VALUES
        local span = math.floor(values_count * var / 200 + 0.5)
        local min_index = math.max(1, closest_index - span)
        local max_index = math.min(values_count, closest_index + span)

        return BODY_DELAY_DISCRETE_VALUES[math.random(min_index, max_index)]
    end

    local function update_body_yaw_flipper(
        body_yaw_state,
        key,
        base_delay,
        variability
    )
        local state_key = key .. "_state"
        local packets_key = key .. "_packets"
        local last_flip_key = key .. "_last_flip"

        if globals.choked_commands ~= 0 then
            return body_yaw_state[state_key] == true
        end

        body_yaw_state[packets_key] = body_yaw_state[packets_key] + 1

        local delay = clamp_number(math.floor(base_delay or 1), 1, 20)
        if (variability or 0) > 0 then
            delay = get_random_body_delay(delay, variability)
        end

        local ticks_from_flip = body_yaw_state[packets_key] - body_yaw_state[last_flip_key]
        if ticks_from_flip >= delay then
            body_yaw_state[state_key] = not body_yaw_state[state_key]
            body_yaw_state[last_flip_key] = body_yaw_state[packets_key]
        end

        return body_yaw_state[state_key] == true
    end

    local function find_closest_discrete_delay_index(delay)
        local closest_index = 1
        local closest_delta = math.huge

        for index = 1, #DELAY_DISCRETE_VALUES do
            local delta = math.abs(delay - DELAY_DISCRETE_VALUES[index])
            if delta < closest_delta then
                closest_delta = delta
                closest_index = index
            end
        end

        return closest_index
    end

    local function get_jitter_delay(base_delay, delay_variability)
        local delay = clamp_number(math.floor(base_delay), 1, 16)
        local variability = 0
        if type(delay_variability) == "number" then
            variability = clamp_number(delay_variability, 0, 100)
        end

        if delay <= 1 or variability <= 0 then
            return delay
        end

        local closest_index = find_closest_discrete_delay_index(delay)
        local values_count = #DELAY_DISCRETE_VALUES
        local span = math.floor(values_count * variability / 200 + 0.5)
        local min_index = math.max(1, closest_index - span)
        local max_index = math.min(values_count, closest_index + span)
        return clamp_number(DELAY_DISCRETE_VALUES[math.random(min_index, max_index)], 1, 16)
    end

    local function get_return_delay_value(base_delay, delay_variability)
        local delay = clamp_number(math.floor(base_delay), 2, 32)
        local variability = 0
        if type(delay_variability) == "number" then
            variability = clamp_number(delay_variability, 0, 100)
        end

        if variability <= 0 then
            return delay
        end

        local span = math.floor(30 * variability / 200 + 0.5)
        if span <= 0 then
            return delay
        end

        return math.random(
            math.max(2, delay - span),
            math.min(32, delay + span)
        )
    end

    local function reset_antiaim_view_sync()
        antiaim_runtime_state.last_team_index = nil
        antiaim_runtime_state.last_condition_index = nil
        antiaim_runtime_state.last_defensive_view = false

        if rage ~= nil and rage.antiaim ~= nil and rage.antiaim.inverter ~= nil then
            antiaim_runtime_state.last_side = rage.antiaim:inverter() == true
            return
        end

        antiaim_runtime_state.last_side = nil
    end

    local function sync_jitter_side_on_view_change(
        condition_view,
        team_index,
        condition_index,
        is_defensive_view
    )
        if condition_view == nil then
            return
        end

        local view_changed = antiaim_runtime_state.last_team_index ~= team_index
            or antiaim_runtime_state.last_condition_index ~= condition_index
            or antiaim_runtime_state.last_defensive_view ~= is_defensive_view
        if view_changed ~= true then
            return
        end

        local mode_value = jitter_mode.jitter
        if condition_view.jitter_mode_ref ~= nil then
            mode_value = condition_view.jitter_mode_ref:get()
        end

        local side_mode = jitter_mode.jitter
        if mode_value == jitter_mode.static or mode_value == "Static" then
            side_mode = jitter_mode.static
        elseif mode_value == jitter_mode.return_mode or mode_value == "Return" then
            side_mode = jitter_mode.return_mode
        end
        if side_mode == jitter_mode.static then
            return
        end

        local synced_side = antiaim_runtime_state.last_side
        if type(synced_side) ~= "boolean" then
            synced_side = rage.antiaim:inverter() == true
        end

        local delay = 1
        if condition_view.jitter_delay_ref ~= nil then
            local value = condition_view.jitter_delay_ref:get()
            if type(value) == "number" then
                delay = value
            end
        end

        local delay_variability = 0
        if condition_view.jitter_delay_variability_ref ~= nil then
            local value = condition_view.jitter_delay_variability_ref:get()
            if type(value) == "number" then
                delay_variability = value
            end
        end

        local return_delay = 11
        if condition_view.return_delay_ref ~= nil then
            local value = condition_view.return_delay_ref:get()
            if type(value) == "number" then
                return_delay = clamp_number(math.floor(value), 2, 32)
            end
        end

        local return_delay_variability = 0
        if condition_view.return_delay_variability_ref ~= nil then
            local value = condition_view.return_delay_variability_ref:get()
            if type(value) == "number" then
                return_delay_variability = value
            end
        end

        local jitter_state = get_jitter_state(team_index, condition_index)
        jitter_state.side = synced_side
        jitter_state.switch_count = 0
        jitter_state.trap_switches_left = 0
        jitter_state.next_switch_packet = runtime_state.sent_packets + get_jitter_delay(delay, delay_variability)
        jitter_state.trap_next_check_packet = runtime_state.sent_packets + clamp_number(math.floor(delay), 1, 16)
        jitter_state.next_return_packet = runtime_state.sent_packets + get_return_delay_value(
            return_delay,
            return_delay_variability
        )
        jitter_state.return_end_packet = 0
        jitter_state.return_resume_side = synced_side
        jitter_state.return_resume_delay = clamp_number(math.floor(delay), 1, 16)
        jitter_state.return_offset = 0
    end

    local function get_should_invert_with_chance(
        invert_chance,
        team_index,
        condition_index,
        switch_count
    )
        if invert_chance >= 100 then
            return true
        end

        if invert_chance <= 0 then
            return false
        end

        local seed = switch_count * 83
            + team_index * 23
            + condition_index * 17
            + runtime_state.sent_packets * 3
        local roll = math.floor((math.sin(seed) * 0.5 + 0.5) * 99) + 1
        return roll <= invert_chance
    end

    local function get_side_trap_burst_length(team_index, condition_index, switch_count)
        local seed = switch_count * 61
            + team_index * 29
            + condition_index * 13
            + runtime_state.sent_packets
        local unit = math.sin(seed * 7.913 + 14.579) * 19341.221
        local normalized = unit - math.floor(unit)
        return 2 + math.floor(normalized * 3)
    end

