    local hidden_defensive_state = angles_builder.hidden_defensive_state
    local HIDDEN_DEFENSIVE_THREE_WAY_DEFAULTS = {
        -90,
        180,
        90,
    }
    local HIDDEN_DEFENSIVE_FIVE_WAY_DEFAULTS = {
