    }

    local function reset_hidden_defensive_state()
        hidden_defensive_state.is_overriding = false
        hidden_defensive_state.last_packet = -1
        hidden_defensive_state.pitch_switch_flip = false
        hidden_defensive_state.pitch_switch_packets = 0
        hidden_defensive_state.yaw_flip = false
        hidden_defensive_state.yaw_step_index = 1
        hidden_defensive_state.yaw_step_packets = 0
    end

    local function clear_hidden_defensive_overrides()
        if hidden_defensive_state.is_overriding ~= true then
            return
        end

        reset_hidden_defensive_state()

        local angles = nl.aa and nl.aa.angles
        if angles ~= nil and angles.hidden ~= nil then
            angles.hidden:override()
