    local function get_hidden_defensive_number(item, fallback)
        if item == nil then
            return fallback
        end

        local value = item:get()
        if type(value) ~= "number" then
            return fallback
        end

        return value
    end

    local function get_hidden_defensive_mode(item, fallback)
        if item == nil then
            return fallback
        end

        local value = item:get()
        if type(value) ~= "string" or value == "" then
            return fallback
        end

        return value
    end

    local function get_hidden_defensive_range(
        min_ref,
        max_ref,
        default_min,
        default_max,
        min_limit,
        max_limit
    )
        local min_value = clamp_number(
            get_hidden_defensive_number(min_ref, default_min),
            min_limit,
            max_limit
        )
        local max_value = clamp_number(
            get_hidden_defensive_number(max_ref, default_max),
            min_limit,
            max_limit
        )
        if min_value > max_value then
            min_value, max_value = max_value, min_value
        end

        return min_value, max_value
    end

    local function update_hidden_defensive_packet_state()
        local packet = runtime_state.sent_packets
        if type(packet) ~= "number" then
            packet = 0
        end

        if hidden_defensive_state.last_packet == packet then
            return false
        end

        hidden_defensive_state.last_packet = packet
        hidden_defensive_state.yaw_flip = not hidden_defensive_state.yaw_flip
        return true
    end

    local function is_hidden_defensive_enabled()
        local refs = angles_builder.hidden_defensive_refs
        if refs.enabled == nil then
            return false
        end

        return refs.enabled:get() == true
    end

    local function is_hidden_defensive_freestanding_active()
        local freestanding_ref = nl.aa and nl.aa.angles and nl.aa.angles.freestanding
        if freestanding_ref ~= nil and freestanding_ref.get_override ~= nil then
            local override = freestanding_ref:get_override()
            if type(override) == "boolean" then
                return override == true
            end
        end

        return angles_builder.freestanding_requested == true
            or angles_builder.freestanding_active == true
    end

    local function is_hidden_defensive_selectable_enabled(reference, value)
        if reference == nil or type(value) ~= "string" then
            return false
        end

        local ok_named, named = pcall(reference.get, reference, value)
        if ok_named and type(named) == "boolean" then
            return named
        end

        local ok_list, list = pcall(reference.get, reference)
        if not ok_list or type(list) ~= "table" then
            return false
        end

        for index = 1, #list do
            if list[index] == value then
                return true
            end
        end

        return false
    end

    local function is_hidden_defensive_manual_active()
        if mouse_override_state.yaw_value ~= nil then
            return true
        end

        return angles_builder.manual_yaw_toggle_state.left == true
            or angles_builder.manual_yaw_toggle_state.forward == true
            or angles_builder.manual_yaw_toggle_state.right == true
    end

    local function is_hidden_defensive_safe_head_active()
        if safe_head_controller == nil or safe_head_controller.is_active == nil then
            return false
        end

        return safe_head_controller.is_active() == true
    end

    local function is_hidden_defensive_default_override_active()
        return is_hidden_defensive_manual_active()
            or is_hidden_defensive_freestanding_active()
            or is_hidden_defensive_safe_head_active()
    end

    local function is_hidden_defensive_disabler_active()
        local refs = angles_builder.hidden_defensive_refs
        if refs.disablers == nil then
            return false
        end

        if is_hidden_defensive_selectable_enabled(refs.disablers, "Manual AA")
            and is_hidden_defensive_manual_active() then
            return true
        end

        if is_hidden_defensive_selectable_enabled(refs.disablers, "Freestanding")
            and is_hidden_defensive_freestanding_active() then
            return true
        end

        if is_hidden_defensive_selectable_enabled(refs.disablers, "Safe Head")
            and is_hidden_defensive_safe_head_active() then
            return true
        end

        return false
    end

    local function resolve_hidden_defensive_pitch(packet_advanced)
        local refs = angles_builder.hidden_defensive_refs.pitch
        local mode = get_hidden_defensive_mode(refs.mode, "Disabled")

        if mode ~= "Switch" then
            hidden_defensive_state.pitch_switch_flip = false
            hidden_defensive_state.pitch_switch_packets = 0
        end

        if mode == "Static" then
            return clamp_number(
                get_hidden_defensive_number(refs.static_value, 0),
                -89,
                89
            )
        end

        if mode == "Random" then
            local min_value, max_value = get_hidden_defensive_range(
                refs.random_min,
                refs.random_max,
                -89,
                89,
                -89,
                89
            )
            return utils.random_float(min_value, max_value)
        end

        if mode == "Sway" then
            local min_value, max_value = get_hidden_defensive_range(
                refs.sway_min,
                refs.sway_max,
                -89,
                89,
                -89,
                89
            )
            local speed = clamp_number(
                get_hidden_defensive_number(refs.sway_speed, 30),
                1,
                200
            ) * 0.1
            local sway_time = globals.realtime
            if type(sway_time) ~= "number" then
                sway_time = 0
            end
            return math.map(
                math.sin(sway_time * speed),
                -1,
                1,
                min_value,
                max_value,
                true
            )
        end

        if mode == "Switch" then
            local first_value = clamp_number(
                get_hidden_defensive_number(refs.switch_first, -89),
                -89,
                89
            )
            local second_value = clamp_number(
                get_hidden_defensive_number(refs.switch_second, 89),
                -89,
                89
            )
            local delay = clamp_number(
                math.floor(get_hidden_defensive_number(refs.switch_delay, 1)),
                1,
                16
            )

            if packet_advanced then
                hidden_defensive_state.pitch_switch_packets =
                    hidden_defensive_state.pitch_switch_packets + 1

                if hidden_defensive_state.pitch_switch_packets > delay then
                    hidden_defensive_state.pitch_switch_packets = 1
                    hidden_defensive_state.pitch_switch_flip =
                        not hidden_defensive_state.pitch_switch_flip
                end
            end

            if hidden_defensive_state.pitch_switch_flip == true then
                return second_value
            end

            return first_value
        end

        return 0
    end

    local function resolve_hidden_defensive_yaw(side, packet_advanced)
        local refs = angles_builder.hidden_defensive_refs.yaw
        local mode = get_hidden_defensive_mode(refs.mode, "Disabled")

        if mode ~= "3-Way" and mode ~= "5-Way" then
            hidden_defensive_state.yaw_step_index = 1
            hidden_defensive_state.yaw_step_packets = 0
        end

        if mode == "Random" then
            local min_value, max_value = get_hidden_defensive_range(
                refs.random_min,
                refs.random_max,
                -180,
                180,
                -180,
                180
            )
            return math.normalize_yaw(utils.random_int(min_value, max_value))
        end

        if mode == "Sideways" then
            local min_value, max_value = get_hidden_defensive_range(
                refs.sideways_min,
                refs.sideways_max,
                60,
                120,
                1,
                180
            )
            local yaw_value = utils.random_int(min_value, max_value)
            if hidden_defensive_state.yaw_flip == true then
                yaw_value = -yaw_value
            end

            return math.normalize_yaw(yaw_value)
        end

        if mode == "Opposite" then
            local min_value, max_value = get_hidden_defensive_range(
                refs.opposite_min,
                refs.opposite_max,
                150,
                210,
                90,
                270
            )
            return math.normalize_yaw(utils.random_int(min_value, max_value))
        end

        if mode == "Opposite Jitter" then
            local min_value, max_value = get_hidden_defensive_range(
                refs.opposite_min,
                refs.opposite_max,
                135,
                225,
                90,
                270
            )
            local yaw_value = 180
            if hidden_defensive_state.yaw_flip == true then
                local left_max = math.min(180, max_value)
                local left_min = math.min(min_value, left_max)
                yaw_value = utils.random_int(left_min, left_max)
            else
                local right_min = math.max(180, min_value)
                local right_max = math.max(right_min, max_value)
                yaw_value = utils.random_int(right_min, right_max)
            end

            return math.normalize_yaw(yaw_value)
        end

        if mode == "Side-Based" then
            local min_value, max_value = get_hidden_defensive_range(
                refs.side_based_min,
                refs.side_based_max,
                75,
                105,
                1,
                180
            )
            local yaw_value = utils.random_int(min_value, max_value)
            if side == true then
                yaw_value = -yaw_value
            end

            return math.normalize_yaw(yaw_value)
        end

        if mode == "Spinbot" then
            local speed = clamp_number(
                get_hidden_defensive_number(refs.spin_speed, 30),
                1,
                90
            )
            local randomness = clamp_number(
                get_hidden_defensive_number(refs.spin_randomness, 0),
                0,
                90
            )
            local tickcount = globals.tickcount
            if type(tickcount) ~= "number" then
                tickcount = 0
            end
            local yaw_value = math.normalize_yaw(
                ((tickcount * speed) % 360) - 180
            )
            if randomness > 0 then
                yaw_value = math.normalize_yaw(
                    yaw_value + utils.random_float(-randomness, randomness)
                )
            end

            return yaw_value
        end

        if mode == "3-Way" or mode == "5-Way" then
            local step_refs = refs.three_way
            local fallback_values = HIDDEN_DEFENSIVE_THREE_WAY_DEFAULTS
            local step_count = 3

            if mode == "5-Way" then
                step_refs = refs.five_way
                fallback_values = HIDDEN_DEFENSIVE_FIVE_WAY_DEFAULTS
                step_count = 5
            end

            local delay = clamp_number(
                math.floor(get_hidden_defensive_number(refs.step_delay, 1)),
                1,
                2
            )

            if hidden_defensive_state.yaw_step_index > step_count then
                hidden_defensive_state.yaw_step_index = 1
            end

            if packet_advanced then
                hidden_defensive_state.yaw_step_packets =
                    hidden_defensive_state.yaw_step_packets + 1

                if hidden_defensive_state.yaw_step_packets > delay then
                    hidden_defensive_state.yaw_step_packets = 1
                    hidden_defensive_state.yaw_step_index =
                        hidden_defensive_state.yaw_step_index + 1
                    if hidden_defensive_state.yaw_step_index > step_count then
                        hidden_defensive_state.yaw_step_index = 1
                    end
                end
            end

            return math.normalize_yaw(clamp_number(
                get_hidden_defensive_number(
                    step_refs[hidden_defensive_state.yaw_step_index],
                    fallback_values[hidden_defensive_state.yaw_step_index]
                ),
                -180,
                180
            ))
        end

        return 0
    end

    local function apply_hidden_defensive_overrides(side)
        if is_hidden_defensive_enabled() ~= true
            or runtime_state.is_defensive_active ~= true then
            clear_hidden_defensive_overrides()
            return false
        end

        local angles = nl.aa and nl.aa.angles
        if angles == nil
            or angles.hidden == nil
            or rage == nil
            or rage.antiaim == nil
            or rage.antiaim.override_hidden_yaw_offset == nil
            or rage.antiaim.override_hidden_pitch == nil then
            clear_hidden_defensive_overrides()
            return false
        end

        local packet_advanced = update_hidden_defensive_packet_state()
        local yaw_value = 180
        local pitch_value = 0

        if is_hidden_defensive_disabler_active() == true then
            clear_hidden_defensive_overrides()
            return false
        end

        local safe_head_hidden_yaw = nil
        local safe_head_hidden_pitch = nil
        if is_hidden_defensive_safe_head_active() == true
            and safe_head_controller ~= nil
            and safe_head_controller.get_hidden_override ~= nil then
            safe_head_hidden_yaw, safe_head_hidden_pitch = safe_head_controller.get_hidden_override()
        end

        if is_hidden_defensive_default_override_active() ~= true then
            yaw_value = resolve_hidden_defensive_yaw(side, packet_advanced)
            pitch_value = resolve_hidden_defensive_pitch(packet_advanced)
        elseif type(safe_head_hidden_yaw) == "number" then
            yaw_value = safe_head_hidden_yaw
            if type(safe_head_hidden_pitch) == "number" then
                pitch_value = safe_head_hidden_pitch
            end
        end

        angles.hidden:override(true)
        if yaw_value ~= 180 and yaw_value ~= -180 then
            yaw_value = math.normalize_yaw(yaw_value)
        end
        rage.antiaim:override_hidden_yaw_offset(yaw_value)
        rage.antiaim:override_hidden_pitch(clamp_number(pitch_value, -89, 89))
        hidden_defensive_state.is_overriding = true
        return true
    end

    local function get_inverter(condition_view, team_index, condition_index)
        if condition_view == nil then
            return rage.antiaim:inverter() == true, nil
        end

        local mode_value = jitter_mode.jitter
        if condition_view.jitter_mode_ref ~= nil then
            mode_value = condition_view.jitter_mode_ref:get()
        end

        local side_mode = jitter_mode.jitter
        if mode_value == jitter_mode.static or mode_value == "Static" then
            side_mode = jitter_mode.static
        elseif mode_value == jitter_mode.return_mode or mode_value == "Return" then
            side_mode = jitter_mode.return_mode
        end
        if side_mode == jitter_mode.static then
            if condition_view.static_inverter_ref ~= nil then
                return condition_view.static_inverter_ref:get() == true, nil
            end

            return rage.antiaim:inverter() == true, nil
        end

        local delay = 1
        if condition_view.jitter_delay_ref ~= nil then
            local value = condition_view.jitter_delay_ref:get()
            if type(value) == "number" then
                delay = value
            end
        end

        local delay_variability = 0
        if condition_view.jitter_delay_variability_ref ~= nil then
            local value = condition_view.jitter_delay_variability_ref:get()
            if type(value) == "number" then
                delay_variability = value
            end
        end

        local jitter_state = get_jitter_state(team_index, condition_index)

        if side_mode == jitter_mode.return_mode then
            local return_delay = 11
            if condition_view.return_delay_ref ~= nil then
                local value = condition_view.return_delay_ref:get()
                if type(value) == "number" then
                    return_delay = clamp_number(math.floor(value), 2, 32)
                end
            end

            local return_delay_variability = 0
            if condition_view.return_delay_variability_ref ~= nil then
                local value = condition_view.return_delay_variability_ref:get()
                if type(value) == "number" then
                    return_delay_variability = value
                end
            end

            local return_stay = 1
            if condition_view.return_stay_ref ~= nil then
                local value = condition_view.return_stay_ref:get()
                if type(value) == "number" then
                    return_stay = clamp_number(math.floor(value), 1, 16)
                end
            end

            local return_stay_variability = 0
            if condition_view.return_stay_variability_ref ~= nil then
                local value = condition_view.return_stay_variability_ref:get()
                if type(value) == "number" then
                    return_stay_variability = value
                end
            end

            local return_offset = 0
            if condition_view.return_offset_ref ~= nil then
                local value = condition_view.return_offset_ref:get()
                if type(value) == "number" then
                    return_offset = clamp_number(math.floor(value), -180, 180)
                end
            end

            local resume_mode = 1
            if condition_view.return_resume_ref ~= nil then
                local value = condition_view.return_resume_ref:get()
                if value == 2 or value == "Repeat Last" then
                    resume_mode = 2
                elseif value == 3 or value == "Force Opposite" then
                    resume_mode = 3
                end
            end

            if type(jitter_state.next_return_packet) ~= "number" then
                jitter_state.next_return_packet = runtime_state.sent_packets + get_return_delay_value(
                    return_delay,
                    return_delay_variability
                )
            end

            if type(jitter_state.return_end_packet) ~= "number" then
                jitter_state.return_end_packet = 0
            end

            if type(jitter_state.return_resume_side) ~= "boolean" then
                jitter_state.return_resume_side = jitter_state.side == true
            end

            if type(jitter_state.return_resume_delay) ~= "number" then
                jitter_state.return_resume_delay = clamp_number(math.floor(delay), 1, 16)
            end

            if runtime_state.sent_packets >= jitter_state.return_end_packet and jitter_state.return_end_packet > 0 then
                jitter_state.side = jitter_state.return_resume_side == true
                jitter_state.next_switch_packet = runtime_state.sent_packets + clamp_number(
                    math.floor(jitter_state.return_resume_delay),
                    1,
                    16
                )
                jitter_state.return_end_packet = 0
            end

            if jitter_state.return_end_packet > runtime_state.sent_packets then
                return jitter_state.side == true, jitter_state.return_offset
            end

            if globals.choked_commands ~= 0 then
                return jitter_state.side == true, nil
            end

            if runtime_state.sent_packets >= jitter_state.next_return_packet then
                local next_delay = get_jitter_delay(delay, delay_variability)
                local resume_side = jitter_state.side == true
                local resume_delay = next_delay

                if resume_mode == 2 then
                    resume_side = jitter_state.side == true
                elseif resume_mode == 3 then
                    resume_side = jitter_state.side ~= true
                else
                    local remaining_delay = jitter_state.next_switch_packet - runtime_state.sent_packets
                    if remaining_delay > 0 then
                        resume_side = jitter_state.side == true
                        resume_delay = clamp_number(math.floor(remaining_delay), 1, 16)
                    else
                        resume_side = jitter_state.side ~= true
                    end
                end

                local next_return_delay = get_return_delay_value(
                    return_delay,
                    return_delay_variability
                )
                local next_return_stay = get_jitter_delay(
                    return_stay,
                    return_stay_variability
                )

                jitter_state.return_resume_side = resume_side
                jitter_state.return_resume_delay = clamp_number(math.floor(resume_delay), 1, 16)
                jitter_state.return_offset = return_offset
                jitter_state.return_end_packet = runtime_state.sent_packets + next_return_stay
                jitter_state.next_return_packet = jitter_state.return_end_packet + next_return_delay

                return jitter_state.side == true, jitter_state.return_offset
            end

            if runtime_state.sent_packets >= jitter_state.next_switch_packet then
                jitter_state.side = not jitter_state.side
                jitter_state.switch_count = jitter_state.switch_count + 1
                jitter_state.next_switch_packet = runtime_state.sent_packets + get_jitter_delay(delay, delay_variability)
            end

            return jitter_state.side == true, nil
        end

        local side_random_chance = 0
        if condition_view.side_random_ref ~= nil then
            local value = condition_view.side_random_ref:get()
            if type(value) == "number" then
                side_random_chance = clamp_number(value, 0, 100)
            end
        end

        local side_trap_chance = 0
        if condition_view.side_trap_ref ~= nil then
            local value = condition_view.side_trap_ref:get()
            if type(value) == "number" then
                side_trap_chance = clamp_number(value, 0, 100)
            end
        end

        local trap_check_interval = clamp_number(math.floor(delay), 1, 16)
        if delay <= 1 then
            side_trap_chance = 0
        end

        if type(jitter_state.trap_next_check_packet) ~= "number" then
            jitter_state.trap_next_check_packet = runtime_state.sent_packets + trap_check_interval
        end

        if globals.choked_commands ~= 0 then
            return jitter_state.side == true, nil
        end

        if runtime_state.sent_packets >= jitter_state.next_switch_packet then
            local should_force_trap = jitter_state.trap_switches_left > 0
            if runtime_state.sent_packets >= jitter_state.trap_next_check_packet then
                jitter_state.trap_next_check_packet = runtime_state.sent_packets + trap_check_interval

                if should_force_trap ~= true and side_trap_chance > 0 then
                    local should_start_trap = get_should_invert_with_chance(
                        side_trap_chance,
                        team_index,
                        condition_index,
                        jitter_state.switch_count + 911
                    )
                    if should_start_trap then
                        jitter_state.trap_switches_left = get_side_trap_burst_length(
                            team_index,
                            condition_index,
                            jitter_state.switch_count
                        )
                        should_force_trap = jitter_state.trap_switches_left > 0
                    end
                end
            end

            local should_invert = true
            if should_force_trap ~= true and side_random_chance > 0 then
                should_invert = get_should_invert_with_chance(
                    side_random_chance,
                    team_index,
                    condition_index,
                    jitter_state.switch_count
                )
            end

            if should_invert then
                jitter_state.side = not jitter_state.side
            end

            if should_force_trap then
                jitter_state.trap_switches_left = math.max(
                    0,
                    jitter_state.trap_switches_left - 1
                )
            end

            jitter_state.switch_count = jitter_state.switch_count + 1
            local next_delay = get_jitter_delay(delay, delay_variability)
            if should_force_trap then
                next_delay = 1
            end
            jitter_state.next_switch_packet = runtime_state.sent_packets + next_delay
        end

        return jitter_state.side == true, nil
    end

    local function get_team_index(team_num)
        if team_num == 3 then
            return team.ct
        end

        if team_num == 2 then
            return team.t
        end

        return mode_list:get()
    end

    local function is_on_ground(flags)
        if type(flags) ~= "number" then
            return false
        end

        if bit ~= nil and bit.band ~= nil then
            return bit.band(flags, runtime_cfg.on_ground_flag) == runtime_cfg.on_ground_flag
        end

        return flags % 2 == 1
    end

    local function is_slow_walk_active()
        local ref = nl.aa and nl.aa.misc and nl.aa.misc.slow_walk
        if ref == nil then
            return false
        end

        return ref:get() == true
    end

    local function is_throwing_grenade(player)
        if player == nil then
            return false
        end

        local weapon = player:get_player_weapon()
        if weapon == nil then
            return false
        end

        local weapon_info = weapon:get_weapon_info()
        if weapon_info == nil then
            return false
        end

        local console_name = weapon_info.console_name
        if type(console_name) ~= "string" then
            return false
        end

        if GRENADE_CONSOLE_NAMES[console_name] ~= true then
            return false
        end

        local throw_time = weapon.m_fThrowTime
        if type(throw_time) ~= "number" then
            return false
        end

        return throw_time > 0
    end

    local function is_grenade_weapon(weapon)
        if weapon == nil then
            return false
        end

        local weapon_info = weapon:get_weapon_info()
        if weapon_info == nil then
            return false
        end

        return weapon_info.weapon_type == 9
    end

    local function get_condition_index(player, command)
        if player == nil then
            return condition.standing
        end

        local velocity = player.m_vecVelocity
        local velocity2d = 0
        if velocity ~= nil and velocity.length2d ~= nil then
            velocity2d = velocity:length2d()
        end

        local is_moving = velocity2d > runtime_cfg.moving_speed_threshold
        local duck_amount = player.m_flDuckAmount
        local is_crouched = type(duck_amount) == "number" and duck_amount > 0
        local jump_input = false
        local duck_input = false
        if command ~= nil then
            local jump_value = command.in_jump
            if jump_value == true then
                jump_input = true
            elseif type(jump_value) == "number" and jump_value ~= 0 then
                jump_input = true
            end

            local duck_value = command.in_duck
            if duck_value == true then
                duck_input = true
            elseif type(duck_value) == "number" and duck_value ~= 0 then
                duck_input = true
            end
        end

        local on_ground = is_on_ground(player.m_fFlags)
        if jump_input and on_ground then
            on_ground = false
        end

        if on_ground then
            if is_slow_walk_active() then
                return condition.slow_walking
            end

            if not is_moving then
                if is_crouched then
                    return condition.crouching
                end

                return condition.standing
            end

            if is_crouched then
                return condition.crouch_running
            end

            return condition.running
        end

        if is_crouched or duck_input then
            return condition.air_crouching
        end

        return condition.airborne
    end

    function angles_builder.get_state(player, command)
        local condition_index = get_condition_index(player, command)
        return condition_state_labels[condition_index] or "Standing"
    end

    local function update_runtime_state(command)
        local me = entity.get_local_player()
        if me == nil or not me:is_alive() then
            runtime_state.team_index = mode_list:get()
            runtime_state.condition_index = condition.standing
            runtime_state.base_condition_index = condition.standing
            runtime_state.is_defensive_active = false
            runtime_state.is_throwing_grenade = false
            runtime_state.previous_weapon_index = nil
            runtime_state.weapon_switch_expire_tick = -1
            return
        end

        runtime_state.team_index = get_team_index(me.m_iTeamNum)
        runtime_state.base_condition_index = get_condition_index(me, command)
        runtime_state.is_throwing_grenade = is_throwing_grenade(me)

        local weapon = me:get_player_weapon()
        if weapon ~= nil then
            local weapon_index = weapon:get_weapon_index()
            if type(weapon_index) == "number" then
                if runtime_state.previous_weapon_index ~= nil and runtime_state.previous_weapon_index ~= weapon_index then
                    runtime_state.weapon_switch_expire_tick = globals.tickcount + runtime_cfg.weapon_switch_duration_ticks
                end

                runtime_state.previous_weapon_index = weapon_index
            end
        end

        if globals.tickcount < runtime_state.weapon_switch_expire_tick then
            runtime_state.condition_index = condition.weapon_switch
            return
        end

        runtime_state.condition_index = runtime_state.base_condition_index
    end

    local function get_fallback_condition_index(condition_index, base_condition_index)
        if condition_index == condition.weapon_switch then
            return base_condition_index
        end

        if condition_index == condition.air_crouching then
            return condition.airborne
        end

        if condition_index == condition.crouch_running then
            return condition.crouching
        end

        if condition_index == condition.slow_walking then
            return condition.running
        end

        if condition_index == condition.running then
            return condition.standing
        end

        return nil
    end

    local function resolve_condition_index(team_index, condition_index, base_condition_index)
        local current = condition_index

        for _ = 1, #condition_names do
            if get_condition_enabled_state(team_index, current) == true then
                return current
            end

            local fallback = get_fallback_condition_index(current, base_condition_index)
            if fallback == nil or fallback == current then
                return nil
            end

            current = fallback
        end

        return nil
    end

    local function hash_to_unit(value)
        local hash = math.sin(value * 12.9898 + 78.233) * 43758.5453
        return hash - math.floor(hash)
    end

    local function get_smart_yaw_variation(
        left_yaw,
        right_yaw,
        variability,
        team_index,
        condition_index,
        side
    )
        if type(variability) ~= "number" or variability <= 0 then
            return 0
        end

        local pct = math.max(0, math.min(100, variability)) * 0.01
        local yaw_delta = math.abs(right_yaw - left_yaw)
        local max_range = math.min(runtime_cfg.max_yaw_variation, math.max(3, yaw_delta * 0.35))

        local cadence = math.max(1, 8 - math.floor(pct * 7))
        local sample = math.floor(runtime_state.sent_packets / cadence)
        local side_seed = side and 17 or 29
        local seed = sample * 97 + team_index * 31 + condition_index * 13 + side_seed

        local phase = runtime_state.sent_packets * (0.04 + pct * 0.11)
            + team_index * 0.7
            + condition_index * 0.37
            + (side and 0 or 1.9)
        local wave = math.sin(phase)
        local unit = hash_to_unit(seed) * 2 - 1

        local jitter_weight = 0.2 + pct * 0.5
        local wave_weight = 1 - jitter_weight
        local blended = wave * wave_weight + unit * jitter_weight
        return blended * max_range * pct
    end

    local function resolve_command_tick_count(command)
        if command ~= nil then
            local tick_count = command.tick_count
            if type(tick_count) == "number" then
                return tick_count
            end
        end

        if type(globals.tickcount) == "number" then
            return globals.tickcount
        end

        return runtime_state.sent_packets
    end

    local function get_yaw_modifier_effective_value(
        base_value,
        variability,
        team_index,
        condition_index,
        mode_seed,
        command_tick
    )
        local value = clamp_number(base_value or 0, -180, 180)
        if type(variability) ~= "number" or variability <= 0 then
            return value
        end

        local pct = clamp_number(variability, 0, 100) * 0.01
        local abs_value = math.abs(value)
        if abs_value <= 0 then
            return value
        end

        local cadence = math.max(1, 7 - math.floor(pct * 6))
        local sample = math.floor(command_tick / cadence)
        local seed = sample * 101 + team_index * 37 + condition_index * 19 + mode_seed * 13

        local wave = math.sin(
            command_tick * (0.05 + pct * 0.16)
            + team_index * 0.71
            + condition_index * 0.43
            + mode_seed * 1.29
        )
        local noise = hash_to_unit(seed) * 2 - 1
        local blended = wave * (0.7 - pct * 0.2) + noise * (0.3 + pct * 0.2)
        local max_range = abs_value * pct
        local value_with_variation = value + blended * max_range

        return clamp_number(value_with_variation, -180, 180)
    end

    local function get_three_way_yaw_modifier_add(
        yaw_modifier_state,
        value,
        should_advance
    )
        local normalized_value = clamp_number(value or 0, -180, 180)

        if type(yaw_modifier_state.three_way_state) ~= "number" then
            yaw_modifier_state.three_way_state = 2
        end

        if should_advance == true then
            yaw_modifier_state.three_way_state = yaw_modifier_state.three_way_state + 1
            if yaw_modifier_state.three_way_state > 3 then
                yaw_modifier_state.three_way_state = 1
            end
        end

        local way = yaw_modifier_state.three_way_state
        if way == 1 then
            return -normalized_value
        end

        if way == 2 then
            return 0
        end

        return normalized_value
    end

    local function get_bobro_yaw_modifier_offset(value, index)
        local normalized_value = clamp_number(value or 0, -180, 180)

        return ({
            [1] = -normalized_value,
            [2] = -normalized_value / 2,
            [3] = -normalized_value / 3,
            [4] = normalized_value / 3,
            [5] = normalized_value / 2,
            [6] = normalized_value,
        })[index or 1] or normalized_value
    end

    local function get_drift_yaw_modifier_add(
        yaw_modifier_state,
        value,
        speed,
        variability,
        team_index,
        condition_index,
        command_tick
    )
        local amplitude = math.abs(clamp_number(value or 0, -180, 180))
        if amplitude <= 0 then
            return 0
        end

        local speed_value = clamp_number(math.abs(speed or 210), 1, 720)
        local variability_value = clamp_number(variability or 0, 0, 100)
        local tick_interval = globals.tickinterval
        if type(tick_interval) ~= "number" or tick_interval <= 0 then
            tick_interval = 1 / 64
        end

        if type(yaw_modifier_state.drift_phase) ~= "number" then
            yaw_modifier_state.drift_phase = 0
        end
        if type(yaw_modifier_state.drift_step_index) ~= "number" then
            yaw_modifier_state.drift_step_index = 1
        end
        if type(yaw_modifier_state.drift_next_step_tick) ~= "number" then
            yaw_modifier_state.drift_next_step_tick = command_tick
        end
        if type(yaw_modifier_state.drift_direction) ~= "number" then
            yaw_modifier_state.drift_direction = 1
        end
        if type(yaw_modifier_state.drift_next_reverse_tick) ~= "number" then
            local base_reverse_ticks = math.max(6, math.floor(28 - speed_value / 28))
            yaw_modifier_state.drift_next_reverse_tick = command_tick + base_reverse_ticks
        end

        if command_tick >= yaw_modifier_state.drift_next_reverse_tick then
            yaw_modifier_state.drift_direction = -yaw_modifier_state.drift_direction

            local base_reverse_ticks = math.max(6, math.floor(28 - speed_value / 28))
            local reverse_seed = command_tick * 157
                + team_index * 41
                + condition_index * 23
            local reverse_jitter = math.floor(
                hash_to_unit(reverse_seed) * base_reverse_ticks * (variability_value * 0.004)
            )
            yaw_modifier_state.drift_next_reverse_tick = command_tick + base_reverse_ticks + reverse_jitter
        end

        if variability_value > 0 and globals.choked_commands == 0 then
            local pulse_seed = command_tick * 181
                + team_index * 31
                + condition_index * 17
            local pulse = hash_to_unit(pulse_seed)
            local pulse_threshold = 0.997 - variability_value * 0.0015
            if pulse > pulse_threshold then
                yaw_modifier_state.drift_direction = -yaw_modifier_state.drift_direction
                local settle_ticks = math.max(4, math.floor(10 - speed_value / 90))
                yaw_modifier_state.drift_next_reverse_tick = command_tick + settle_ticks
            end
        end

        if globals.choked_commands == 0 then
            yaw_modifier_state.drift_phase = yaw_modifier_state.drift_phase
                + math.rad(speed_value) * tick_interval * yaw_modifier_state.drift_direction
            if yaw_modifier_state.drift_phase > math.pi * 2 then
                yaw_modifier_state.drift_phase = yaw_modifier_state.drift_phase - math.pi * 2
            elseif yaw_modifier_state.drift_phase < -math.pi * 2 then
                yaw_modifier_state.drift_phase = yaw_modifier_state.drift_phase + math.pi * 2
            end
        end

        if command_tick >= yaw_modifier_state.drift_next_step_tick then
            local cadence = math.max(1, math.floor(10 - speed_value / 90))
            local step_seed = command_tick * 131
                + team_index * 37
                + condition_index * 17
                + yaw_modifier_state.drift_step_index * 19
            local hop = 1 + math.floor(hash_to_unit(step_seed) * 2)
            local step_count = 5
            yaw_modifier_state.drift_step_index = ((yaw_modifier_state.drift_step_index + hop - 1) % step_count) + 1
            yaw_modifier_state.drift_next_step_tick = command_tick + cadence
        end

        local step_scale = {
            -0.58,
            -0.16,
            0.22,
            0.51,
            -0.34,
        }
        local step_index = yaw_modifier_state.drift_step_index
        local phase_shift = step_index * 0.35
        local wave = math.sin(yaw_modifier_state.drift_phase + phase_shift) * amplitude * 0.72
        local step = step_scale[step_index] * amplitude * 0.48
        local add = wave + step

        return clamp_number(add, -amplitude, amplitude)
    end

    local function is_yaw_modifier_switch_active(
        yaw_modifier_state,
        base_delay,
        variability,
        force_reset
    )
        if type(yaw_modifier_state.yaw_modifier_switch_state) ~= "boolean" then
            yaw_modifier_state.yaw_modifier_switch_state = true
            yaw_modifier_state.yaw_modifier_switch_packets = 0
            yaw_modifier_state.yaw_modifier_switch_last_flip = 0
        end

        if force_reset == true then
            yaw_modifier_state.yaw_modifier_switch_state = true
            yaw_modifier_state.yaw_modifier_switch_packets = 0
            yaw_modifier_state.yaw_modifier_switch_last_flip = 0
            return yaw_modifier_state.yaw_modifier_switch_state == true
        end

        local delay = clamp_number(math.floor(base_delay or 0), 0, 20)
        if delay <= 0 then
            yaw_modifier_state.yaw_modifier_switch_state = true
            yaw_modifier_state.yaw_modifier_switch_packets = 0
            yaw_modifier_state.yaw_modifier_switch_last_flip = 0
            return yaw_modifier_state.yaw_modifier_switch_state == true
        end

        if globals.choked_commands ~= 0 then
            return yaw_modifier_state.yaw_modifier_switch_state == true
        end

        yaw_modifier_state.yaw_modifier_switch_packets = yaw_modifier_state.yaw_modifier_switch_packets + 1

        local effective_delay = delay
        if (variability or 0) > 0 then
            effective_delay = get_random_body_delay(delay, variability)
        end

        local ticks = yaw_modifier_state.yaw_modifier_switch_packets
            - yaw_modifier_state.yaw_modifier_switch_last_flip
        if ticks >= effective_delay then
            yaw_modifier_state.yaw_modifier_switch_state = not yaw_modifier_state.yaw_modifier_switch_state
            yaw_modifier_state.yaw_modifier_switch_last_flip = yaw_modifier_state.yaw_modifier_switch_packets
        end

        return yaw_modifier_state.yaw_modifier_switch_state == true
    end

    local function get_current_max_desync()
        if rage == nil or rage.antiaim == nil or rage.antiaim.get_max_desync == nil then
            return nil
        end

        local value = rage.antiaim:get_max_desync()
        if type(value) ~= "number" then
            return nil
        end

        return clamp_number(value, 0, 60)
    end

    local function resolve_body_variability_base(limit_value, max_desync_value)
        local base = clamp_number(limit_value or 0, 0, 60)
        if type(max_desync_value) ~= "number" then
            return base
        end

        if base >= max_desync_value then
            return max_desync_value
        end

        return base
    end

    local function get_body_variability_upper_bound(limit_value, max_desync_value)
        local limit = clamp_number(limit_value or 0, 0, 60)
        if type(max_desync_value) ~= "number" then
            return 60
        end

        if limit >= max_desync_value then
            return max_desync_value
        end

        return 60
    end

    local function get_smart_body_variation(
        base_limit,
        variability,
        team_index,
        condition_index,
        channel_seed
    )
        if type(variability) ~= "number" or variability <= 0 then
            return 0
        end

        local pct = math.max(0, math.min(100, variability)) * 0.01
        local normalized_limit = clamp_number(base_limit or 0, 0, 60)
        if normalized_limit <= 0 then
            return 0
        end

        local strength_floor = 0.08 + pct * 0.16
        local strength_curve = pct ^ 1.35
        local strength = math.min(1, strength_floor + strength_curve * 0.84)
        local max_range = math.max(1, normalized_limit * strength)
        max_range = math.min(normalized_limit, max_range)

        local cadence_slow = math.max(1, 10 - math.floor(pct * 8))
        local cadence_fast = math.max(1, 4 - math.floor(pct * 3))
        local sample_slow = math.floor(runtime_state.sent_packets / cadence_slow)
        local sample_fast = math.floor(runtime_state.sent_packets / cadence_fast)

        local wave_primary = math.sin(
            runtime_state.sent_packets * (0.035 + pct * 0.12)
            + team_index * 0.61
            + condition_index * 0.37
            + channel_seed * 1.33
        )
        local wave_secondary = math.sin(
            runtime_state.sent_packets * (0.11 + pct * 0.19)
            + team_index * 0.23
            + condition_index * 0.53
            + channel_seed * 2.07
        )
        local wave_mix = wave_primary * 0.65 + wave_secondary * 0.35

        local seed_slow = sample_slow * 97 + team_index * 31 + condition_index * 17 + channel_seed * 13
        local seed_fast = sample_fast * 131 + team_index * 19 + condition_index * 43 + channel_seed * 29
        local random_slow = hash_to_unit(seed_slow) * 2 - 1
        local random_fast = hash_to_unit(seed_fast) * 2 - 1
        local random_mix = random_slow * 0.55 + random_fast * 0.45

        local random_weight = 0.34 + pct * 0.48
        local wave_weight = 1 - random_weight
        local blended = wave_mix * wave_weight + random_mix * random_weight

        local abs_blended = math.abs(blended)
        local curve_power = 0.72 - pct * 0.22
        local curved = abs_blended ^ math.max(0.35, curve_power)
        if blended < 0 then
            curved = -curved
        end

        local burst_seed = sample_fast * 149 + team_index * 41 + condition_index * 23 + channel_seed * 59
        local burst_roll = hash_to_unit(burst_seed)
        local burst_threshold = 0.985 - pct * 0.26
        local burst_multiplier = 1
        if burst_roll > burst_threshold then
            burst_multiplier = 1.15 + pct * 0.75
        end

        return curved * max_range * burst_multiplier
    end

    local function is_selectable_enabled(reference, value)
        if reference == nil or type(value) ~= "string" then
            return false
        end

        local ok_named, named = pcall(reference.get, reference, value)
        if ok_named and type(named) == "boolean" then
            return named
        end

        local ok_list, list = pcall(reference.get, reference)
        if not ok_list or type(list) ~= "table" then
            return false
        end

        for index = 1, #list do
            if list[index] == value then
                return true
            end
        end

        return false
    end

    local other_aa_state = angles_builder.other_aa_state

    local function reset_other_special_aa_state()
        other_aa_state.is_overriding = false
        other_aa_state.last_packet = -1
        other_aa_state.pitch_random = 0
        other_aa_state.pitch_random_packet = -1
        other_aa_state.pitch_spin = -89
        other_aa_state.pitch_spin_direction = 1
        other_aa_state.pitch_last_time = 0
        other_aa_state.pitch_switch_flip = false
        other_aa_state.pitch_switch_packets = 0
        other_aa_state.yaw_spin = 0
        other_aa_state.yaw_last_time = 0
        other_aa_state.yaw_random = 180
        other_aa_state.yaw_random_packet = -1
    end

    local function clear_other_special_aa_overrides()
        reset_other_special_aa_state()

        local angles = nl.aa and nl.aa.angles
        if angles ~= nil then
            if angles.pitch ~= nil then
                angles.pitch:override()
            end

            if angles.yaw ~= nil then
                angles.yaw:override()
            end

            if angles.yaw_add ~= nil then
                angles.yaw_add:override()
            end

            if angles.yaw_base ~= nil then
                angles.yaw_base:override()
            end

            if angles.yaw_modifier ~= nil then
                angles.yaw_modifier:override()
            end

            if angles.modifier_offset ~= nil then
                angles.modifier_offset:override()
            end

            if angles.options ~= nil then
                angles.options:override()
            end
        end

        clear_body_yaw_overrides()

        local fake_lag = nl.aa and nl.aa.fake_lag
        if fake_lag ~= nil and fake_lag.enabled ~= nil then
            fake_lag.enabled:override()
        end
    end

    local function has_alive_enemy()
        local local_player = entity.get_local_player()
        if local_player == nil then
            return false
        end

        local local_team = local_player.m_iTeamNum
        if type(local_team) ~= "number" then
            return false
        end

        local player_resource = entity.get_player_resource()
        if player_resource ~= nil then
            for player_index = 1, globals.max_players do
                local is_connected = player_resource.m_bConnected[player_index]
                if is_connected == true or is_connected == 1 then
                    local player_team = player_resource.m_iTeam[player_index]
                    local player_health = player_resource.m_iHealth[player_index]

                    if (player_team == 2 or player_team == 3)
                        and player_team ~= local_team
                        and type(player_health) == "number"
                        and player_health > 0 then
                        return true
                    end
                end
            end

            return false
        end

        local result = false

        entity.get_players(true, true, function(enemy_player)
            if result == true or enemy_player == nil then
                return
            end

            if enemy_player:is_alive() == true then
                result = true
            end
        end)

        return result
    end

    local function is_other_special_aa_active()
        local ref = angles_builder.other_aa_refs
        if ref.disable_on == nil then
            return false
        end

        local local_player = entity.get_local_player()
        if local_player == nil or local_player:is_alive() ~= true then
            return false
        end

        local game_rules = entity.get_game_rules()
        if game_rules == nil then
            return false
        end

        if is_selectable_enabled(ref.disable_on, "Warmup")
            and game_rules.m_bWarmupPeriod == true then
            return true
        end

        if is_selectable_enabled(ref.disable_on, "Round End") then
            if game_rules.m_bWarmupPeriod ~= true
                and other_aa_state.round_end_active == true
                and has_alive_enemy() ~= true then
                return true
            end
        end

        return false
    end

    local function resolve_other_special_yaw()
        local ref = angles_builder.other_aa_refs
        local mode = "Spin"
        if ref.yaw_mode ~= nil then
            local value = ref.yaw_mode:get()
            if type(value) == "string" and value ~= "" then
                mode = value
            end
        end

        if mode == "Disabled" then
            return nil
        end

        if mode == "Static" then
            if ref.yaw_static ~= nil then
                local value = ref.yaw_static:get()
                if type(value) == "number" then
                    return clamp_number(value, -180, 180)
                end
            end

            return 180
        end

        if mode == "Random" then
            local packet = runtime_state.sent_packets
            if type(packet) ~= "number" then
                packet = 0
            end

            if other_aa_state.yaw_random_packet ~= packet then
                other_aa_state.yaw_random_packet = packet

                local min_value = -180
                local max_value = 180
                if ref.yaw_random_min ~= nil then
                    local value = ref.yaw_random_min:get()
                    if type(value) == "number" then
                        min_value = clamp_number(value, -180, 180)
                    end
                end
                if ref.yaw_random_max ~= nil then
                    local value = ref.yaw_random_max:get()
                    if type(value) == "number" then
                        max_value = clamp_number(value, -180, 180)
                    end
                end

                if min_value > max_value then
                    min_value, max_value = max_value, min_value
                end

                other_aa_state.yaw_random = utils.random_int(min_value, max_value)
            end

            return math.normalize_yaw(other_aa_state.yaw_random)
        end

        local spin_speed = 1000
        if ref.yaw_spin_speed ~= nil then
            local value = ref.yaw_spin_speed:get()
            if type(value) == "number" then
                spin_speed = clamp_number(value, 1, 2000)
            end
        end

        local now = globals.realtime
        if type(now) ~= "number" then
            now = other_aa_state.yaw_last_time
        end

        local dt = now - other_aa_state.yaw_last_time
        other_aa_state.yaw_last_time = now

        if dt < 0 or dt > 0.25 then
            dt = 0
        end

        other_aa_state.yaw_spin = math.normalize_yaw(
            other_aa_state.yaw_spin + spin_speed * dt
        )
        return other_aa_state.yaw_spin
    end

    local function resolve_other_special_pitch(mode, packet_advanced)
        local ref = angles_builder.other_aa_refs

        if mode ~= "Random" then
            other_aa_state.pitch_random_packet = -1
        end

        if mode ~= "Spin" then
            other_aa_state.pitch_last_time = 0
            other_aa_state.pitch_spin = -89
            other_aa_state.pitch_spin_direction = 1
        end

        if mode ~= "Switch" then
            other_aa_state.pitch_switch_flip = false
            other_aa_state.pitch_switch_packets = 0
        end

        if mode == "Static" then
            local value = 0
            if ref.pitch_static ~= nil then
                local current = ref.pitch_static:get()
                if type(current) == "number" then
                    value = current
                end
            end

            return clamp_number(
                value,
                -89,
                89
            )
        end

        if mode == "Random" then
            local packet = runtime_state.sent_packets
            if type(packet) ~= "number" then
                packet = 0
            end

            if other_aa_state.pitch_random_packet ~= packet then
                other_aa_state.pitch_random_packet = packet

                local min_value = -89
                local max_value = 89

                if ref.pitch_random_min ~= nil then
                    local value = ref.pitch_random_min:get()
                    if type(value) == "number" then
                        min_value = clamp_number(
                            value,
                            -89,
                            89
                        )
                    end
                end

                if ref.pitch_random_max ~= nil then
                    local value = ref.pitch_random_max:get()
                    if type(value) == "number" then
                        max_value = clamp_number(
                            value,
                            -89,
                            89
                        )
                    end
                end

                if min_value > max_value then
                    min_value, max_value = max_value, min_value
                end

                other_aa_state.pitch_random = utils.random_float(min_value, max_value)
            end

            return clamp_number(
                other_aa_state.pitch_random,
                -89,
                89
            )
        end

        if mode == "Spin" then
            local min_value = -89
            local max_value = 89

            if ref.pitch_spin_min ~= nil then
                local value = ref.pitch_spin_min:get()
                if type(value) == "number" then
                    min_value = clamp_number(
                        value,
                        -89,
                        89
                    )
                end
            end

            if ref.pitch_spin_max ~= nil then
                local value = ref.pitch_spin_max:get()
                if type(value) == "number" then
                    max_value = clamp_number(
                        value,
                        -89,
                        89
                    )
                end
            end

            if min_value > max_value then
                min_value, max_value = max_value, min_value
            end

            local spin_speed = 260
            if ref.pitch_spin_speed ~= nil then
                local value = ref.pitch_spin_speed:get()
                if type(value) == "number" then
                    spin_speed = clamp_number(value, 1, 720)
                end
            end

            local now = globals.realtime
            if type(now) ~= "number" then
                now = other_aa_state.pitch_last_time
            end

            if min_value == max_value then
                other_aa_state.pitch_last_time = now
                other_aa_state.pitch_spin = min_value
                other_aa_state.pitch_spin_direction = 1
                return other_aa_state.pitch_spin
            end

            if other_aa_state.pitch_last_time == 0
                or other_aa_state.pitch_spin < min_value
                or other_aa_state.pitch_spin > max_value then
                other_aa_state.pitch_last_time = now
                other_aa_state.pitch_spin = min_value
                other_aa_state.pitch_spin_direction = 1
                return other_aa_state.pitch_spin
            end

            local dt = now - other_aa_state.pitch_last_time
            other_aa_state.pitch_last_time = now

            if dt < 0 or dt > 0.25 then
                dt = 0
            end

            local pitch_spin = other_aa_state.pitch_spin
                + other_aa_state.pitch_spin_direction * spin_speed * dt

            while pitch_spin > max_value or pitch_spin < min_value do
                if pitch_spin > max_value then
                    pitch_spin = max_value - (pitch_spin - max_value)
                    other_aa_state.pitch_spin_direction = -1
                elseif pitch_spin < min_value then
                    pitch_spin = min_value + (min_value - pitch_spin)
                    other_aa_state.pitch_spin_direction = 1
                end
            end

            other_aa_state.pitch_spin = clamp_number(
                pitch_spin,
                -89,
                89
            )

            return other_aa_state.pitch_spin
        end

        if mode == "Switch" then
            local first_value = -89
            local second_value = 89
            local delay = 1

            if ref.pitch_switch_first ~= nil then
                local value = ref.pitch_switch_first:get()
                if type(value) == "number" then
                    first_value = clamp_number(
                        value,
                        -89,
                        89
                    )
                end
            end

            if ref.pitch_switch_second ~= nil then
                local value = ref.pitch_switch_second:get()
                if type(value) == "number" then
                    second_value = clamp_number(
                        value,
                        -89,
                        89
                    )
                end
            end

            if ref.pitch_switch_delay ~= nil then
                local value = ref.pitch_switch_delay:get()
                if type(value) == "number" then
                    delay = clamp_number(math.floor(value), 1, 16)
                end
            end

            if packet_advanced then
                other_aa_state.pitch_switch_packets =
                    other_aa_state.pitch_switch_packets + 1

                if other_aa_state.pitch_switch_packets > delay then
                    other_aa_state.pitch_switch_packets = 1
                    other_aa_state.pitch_switch_flip =
                        not other_aa_state.pitch_switch_flip
                end
            end

            if other_aa_state.pitch_switch_flip == true then
                return second_value
            end

            return first_value
        end

        return nil
    end

    local function apply_other_special_aa(command)
        if is_other_special_aa_active() ~= true then
            clear_other_special_aa_overrides()
            return false
        end

        local angles = nl.aa and nl.aa.angles
        if angles == nil then
            clear_other_special_aa_overrides()
            return false
        end

        clear_hidden_defensive_overrides()

        local packet = runtime_state.sent_packets
        if type(packet) ~= "number" then
            packet = 0
        end

        local packet_advanced = other_aa_state.last_packet ~= packet
        other_aa_state.last_packet = packet

        local pitch_mode = "Disabled"
        if angles_builder.other_aa_refs.pitch_mode ~= nil then
            local value = angles_builder.other_aa_refs.pitch_mode:get()
            if type(value) == "string" and value ~= "" then
                pitch_mode = value
            end
        end

        if pitch_mode == "Fake Down" then
            pitch_mode = "Down"
        end

        local use_custom_pitch = pitch_mode ~= "Disabled"
            and pitch_mode ~= "Down"

        if angles.pitch ~= nil then
            if use_custom_pitch == true then
                angles.pitch:override("Disabled")
            else
                angles.pitch:override(pitch_mode)
            end
        end

        if use_custom_pitch == true then
            local pitch_value = resolve_other_special_pitch(
                pitch_mode,
                packet_advanced
            )

            if type(pitch_value) == "number"
                and command ~= nil
                and command.view_angles ~= nil then
                local local_player = entity.get_local_player()
                if local_player ~= nil and local_player:is_alive() == true then
                    local move_type = local_player.m_MoveType
                    if move_type ~= 8 and move_type ~= 9 then
                        if command.in_attack ~= true
                            and command.in_attack2 ~= true
                            and command.in_use ~= true then
                            command.view_angles.x = clamp_number(pitch_value, -89, 89)
                            command.upmove = 0
                        end
                    end
                end
            end
        else
            other_aa_state.pitch_random = 0
            other_aa_state.pitch_random_packet = -1
            other_aa_state.pitch_spin = -89
            other_aa_state.pitch_spin_direction = 1
            other_aa_state.pitch_last_time = 0
            other_aa_state.pitch_switch_flip = false
            other_aa_state.pitch_switch_packets = 0
        end

        local yaw_value = resolve_other_special_yaw()
        if yaw_value == nil then
            if angles.yaw ~= nil then
                angles.yaw:override("Disabled")
            end

            if angles.yaw_add ~= nil then
                angles.yaw_add:override()
            end

            if angles.yaw_base ~= nil then
                angles.yaw_base:override()
            end
        else
            if angles.yaw ~= nil then
                angles.yaw:override("Backward")
            end

            if angles.yaw_add ~= nil then
                angles.yaw_add:override(math.normalize_yaw(yaw_value))
            end

            if angles.yaw_base ~= nil then
                angles.yaw_base:override("Local View")
            end
        end

        if angles.yaw_modifier ~= nil then
            angles.yaw_modifier:override("Disabled")
        end

        if angles.modifier_offset ~= nil then
            angles.modifier_offset:override()
        end

        if angles.options ~= nil then
            angles.options:override({
            })
        end

        if is_selectable_enabled(angles_builder.other_aa_refs.disablers, "Body Yaw") then
            if angles.body_yaw ~= nil then
                angles.body_yaw:override(false)
            end

            if angles.left_limit ~= nil then
                angles.left_limit:override()
            end

            if angles.right_limit ~= nil then
                angles.right_limit:override()
            end
        else
            clear_body_yaw_overrides()
        end

        local fake_lag = nl.aa and nl.aa.fake_lag
        if fake_lag ~= nil and fake_lag.enabled ~= nil then
            if is_selectable_enabled(angles_builder.other_aa_refs.disablers, "Fake Lags") then
                fake_lag.enabled:override(false)
            else
                fake_lag.enabled:override()
            end
        end

        other_aa_state.is_overriding = true
        return true
    end

    local function get_crouch_direction_override_value(
        base_value,
        direction_name,
        directions_ref,
        direction_refs
    )
        if type(direction_name) ~= "string" then
            return base_value
        end

        if direction_name == CROUCH_MOVE_DEFAULT_DIRECTION then
            return base_value
        end

        if is_selectable_enabled(directions_ref, direction_name) ~= true then
            return base_value
        end

        if type(direction_refs) ~= "table" then
            return base_value
        end

        local ref = direction_refs[direction_name]
        if ref == nil then
            return base_value
        end

        local value = ref:get()
        if type(value) ~= "number" then
            return base_value
        end

        return value
    end

    local break_lc = {
    }

    function break_lc.is_item_enabled(reference)
        if reference == nil then
            return false
        end

        local ok_override, override = pcall(reference.get_override, reference)
        if ok_override and override ~= nil then
            return override == true
        end

        local ok_value, value = pcall(reference.get, reference)
        if not ok_value then
            return false
        end

        return value == true
    end

    function break_lc.is_revolver_weapon(weapon)
        if weapon == nil then
            return false
        end

        local weapon_info = weapon:get_weapon_info()
        if weapon_info == nil then
            return false
        end

        return weapon_info.is_revolver == true
    end

    function break_lc.is_disabled(local_weapon, include_trigger_only_disabler)
        if break_lc.is_revolver_weapon(local_weapon) then
            return true
        end

        local refs = angles_builder.break_lc_refs
        if refs.disablers == nil then
            return false
        end

        if is_selectable_enabled(refs.disablers, "On Grenade")
            and is_grenade_weapon(local_weapon) then
            return true
        end

        if is_selectable_enabled(refs.disablers, "On Pin Pulled")
            and local_weapon ~= nil
            and local_weapon.m_bPinPulled == true then
            return true
        end

        if include_trigger_only_disabler == true
            and is_selectable_enabled(refs.disablers, "On Hide Shots (for triggers only)")
            and break_lc.is_item_enabled(nl.rage and nl.rage.main and nl.rage.main.hide_shots) then
            return true
        end

        return false
    end

    function break_lc.is_trigger_active(local_player, local_weapon)
        local refs = angles_builder.break_lc_refs
        if refs.triggers == nil or local_player == nil or local_player:is_alive() ~= true then
            return false
        end

        if is_selectable_enabled(refs.triggers, "Weapon Switch")
            and runtime_state.condition_index == condition.weapon_switch then
            return true
        end

        if is_selectable_enabled(refs.triggers, "Flashed") then
            local anim_state = local_player:get_anim_state()
            if type(anim_state) == "table" and anim_state.flashed == true then
                return true
            end
        end

        if is_selectable_enabled(refs.triggers, "Reloading")
            and local_weapon ~= nil then
            local reload = local_weapon:get_weapon_reload()
            if type(reload) == "number" and reload >= 0 then
                return true
            end
        end

        if is_selectable_enabled(refs.triggers, "Flinching") then
            local layer = local_player:get_anim_overlay(10)
            if type(layer) == "table"
                and layer.activity == 982 then
                local weight = layer.weight
                if type(weight) == "number" and weight > 0 then
                    return true
                end
            end
        end

        return false
    end

    function break_lc.is_custom_tickbase_enabled(view)
        if type(view) ~= "table" then
            return false
        end

        local ref = view.break_lc_custom_tickbase_enabled_ref
        if ref == nil then
            return false
        end

        return ref:get() == true
    end

    function break_lc.uses_custom_advanced_tickbase(view)
        return break_lc.is_custom_tickbase_enabled(view) == true
    end

    local function get_break_lc_tickbase_number(reference, fallback)
        local value = fallback
        if reference ~= nil and reference.get ~= nil then
            local ok_value, raw = pcall(reference.get, reference)
            if ok_value and type(raw) == "number" then
                value = raw
            end
        end

        if type(value) ~= "number" then
            value = fallback
        end

        if type(value) ~= "number" then
            return 0
        end

        return math.floor(value)
    end

    local function get_break_lc_tickbase_random_int(
        command_number,
        team_index,
        condition_index,
        salt,
        min_value,
        max_value
    )
        local low = math.min(min_value, max_value)
        local high = math.max(min_value, max_value)
        if high <= low then
            return low
        end

        local command_seed = tonumber(command_number) or 0
        local state_seed = (tonumber(team_index) or 0) * 37
            + (tonumber(condition_index) or 0) * 17
            + (tonumber(salt) or 0) * 11
        local seed = math.sin(command_seed * 12.9898 + state_seed * 78.233) * 43758.5453
        local normalized = seed - math.floor(seed)
        return low + math.floor(normalized * (high - low + 1))
    end

    function break_lc.get_custom_tickbase_interval(
        view,
        command_number,
        team_index,
        condition_index
    )
        if type(view) ~= "table" then
            return nil
        end

        local choke = clamp_number(
            get_break_lc_tickbase_number(view.break_lc_tickbase_choke_ref, 16),
            2,
            22
        )

        local randomize_ref = view.break_lc_tickbase_randomize_ref
        if randomize_ref == nil or randomize_ref:get() ~= true then
            return choke
        end

        local type_name = get_break_lc_tickbase_type_name(
            view.break_lc_tickbase_type_ref ~= nil
                and view.break_lc_tickbase_type_ref:get()
                or nil
        )

        if type_name == "Ways" then
            local slider_count = clamp_number(
                get_break_lc_tickbase_number(view.break_lc_tickbase_sliders_ref, 3),
                2,
                8
            )
            local slot_index = get_break_lc_tickbase_random_int(
                command_number,
                team_index,
                condition_index,
                1,
                1,
                slider_count
            )
            local slot_ref = view["break_lc_tickbase_" .. slot_index .. "_ref"]
            return clamp_number(
                get_break_lc_tickbase_number(slot_ref, 2),
                2,
                22
            )
        end

        local min_value = clamp_number(
            get_break_lc_tickbase_number(view.break_lc_tickbase_random_min_ref, 16),
            2,
            22
        )
        local max_value = clamp_number(
            get_break_lc_tickbase_number(view.break_lc_tickbase_random_max_ref, 16),
            2,
            22
        )
        return get_break_lc_tickbase_random_int(
            command_number,
            team_index,
            condition_index,
            2,
            min_value,
            max_value
        )
    end

    function break_lc.should_force_custom_defensive(
        view,
        command,
        team_index,
        condition_index
    )
        if break_lc.uses_custom_advanced_tickbase(view) ~= true then
            return false
        end

        if break_lc.is_item_enabled(nl.rage and nl.rage.main and nl.rage.main.double_tap) ~= true then
            return false
        end

        if command == nil or type(command.command_number) ~= "number" then
            return false
        end

        local interval = break_lc.get_custom_tickbase_interval(
            view,
            command.command_number,
            team_index,
            condition_index
        )
        if type(interval) ~= "number" or interval < 2 then
            return false
        end

        return command.command_number % interval == 0
    end

    local movement_helpers = {
    }

    function movement_helpers.get_command_value(command, key)
        if command == nil then
            return false
        end

        local value = command[key]
        if value == true then
            return true
        end

        if type(value) == "number" then
            return value ~= 0
        end

        return false
    end

    function movement_helpers.get_crouch_move_direction(command)
        local forward_move = 0
        local side_move = 0
        if command ~= nil then
            if type(command.forwardmove) == "number" then
                forward_move = command.forwardmove
            end

            if type(command.sidemove) == "number" then
                side_move = command.sidemove
            end
        end

        local moving_forward = forward_move > 1
        local moving_back = forward_move < -1
        if moving_forward ~= true and moving_back ~= true then
            moving_forward = movement_helpers.get_command_value(command, "in_forward")
            moving_back = movement_helpers.get_command_value(command, "in_back")
        end
        if moving_forward == moving_back then
            moving_forward = false
            moving_back = false
        end

        local moving_right = side_move > 1
        local moving_left = side_move < -1
        if moving_right ~= true and moving_left ~= true then
            moving_right = movement_helpers.get_command_value(command, "in_moveright")
            moving_left = movement_helpers.get_command_value(command, "in_moveleft")
        end
        if moving_right == moving_left then
            moving_right = false
            moving_left = false
        end

        local forward_name = nil
        if moving_forward then
            forward_name = "Forward"
        elseif moving_back then
            forward_name = "Backward"
        end

        if moving_right then
            if forward_name ~= nil then
                return forward_name .. "-Right"
            end

            return "Right"
        end

        if moving_left then
            if forward_name ~= nil then
                return forward_name .. "-Left"
            end

            return "Left"
        end

        if forward_name ~= nil then
            return forward_name
        end

        return CROUCH_MOVE_DEFAULT_DIRECTION
    end

    function movement_helpers.is_fake_duck_active()
        local fake_duck = nl.aa and nl.aa.misc and nl.aa.misc.fake_duck
        if fake_duck == nil then
            return false
        end

        return fake_duck:get() == true
    end

    function movement_helpers.is_peek_assist_active()
        local peek_assist = nl.rage and nl.rage.main and nl.rage.main.peek_assist
        if type(peek_assist) ~= "table" then
            return false
        end

        local ref = peek_assist[1]
        if ref == nil then
            return false
        end

        return ref:get() == true
    end

    local mouse_override = {
    }

    function mouse_override.is_menu_open()
        return ui.get_alpha() > 0
    end

    function mouse_override.set_cursor_clipped(state)
        if mouse_override_state.ffi_ready ~= true then
            return
        end

        local ffi = mouse_override_state.ffi
        if ffi == nil or mouse_override_state.clip_rect == nil then
            return
        end

        if state == true then
            local ok_hwnd, hwnd = pcall(ffi.C.GetForegroundWindow)
            if not ok_hwnd or hwnd == nil or hwnd == ffi.NULL then
                return
            end

            local ok_rect, rect_result = pcall(
                ffi.C.GetWindowRect,
                hwnd,
                mouse_override_state.clip_rect
            )
            if not ok_rect or rect_result == 0 then
                return
            end

            mouse_override_state.lock_center_x = math.floor(
                (mouse_override_state.clip_rect[0].left + mouse_override_state.clip_rect[0].right) * 0.5
            )
            mouse_override_state.lock_center_y = math.floor(
                (mouse_override_state.clip_rect[0].top + mouse_override_state.clip_rect[0].bottom) * 0.5
            )

            pcall(ffi.C.ClipCursor, mouse_override_state.clip_rect)
            if mouse_override_state.is_cursor_clipped ~= true then
                pcall(ffi.C.SetCursorPos, mouse_override_state.lock_center_x, mouse_override_state.lock_center_y)
            end
            mouse_override_state.is_cursor_clipped = true
            return
        end

        if mouse_override_state.is_cursor_clipped ~= true then
            return
        end

        pcall(ffi.C.ClipCursor, nil)
        mouse_override_state.is_cursor_clipped = false
    end

    function mouse_override.hide_cursor()
        if mouse_override_state.ffi_ready ~= true then
            return
        end

        local ffi = mouse_override_state.ffi
        if ffi == nil then
            return
        end

        pcall(ffi.C.SetCursor, mouse_override_state.null_cursor)
    end

    function mouse_override.get_slider_value(reference, fallback)
        if reference == nil then
            return fallback
        end

        local value = reference:get()
        if type(value) ~= "number" then
            return fallback
        end

        return value
    end

    function mouse_override.is_hotkey_bound(reference)
        if reference == nil then
            return false
        end

        local ok_key, key = pcall(reference.key, reference)
        if not ok_key then
            return false
        end

        if type(key) ~= "number" then
            return false
        end

        return key ~= 0
    end

    function mouse_override.apply_delta(dx, dy)
        local refs = angles_builder.mouse_override_refs
        local max_radius = mouse_override.get_slider_value(
            refs.max_radius,
            mouse_override_defaults.max_radius
        )
        local sensitivity = mouse_override.get_slider_value(
            refs.sensitivity,
            mouse_override_defaults.sensitivity
        ) * 0.01

        mouse_override_state.offset_x = mouse_override_state.offset_x + dx * sensitivity
        mouse_override_state.offset_y = mouse_override_state.offset_y + dy * sensitivity

        local distance = math.sqrt(
            mouse_override_state.offset_x * mouse_override_state.offset_x
            + mouse_override_state.offset_y * mouse_override_state.offset_y
        )
        if distance > max_radius then
            mouse_override_state.offset_x = mouse_override_state.offset_x / distance * max_radius
            mouse_override_state.offset_y = mouse_override_state.offset_y / distance * max_radius
        end
    end

    function mouse_override.get_colors()
        local refs = angles_builder.mouse_override_refs
        local active_color = mouse_override_defaults.normal_color
        local disabled_color = mouse_override_defaults.clamp_color

        if refs.color_active ~= nil then
            local ok_active, value_active = pcall(refs.color_active.get, refs.color_active)
            if ok_active and value_active ~= nil then
                active_color = value_active
            end
        end

        if refs.color_disabled ~= nil then
            local ok_disabled, value_disabled = pcall(refs.color_disabled.get, refs.color_disabled)
            if ok_disabled and value_disabled ~= nil then
                disabled_color = value_disabled
            end
        end

        return active_color, disabled_color
    end

    angles_builder.start_mouse_override_radii_preview = function()
        mouse_override_state.radii_preview_until = globals.realtime + mouse_override_defaults.radii_preview_time
    end

    function mouse_override.update_state()
        local refs = angles_builder.mouse_override_refs
        local hotkey_ref = refs.hotkey
        if hotkey_ref == nil
            or mouse_override.is_hotkey_bound(hotkey_ref) ~= true then
            mouse_override_state.is_holding = false
            mouse_override_state.is_overriding = false
            mouse_override_state.yaw_value = nil
            mouse_override_state.inverter_value = nil
            mouse_override_state.offset_x = 0
            mouse_override_state.offset_y = 0
            mouse_override.set_cursor_clipped(false)
            return
        end

        local hotkey_active = hotkey_ref:get() == true and not mouse_override.is_menu_open()
        if hotkey_active then
            if mouse_override_state.is_holding ~= true then
                mouse_override_state.is_holding = true
                if is_selectable_enabled(refs.options, "Reset On Release") then
                    mouse_override_state.offset_x = 0
                    mouse_override_state.offset_y = 0
                    mouse_override_state.is_overriding = false
                    mouse_override_state.yaw_value = nil
                    mouse_override_state.inverter_value = nil
                end
            end
        elseif mouse_override_state.is_holding == true then
            mouse_override_state.is_holding = false

            local clamp_radius = mouse_override.get_slider_value(
                refs.clamp_radius,
                mouse_override_defaults.clamp_radius
            )
            local distance = math.sqrt(
                mouse_override_state.offset_x * mouse_override_state.offset_x
                + mouse_override_state.offset_y * mouse_override_state.offset_y
            )
            if distance < clamp_radius then
                mouse_override_state.offset_x = 0
                mouse_override_state.offset_y = 0
                mouse_override_state.is_overriding = false
                mouse_override_state.yaw_value = nil
                mouse_override_state.inverter_value = nil
            end
        end

        local distance = math.sqrt(
            mouse_override_state.offset_x * mouse_override_state.offset_x
            + mouse_override_state.offset_y * mouse_override_state.offset_y
        )
        if distance < mouse_override_defaults.center_deadzone then
            if mouse_override_state.is_overriding == true then
                mouse_override_state.offset_x = 0
                mouse_override_state.offset_y = 0
            end
            mouse_override_state.is_overriding = false
            mouse_override_state.yaw_value = nil
            mouse_override_state.inverter_value = nil
            return
        end

        mouse_override_state.is_overriding = true
        local angle_rad = math.atan2(mouse_override_state.offset_y, mouse_override_state.offset_x)
        local angle_deg = math.deg(angle_rad)
        mouse_override_state.yaw_value = math.floor(math.normalize_yaw(90 - angle_deg) + 0.5)
        mouse_override_state.inverter_value = (
            (mouse_override_state.offset_x > 0)
            == (mouse_override_state.offset_y > 0)
        )
    end

    function mouse_override.on_mouse_input()
        if mouse_override_state.ffi_ready ~= true then
            return
        end

        local hotkey_ref = angles_builder.mouse_override_refs.hotkey
        if hotkey_ref == nil then
            return
        end

        if mouse_override.is_menu_open() then
            return
        end

        local hotkey_active = hotkey_ref:get() == true
        if hotkey_active ~= true and mouse_override_state.is_holding ~= true then
            return
        end

        mouse_override.set_cursor_clipped(true)
        if mouse_override_state.is_cursor_clipped
            and hotkey_active
            and mouse_override_state.is_holding then
            local mouse = ui.get_mouse_position()
            if mouse ~= nil then
                local dx = mouse.x - mouse_override_state.lock_center_x
                local dy = mouse.y - mouse_override_state.lock_center_y
                if dx ~= 0 or dy ~= 0 then
                    mouse_override.apply_delta(dx, dy)
                    local ffi = mouse_override_state.ffi
                    if ffi ~= nil then
                        pcall(ffi.C.SetCursorPos, mouse_override_state.lock_center_x, mouse_override_state.lock_center_y)
                    end
                end
            end
        end

        mouse_override.hide_cursor()
        return false
    end

    function mouse_override.on_pre_render()
        if mouse_override_state.ffi_ready ~= true then
            return
        end

        local hotkey_ref = angles_builder.mouse_override_refs.hotkey
        if hotkey_ref == nil then
            mouse_override.set_cursor_clipped(false)
            return
        end

        if mouse_override.is_menu_open() then
            mouse_override.set_cursor_clipped(false)
            return
        end

        local should_lock_cursor = hotkey_ref:get() == true
            or mouse_override_state.is_holding == true
        if should_lock_cursor ~= true then
            mouse_override.set_cursor_clipped(false)
            return
        end

        mouse_override.set_cursor_clipped(true)
        mouse_override.hide_cursor()
    end

    function mouse_override.on_render()
        local hotkey_ref = angles_builder.mouse_override_refs.hotkey
        if hotkey_ref == nil then
            return
        end

        if mouse_override.is_hotkey_bound(hotkey_ref) ~= true then
            return
        end

        local show_radii = mouse_override.is_menu_open() and globals.realtime < mouse_override_state.radii_preview_until
        local show_dot = mouse_override_state.is_overriding or mouse_override_state.is_holding
        if show_radii ~= true and show_dot ~= true then
            return
        end

        local screen = render.screen_size()
        local center = screen * 0.5
        local dot_position = center + vector(mouse_override_state.offset_x, mouse_override_state.offset_y)

        local normal_color, clamp_color = mouse_override.get_colors()
        local clamp_radius = mouse_override.get_slider_value(
            angles_builder.mouse_override_refs.clamp_radius,
            mouse_override_defaults.clamp_radius
        )
        local max_radius = mouse_override.get_slider_value(
            angles_builder.mouse_override_refs.max_radius,
            mouse_override_defaults.max_radius
        )
        local distance = math.sqrt(
            mouse_override_state.offset_x * mouse_override_state.offset_x
            + mouse_override_state.offset_y * mouse_override_state.offset_y
        )
        local dot_color = normal_color
        if distance < clamp_radius then
            dot_color = clamp_color
        end

        if show_radii then
            local clamp_render_color = clamp_color:clone()
            clamp_render_color.a = math.floor(clamp_render_color.a * 0.35)

            local max_render_color = normal_color:clone()
            max_render_color.a = math.floor(max_render_color.a * 0.2)

            render.circle_outline(center, clamp_render_color, clamp_radius, 0, 1.0, 1)
            render.circle_outline(center, max_render_color, max_radius, 0, 1.0, 1)
        end

        if show_dot then
            render.circle_gradient(
                dot_position,
                color(dot_color.r, dot_color.g, dot_color.b, 0),
                color(dot_color.r, dot_color.g, dot_color.b, dot_color.a),
                mouse_override_defaults.dot_radius,
                0,
                1.0
            )
        end
    end

    angles_builder.manual_yaw = angles_builder.manual_yaw or {
    }

    function angles_builder.manual_yaw.update_toggle_state()
        local direction = "Disabled"
        local direction_ref = angles_builder.manual_yaw_refs.direction
        if direction_ref ~= nil then
            local value = direction_ref:get()
            if type(value) == "string" and value ~= "" then
                direction = value
            end
        end

        angles_builder.manual_yaw_toggle_state.left = direction == "Left"
        angles_builder.manual_yaw_toggle_state.forward = direction == "Forward"
        angles_builder.manual_yaw_toggle_state.right = direction == "Right"
    end

    function angles_builder.manual_yaw.get_offset()
        if mouse_override_state.yaw_value ~= nil then
            return mouse_override_state.yaw_value
        end

        if angles_builder.manual_yaw_toggle_state.left == true then
            return -90
        end

        if angles_builder.manual_yaw_toggle_state.forward == true then
            return 180
        end

        if angles_builder.manual_yaw_toggle_state.right == true then
            return 90
        end

        return nil
    end

    function angles_builder.manual_yaw.is_active()
        return angles_builder.manual_yaw.get_offset() ~= nil
    end

    function angles_builder.manual_yaw.uses_at_target()
        local at_target_ref = angles_builder.manual_yaw_refs.at_target_on
        if at_target_ref == nil then
            return false
        end

        if angles_builder.manual_yaw_toggle_state.left == true then
            return is_selectable_enabled(at_target_ref, "Left")
        end

        if angles_builder.manual_yaw_toggle_state.forward == true then
            return is_selectable_enabled(at_target_ref, "Forward")
        end

        if angles_builder.manual_yaw_toggle_state.right == true then
            return is_selectable_enabled(at_target_ref, "Right")
        end

        return false
    end

    local freestanding = {
    }

    function freestanding.update_requested()
        local refs = angles_builder.freestanding_refs
        local hotkey_ref = refs.hotkey
        if hotkey_ref == nil then
            angles_builder.freestanding_toggle_state = false
            angles_builder.freestanding_requested = false
            return
        end

        local should_enable = hotkey_ref:get() == true

        if should_enable ~= true
            and is_selectable_enabled(refs.tweaks, "Force with Peek Assist")
            and movement_helpers.is_peek_assist_active() then
            should_enable = true
        end

        angles_builder.freestanding_requested = should_enable == true
    end

    function freestanding.is_disabler_active(local_player, command)
        local refs = angles_builder.freestanding_refs
        if refs.disablers == nil then
            return false
        end

        local velocity = local_player.m_vecVelocity
        local velocity_length = 0
        if velocity ~= nil and velocity.length ~= nil then
            velocity_length = velocity:length()
        end

        local is_jumping = not is_on_ground(local_player.m_fFlags)
            or movement_helpers.get_command_value(command, "in_jump")
        local is_fakeducking = movement_helpers.is_fake_duck_active()
        local duck_amount = local_player.m_flDuckAmount or 0
        local is_crouching = (
            (velocity_length <= 1.1001 and duck_amount ~= 0)
            or (velocity_length > 1.1001 and duck_amount == 1)
        ) and not is_fakeducking
        local is_standing = velocity_length <= 1.1001
            and not is_crouching
            and not is_jumping
        local is_slowwalking = is_slow_walk_active()
            and velocity_length >= 1.1001
            and not is_jumping
            and not is_crouching

        if is_selectable_enabled(refs.disablers, "Standing") and is_standing then
            return true
        end

        if is_selectable_enabled(refs.disablers, "Jumping") and is_jumping then
            return true
        end

        if is_selectable_enabled(refs.disablers, "Fake Duck") and is_fakeducking then
            return true
        end

        if is_selectable_enabled(refs.disablers, "Crouching") and is_crouching then
            return true
        end

        if is_selectable_enabled(refs.disablers, "Slow-Motion") and is_slowwalking then
            return true
        end

        return false
    end

    function freestanding.update(command)
        local freestanding_ref = nl.aa and nl.aa.angles and nl.aa.angles.freestanding
        local refs = angles_builder.freestanding_refs
        if refs.hotkey == nil or refs.disablers == nil or refs.tweaks == nil then
            angles_builder.freestanding_toggle_state = false
            angles_builder.freestanding_requested = false
            angles_builder.freestanding_active = false
            angles_builder.freestanding_static = false
            if freestanding_ref ~= nil then
                freestanding_ref:override()
            end
            return
        end

        freestanding.update_requested()

        local manual_active = angles_builder.manual_yaw.is_active()
        if runtime_state.is_throwing_grenade == true or manual_active then
            if runtime_state.is_throwing_grenade ~= true
                and manual_active
                and is_selectable_enabled(refs.tweaks, "Reset on Manual AA") then
                angles_builder.freestanding_toggle_state = false
            end
            angles_builder.freestanding_requested = false
        end

        local local_player = entity.get_local_player()
        local can_enable = angles_builder.freestanding_requested == true
        if local_player == nil or local_player:is_alive() ~= true then
            can_enable = false
        end
        if can_enable and freestanding.is_disabler_active(local_player, command) then
            can_enable = false
        end

        if freestanding_ref ~= nil then
            freestanding_ref:override(can_enable)
        end

        angles_builder.freestanding_static = false
        if can_enable and rage ~= nil and rage.antiaim ~= nil and rage.antiaim.get_target ~= nil then
            local ok_target, target = pcall(rage.antiaim.get_target, rage.antiaim, true)
            angles_builder.freestanding_active = ok_target and target ~= nil
            if angles_builder.freestanding_active
                and is_selectable_enabled(refs.tweaks, "Static")
                and type(target) == "number" then
                angles_builder.freestanding_static = true
            end
        else
            angles_builder.freestanding_active = false
        end
    end

    do
        safe_head_controller = (function()
            local safe_head_enabled = false
            local safe_head_active = false
            local safe_head_state = nil

            local function reset_safe_head_state()
                safe_head_active = false
                safe_head_state = nil
            end

            local function set_safe_head_hidden_override(state)
                local angles = nl.aa and nl.aa.angles
                if angles == nil or angles.hidden == nil then
                    return
                end

                if state == true then
                    angles.hidden:override(false)
                    return
                end

                if hidden_defensive_state.is_overriding ~= true then
                    angles.hidden:override()
                end
            end

            local function get_safe_head_yaw_add(state_name)
                if state_name == "Air Crouch Knife" then
                    return 37
                end

                return 0
            end

            local function get_safe_head_hidden_override(state_name)
                local yaw_add = get_safe_head_yaw_add(state_name)
                return -180 + yaw_add, 0
            end

            local function should_apply_safe_head_hidden_override()
                if safe_head_active ~= true or safe_head_state == nil then
                    return false
                end

                if runtime_state.is_defensive_active ~= true then
                    return false
                end

                if is_hidden_defensive_enabled() ~= true then
                    return false
                end

                return is_hidden_defensive_disabler_active() ~= true
            end

            local function is_safe_head_state_enabled(state_name)
                local states_ref = angles_builder.safe_head_refs.states
                if states_ref == nil then
                    return true
                end

                local ok_values, values = pcall(states_ref.get, states_ref)
                if not ok_values or type(values) ~= "table" or #values == 0 then
                    return true
                end

                return is_selectable_enabled(states_ref, state_name)
            end

            local function is_safe_head_torso_hit(trace, local_player)
                if trace == nil or local_player == nil or trace.entity ~= local_player then
                    return false
                end

                local hitbox = trace.hitbox
                if type(hitbox) == "number" then
                    return hitbox >= 2 and hitbox <= 6
                end

                local hitgroup = trace.hitgroup
                return hitgroup == 2 or hitgroup == 3
            end

            local function can_threat_lethally_bodyshot(local_player, threat)
                if local_player == nil
                    or threat == nil
                    or utils == nil
                    or utils.trace_bullet == nil then
                    return false
                end

                if threat:is_alive() ~= true
                    or threat:is_dormant() == true
                    or threat:is_enemy() ~= true then
                    return false
                end

                local health = local_player.m_iHealth
                if type(health) ~= "number" or health <= 0 then
                    return false
                end

                local eye_position = threat:get_eye_position()
                if eye_position == nil then
                    return false
                end

                local weapon = threat:get_player_weapon()
                if weapon == nil or weapon:is_weapon() ~= true then
                    return false
                end

                local weapon_info = weapon:get_weapon_info()
                if weapon_info == nil then
                    return false
                end

                local weapon_type = weapon_info.weapon_type
                if weapon_type == 0 or weapon_type == 9 then
                    return false
                end

                if weapon:get_weapon_reload() ~= -1 then
                    return false
                end

                if weapon.m_iClip1 ~= nil and weapon.m_iClip1 <= 0 then
                    return false
                end

                local current_time = globals.curtime
                local next_primary_attack = weapon.m_flNextPrimaryAttack or 0
                if weapon_info.is_revolver == true then
                    if current_time < next_primary_attack then
                        return false
                    end
                else
                    local next_attack = threat.m_flNextAttack or 0
                    if current_time < next_attack or current_time < next_primary_attack then
                        return false
                    end
                end

                local function is_hitbox_lethal(hitbox_index)
                    local hitbox_position = local_player:get_hitbox_position(hitbox_index)
                    if hitbox_position == nil then
                        return false
                    end

                    local damage, trace = utils.trace_bullet(
                        threat,
                        eye_position,
                        hitbox_position
                    )
                    if type(damage) ~= "number" or damage < health then
                        return false
                    end

                    return is_safe_head_torso_hit(trace, local_player)
                end

                return is_hitbox_lethal(2)
                    or is_hitbox_lethal(3)
                    or is_hitbox_lethal(4)
                    or is_hitbox_lethal(5)
                    or is_hitbox_lethal(6)
            end

            local function is_safe_head_disable_active(local_player, threat)
                local disable_on_ref = angles_builder.safe_head_refs.disable_on
                if disable_on_ref == nil then
                    return false
                end

                if is_selectable_enabled(disable_on_ref, "Freestanding")
                    and (
                        angles_builder.freestanding_requested == true
                        or angles_builder.freestanding_active == true
                    ) then
                    return true
                end

                if is_selectable_enabled(disable_on_ref, "Manual Yaw")
                    and angles_builder.manual_yaw.is_active() then
                    return true
                end

                if is_selectable_enabled(disable_on_ref, "Weapon Switch")
                    and runtime_state.condition_index == condition.weapon_switch then
                    return true
                end

                if is_selectable_enabled(disable_on_ref, "Lethal")
                    and can_threat_lethally_bodyshot(local_player, threat) == true then
                    return true
                end

                return false
            end

            local function get_safe_head_state(local_player, threat)
                if local_player == nil or threat == nil then
                    return nil
                end

                local weapon = local_player:get_player_weapon()
                if weapon == nil then
                    return nil
                end

                local weapon_info = weapon:get_weapon_info()
                if weapon_info == nil then
                    return nil
                end

                local weapon_name = weapon_info.weapon_name
                local weapon_index = weapon:get_weapon_index()

                local local_origin = local_player:get_origin()
                local threat_origin = threat:get_origin()
                if local_origin == nil or threat_origin == nil then
                    return nil
                end

                local velocity = local_player.m_vecVelocity
                local velocity2d = 0
                if velocity ~= nil and velocity.length2d ~= nil then
                    velocity2d = velocity:length2d()
                end

                local duck_amount = local_player.m_flDuckAmount or 0
                local is_crouched = duck_amount > 0
                local is_moving = velocity2d > runtime_cfg.moving_speed_threshold
                local height = local_origin.z - threat_origin.z
                local distance_sqr = local_origin:dist2dsqr(threat_origin)

                if is_on_ground(local_player.m_fFlags) then
                    local is_distance_state = not is_moving or is_crouched
                    if is_distance_state and height >= 10 and distance_sqr > 1000 * 1000 then
                        return "Distance"
                    end

                    if is_crouched then
                        if height >= 48 then
                            return "Crouch"
                        end
                    elseif not is_moving and height >= 24 then
                        return "Standing"
                    end

                    return nil
                end

                if is_crouched ~= true then
                    return nil
                end

                if weapon_index == 31 and height > -20 and distance_sqr < 500 * 500 then
                    return "Air Crouch Taser"
                end

                if weapon_name == "weapon_knife" and height > -100 then
                    return "Air Crouch Knife"
                end

                if height > 130 then
                    return "Air Crouch"
                end

                return nil
            end

            local function update_safe_head_state()
                if safe_head_enabled ~= true then
                    reset_safe_head_state()
                    return
                end

                local local_player = entity.get_local_player()
                if local_player == nil or local_player:is_alive() ~= true then
                    reset_safe_head_state()
                    return
                end

                local threat = entity.get_threat()
                if threat == nil then
                    reset_safe_head_state()
                    return
                end

                if is_safe_head_disable_active(local_player, threat) == true then
                    reset_safe_head_state()
                    return
                end

                local state_name = get_safe_head_state(local_player, threat)
                if state_name == nil or is_safe_head_state_enabled(state_name) ~= true then
                    reset_safe_head_state()
                    return
                end

                safe_head_state = state_name
                safe_head_active = true

                local freestanding_ref = nl.aa and nl.aa.angles and nl.aa.angles.freestanding
                if freestanding_ref ~= nil then
                    freestanding_ref:override(false)
                end
            end

            local function apply_safe_head_antiaim()
                if safe_head_active ~= true or safe_head_state == nil then
                    return false
                end

                if nl.aa == nil or nl.aa.angles == nil then
                    reset_safe_head_state()
                    return false
                end

                local yaw_add = get_safe_head_yaw_add(safe_head_state)
                local left_limit = 0
                local right_limit = 0
                if safe_head_state == "Air Crouch Knife" then
                    left_limit = 60
                    right_limit = 60
                end

                if rage ~= nil and rage.antiaim ~= nil and rage.antiaim.inverter ~= nil then
                    rage.antiaim:inverter(false)
                end

                if should_apply_safe_head_hidden_override() == true
                    and rage ~= nil
                    and rage.antiaim ~= nil
                    and rage.antiaim.override_hidden_pitch ~= nil
                    and rage.antiaim.override_hidden_yaw_offset ~= nil
                    and nl.aa.angles.hidden ~= nil then
                    local hidden_yaw, hidden_pitch = get_safe_head_hidden_override(
                        safe_head_state
                    )

                    nl.aa.angles.hidden:override(true)
                    if hidden_yaw ~= 180 and hidden_yaw ~= -180 then
                        hidden_yaw = math.normalize_yaw(hidden_yaw)
                    end
                    rage.antiaim:override_hidden_yaw_offset(hidden_yaw)
                    rage.antiaim:override_hidden_pitch(
                        clamp_number(hidden_pitch, -89, 89)
                    )
                    hidden_defensive_state.is_overriding = true
                else
                    clear_hidden_defensive_overrides()
                    set_safe_head_hidden_override(true)
                end

                nl.aa.angles.pitch:override("Down")
                nl.aa.angles.yaw:override("Backward")
                nl.aa.angles.yaw_add:override(yaw_add)
                nl.aa.angles.inverter:override(false)
                nl.aa.angles.yaw_modifier:override("Disabled")
                nl.aa.angles.modifier_offset:override(0)
                nl.aa.angles.options:override({
                })

                if nl.aa.angles.yaw_base ~= nil then
                    nl.aa.angles.yaw_base:override("At Target")
                end

                if nl.aa.angles.left_limit ~= nil then
                    nl.aa.angles.left_limit:override(left_limit)
                end

                if nl.aa.angles.right_limit ~= nil then
                    nl.aa.angles.right_limit:override(right_limit)
                end

                if nl.aa.angles.body_yaw ~= nil then
                    nl.aa.angles.body_yaw:override(true)
                end

                if nl.aa.angles.body_freestanding ~= nil then
                    nl.aa.angles.body_freestanding:override(false)
                end

                if nl.aa.angles.freestanding ~= nil then
                    nl.aa.angles.freestanding:override(false)
                end

                return true
            end

            return {
                get_states = function()
                    return SAFE_HEAD_STATE_NAMES
                end,
                get_hidden_override = function()
                    if safe_head_active ~= true or safe_head_state == nil then
                        return nil, nil
                    end

                    return get_safe_head_hidden_override(safe_head_state)
                end,
                set_enabled = function(state)
                    safe_head_enabled = state == true
                    set_safe_head_hidden_override(safe_head_enabled)
                    if safe_head_enabled ~= true then
                        reset_safe_head_state()
                    end
                end,
                update = function()
                    update_safe_head_state()
                end,
                apply = function()
                    return apply_safe_head_antiaim()
                end,
                is_active = function()
                    return safe_head_active == true
                end,
                shutdown = function()
                    reset_safe_head_state()
                    safe_head_enabled = false
                    set_safe_head_hidden_override(false)
                end,
            }
        end)()
    end

    local function update_antiaims(command)
        if is_bombsite_efix_aa_override_active == true then
            reset_antiaim_view_sync()
            if nl.aa.angles.pitch ~= nil then
                nl.aa.angles.pitch:override("Disabled")
            end
            if nl.aa.angles.yaw ~= nil then
                nl.aa.angles.yaw:override("Disabled")
            end
            nl.aa.angles.yaw_add:override()
            nl.aa.angles.inverter:override()
            nl.aa.angles.options:override()
            nl.aa.angles.yaw_modifier:override()
            nl.aa.angles.modifier_offset:override()
            if nl.aa.angles.yaw_base ~= nil then
                nl.aa.angles.yaw_base:override()
            end
            if nl.aa.angles.body_yaw ~= nil then
                nl.aa.angles.body_yaw:override(true)
            end
            if nl.aa.angles.left_limit ~= nil then
                nl.aa.angles.left_limit:override(0)
            end
            if nl.aa.angles.right_limit ~= nil then
                nl.aa.angles.right_limit:override(0)
            end
            clear_exploit_overrides()
            clear_hidden_defensive_overrides()
            reset_other_special_aa_state()
            return
        end

        if apply_other_special_aa(command) == true then
            reset_antiaim_view_sync()
            antiaim_runtime_state.last_side = nil
            clear_exploit_overrides()
            return
        end

        local yaw_add = 0

        local left_yaw = -20
        local right_yaw = 40
        local yaw_variability = 0
        local yaw_modifier_enabled = false
        local yaw_modifier_switch_delay = 0
        local yaw_modifier_switch_variability = 0
        local yaw_modifier_mode = "Left Add"
        local yaw_modifier_value = 0
        local yaw_modifier_spin_speed = 210
        local yaw_modifier_variability = 0
        local applied_yaw_modifier = "Disabled"
        local applied_modifier_offset = nil
        local break_lc_double_tap = false
        local break_lc_hide_shots = false
        local body_yaw_enabled = false
        local body_switch_delay = 0
        local body_switch_variability = 0
        local body_left_limit = 60
        local body_right_limit = 60
        local body_limit_variability = 0

        local team_index = runtime_state.team_index
        local condition_index = resolve_condition_index(
            team_index,
            runtime_state.condition_index,
            runtime_state.base_condition_index
        )
        local team_view = nil
        local state_view = nil
        if condition_index ~= nil then
            team_view = condition_views[team_index]
            if team_view ~= nil then
                state_view = team_view[condition_index]
            end
        end

        local safe_head_applied = safe_head_controller.apply(command) == true
        if safe_head_applied == true then
            local local_player = entity.get_local_player()
            local local_weapon = nil
            if local_player ~= nil then
                local_weapon = local_player:get_player_weapon()
            end

            local break_lc_view = state_view
            local break_lc_double_tap = false
            local break_lc_hide_shots = false
            if break_lc_view ~= nil
                and break_lc_view.break_lc_mode_ref ~= nil
                and break_lc.is_disabled(local_weapon, false) ~= true then
                break_lc_double_tap = is_selectable_enabled(
                    break_lc_view.break_lc_mode_ref,
                    "Double Tap"
                )
                break_lc_hide_shots = is_selectable_enabled(
                    break_lc_view.break_lc_mode_ref,
                    "Hide Shots"
                )

                local value = break_lc_view.break_lc_mode_ref:get()
                if type(value) == "string" then
                    if value == "Double Tap" then
                        break_lc_double_tap = true
                    elseif value == "Hide Shots" then
                        break_lc_hide_shots = true
                    end
                elseif type(value) == "number" then
                    if value == 1 then
                        break_lc_double_tap = true
                    elseif value == 2 then
                        break_lc_hide_shots = true
                    end
                end
            end

            if break_lc.is_trigger_active(local_player, local_weapon)
                and break_lc.is_disabled(local_weapon, true) ~= true then
                break_lc_double_tap = true
                break_lc_hide_shots = true
            end

            local break_lc_native_double_tap = break_lc_double_tap
            local break_lc_custom_tickbase_active = break_lc_double_tap == true
                or break_lc_hide_shots == true
            if break_lc_custom_tickbase_active == true
                and break_lc.should_force_custom_defensive(
                    break_lc_view,
                    command,
                    team_index,
                    condition_index
                ) then
                command.force_defensive = true
            end
            if break_lc_double_tap == true
                and break_lc.uses_custom_advanced_tickbase(break_lc_view) == true then
                break_lc_native_double_tap = false
            end

            local rage_main = nl.rage and nl.rage.main
            if rage_main ~= nil and runtime_state.is_defensive_active ~= true then
                if rage_main.double_tap_lag_options ~= nil then
                    if break_lc_native_double_tap then
                        rage_main.double_tap_lag_options:override("Always On")
                    else
                        rage_main.double_tap_lag_options:override()
                    end
                end

                if rage_main.hide_shots_options ~= nil then
                    if break_lc_hide_shots then
                        rage_main.hide_shots_options:override("Break LC")
                    else
                        rage_main.hide_shots_options:override()
                    end
                end
            end

            antiaim_runtime_state.last_side = false
            reset_other_special_aa_state()
            return
        end
        if condition_index == nil then
            reset_antiaim_view_sync()
            nl.aa.angles.yaw_add:override()
            nl.aa.angles.inverter:override()
            nl.aa.angles.options:override()
            nl.aa.angles.pitch:override()
            nl.aa.angles.yaw:override()
            nl.aa.angles.yaw_modifier:override()
            nl.aa.angles.modifier_offset:override()
            if nl.aa.angles.yaw_base ~= nil then
                nl.aa.angles.yaw_base:override()
            end
            clear_body_yaw_overrides()
            clear_exploit_overrides()
            clear_hidden_defensive_overrides()
            clear_other_special_aa_overrides()
            return
        end

        if team_view == nil then
            reset_antiaim_view_sync()
            nl.aa.angles.yaw_add:override()
            nl.aa.angles.inverter:override()
            nl.aa.angles.options:override()
            nl.aa.angles.pitch:override()
            nl.aa.angles.yaw:override()
            nl.aa.angles.yaw_modifier:override()
            nl.aa.angles.modifier_offset:override()
            if nl.aa.angles.yaw_base ~= nil then
                nl.aa.angles.yaw_base:override()
            end
            clear_body_yaw_overrides()
            clear_exploit_overrides()
            clear_hidden_defensive_overrides()
            clear_other_special_aa_overrides()
            return
        end

        local view = state_view
        if view == nil then
            reset_antiaim_view_sync()
            nl.aa.angles.yaw_add:override()
            nl.aa.angles.inverter:override()
            nl.aa.angles.options:override()
            nl.aa.angles.pitch:override()
            nl.aa.angles.yaw:override()
            nl.aa.angles.yaw_modifier:override()
            nl.aa.angles.modifier_offset:override()
            if nl.aa.angles.yaw_base ~= nil then
                nl.aa.angles.yaw_base:override()
            end
            clear_body_yaw_overrides()
            clear_exploit_overrides()
            clear_hidden_defensive_overrides()
            clear_other_special_aa_overrides()
            return
        end

        local use_hidden_defensive = runtime_state.is_defensive_active == true
            and is_hidden_defensive_enabled() == true
        local defensive_builder_enabled = true
        if view.defensive_enabled_ref ~= nil then
            defensive_builder_enabled = view.defensive_enabled_ref:get() == true
        end

        local is_defensive_view = false
        -- Hidden defensive uses native hidden overrides and must keep the normal builder view.
        if runtime_state.is_defensive_active == true
            and defensive_builder_enabled == true
            and view.lc_runtime_view ~= nil
            and use_hidden_defensive ~= true then
            view = view.lc_runtime_view
            is_defensive_view = true
        end

        nl.aa.angles.pitch:override("Down")
        nl.aa.angles.yaw:override("Backward")
        nl.aa.angles.yaw_modifier:override("Disabled")
        nl.aa.angles.modifier_offset:override()

        sync_jitter_side_on_view_change(
            view,
            team_index,
            condition_index,
            is_defensive_view
        )

        local side, side_offset_override = get_inverter(view, team_index, condition_index)

        if view.left_yaw_ref ~= nil then
            local value = view.left_yaw_ref:get()
            if type(value) == "number" then
                left_yaw = value
            end
        end

        if view.right_yaw_ref ~= nil then
            local value = view.right_yaw_ref:get()
            if type(value) == "number" then
                right_yaw = value
            end
        end

        if condition_index == condition.crouch_running then
            local move_direction = movement_helpers.get_crouch_move_direction(command)
            left_yaw = get_crouch_direction_override_value(
                left_yaw,
                move_direction,
                view.left_yaw_crouch_dirs_ref,
                view.left_yaw_crouch_dir_refs
            )
            right_yaw = get_crouch_direction_override_value(
                right_yaw,
                move_direction,
                view.right_yaw_crouch_dirs_ref,
                view.right_yaw_crouch_dir_refs
            )
        end

        if view.variability_ref ~= nil then
            local value = view.variability_ref:get()
            if type(value) == "number" then
                yaw_variability = value
            end
        end

        local local_player = entity.get_local_player()
        local local_weapon = nil
        if local_player ~= nil then
            local_weapon = local_player:get_player_weapon()
        end

        local break_lc_view = state_view
        if break_lc_view ~= nil
            and break_lc_view.break_lc_mode_ref ~= nil
            and break_lc.is_disabled(local_weapon, false) ~= true then
            break_lc_double_tap = is_selectable_enabled(
                break_lc_view.break_lc_mode_ref,
                "Double Tap"
            )
            break_lc_hide_shots = is_selectable_enabled(
                break_lc_view.break_lc_mode_ref,
                "Hide Shots"
            )

            local value = break_lc_view.break_lc_mode_ref:get()
            if type(value) == "string" then
                if value == "Double Tap" then
                    break_lc_double_tap = true
                elseif value == "Hide Shots" then
                    break_lc_hide_shots = true
                end
            elseif type(value) == "number" then
                if value == 1 then
                    break_lc_double_tap = true
                elseif value == 2 then
                    break_lc_hide_shots = true
                end
            end
        end

        if break_lc.is_trigger_active(local_player, local_weapon)
            and break_lc.is_disabled(local_weapon, true) ~= true then
            break_lc_double_tap = true
            break_lc_hide_shots = true
        end

        local break_lc_native_double_tap = break_lc_double_tap
        local break_lc_custom_tickbase_active = break_lc_double_tap == true
            or break_lc_hide_shots == true
        local break_lc_custom_defensive = false
        if break_lc_custom_tickbase_active == true
            and break_lc.should_force_custom_defensive(
                break_lc_view,
                command,
                team_index,
                condition_index
            ) then
            break_lc_custom_defensive = true
        end
        if break_lc_double_tap == true
            and break_lc.uses_custom_advanced_tickbase(break_lc_view) == true then
            break_lc_native_double_tap = false
        end
        if break_lc_custom_defensive == true and command ~= nil then
            command.force_defensive = true
        end

        if view.body_yaw_switch_ref ~= nil then
            body_yaw_enabled = view.body_yaw_switch_ref:get() == true
        end

        if view.body_yaw_switch_delay_ref ~= nil then
            local value = view.body_yaw_switch_delay_ref:get()
            if type(value) == "number" then
                body_switch_delay = value
            end
        end

        if view.body_yaw_switch_var_ref ~= nil then
            local value = view.body_yaw_switch_var_ref:get()
            if type(value) == "number" then
                body_switch_variability = value
            end
        end

        if view.body_left_ref ~= nil then
            local value = view.body_left_ref:get()
            if type(value) == "number" then
                body_left_limit = value
            end
        end

        if view.body_right_ref ~= nil then
            local value = view.body_right_ref:get()
            if type(value) == "number" then
                body_right_limit = value
            end
        end

        if view.body_var_ref ~= nil then
            local value = view.body_var_ref:get()
            if type(value) == "number" then
                body_limit_variability = value
            end
        end

        if view.yaw_modifier_switch_ref ~= nil then
            yaw_modifier_enabled = view.yaw_modifier_switch_ref:get() == true
        end

        if view.yaw_modifier_switch_delay_ref ~= nil then
            local value = view.yaw_modifier_switch_delay_ref:get()
            if type(value) == "number" then
                yaw_modifier_switch_delay = value
            end
        end

        if view.yaw_modifier_switch_var_ref ~= nil then
            local value = view.yaw_modifier_switch_var_ref:get()
            if type(value) == "number" then
                yaw_modifier_switch_variability = value
            end
        end

        if view.yaw_modifier_mode_ref ~= nil then
            local value = view.yaw_modifier_mode_ref:get()
            if type(value) == "number" or type(value) == "string" then
                yaw_modifier_mode = value
            end
        end

        if view.yaw_modifier_value_ref ~= nil then
            local value = view.yaw_modifier_value_ref:get()
            if type(value) == "number" then
                yaw_modifier_value = value
            end
        end

        if view.yaw_modifier_speed_ref ~= nil then
            local value = view.yaw_modifier_speed_ref:get()
            if type(value) == "number" then
                yaw_modifier_spin_speed = value
            end
        end

        if view.yaw_modifier_variability_ref ~= nil then
            local value = view.yaw_modifier_variability_ref:get()
            if type(value) == "number" then
                yaw_modifier_variability = value
            end
        end

        if type(side_offset_override) == "number" and view.return_variations_ref ~= nil then
            if is_selectable_enabled(view.return_variations_ref, "Disable Jitter") then
                yaw_variability = 0
            end

            if is_selectable_enabled(view.return_variations_ref, "Disable Body Yaw") then
                body_yaw_enabled = false
            end

            if is_selectable_enabled(view.return_variations_ref, "Disable Yaw Modifier") then
                yaw_modifier_enabled = false
            end

            if is_selectable_enabled(view.return_variations_ref, "Force Inverter") then
                side = true
            end
        end

        local command_tick = resolve_command_tick_count(command)
        local manual_offset = angles_builder.manual_yaw.get_offset()
        local mouse_override_active = mouse_override_state.yaw_value ~= nil

        local manual_mode = "Default"
        if angles_builder.manual_yaw_mode_ref ~= nil then
            local mode_value = angles_builder.manual_yaw_mode_ref:get()
            if type(mode_value) == "string" and mode_value ~= "" then
                manual_mode = mode_value
            end
        end

        local is_manual_static = false
        if manual_offset ~= nil then
            if mouse_override_active then
                is_manual_static = is_selectable_enabled(
                    angles_builder.mouse_override_refs.options,
                    "Static"
                )
            else
                is_manual_static = manual_mode == "Static"
            end
        end
        local is_freestanding_static = angles_builder.freestanding_static == true
        local is_static_mode = is_manual_static or is_freestanding_static

        if is_static_mode ~= true then
            rage.antiaim:inverter(side)
        end

        local resolved_left_yaw = left_yaw
        local resolved_right_yaw = right_yaw
        local yaw_modifier_add = 0
        local yaw_modifier_state = get_body_yaw_state(team_index, condition_index)
        local mode_changed = yaw_modifier_state.mode ~= yaw_modifier_mode
        yaw_modifier_state.mode = yaw_modifier_mode
        if mode_changed == true then
            yaw_modifier_state.drift_phase = 0
            yaw_modifier_state.drift_step_index = 1
            yaw_modifier_state.drift_next_step_tick = command_tick
            yaw_modifier_state.drift_direction = 1
            yaw_modifier_state.drift_next_reverse_tick = nil
            yaw_modifier_state.sanya_counter = 0
            yaw_modifier_state.bobro_step = 1
        end

        if yaw_modifier_enabled and manual_offset == nil then
            local switch_active = is_yaw_modifier_switch_active(
                yaw_modifier_state,
                yaw_modifier_switch_delay,
                yaw_modifier_switch_variability,
                mode_changed
            )

            if switch_active == true then
                local mode_seed = 1
                if yaw_modifier_mode == 2 or yaw_modifier_mode == "Right Add" then
                    mode_seed = 2
                elseif yaw_modifier_mode == 3 or yaw_modifier_mode == "Center" then
                    mode_seed = 3
                elseif yaw_modifier_mode == 4 or yaw_modifier_mode == "3-way" then
                    mode_seed = 4
                elseif yaw_modifier_mode == 5 or yaw_modifier_mode == "Spin" then
                    mode_seed = 5
                elseif yaw_modifier_mode == 6 or yaw_modifier_mode == "Hybrid" then
                    mode_seed = 6
                elseif yaw_modifier_mode == 7 or yaw_modifier_mode == "Stair" then
                    mode_seed = 7
                end

                local modifier_value = get_yaw_modifier_effective_value(
                    yaw_modifier_value,
                    yaw_modifier_variability,
                    team_index,
                    condition_index,
                    mode_seed,
                    command_tick
                )

                if yaw_modifier_mode == 1 or yaw_modifier_mode == "Left Add" then
                    resolved_left_yaw = resolved_left_yaw + modifier_value
                    yaw_modifier_state.three_way_state = 2
                elseif yaw_modifier_mode == 2 or yaw_modifier_mode == "Right Add" then
                    resolved_right_yaw = resolved_right_yaw + modifier_value
                    yaw_modifier_state.three_way_state = 2
                elseif yaw_modifier_mode == 3 or yaw_modifier_mode == "Center" then
                    local half_value = modifier_value * 0.5
                    resolved_left_yaw = resolved_left_yaw + half_value
                    resolved_right_yaw = resolved_right_yaw - half_value
                    yaw_modifier_state.three_way_state = 2
                elseif yaw_modifier_mode == 4 or yaw_modifier_mode == "3-way" then
                    yaw_modifier_add = yaw_modifier_add + get_three_way_yaw_modifier_add(
                        yaw_modifier_state,
                        modifier_value,
                        globals.choked_commands == 0
                    )
                elseif yaw_modifier_mode == 5 or yaw_modifier_mode == "Spin" then
                    local spin_time = globals.curtime
                    if type(spin_time) ~= "number" then
                        spin_time = command_tick * globals.tickinterval
                    end

                    local spin_amount = math.abs(modifier_value)
                    if spin_amount > 0 then
                        local spin_speed = clamp_number(math.abs(yaw_modifier_spin_speed), 1, 720)
                        local spin_raw = (spin_time * spin_speed) % 360 - 180
                        local spin_offset = (spin_raw / 180) * spin_amount
                        yaw_modifier_add = yaw_modifier_add + spin_offset
                    end
                    yaw_modifier_state.three_way_state = 2
                elseif yaw_modifier_mode == 6 or yaw_modifier_mode == "Hybrid" then
                    local sanya_value = clamp_number(modifier_value, -180, 180)
                    local sanya_add = sanya_value * 0.5
                    local sanya_offset = math.abs(sanya_value) * 0.5
                    if globals.choked_commands == 0 then
                        yaw_modifier_state.sanya_counter = (yaw_modifier_state.sanya_counter or 0) + 1
                    end

                    resolved_left_yaw = resolved_left_yaw + sanya_add
                    resolved_right_yaw = resolved_right_yaw - sanya_add
                    applied_yaw_modifier = yaw_modifier_state.sanya_counter % 10 == 0 and "Random" or "3-way"
                    applied_modifier_offset = sanya_offset
                    yaw_modifier_state.three_way_state = 2
                elseif yaw_modifier_mode == 7 or yaw_modifier_mode == "Stair" then
                    local bobro_step = yaw_modifier_state.bobro_step
                    if type(bobro_step) ~= "number" then
                        bobro_step = 1
                    end

                    if globals.choked_commands == 0 then
                        bobro_step = bobro_step + 1
                        if bobro_step >= 7 then
                            bobro_step = 1
                        end
                    end

                    yaw_modifier_state.bobro_step = bobro_step
                    applied_yaw_modifier = "3-Way"
                    applied_modifier_offset = get_bobro_yaw_modifier_offset(modifier_value, bobro_step)
                    yaw_modifier_state.three_way_state = 2
                end
            end
        else
            yaw_modifier_state.three_way_state = 2
            yaw_modifier_state.yaw_modifier_switch_state = true
            yaw_modifier_state.yaw_modifier_switch_packets = 0
            yaw_modifier_state.yaw_modifier_switch_last_flip = 0
            yaw_modifier_state.drift_phase = 0
            yaw_modifier_state.drift_step_index = 1
            yaw_modifier_state.drift_next_step_tick = command_tick
            yaw_modifier_state.drift_direction = 1
            yaw_modifier_state.drift_next_reverse_tick = nil
            yaw_modifier_state.sanya_counter = 0
            yaw_modifier_state.bobro_step = 1
        end

        resolved_left_yaw = clamp_number(resolved_left_yaw, -180, 180)
        resolved_right_yaw = clamp_number(resolved_right_yaw, -180, 180)

        local offset = side and resolved_left_yaw or resolved_right_yaw
        if manual_offset ~= nil then
            offset = manual_offset
        elseif type(side_offset_override) == "number" then
            offset = side_offset_override
        elseif yaw_variability > 0 then
            offset = offset + get_smart_yaw_variation(
                resolved_left_yaw,
                resolved_right_yaw,
                yaw_variability,
                team_index,
                condition_index,
                side
            )
        end
        offset = offset + yaw_modifier_add
        offset = math.max(-180, math.min(180, offset))
        yaw_add = yaw_add + offset

        if nl.aa.angles.yaw_base ~= nil then
            if manual_offset ~= nil then
                local use_at_target = false
                if mouse_override_active then
                    use_at_target = is_selectable_enabled(
                        angles_builder.mouse_override_refs.options,
                        "At Target"
                    )
                else
                    use_at_target = angles_builder.manual_yaw.uses_at_target()
                end

                if use_at_target then
                    nl.aa.angles.yaw_base:override("At Target")
                else
                    nl.aa.angles.yaw_base:override("Local View")
                end
            else
                nl.aa.angles.yaw_base:override()
            end
        end

        nl.aa.angles.yaw_modifier:override(applied_yaw_modifier)
        if applied_modifier_offset ~= nil then
            nl.aa.angles.modifier_offset:override(applied_modifier_offset)
        else
            nl.aa.angles.modifier_offset:override()
        end
        nl.aa.angles.yaw_add:override(yaw_add)
        if is_static_mode ~= true then
            nl.aa.angles.inverter:override(side)
        else
            nl.aa.angles.inverter:override()
        end

        antiaim_runtime_state.last_team_index = team_index
        antiaim_runtime_state.last_condition_index = condition_index
        antiaim_runtime_state.last_defensive_view = is_defensive_view
        antiaim_runtime_state.last_side = side

        nl.aa.angles.options:override({
        })

        if is_static_mode == true then
            clear_body_yaw_overrides()
        else
            local body_yaw_value = body_yaw_enabled
            local body_left_value = body_left_limit
            local body_right_value = body_right_limit
            local body_state = get_body_yaw_state(team_index, condition_index)

            if body_yaw_enabled ~= true then
                body_state.switch_state = false
                body_state.switch_packets = 0
                body_state.switch_last_flip = 0
            else
                local switch_delay = clamp_number(math.floor(body_switch_delay), 0, 20)
                local switch_var = clamp_number(body_switch_variability, 0, 100)
                if switch_delay == 0 then
                    body_yaw_value = true
                else
                    body_yaw_value = update_body_yaw_flipper(
                        body_state,
                        "switch",
                        switch_delay,
                        switch_var
                    )
                end

                local limit_var = clamp_number(body_limit_variability, 0, 100)
                if limit_var > 0 then
                    local max_desync_value = get_current_max_desync()
                    local left_base = resolve_body_variability_base(
                        body_left_limit,
                        max_desync_value
                    )
                    local right_base = resolve_body_variability_base(
                        body_right_limit,
                        max_desync_value
                    )
                    local left_upper = get_body_variability_upper_bound(
                        body_left_limit,
                        max_desync_value
                    )
                    local right_upper = get_body_variability_upper_bound(
                        body_right_limit,
                        max_desync_value
                    )

                    body_left_value = clamp_number(
                        left_base + get_smart_body_variation(
                            left_base,
                            limit_var,
                            team_index,
                            condition_index,
                            1
                        ),
                        0,
                        left_upper
                    )
                    body_right_value = clamp_number(
                        right_base + get_smart_body_variation(
                            right_base,
                            limit_var,
                            team_index,
                            condition_index,
                            2
                        ),
                        0,
                        right_upper
                    )
                else
                    body_left_value = clamp_number(body_left_limit, 0, 60)
                    body_right_value = clamp_number(body_right_limit, 0, 60)
                end
            end

            if nl.aa.angles.body_yaw ~= nil then
                nl.aa.angles.body_yaw:override(body_yaw_value)
            end

            if body_yaw_value == true then
                if nl.aa.angles.left_limit ~= nil then
                    nl.aa.angles.left_limit:override(
                        clamp_number(math.floor(body_left_value), 0, 60)
                    )
                end

                if nl.aa.angles.right_limit ~= nil then
                    nl.aa.angles.right_limit:override(
                        clamp_number(math.floor(body_right_value), 0, 60)
                    )
                end
            else
                if nl.aa.angles.left_limit ~= nil then
                    nl.aa.angles.left_limit:override()
                end

                if nl.aa.angles.right_limit ~= nil then
                    nl.aa.angles.right_limit:override()
                end
            end
        end

        local rage_main = nl.rage and nl.rage.main
        if rage_main ~= nil and runtime_state.is_defensive_active ~= true then
            if rage_main.double_tap_lag_options ~= nil then
                if break_lc_native_double_tap then
                    rage_main.double_tap_lag_options:override("Always On")
                else
                    rage_main.double_tap_lag_options:override()
                end
            end

            if rage_main.hide_shots_options ~= nil then
                if break_lc_hide_shots then
                    rage_main.hide_shots_options:override("Break LC")
                else
                    rage_main.hide_shots_options:override()
                end
            end
        end

        if use_hidden_defensive == true then
            apply_hidden_defensive_overrides(side)
            return
        end

        clear_hidden_defensive_overrides()
    end

    local antiaim_callbacks = {
    }

    function antiaim_callbacks.update_player(cmd)
        local choked = nil
        if cmd ~= nil then
            choked = cmd.choked_commands
        end

        if type(choked) ~= "number" then
            choked = globals.choked_commands
        end

        if type(choked) ~= "number" then
            choked = 0
        end

        if choked == 0 then
            runtime_state.sent_packets = runtime_state.sent_packets + 1
        end
    end

    function antiaim_callbacks.on_createmove(cmd)
        antiaim_callbacks.update_player(cmd)
        update_runtime_state(cmd)
        mouse_override.update_state()
        freestanding.update(cmd)
        if update_defensive_state ~= nil then
            update_defensive_state(cmd)
        end
        safe_head_controller.update(cmd)
        update_antiaims(cmd)
    end

    function antiaim_callbacks.on_shutdown()
        mouse_override.set_cursor_clipped(false)
        mouse_override_state.offset_x = 0
        mouse_override_state.offset_y = 0
        mouse_override_state.is_holding = false
        mouse_override_state.is_overriding = false
        mouse_override_state.yaw_value = nil
        mouse_override_state.inverter_value = nil

        local freestanding_ref = nl.aa and nl.aa.angles and nl.aa.angles.freestanding
        if freestanding_ref ~= nil then
            freestanding_ref:override()
        end

        local avoid_backstab_ref = nl.aa and nl.aa.angles and nl.aa.angles.avoid_backstab
        if avoid_backstab_ref ~= nil then
            avoid_backstab_ref:override()
        end

        clear_hidden_defensive_overrides()
        clear_other_special_aa_overrides()
        safe_head_controller.shutdown()
    end

    events.mouse_input(mouse_override.on_mouse_input, true)
    events.pre_render(mouse_override.on_pre_render, true)
    events.render(mouse_override.on_render, true)
    events.createmove(antiaim_callbacks.on_createmove)
    events.round_end(function()
        other_aa_state.round_end_active = true
    end, true)
    events.round_prestart(function()
        other_aa_state.round_end_active = false
    end, true)
    events.round_start(function()
        other_aa_state.round_end_active = false
    end, true)

    local defensive_runtime = {
        sv_maxcmds = cvar.sv_maxusrcmdprocessticks,
        data = {
            max_tickbase = 0,
            tickbase_diff = 0,
            ticks_processed = 0,
            last_alive = false,
            last_spawn_time = 0,
        },
    }

    function defensive_runtime.reset()
        local data = defensive_runtime.data
        data.max_tickbase = 0
        data.tickbase_diff = 0
        data.ticks_processed = 0
        data.last_alive = false
        data.last_spawn_time = 0
        runtime_state.is_defensive_active = false
    end

    update_defensive_state = function(cmd)
        local data = defensive_runtime.data
        local me = entity.get_local_player()
        if me == nil then
            defensive_runtime.reset()
            return
        end

        local is_alive = me:is_alive() == true
        if is_alive ~= data.last_alive then
            data.max_tickbase = 0
            data.tickbase_diff = 0
            data.ticks_processed = 0
            data.last_alive = is_alive
            runtime_state.is_defensive_active = false
            return
        end

        if is_alive ~= true then
            runtime_state.is_defensive_active = false
            return
        end

        local spawn_time = me.m_flSpawnTime
        if spawn_time ~= data.last_spawn_time then
            data.max_tickbase = 0
            data.tickbase_diff = 0
            data.ticks_processed = 0
            data.last_spawn_time = spawn_time
            runtime_state.is_defensive_active = false
            return
        end

        local tickbase = me.m_nTickBase
        if type(tickbase) ~= "number" then
            defensive_runtime.reset()
            return
        end

        local choked = 0
        if cmd ~= nil and type(cmd.choked_commands) == "number" then
            choked = cmd.choked_commands
        elseif type(globals.choked_commands) == "number" then
            choked = globals.choked_commands
        end

        local max_ticks = 0
        if defensive_runtime.sv_maxcmds ~= nil then
            local value = defensive_runtime.sv_maxcmds:int()
            if type(value) == "number" then
                max_ticks = math.abs(value) - 1
            end
        end

        if max_ticks <= 1 then
            data.tickbase_diff = 0
            data.ticks_processed = 0
            runtime_state.is_defensive_active = false
            return
        end

        if tickbase > data.max_tickbase then
            if choked == 0 then
                if math.abs(tickbase - data.max_tickbase) > max_ticks then
                    data.max_tickbase = tickbase
                    data.tickbase_diff = 0
                    data.ticks_processed = 0
                    runtime_state.is_defensive_active = false
                    return
                end

                data.max_tickbase = tickbase
            end
        end

        data.tickbase_diff = math.max(
            data.max_tickbase - tickbase,
            0
        )
        data.ticks_processed = math.min(
            data.tickbase_diff,
            max_ticks - choked
        )

        runtime_state.is_defensive_active =
            data.ticks_processed > 1
            and data.ticks_processed < max_ticks
    end

    events.level_init(function()
        other_aa_state.round_end_active = false
        defensive_runtime.reset()
        clear_hidden_defensive_overrides()
        clear_other_special_aa_overrides()
    end)
    events.shutdown(antiaim_callbacks.on_shutdown, true)

    function angles_builder.set_visibility(visible)
        layout_state.is_builder_visible = visible == true

        if layout_state.is_builder_visible ~= true then
            layout_state.is_defensive_builder_open = false
            selector_group:visibility(true)
            mode_group:visibility(false)
            transfer_group:visibility(false)
            portal_group:visibility(false)
            hide_all_condition_views()
            update_team_visibility(mode_list:get())
            return
        end

        if layout_state.is_condition_menu_open == true then
            selector_group:visibility(false)
            mode_group:visibility(false)
            transfer_group:visibility(false)
            update_team_visibility(mode_list:get())
            hide_all_condition_views()

            portal_group:visibility(true)
            local team_view = condition_views[layout_state.active_team_index]
            if team_view ~= nil then
                local view = team_view[layout_state.active_condition_index]
                if view ~= nil then
                    set_condition_groups_visibility(
                        view,
                        true,
                        layout_state.is_defensive_builder_open == true
                    )
                end
            end

            update_nav_buttons()
            return
        end

        show_main_layout()
    end
end

