            Arrows = color(175, 255, 55, 255),
            Desync = color(35, 128, 255, 255),
        }

        angles_builder.manual_arrows_render = function()
            local me = entity.get_local_player()
            if me == nil or not me:is_alive() then
                return
            end

            local style = angles_builder.manual_yaw_arrows_style
            if style == "Disabled" then
                return
            end

            local is_left = angles_builder.manual_yaw_toggle_state.left == true
            local is_right = angles_builder.manual_yaw_toggle_state.right == true
            local is_forward = angles_builder.manual_yaw_toggle_state.forward == true
            if is_left ~= true
                and is_right ~= true
                and is_forward ~= true
                and style ~= "Team-Skeet" then
                return
            end

            local screen = render.screen_size()
            local center = screen * 0.5

            local color_arrows = angles_builder.manual_yaw_arrows_colors.Arrows
            local color_desync = angles_builder.manual_yaw_arrows_colors.Desync
            local color_disabled = angles_builder.manual_yaw_arrows_color_disabled
            local color_simple = color_arrows
            if angles_builder.manual_yaw_arrows_simple_color_ref ~= nil then
                local simple_value = angles_builder.manual_yaw_arrows_simple_color_ref:get()
                if simple_value ~= nil then
                    color_simple = simple_value
                end
            end
            local padding = angles_builder.manual_yaw_arrows_padding
            if angles_builder.manual_yaw_arrows_offset_ref ~= nil then
                local offset_value = angles_builder.manual_yaw_arrows_offset_ref:get()
                if type(offset_value) == "number" then
                    padding = offset_value
                end
            end

            if style == "Classic" then
                if is_left then
                    local text = "<"
                    local text_size = render.measure_text(
                        angles_builder.manual_yaw_arrows_font_classic,
                        "s",
                        text
                    )
                    local text_pos = vector(
                        center.x - text_size.x - padding + 1,
                        center.y - text_size.y * 0.5 - 1
                    )
                    render.text(
                        angles_builder.manual_yaw_arrows_font_classic,
                        text_pos,
                        color_simple,
                        "s",
                        text
                    )
                end

                if is_right then
                    local text = ">"
                    local text_size = render.measure_text(
                        angles_builder.manual_yaw_arrows_font_classic,
                        "s",
                        text
                    )
                    local text_pos = vector(
                        center.x + padding,
                        center.y - text_size.y * 0.5 - 1
                    )
                    render.text(
                        angles_builder.manual_yaw_arrows_font_classic,
                        text_pos,
                        color_simple,
                        "s",
                        text
                    )
                end

                if is_forward then
                    local text = "^"
                    local text_size = render.measure_text(
                        angles_builder.manual_yaw_arrows_font_classic,
                        "s",
                        text
                    )
                    local text_pos = vector(
                        center.x - text_size.x * 0.5,
                        center.y - padding
                    )
                    render.text(
                        angles_builder.manual_yaw_arrows_font_classic,
