                angles_builder.manual_yaw_arrows_color_ref:visibility(is_team_skeet)
            end
            events.render(angles_builder.manual_arrows_render, enabled)
        end

        if angles_builder.manual_yaw_arrows_ref ~= nil then
            angles_builder.manual_yaw_arrows_ref:set_callback(
                angles_builder.update_manual_arrows_event,
                true
            )
        end

        if angles_builder.manual_yaw_refs.direction ~= nil then
            angles_builder.manual_yaw_refs.direction:set_callback(
                angles_builder.manual_yaw.update_toggle_state,
                true
            )
        end
    end

    do
        unlock_fake_duck_speed_ref = config.push(
            unlockers_group:switch(
                icons.get("duck", 1.5, 6, "{Link Active}") .. "Fast Fake Duck",
                false
            ),
            "angles_features_unlock_fake_duck_speed"
        )
        freezetime_aa_ref = config.push(
            unlockers_group:switch(
                icons.get("snowflake", 1.5, 6, "{Link Active}") .. "Freezetime Fake Duck",
                false
            ),
            "angles_features_freezetime_aa"
        )
    end

    do
        local ref = angles_builder.hidden_defensive_refs

        ref.enabled = config.push(
            exploits_group:switch(
                icons.get("shield", 1, 6, "{Link Active}") .. "Hidden Defensive AA",
                false
            ),
