            local show_yaw_spin = yaw_mode == "Spinbot"
            local show_yaw_three_way = yaw_mode == "3-Way"
            local show_yaw_five_way = yaw_mode == "5-Way"
            local show_yaw_step = show_yaw_three_way or show_yaw_five_way

            if ref.yaw.random_min ~= nil then
                ref.yaw.random_min:visibility(show_yaw_random)
