            if ref.yaw.random_max ~= nil then
                ref.yaw.random_max:visibility(show_yaw_random)
            end
            if ref.yaw.sideways_min ~= nil then
                ref.yaw.sideways_min:visibility(show_yaw_sideways)
            end
            if ref.yaw.sideways_max ~= nil then
                ref.yaw.sideways_max:visibility(show_yaw_sideways)
            end
            if ref.yaw.opposite_min ~= nil then
