            if ref.yaw.spin_randomness ~= nil then
                ref.yaw.spin_randomness:visibility(show_yaw_spin)
            end

            for index = 1, #ref.yaw.three_way do
                local item = ref.yaw.three_way[index]
                if item ~= nil then
                    item:visibility(show_yaw_three_way)
                end
