            end
        end

        if ref.pitch.mode ~= nil then
            ref.pitch.mode:set_callback(update_hidden_defensive_visibility, true)
        end

        if ref.yaw.mode ~= nil then
            ref.yaw.mode:set_callback(update_hidden_defensive_visibility, true)
        end
    end

