    local unlock_fake_duck_speed
    do
        local function on_createmove_run(cmd)
            local local_player = entity.get_local_player()
            if local_player == nil then
                return
            end

            local fake_duck_ref = nl.aa and nl.aa.misc and nl.aa.misc.fake_duck
            if fake_duck_ref == nil or fake_duck_ref:get() ~= true then
                return
            end

            local forwardmove = cmd.forwardmove
            local sidemove = cmd.sidemove

            if math.abs(forwardmove) <= 5.0 and math.abs(sidemove) <= 5.0 then
                return
            end

            if local_player.m_flDuckAmount == 1 then
                return
            end

            local speed = (forwardmove * forwardmove + sidemove * sidemove) ^ 0.5
            local factor = 140 / speed

            cmd.forwardmove = forwardmove * factor
            cmd.sidemove = sidemove * factor
        end 

        local callbacks
        do
            local function on_enabled(item)
                local enabled = false
                if item ~= nil then
                    local ok_enabled, value = pcall(item.get, item)
                    enabled = ok_enabled and value == true
                end

                events.createmove_run(on_createmove_run, enabled)
            end

            if unlock_fake_duck_speed_ref ~= nil then
                unlock_fake_duck_speed_ref:set_callback(on_enabled, true)
            end
        end
    end

    local freezetime_aa
    do
        local is_freezetime_fake_duck_active = false

        local function restore_freezetime()
            if is_freezetime_fake_duck_active ~= true then
                return
            end

            local game_rules = entity.get_game_rules()
            if game_rules ~= nil then
                game_rules.m_bFreezePeriod = true
            end

            local angles_enabled_ref = nl.aa and nl.aa.angles and nl.aa.angles.enabled
            if angles_enabled_ref ~= nil then
                angles_enabled_ref:override()
            end

            is_freezetime_fake_duck_active = false
        end

        local function on_createmove()
            local fake_duck_ref = nl.aa and nl.aa.misc and nl.aa.misc.fake_duck
            if fake_duck_ref == nil or fake_duck_ref:get() ~= true then
                return
            end

            local game_rules = entity.get_game_rules()
            if game_rules == nil then
                return
            end

            if game_rules.m_bFreezePeriod ~= true then
                return
            end

            game_rules.m_bFreezePeriod = false

            local angles_enabled_ref = nl.aa and nl.aa.angles and nl.aa.angles.enabled
            if angles_enabled_ref ~= nil then
                angles_enabled_ref:override(false)
            end

            is_freezetime_fake_duck_active = true
        end

        local function on_createmove_run()
            restore_freezetime()
        end

        local callbacks
        do
            local function on_enabled(item)
                local enabled = false
                if item ~= nil then
                    local ok_enabled, value = pcall(item.get, item)
                    enabled = ok_enabled and value == true
                end

                events.createmove(on_createmove, enabled)
                events.createmove_run(on_createmove_run, enabled)

                if enabled ~= true then
                    restore_freezetime()
                end
            end

            if freezetime_aa_ref ~= nil then
                freezetime_aa_ref:set_callback(on_enabled, true)
            end

            events.shutdown(restore_freezetime, true)
        end
    end

    do
        local function set_avoid_backstab_override(state)
            local avoid_backstab_ref = nl.aa and nl.aa.angles and nl.aa.angles.avoid_backstab
            if avoid_backstab_ref == nil then
                return
            end

            if state == true then
                avoid_backstab_ref:override(true)
                return
            end

            avoid_backstab_ref:override()
        end

        local fluctuate_fake_lags_flip = false

        local function reset_fluctuate_fake_lags()
            fluctuate_fake_lags_flip = false

            local override_state = angles_builder.fake_lag_limit_override_state
            if override_state ~= nil then
                override_state.fluctuate = nil
            end

            if angles_builder.apply_fake_lag_limit_override ~= nil then
                angles_builder.apply_fake_lag_limit_override()
            end
        end

        local function is_exploit_charged()
            if rage == nil or rage.exploit == nil then
                return false
            end

            local ok_exploit, exploit_charge = pcall(rage.exploit.get, rage.exploit)
            if not ok_exploit or type(exploit_charge) ~= "number" then
                return false
            end

            return exploit_charge >= 1
        end

        local function is_revolver_weapon(weapon)
            if weapon == nil then
                return false
            end

            local weapon_info = weapon:get_weapon_info()
            if weapon_info == nil then
                return false
            end

            return weapon_info.is_revolver == true
        end

        local function on_fluctuate_fake_lags_createmove(cmd)
            local override_state = angles_builder.fake_lag_limit_override_state
            if override_state == nil or angles_builder.apply_fake_lag_limit_override == nil then
                return
            end

            local local_player = entity.get_local_player()
            if local_player ~= nil then
                local local_weapon = local_player:get_player_weapon()
                if is_revolver_weapon(local_weapon) then
                    reset_fluctuate_fake_lags()
                    return
                end
            end

            if is_exploit_charged() then
                if fluctuate_fake_lags_flip then
                    reset_fluctuate_fake_lags()
                else
                    override_state.fluctuate = nil
                    angles_builder.apply_fake_lag_limit_override()
                end
                return
            end

            override_state.fluctuate = nil

            local fake_duck_ref = nl.aa and nl.aa.misc and nl.aa.misc.fake_duck
            if fake_duck_ref ~= nil and fake_duck_ref:get() == true then
                angles_builder.apply_fake_lag_limit_override()
                return
            end

            local choked_commands = 0
            if cmd ~= nil then
                local cmd_choked_commands = cmd.choked_commands
                if type(cmd_choked_commands) == "number" then
                    choked_commands = cmd_choked_commands
                end
            end

            if choked_commands == 0 then
                fluctuate_fake_lags_flip = not fluctuate_fake_lags_flip
            end

            if fluctuate_fake_lags_flip then
                override_state.fluctuate = 1
            end

            angles_builder.apply_fake_lag_limit_override()
        end

        local avoid_backstab_ref = config.push(
            avoid_backstab_group:switch(
                icons.get("knife-kitchen", 1, 6, "{Link Active}") .. "Avoid Backstab",
                false
            ),
            "angles_features_avoid_backstab"
        )
        if avoid_backstab_ref ~= nil then
            avoid_backstab_ref:tooltip(
                "Rotates the player towards an enemy\nif they are close and are holding a\nknife.\nThis option is overridden to \"On\"."
            )

            avoid_backstab_ref:set_callback(function(item)
                set_avoid_backstab_override(item:get() == true)
            end, true)
        end

        local safe_head_ref = config.push(
            avoid_backstab_group:switch(
                icons.get("face-explode", 1, 6.5, "{Link Active}") .. "Safe Head",
                false
            ),
            "angles_features_safe_head"
        )
        if safe_head_ref ~= nil then
            local safe_head_group = safe_head_ref:create()
            if safe_head_group ~= nil then
                angles_builder.safe_head_refs.states = config.push(
                    safe_head_group:listable(
                        "States",
                        safe_head_controller.get_states()
                    ),
                    "angles_features_safe_head_states"
                )
                angles_builder.safe_head_refs.disable_on = config.push(
                    safe_head_group:listable(
                        "Disable On",
                        {
                            "Freestanding",
                            "Manual Yaw",
                            "Weapon Switch",
                            "Lethal",
                        }
                    ),
                    "angles_features_safe_head_disable_on"
                )
            end

            safe_head_ref:set_callback(function(item)
                safe_head_controller.set_enabled(item:get() == true)
            end, true)
        end

        local fluctuate_fake_lags_ref = config.push(
            avoid_backstab_group:switch(
                icons.get("signal", 1, 6, "{Link Active}") .. "Fluctuate Fake Lags",
                false
            ),
            "angles_features_fluctuate_fake_lags"
        )
        if fluctuate_fake_lags_ref ~= nil then
            fluctuate_fake_lags_ref:set_callback(function(item)
                local enabled = false
                if item ~= nil then
                    local ok_enabled, value = pcall(item.get, item)
                    enabled = ok_enabled and value == true
                end

                events.createmove(on_fluctuate_fake_lags_createmove, enabled)
                if enabled ~= true then
                    reset_fluctuate_fake_lags()
                end
            end, true)
        end

        angles_builder.break_lc_refs.label = avoid_backstab_group:label(
            icons.get("wrench", 1.5, 6, "{Link Active}") .. "Break LC"
        )
        if angles_builder.break_lc_refs.label ~= nil then
            local break_lc_group = angles_builder.break_lc_refs.label:create()
            angles_builder.break_lc_refs.disablers = config.push(
                break_lc_group:selectable("Disablers", {
                    "On Grenade",
                    "On Pin Pulled",
                    "On Hide Shots (for triggers only)",
                }),
                "angles_features_break_lc_disablers"
            )
            angles_builder.break_lc_refs.triggers = config.push(
                break_lc_group:listable("Triggers", {
                    "Weapon Switch",
                    "Flashed",
                    "Reloading",
                    "Flinching",
                }),
                "angles_features_break_lc_triggers"
            )
        end

        events.shutdown(reset_fluctuate_fake_lags, true)
    end

    local function apply_angles_visibility(selected_index)
        angles_test_menu.applied_index = selected_index
        if angles_builder ~= nil and angles_builder.set_visibility ~= nil then
            angles_builder.set_visibility(selected_index == 1)
        end
        hotkeys_group:visibility(selected_index == 2)
        mouse_override_group:visibility(selected_index == 2)
        freestanding_group:visibility(selected_index == 2)
        unlockers_group:visibility(selected_index == 3)
        avoid_backstab_group:visibility(selected_index == 3)
        exploits_group:visibility(selected_index == 3)
        other_group:visibility(selected_index == 3)
    end

    local function hide_angles_sections()
        if angles_builder ~= nil and angles_builder.set_visibility ~= nil then
            angles_builder.set_visibility(false)
        end
        hotkeys_group:visibility(false)
        mouse_override_group:visibility(false)
        freestanding_group:visibility(false)
        unlockers_group:visibility(false)
        avoid_backstab_group:visibility(false)
        exploits_group:visibility(false)
        other_group:visibility(false)
    end

    local function finish_angles_transition(expected_token, selected_index)
        if angles_test_menu.token ~= expected_token then
            return
        end

        apply_angles_visibility(selected_index)
    end

    local function update_angles_visibility()
        local selected_index = section_list:get()
        angles_test_menu.token = angles_test_menu.token + 1

        is_updating_section_list = true
        angles_builder.update_section_items(selected_index)
        section_list:set(selected_index)
        is_updating_section_list = false

        if angles_test_menu.applied_index == nil then
            apply_angles_visibility(selected_index)
            return
        end

        if angles_test_menu.applied_index == selected_index then
            apply_angles_visibility(selected_index)
            return
        end

        hide_angles_sections()
        utils.execute_after(
            angles_test_menu.delay,
            finish_angles_transition,
            angles_test_menu.token,
            selected_index
        )
    end

    section_list:set_callback(function()
        if is_updating_section_list then
            return
        end

        update_angles_visibility()
    end, true)
end

