local grenade_throw_state = {
}
do
    local super_toss_active = false
    local grenade_release_active = false
    local active_state = false

    local function sync_active_state()
        local is_active = super_toss_active == true or grenade_release_active == true
        if active_state == is_active then
            return
        end

        active_state = is_active
    end

    function grenade_throw_state.set_super_toss_active(state)
        local is_active = state == true
        if super_toss_active == is_active then
            return
        end

        super_toss_active = is_active
        sync_active_state()
    end

    function grenade_throw_state.set_grenade_release_active(state)
        local is_active = state == true
        if grenade_release_active == is_active then
            return
        end

        grenade_release_active = is_active
        sync_active_state()
    end

    function grenade_throw_state.is_active()
        return active_state == true
    end
end

