            },
            ["Air-Crouch"] = {
                name = "person-falling-burst",
            },
        }

        local function is_auto_hide_shots_state_enabled(reference, value)
            if reference == nil or type(value) ~= "string" then
                return false
            end

            local ok_named, named = pcall(reference.get, reference, value)
            if ok_named and type(named) == "boolean" then
                return named
            end

            local ok_list, list = pcall(reference.get, reference)
            if not ok_list or type(list) ~= "table" then
                return false
            end

            for i = 1, #list do
                if list[i] == value then
                    return true
                end
            end

            return false
        end

        local function make_auto_hide_shots_weapon_label(weapon_label)
            if type(weapon_label) ~= "string" or weapon_label == "" then
                return ""
            end

            local states_ref = rage_ref.auto_hide_shots.weapon_states[weapon_label]
            if states_ref == nil then
                return weapon_label
            end

            local badges = {
            }
            for i = 1, #auto_hide_shots_state_list do
                local state_name = auto_hide_shots_state_list[i]
                if is_auto_hide_shots_state_enabled(states_ref, state_name) then
                    local icon_data = auto_hide_shots_state_icons[state_name]
                    if icon_data ~= nil then
                        badges[#badges + 1] = string.format(
                            "\a%s%s\aDEFAULT",
                            AUTO_HIDE_SHOTS_BADGE_COLOR,
                            ui.get_icon(icon_data.name)
                        )
                    end
                end
            end

            if #badges == 0 then
                return weapon_label
            end

            return weapon_label
                .. string.format("\a%s  %s  \aDEFAULT", AUTO_HIDE_SHOTS_BADGE_COLOR, AUTO_HIDE_SHOTS_SEPARATOR)
                .. table.concat(badges, "\aDEFAULT " .. HSP)
        end

        local function update_auto_hide_shots_weapon_items()
            if rage_ref.auto_hide_shots.weapons == nil then
                return
            end

            for i = 1, #auto_hide_shots_weapon_data do
                local weapon_data = auto_hide_shots_weapon_data[i]
                auto_hide_shots_weapon_items[i] = make_auto_hide_shots_weapon_label(weapon_data.label)
            end

            rage_ref.auto_hide_shots.weapons:update(auto_hide_shots_weapon_items)
        end

        for i = 1, #auto_hide_shots_weapon_data do
            auto_hide_shots_weapon_list[i] = auto_hide_shots_weapon_data[i].label
            auto_hide_shots_weapon_items[i] = auto_hide_shots_weapon_data[i].label
