        if rage_ref.auto_hide_shots.enabled ~= nil then
            local auto_hide_shots_group = rage_ref.auto_hide_shots.enabled:create()

            rage_ref.auto_hide_shots.weapons = config.push(
                auto_hide_shots_group:list("Weapons", auto_hide_shots_weapon_items),
                "main_rage_auto_hide_shots_weapons"
            )

            for i = 1, #auto_hide_shots_weapon_data do
                local weapon_data = auto_hide_shots_weapon_data[i]

                rage_ref.auto_hide_shots.weapon_states[weapon_data.label] = config.push(
                    auto_hide_shots_group:selectable(
                        "States##" .. weapon_data.key,
                        auto_hide_shots_state_list
                    ),
                    "main_rage_auto_hide_shots_states_" .. weapon_data.key
                )
                local states_ref = rage_ref.auto_hide_shots.weapon_states[weapon_data.label]
                if states_ref ~= nil then
                    states_ref:set_callback(update_auto_hide_shots_weapon_items, true)
                end
            end

            if rage_ref.auto_hide_shots.weapons ~= nil then
                rage_ref.auto_hide_shots.weapons:set_callback(function(item)
                    if item == nil then
                        return
                    end

                    local selected_weapon = nil
                    local selected_index = item:get()
                    if type(selected_index) == "number" then
                        local selected_data = auto_hide_shots_weapon_data[selected_index]
                        if selected_data ~= nil then
                            selected_weapon = selected_data.label
                        end
                    end

                    for i = 1, #auto_hide_shots_weapon_data do
                        local weapon_data = auto_hide_shots_weapon_data[i]
                        local states_ref = rage_ref.auto_hide_shots.weapon_states[weapon_data.label]
                        if states_ref ~= nil then
                            states_ref:visibility(selected_weapon == weapon_data.label)
                        end
                    end
                end, true)

                update_auto_hide_shots_weapon_items()
            end
        end
    end
    rage_ref.tweaks_selectable = config.push(
