        )
    end

    do
        local auto_stop_items = {
            "Early",
            "In Air",
            "Full Stop",
            "Move Between Shots",
        }
        local weapon_items = {
        }
        local JUMP_OVERRIDE_ICON = "person-falling"
        local NOSCOPE_OVERRIDE_ICON = "crosshairs-simple"
        local OVERRIDE_BADGE_COLOR = "\a7A7A7AFF"
        local OVERRIDE_SEPARATOR = "•"

        local function format_hitchance_value(value)
            if value == 0 then
                return "Off"
            end

            return value .. "%"
        end

        local function format_distance_value(value)
            if value == 201 then
                return "Inf"
            end

            return string.format("%.1fm", value * 0.1)
        end

        local function make_weapon_override_badge(icon_name, value)
            if type(value) ~= "number" or value <= 0 then
                return ""
            end

            return string.format(
                "%s%s  %s%%\aDEFAULT",
                OVERRIDE_BADGE_COLOR,
                ui.get_icon(icon_name),
                tostring(value)
            )
        end

        local function make_weapon_list_label(weapon)
            if type(weapon) ~= "table" then
                return ""
            end

            local jumping_value = 0
            local noscope_value = 0

            if weapon.jumping ~= nil then
                jumping_value = weapon.jumping:get()
            end

            if weapon.noscope ~= nil then
                noscope_value = weapon.noscope:get()
            end

            local badges = {
            }

            local jumping_badge = make_weapon_override_badge(JUMP_OVERRIDE_ICON, jumping_value)
            if jumping_badge ~= "" then
                badges[#badges + 1] = jumping_badge
            end

            local noscope_badge = make_weapon_override_badge(NOSCOPE_OVERRIDE_ICON, noscope_value)
            if noscope_badge ~= "" then
                badges[#badges + 1] = noscope_badge
            end

            if #badges == 0 then
                return weapon.label
            end

            return weapon.label
                .. string.format("%s   %s   \aDEFAULT", OVERRIDE_BADGE_COLOR, OVERRIDE_SEPARATOR)
                .. table.concat(
                    badges,
                    string.format("%s,   \aDEFAULT", OVERRIDE_BADGE_COLOR)
                )
        end

        local function update_weapon_list_items()
            if rage_hitchance_override_ref.weapon_list == nil then
                return
            end

            for i = 1, #rage_hitchance_override_ref.order do
                local weapon_key = rage_hitchance_override_ref.order[i]
                local weapon = rage_hitchance_override_ref.weapons[weapon_key]
                weapon_items[i] = make_weapon_list_label(weapon)
            end

            rage_hitchance_override_ref.weapon_list:update(weapon_items)
        end

        local function get_selected_weapon_key()
            local selected_index = rage_hitchance_override_ref.weapon_list:get()
            if type(selected_index) ~= "number" then
                selected_index = 1
            end

            return rage_hitchance_override_ref.order[selected_index]
        end

        local function update_hitchance_override_visibility()
            local selected_key = get_selected_weapon_key()

            for i = 1, #rage_hitchance_override_ref.order do
                local weapon_key = rage_hitchance_override_ref.order[i]
                local weapon = rage_hitchance_override_ref.weapons[weapon_key]
                local is_selected = weapon_key == selected_key

                if weapon.jumping ~= nil then
                    weapon.jumping:visibility(is_selected)
                    weapon.jumping:disabled(weapon_key == "auto_snipers")
                end

                if weapon.noscope ~= nil then
                    weapon.noscope:visibility(is_selected)
                    weapon.noscope:disabled(weapon_key == "r8_revolver")
                end

                if weapon.noscope_gear ~= nil then
                    weapon.noscope_gear:visibility(is_selected and weapon_key ~= "r8_revolver")
                end
            end
        end

        for i = 1, #rage_hitchance_override_ref.order do
            local weapon_key = rage_hitchance_override_ref.order[i]
            local weapon = rage_hitchance_override_ref.weapons[weapon_key]

            weapon_items[i] = make_weapon_list_label(weapon)
        end

        rage_hitchance_override_ref.weapon_list = config.push(
            rage_hitchance_override_group:list(
                "##Weapons",
                weapon_items
            ),
            "main_rage_hitchance_override_weapon_list"
        )

        for i = 1, #rage_hitchance_override_ref.order do
            local weapon_key = rage_hitchance_override_ref.order[i]
            local weapon = rage_hitchance_override_ref.weapons[weapon_key]

            weapon.jumping = config.push(
                rage_hitchance_override_group:slider(
                    icons.get(JUMP_OVERRIDE_ICON, 1.5, 6, "{Link Active}") .. "Jumping##" .. weapon_key,
                    0,
                    100,
                    0,
                    1,
                    format_hitchance_value
                ),
                "main_rage_hitchance_override_" .. weapon_key .. "_jumping"
            )
            weapon.jumping:set_callback(update_weapon_list_items, true)
            weapon.noscope = config.push(
                rage_hitchance_override_group:slider(
                    icons.get(NOSCOPE_OVERRIDE_ICON, 1, 6, "{Link Active}") .. "No Scope##" .. weapon_key,
                    0,
                    100,
                    0,
                    1,
                    format_hitchance_value
                ),
                "main_rage_hitchance_override_" .. weapon_key .. "_no_scope"
            )
            weapon.noscope:set_callback(update_weapon_list_items, true)

            if weapon.noscope ~= nil then
                weapon.noscope_gear = weapon.noscope:create()
            end

            if weapon.noscope_gear ~= nil then
                weapon.noscope_distance = config.push(
                    weapon.noscope_gear:slider(
