            "3:2",
        }
        local aspect_ratio_values = {
            ["16:10"] = 160,
            ["16:9"] = 177,
            ["4:3"] = 133,
            ["5:4"] = 125,
            ["3:2"] = 150,
        }
        local aspect_ratio_keys = {
        }

        for i = 1, #aspect_ratio_names do
            local ratio_name = aspect_ratio_names[i]
            local ratio_value = aspect_ratio_values[ratio_name]
            aspect_ratio_keys[ratio_value] = ratio_name
        end

        local function on_aspect_ratio_display(value)
            if value == 0 then
                return "Off"
            end

            local ratio_name = aspect_ratio_keys[value]
            if ratio_name == nil then
                return nil
            end

            return "\a{Link Active}" .. ratio_name
        end

        visuals_ref.aspect_ratio_proportion = config.push(
            aspect_ratio_group:slider(
                "##Proportion",
                0,
                300,
                0,
                0.01,
                on_aspect_ratio_display
            ),
            "main_visuals_tweaks_aspect_ratio_proportion"
        )

        local function make_ratio_button_label(text)
            local target_width = math.ceil(#text * 1.34)
            if target_width <= #text then
                return text
            end

            local padding = target_width - #text
            local left_padding = math.floor(padding * 0.5)
            local right_padding = padding - left_padding

            return string.rep(" ", left_padding) .. text .. string.rep(" ", right_padding)
        end

        if visuals_ref.aspect_ratio_proportion ~= nil then
            for i = 1, #aspect_ratio_names do
                local ratio_name = aspect_ratio_names[i]
                local ratio_value = aspect_ratio_values[ratio_name]
                local button_label = make_ratio_button_label(ratio_name)

                aspect_ratio_group:button(
                    button_label,
                    function()
                        visuals_ref.aspect_ratio_proportion:set(ratio_value)
                    end,
                    true
                )
            end
        end
    end

