    visuals_ref.hit_marker_enabled = config.push(
        visuals_world_group:switch(
            icons.get("bullseye-arrow", 1, 6, "{Link Active}") .. "Hit Marker",
            false
        ),
        "main_visuals_other_hit_marker_enabled"
    )
    if visuals_ref.hit_marker_enabled ~= nil then
        local HIT_MARKER_DOUBLE_CLICK_TIME = 0.3
        local HIT_MARKER_DISABLED_SHIFT = 10
        local HIT_MARKER_SHIFT_SPEED = 10
        local HIT_MARKER_ICON_TEXT_SHIFT = 5
        local HIT_MARKER_DISABLED_ICON = "xmark"
        local HIT_MARKER_DISABLED_ICON_COLOR = "CE4848FF"
        local HIT_MARKER_TYPE_NAMES = {
            "Damage",
            "Screen",
            "World",
        }

        local hit_marker_click_state = {
            index = 0,
            time = -1000.0,
            initialized = false,
        }
        local hit_marker_shift_state = {
            current = 0.0,
            target = 0.0,
            last_key = "",
        }

        local hit_marker_group = visuals_ref.hit_marker_enabled:create()

        local function get_hit_marker_enabled_ref(index)
            if index == 1 then
                return visuals_ref.hit_marker_damage_enabled
            end

            if index == 2 then
                return visuals_ref.hit_marker_screen_enabled
            end

            if index == 3 then
                return visuals_ref.hit_marker_world_enabled
            end

            return nil
        end

        local function is_any_hit_marker_type_enabled()
            for index = 1, #HIT_MARKER_TYPE_NAMES do
                local enabled_ref = get_hit_marker_enabled_ref(index)
                if enabled_ref ~= nil and enabled_ref:get() == true then
                    return true
                end
            end

            return false
        end

        local function make_hit_marker_shift_padding(width)
            if type(width) ~= "number" or width <= 0 then
                return ""
            end

            local full_width = math.floor(width)
            local has_half = width - full_width >= 0.5
            local padding = ""

            if full_width > 0 then
                padding = string.rep(" ", full_width)
            end

            if has_half then
                padding = padding .. HSP
            end

            return padding
        end

        local function update_hit_marker_shift_target()
            hit_marker_shift_state.target = is_any_hit_marker_type_enabled() and 1.0 or 0.0
        end

        local function make_hit_marker_type_name(index)
            local name = HIT_MARKER_TYPE_NAMES[index]
            if name == nil then
                return ""
            end

            local enabled_ref = get_hit_marker_enabled_ref(index)
            if enabled_ref ~= nil and enabled_ref:get() == true then
                return icons.get("check", 1, HIT_MARKER_ICON_TEXT_SHIFT, "A0CE48FF") .. name
            end

            return icons.get(
                HIT_MARKER_DISABLED_ICON,
                1.5,
                HIT_MARKER_ICON_TEXT_SHIFT + 0.5,
                HIT_MARKER_DISABLED_ICON_COLOR
            ) .. name
        end

        local function make_hit_marker_type_items_key()
            local enabled_state = {
            }

            for index = 1, #HIT_MARKER_TYPE_NAMES do
                local enabled_ref = get_hit_marker_enabled_ref(index)
                enabled_state[index] = enabled_ref ~= nil and enabled_ref:get() == true and "1" or "0"
            end

            return table.concat(enabled_state, "")
                .. ":"
                .. tostring(math.floor(hit_marker_shift_state.current * HIT_MARKER_DISABLED_SHIFT * 2 + 0.5))
        end

        local function update_hit_marker_type_items()
            if visuals_ref.hit_marker_type == nil then
                return
            end

            local key = make_hit_marker_type_items_key()
            if hit_marker_shift_state.last_key == key then
                return
            end

            hit_marker_shift_state.last_key = key

            visuals_ref.hit_marker_type:update({
                make_hit_marker_type_name(1),
                make_hit_marker_type_name(2),
                make_hit_marker_type_name(3),
            })
        end

        local function update_hit_marker_world_settings_visibility()
            local is_world = visuals_ref.hit_marker_type ~= nil and visuals_ref.hit_marker_type:get() == 3
            local is_diagonal = visuals_ref.hit_marker_world_mode ~= nil and (
                visuals_ref.hit_marker_world_mode:get() == "Diagonal" or
                visuals_ref.hit_marker_world_mode:get() == 2
            )

            if visuals_ref.hit_marker_world_enabled ~= nil then
                visuals_ref.hit_marker_world_enabled:visibility(false)
            end
            if visuals_ref.hit_marker_world_mode ~= nil then
                visuals_ref.hit_marker_world_mode:visibility(is_world)
            end
            if visuals_ref.hit_marker_world_gap ~= nil then
                visuals_ref.hit_marker_world_gap:visibility(is_world and not is_diagonal)
            end
            if visuals_ref.hit_marker_world_size ~= nil then
                visuals_ref.hit_marker_world_size:visibility(is_world and not is_diagonal)
            end
            if visuals_ref.hit_marker_world_color ~= nil then
                visuals_ref.hit_marker_world_color:visibility(is_world)
            end
        end

        local function on_hit_marker_ui_render()
            update_hit_marker_shift_target()
            update_hit_marker_world_settings_visibility()

            local current = hit_marker_shift_state.current
            local target = hit_marker_shift_state.target

            if current ~= target then
                local step = globals.frametime * HIT_MARKER_SHIFT_SPEED

                if current < target then
                    current = math.min(current + step, target)
                else
                    current = math.max(current - step, target)
                end

                hit_marker_shift_state.current = current
                update_hit_marker_type_items()
                return
            end

            if ui.get_alpha() > 0 then
                update_hit_marker_type_items()
            end
        end

        local function handle_hit_marker_type_click(index)
            if type(index) ~= "number" then
                return
            end

            if not hit_marker_click_state.initialized then
                hit_marker_click_state.initialized = true
                hit_marker_click_state.index = index
                return
            end

            local time = globals.realtime
            local is_double_click = hit_marker_click_state.index == index and
                time - hit_marker_click_state.time <= HIT_MARKER_DOUBLE_CLICK_TIME

            hit_marker_click_state.index = index
            hit_marker_click_state.time = time

            if not is_double_click then
                return
            end

            local enabled_ref = get_hit_marker_enabled_ref(index)
            if enabled_ref == nil then
                return
            end

            enabled_ref:set(enabled_ref:get() ~= true)
            update_hit_marker_shift_target()
            hit_marker_click_state.index = 0
            hit_marker_click_state.time = -1000.0
            update_hit_marker_type_items()
        end

        visuals_ref.hit_marker_type = config.push(
            hit_marker_group:list(
                "##TYPE",
                {
                    make_hit_marker_type_name(1),
                    make_hit_marker_type_name(2),
                    make_hit_marker_type_name(3),
                }
            ),
            "main_visuals_other_hit_marker_type"
        )

        visuals_ref.hit_marker_damage_enabled = config.push(
            hit_marker_group:switch(
                "Enable##DAMAGE",
                false
            ),
            "main_visuals_other_hit_marker_damage_enabled"
        )
        visuals_ref.hit_marker_damage_speed = config.push(
            hit_marker_group:slider(
                "Speed##Damage",
                0,
                128,
                58,
                nil,
                "u/s"
            ),
            "main_visuals_other_hit_marker_damage_speed"
        )
        visuals_ref.hit_marker_damage_duration = config.push(
            hit_marker_group:slider(
                "Duration##Damage",
                1,
                8,
                4,
                nil,
                "s"
            ),
            "main_visuals_other_hit_marker_damage_duration"
        )
        visuals_ref.hit_marker_damage_color = config.push(
            hit_marker_group:color_picker(
                "Color##DAMAGE",
                {
                    ["Body"] = {
                        color(255, 255, 255, 255),
                    },
                    ["Head"] = {
                        color(150, 185, 5, 255),
                    },
                    ["Mismatch"] = {
                        color(255, 0, 0, 255),
                    },
                }
            ),
            "main_visuals_other_hit_marker_damage_color"
        )

        visuals_ref.hit_marker_screen_enabled = config.push(
            hit_marker_group:switch(
                "Enable##SCREEN",
                false
            ),
            "main_visuals_other_hit_marker_screen_enabled"
        )
        visuals_ref.hit_marker_screen_color = config.push(
            hit_marker_group:color_picker(
                "Color##SCREEN",
                color(255, 255, 255, 255)
            ),
            "main_visuals_other_hit_marker_screen_color"
        )

        visuals_ref.hit_marker_world_enabled = config.push(
            hit_marker_group:switch(
                "Enable##WORLD",
                false
            ),
            "main_visuals_other_hit_marker_world_enabled"
        )
        visuals_ref.hit_marker_world_mode = config.push(
            hit_marker_group:combo(
                "Mode##WORLD",
                {
                    "Default",
                    "Diagonal",
                }
            ),
            "main_visuals_other_hit_marker_world_mode"
