        local function update_hit_marker_visibility(item)
            if item == nil then
                return
            end

            local ok_value, value = pcall(item.get, item)
            if not ok_value then
                return
            end

            handle_hit_marker_type_click(value)
            update_hit_marker_type_items()

            local is_damage = value == 1
            if visuals_ref.hit_marker_damage_enabled ~= nil then
                visuals_ref.hit_marker_damage_enabled:visibility(false)
            end
            if visuals_ref.hit_marker_damage_speed ~= nil then
                visuals_ref.hit_marker_damage_speed:visibility(is_damage)
            end
            if visuals_ref.hit_marker_damage_duration ~= nil then
                visuals_ref.hit_marker_damage_duration:visibility(is_damage)
            end
            if visuals_ref.hit_marker_damage_color ~= nil then
                visuals_ref.hit_marker_damage_color:visibility(is_damage)
            end

            local is_screen = value == 2
            if visuals_ref.hit_marker_screen_enabled ~= nil then
                visuals_ref.hit_marker_screen_enabled:visibility(false)
            end
            if visuals_ref.hit_marker_screen_color ~= nil then
                visuals_ref.hit_marker_screen_color:visibility(is_screen)
            end

            local is_world = value == 3
            if is_world then
                update_hit_marker_world_settings_visibility()
            else
                if visuals_ref.hit_marker_world_enabled ~= nil then
                    visuals_ref.hit_marker_world_enabled:visibility(false)
                end
                if visuals_ref.hit_marker_world_mode ~= nil then
                    visuals_ref.hit_marker_world_mode:visibility(false)
                end
                if visuals_ref.hit_marker_world_gap ~= nil then
                    visuals_ref.hit_marker_world_gap:visibility(false)
                end
                if visuals_ref.hit_marker_world_size ~= nil then
                    visuals_ref.hit_marker_world_size:visibility(false)
                end
                if visuals_ref.hit_marker_world_color ~= nil then
                    visuals_ref.hit_marker_world_color:visibility(false)
                end
            end
        end

        if visuals_ref.hit_marker_type ~= nil then
            visuals_ref.hit_marker_type:set_callback(
                update_hit_marker_visibility,
                true
            )
        end

        events.render(on_hit_marker_ui_render, true)
    end

