    local function is_animation_selected(name)
        local reference = visuals_ref.local_player_animations_select
        if reference == nil then
            return false
        end

        local ok_named, named_value = pcall(reference.get, reference, name)
        if ok_named and type(named_value) == "boolean" then
            return named_value
        end

        local ok_values, values = pcall(reference.get, reference)
        if not ok_values or type(values) ~= "table" then
            return false
        end

        local options = nil
        local ok_options, option_values = pcall(reference.list, reference)
        if ok_options and type(option_values) == "table" then
            options = option_values
        end

        for i = 1, #values do
            local value = values[i]
            if value == name then
                return true
            end

            if type(value) == "number" and options ~= nil and options[value] == name then
                return true
            end
        end

        return false
    end

    local function resolve_mode_name(reference, value)
        if type(value) == "string" then
            return value
        end

        if type(value) ~= "number" or reference == nil then
            return nil
        end

        local ok_list, items = pcall(reference.list, reference)
        if not ok_list or type(items) ~= "table" then
            return nil
        end

        local direct = items[value]
        if type(direct) == "string" then
            return direct
        end

        local shifted = items[value + 1]
        if type(shifted) == "string" then
            return shifted
        end

        return nil
    end

    local function normalize_air_mode(value)
        local resolved = resolve_mode_name(visuals_ref.local_player_air_mode, value)
        if resolved ~= nil then
            value = resolved
        end

        if value == "Static" or value == 2 then
            return "Static"
        end

        if value == "Kangaroo" or value == 3 then
            return "Kangaroo"
        end

        return "Disabled"
    end

    local function normalize_ground_mode(value)
        local resolved = resolve_mode_name(visuals_ref.local_player_ground_mode, value)
        if resolved ~= nil then
            value = resolved
        end

        if value == "Jitter" or value == 2 then
            return "Jitter"
        end

        if value == "Kangaroo" or value == 3 then
            return "Kangaroo"
        end

        if value == "Pacan4ik" or value == 4 then
            return "Pacan4ik"
        end

        return "Disabled"
    end

