        )

        clantag_ref.stealer_target = config.push(
            clantag_group:list("Stealer Target", {
                "No players",
            }),
            "main_misc_clantag_stealer_target"
        )
        if clantag_ref.stealer_target ~= nil then
            clantag_ref.stealer_target:tooltip("Choose player to steal clan tag from.")
        end

        clantag_ref.refresh_targets = function()
            if clantag_ref.stealer_target == nil then
                return
            end

            local function read_clan_tag(resource, player_index)
                if type(player_index) ~= "number" then
                    return ""
                end

                if player_index < 0 or player_index > 128 then
                    return ""
                end

                if resource == nil then
                    return ""
                end

                local ok_clans, clans = pcall(function()
                    return resource.m_szClan
                end)
                if not ok_clans then
                    return ""
                end

                if clans == nil then
                    return ""
                end

                local ok_value, value = pcall(function()
                    return clans[player_index]
                end)

                if type(value) ~= "string" and player_index > 0 then
                    ok_value, value = pcall(function()
                        return clans[player_index - 1]
                    end)
                end

                if not ok_value or type(value) ~= "string" then
                    return ""
                end

                value = value:gsub("%z", "")
                value = value:gsub("^%s+", "")
                value = value:gsub("%s+$", "")

                return value
            end

            local selected = clantag_ref.stealer_target:get()
            local old_index = nil
            if type(selected) == "number" then
                old_index = clantag_ref.target_indices[selected]
            end

            local target_player_index = clantag_ref.selected_player_index
            if type(old_index) == "number" and old_index > 0 then
                target_player_index = old_index
            end

            local local_player = entity.get_local_player()
            local names = {
            }
            local indices = {
            }

            if local_player == nil then
                names[1] = "No players"
                indices[1] = 0

                clantag_ref.stealer_target:update(names)
                clantag_ref.target_indices = indices
                clantag_ref.stealer_target:set(1)
                clantag_ref.selected_player_index = nil
                return
            end

            local local_player_index = local_player:get_index()

            entity.get_players(false, true, function(player)
                if player == nil then
                    return
                end

                local ok_is_player, is_player = pcall(player.is_player, player)
                if not ok_is_player or is_player ~= true then
                    return
                end

                local player_index = player:get_index()
                if type(player_index) ~= "number" or player_index <= 0 then
                    return
                end

                if local_player_index ~= nil and player_index == local_player_index then
                    return
                end

                local clan_tag = read_clan_tag(
                    player:get_resource(),
                    player_index
                )

                if clan_tag == "" then
                    clan_tag = read_clan_tag(
                        entity.get_player_resource(),
                        player_index
                    )
                end

                if clan_tag == "" then
                    local cached_tag = clantag_ref.cached_player_tags[player_index]
                    if type(cached_tag) == "string" and cached_tag ~= "" then
                        clan_tag = cached_tag
                    end
                else
                    clantag_ref.cached_player_tags[player_index] = clan_tag
                end

                if clan_tag == "" then
                    return
                end

                local name = player:get_name()
                if type(name) ~= "string" or name == "" then
                    name = "Player " .. tostring(player_index)
                end

                names[#names + 1] = name
                indices[#indices + 1] = player_index
            end)

            if #names == 0 then
                names[1] = "No players"
                indices[1] = 0
            end

            clantag_ref.stealer_target:update(names)
            clantag_ref.target_indices = indices

            local new_selected = 1
            if type(target_player_index) == "number" and target_player_index > 0 then
                for i = 1, #indices do
                    if indices[i] == target_player_index then
                        new_selected = i
                        break
                    end
                end
            end

            clantag_ref.stealer_target:set(new_selected)

            local resolved_player_index = clantag_ref.target_indices[new_selected]
            if type(resolved_player_index) == "number" and resolved_player_index > 0 then
                clantag_ref.selected_player_index = resolved_player_index
            else
                clantag_ref.selected_player_index = nil
            end
        end

        if clantag_ref.stealer_target ~= nil then
            clantag_ref.stealer_target:set_callback(function(item)
                if item == nil then
                    return
                end

                local selected_index = item:get()
                if type(selected_index) ~= "number" then
                    return
                end

                local player_index = clantag_ref.target_indices[selected_index]
                if type(player_index) == "number" and player_index > 0 then
                    clantag_ref.selected_player_index = player_index
                else
                    clantag_ref.selected_player_index = nil
                end
            end)
        end

        local MODE_ORIGINAL = "Original"
        local MODE_CUSTOM = "Custom"
        local MODE_REVERSE = "Reverse"
        local MODE_STEALER = "Stealer"

        local function normalize_mode(value)
            if value == MODE_ORIGINAL or value == 1 then
                return MODE_ORIGINAL
            end

            if value == MODE_CUSTOM or value == 2 then
                return MODE_CUSTOM
            end

            if value == MODE_REVERSE or value == 3 then
                return MODE_REVERSE
            end

            if value == MODE_STEALER or value == 4 then
                return MODE_STEALER
            end

            return MODE_ORIGINAL
        end

        local function update_clantag_mode_visibility()
            local mode = MODE_ORIGINAL
            if clantag_ref.mode ~= nil then
                local ok_mode, mode_value = pcall(clantag_ref.mode.get, clantag_ref.mode)
                if ok_mode then
                    mode = normalize_mode(mode_value)
                end
            end

            local is_custom = mode == MODE_CUSTOM
            local is_stealer = mode == MODE_STEALER

            if clantag_ref.custom_type ~= nil then
                clantag_ref.custom_type:visibility(is_custom)
            end

            if clantag_ref.custom_text ~= nil then
                clantag_ref.custom_text:visibility(is_custom)
            end

            if clantag_ref.stealer_target ~= nil then
                clantag_ref.stealer_target:visibility(is_stealer)
            end

            if is_stealer and clantag_ref.refresh_targets ~= nil then
                clantag_ref.refresh_targets()
            end
        end

        if clantag_ref.mode ~= nil then
            clantag_ref.mode:set_callback(update_clantag_mode_visibility, true)
        end
    end

    weapons_ref.super_toss_enabled = config.push(
        weapons_group:switch(
            icons.get("bomb", 1, 6, "{Link Active}") .. "Super Toss",
            false
        ),
        "main_misc_weapons_super_toss_enabled"
    )
    if weapons_ref.super_toss_enabled ~= nil then
        weapons_ref.super_toss_enabled:tooltip(
            "Optimizes grenade throw angles based on your movement.\n\nWorks independently from Grenade Release."
        )
    end

    weapons_ref.grenade_release_enabled = config.push(
        weapons_group:switch(
            icons.get("land-mine-on", 0.5, 5.5, "{Link Active}") .. "Grenade Release",
            false
        ),
        "main_misc_weapons_grenade_release_enabled"
    )
    if weapons_ref.grenade_release_enabled ~= nil then
        weapons_ref.grenade_release_enabled:tooltip(
            "Automatically releases HE and Molotov when a throw has a valid hit scenario.\n\nPin-Pulled Only is always enabled."
        )

        local grenade_release_group = weapons_ref.grenade_release_enabled:create()

        local function format_he_damage(value)
            if value == 0 then
                return "Off"
            end

            return string.format("%dhp", value)
        end

        local function format_molotov_range(value)
            if value == 0 then
                return "Off"
            end

            return string.format("%.1fm", value / 10)
        end

        weapons_ref.grenade_release_he_damage = config.push(
            grenade_release_group:slider("HE Damage", 0, 50, 25, 1, format_he_damage),
            "main_misc_weapons_grenade_release_he_damage"
        )

        weapons_ref.grenade_release_molotov_range = config.push(
            grenade_release_group:slider("Molotov Range", 0, 20, 10, 1, format_molotov_range),
            "main_misc_weapons_grenade_release_molotov_range"
        )

        weapons_ref.grenade_release_predict_molotov = config.push(
            grenade_release_group:switch("Predict Molotov", true),
            "main_misc_weapons_grenade_release_predict_molotov"
        )
        if weapons_ref.grenade_release_predict_molotov ~= nil then
            weapons_ref.grenade_release_predict_molotov:tooltip(
                "Allows Smoke to auto-release when it can extinguish active Molotov fire."
            )
        end
    end

    weapons_ref.quick_switch_enabled = config.push(
        weapons_group:switch(
            icons.get("shuffle", 1, 6, "{Link Active}") .. "Quick Switch",
            false
        ),
        "main_misc_weapons_quick_switch_enabled"
    )
    if weapons_ref.quick_switch_enabled ~= nil then
        weapons_ref.quick_switch_enabled:tooltip(
            "Automatically switches back to weapons after grenade throws and Zeus shots.\n\nWhen enabled, it also disables \"Quick Switch\" in Miscellaneous > Main > Other > Weapon Actions while active."
        )
    end

    weapons_ref.better_interactions_enabled = config.push(
        weapons_group:switch(
            icons.get("hand", 1, 6, "{Link Active}") .. "Better Interactions",
            false
        ),
        "main_misc_weapons_better_interactions_enabled"
    )
    if weapons_ref.better_interactions_enabled ~= nil then
        weapons_ref.better_interactions_enabled:tooltip(
            "Improves +use interactions.\n\nBombsite E-Fix: blocks accidental C4 pullout in bombzone and plants on +use when C4 is already in hand. \n\nHold +jump to prevent forced plant.\n\nHostage Assist: speeds up hostage pickup while holding +use nearby."
        )
    end

    misc_ref.trash_talk_enabled = config.push(
        other_group:switch(
            icons.get("comments", 0.5, 6, "{Link Active}") .. "Trash Talk",
            false
        ),
        "main_misc_trash_talk_enabled"
    )

    misc_ref.shared_logo_enabled = config.push(
        other_group:switch(icons.get("share-nodes", 1.5, 7, "{Link Active}") .. "Shared Logo", false),
        "main_misc_shared_logo_enabled"
    )
    if misc_ref.shared_logo_enabled ~= nil then
        misc_ref.shared_logo_enabled:tooltip(
            "Shows the Aesthetic icon next to users running this script in the scoreboard."
        )
    end

    misc_ref.game_focus_enabled = config.push(
        other_group:switch(
            icons.get("bullseye-arrow", 1, 6.5, "{Link Active}") .. "Game Focus",
            false
        ),
        "main_misc_game_focus_enabled"
    )
    if misc_ref.game_focus_enabled ~= nil then
        misc_ref.game_focus_enabled:tooltip(
            "Tabs into the game when events occur.\n\nEvents: Match Found, Round Start."
        )
    end

    local practice_server_commands =
    "sv_cheats 1;mp_roundtime_defuse 99999;mp_warmup_end;mp_buytime 99999999;mp_buy_anywhere 1;sv_infinite_ammo 1;impulse 101;sv_airaccelerate 100;sv_regeneration_force_on 1;mp_respawn_on_death_ct 1;mp_respawn_on_death_t 1;bot_stop 1;mp_roundtime_hostage 10000"
    local practice_server_sound = "ui/armsrace_level_up.wav"
    local unicode_space = "\u{00A0}"
    local practice_server_button_label = string.rep(unicode_space, 22)
        .. "Practice Server Setup"
        .. string.rep(unicode_space, 22)
    other_group:button(
        practice_server_button_label,
        function()
            sounds.play(practice_server_sound)
            utils.console_exec(practice_server_commands)
        end, true
    )

    local function apply_misc_visibility(selected_index)
        misc_test_menu.applied_index = selected_index
        rage_hitchance_override_group:visibility(selected_index == 1)
        logs_group:visibility(selected_index == 1)
        dormant_aimbot_group:visibility(selected_index == 1)
        force_shot_group:visibility(selected_index == 1)
        tweaks_group:visibility(selected_index == 1)
        visuals_group:visibility(selected_index == 2)
        visuals_tweaks_group:visibility(selected_index == 2)
        visuals_world_group:visibility(selected_index == 2)
        model_changer_group:visibility(selected_index == 2)
        local_player_animations_group:visibility(selected_index == 2)
        grenades_group:visibility(selected_index == 2)
        movement_group:visibility(selected_index == 3)
        weapons_group:visibility(selected_index == 3)
        other_group:visibility(selected_index == 3)
    end

    local function hide_misc_sections()
        rage_hitchance_override_group:visibility(false)
        logs_group:visibility(false)
        dormant_aimbot_group:visibility(false)
        force_shot_group:visibility(false)
        tweaks_group:visibility(false)
        visuals_group:visibility(false)
        visuals_tweaks_group:visibility(false)
        visuals_world_group:visibility(false)
        model_changer_group:visibility(false)
        local_player_animations_group:visibility(false)
        grenades_group:visibility(false)
        movement_group:visibility(false)
        weapons_group:visibility(false)
        other_group:visibility(false)
    end

    local function finish_misc_transition(expected_token, selected_index)
        if misc_test_menu.token ~= expected_token then
            return
        end

        apply_misc_visibility(selected_index)
    end

    local function update_misc_visibility()
        local selected_index = section_list:get()
        misc_test_menu.token = misc_test_menu.token + 1

        is_updating_section_list = true
        section_list:update(make_section_items(selected_index))
        section_list:set(selected_index)
        is_updating_section_list = false

        if misc_test_menu.applied_index == nil then
            apply_misc_visibility(selected_index)
            return
        end

        if misc_test_menu.applied_index == selected_index then
            apply_misc_visibility(selected_index)
            return
        end

        hide_misc_sections()
        utils.execute_after(
            misc_test_menu.delay,
            finish_misc_transition,
            misc_test_menu.token,
            selected_index
        )
    end

    section_list:set_callback(function()
        if is_updating_section_list then
            return
        end

        update_misc_visibility()
    end, true)
end

do
    local ref = rage_ref.force_shot
    local constants = {
        trace_count = 128,
        trace_length = 8192,
        accuracy_threshold = 0.023,
        default_hit_chance = 50,
        ssg08_weapon_index = 40,
        target_hitbox_index = 0,
    }
    local state = {
        hit_chance_overridden = false,
    }
    local native_hit_chance = nl.rage.selection.hit_chance

    local function get_reference_value(reference)
        if reference == nil then
            return nil
        end

        local ok_override, override = pcall(reference.get_override, reference)
        if ok_override and override ~= nil then
            return override
        end

        local ok_value, value = pcall(reference.get, reference)
        if not ok_value then
            return nil
        end

        return value
    end

    local function get_default_hit_chance()
        local value = get_reference_value(native_hit_chance)
        if type(value) ~= "number" then
            return constants.default_hit_chance
        end

        value = math.floor(value + 0.5)
        if value < 0 then
            return 0
        end

        if value > 100 then
            return 100
        end

        return value
    end

    local function clear_hit_chance_override()
        if native_hit_chance == nil then
            return
        end

        if state.hit_chance_overridden ~= true then
            return
        end

        native_hit_chance:override()
        state.hit_chance_overridden = false
    end

    local function apply_hit_chance_override()
        if native_hit_chance == nil then
            return
        end

        native_hit_chance:override(0)
        state.hit_chance_overridden = true
    end

    local function get_required_hit_chance()
        if ref == nil or ref.hit_chance == nil then
            return get_default_hit_chance()
        end

        local value = ref.hit_chance:get()
        if type(value) ~= "number" then
            return get_default_hit_chance()
        end

        return value
    end

    local function is_ssg08(weapon)
        if weapon == nil then
            return false
        end

        local weapon_index = weapon:get_weapon_index()
        if type(weapon_index) ~= "number" then
            return false
        end

        return weapon_index == constants.ssg08_weapon_index
    end

    local function get_current_hit_chance(local_player, weapon, threat)
        if local_player == nil or weapon == nil or threat == nil then
            return nil
        end

        local eye_position = local_player:get_eye_position()
        if eye_position == nil then
            return nil
        end

        local target_position = threat:get_hitbox_position(constants.target_hitbox_index)
        if target_position == nil then
            target_position = threat:get_origin()
        end
        if target_position == nil then
            return nil
        end

        local forward = eye_position:to(target_position)
        if forward:lengthsqr() <= 0 then
            return nil
        end

        local right, up = forward:vectors()
        if right == nil or up == nil then
            return nil
        end

        local spread = weapon:get_spread()
        local inaccuracy = weapon:get_inaccuracy()
        if type(spread) ~= "number" or type(inaccuracy) ~= "number" then
            return nil
        end

        local threat_index = threat:get_index()
        if type(threat_index) ~= "number" then
            return nil
        end

        local hits = 0

        for _ = 1, constants.trace_count do
            local spread_angle = utils.random_float(0, math.pi * 2)
            local spread_radius = utils.random_float(0, spread)
            local inaccuracy_angle = utils.random_float(0, math.pi * 2)
            local inaccuracy_radius = utils.random_float(0, inaccuracy)

            local offset_x = math.cos(spread_angle) * spread_radius
                + math.cos(inaccuracy_angle) * inaccuracy_radius
            local offset_y = math.sin(spread_angle) * spread_radius
                + math.sin(inaccuracy_angle) * inaccuracy_radius

            local shot_direction = vector(
                forward.x + offset_x * right.x + offset_y * up.x,
                forward.y + offset_x * right.y + offset_y * up.y,
                forward.z + offset_x * right.z + offset_y * up.z
            )
            local normalized_direction = shot_direction:normalized()
            local shot_end = vector(
                eye_position.x + normalized_direction.x * constants.trace_length,
                eye_position.y + normalized_direction.y * constants.trace_length,
                eye_position.z + normalized_direction.z * constants.trace_length
            )

            local damage, trace = utils.trace_bullet(local_player, eye_position, shot_end)
            if type(damage) == "number" and damage > 0 and trace ~= nil and trace.entity ~= nil then
                local hit_index = trace.entity:get_index()
                if type(hit_index) == "number" and hit_index == threat_index then
                    hits = hits + 1
                end
            end
        end

        return math.floor((hits / constants.trace_count) * 100 + 0.5)
    end

    local function on_createmove_run()
        if native_hit_chance == nil then
            return
        end

        local local_player = entity.get_local_player()
        if local_player == nil or local_player:is_alive() ~= true then
            clear_hit_chance_override()
            return
        end

        local weapon = local_player:get_player_weapon()
        if weapon == nil then
            clear_hit_chance_override()
            return
        end

        if not is_ssg08(weapon) then
            clear_hit_chance_override()
            return
        end

        local threat = entity.get_threat()
        if threat == nil or threat:is_alive() ~= true or threat:is_dormant() == true then
            clear_hit_chance_override()
            return
        end

        local current_inaccuracy = weapon:get_inaccuracy()
        if type(current_inaccuracy) ~= "number" then
            clear_hit_chance_override()
            return
        end

        if current_inaccuracy > constants.accuracy_threshold then
            clear_hit_chance_override()
            return
        end

        local required_hit_chance = get_required_hit_chance()
        if required_hit_chance == 0 then
            apply_hit_chance_override()
            return
        end

        local current_hit_chance = get_current_hit_chance(local_player, weapon, threat)
        if type(current_hit_chance) ~= "number" then
            clear_hit_chance_override()
            return
        end

        if current_hit_chance >= required_hit_chance then
            apply_hit_chance_override()
            return
        end
        clear_hit_chance_override()
    end

    if ref ~= nil and ref.enabled ~= nil then
        ref.enabled:set_callback(function(item)
            local enabled = item ~= nil and item:get() == true
            events.createmove_run(on_createmove_run, enabled)

            if enabled ~= true then
                clear_hit_chance_override()
            end
        end, true)
    end

    events.shutdown(clear_hit_chance_override, true)
end

do
    local constants = {
        attack_inaccuracy = 0.01,
        on_ground = 1,
        unsupported_weapon_types = {
            [0] = true,
            [9] = true,
        },
        point_templates = {
            {
                hitbox = "Stomach",
                offset = vector(0, 0, 40),
                scale = 5,
            },
            {
                hitbox = "Chest",
                offset = vector(0, 0, 50),
                scale = 6,
            },
            {
                hitbox = "Head",
                offset = vector(0, 0, 58),
                scale = 3,
            },
            {
                hitbox = "Legs",
                offset = vector(0, 0, 20),
                scale = 4,
            },
        },
    }

    local ref = rage_ref.dormant_aimbot
    local callbacks_registered = false

    local function get_menu_number(item, fallback)
        if item == nil then
            return fallback
        end

        local value = item:get_override()
        if value == nil then
            value = item:get()
        end

        value = tonumber(value)
        if value == nil then
            return fallback
        end

        return value
    end

    local function has_hitbox_selection(selected_hitboxes, hitbox)
        if selected_hitboxes == nil then
            return false
        end

        for index = 1, #selected_hitboxes do
            if selected_hitboxes[index] == hitbox then
                return true
            end
        end

        return false
    end

    local function is_supported_weapon(weapon, weapon_info)
        if weapon == nil or not weapon:is_weapon() or weapon_info == nil then
            return false
        end

        if constants.unsupported_weapon_types[weapon_info.weapon_type] then
            return false
        end

        if weapon:get_weapon_reload() ~= -1 then
            return false
        end

        if weapon.m_iClip1 ~= nil and weapon.m_iClip1 <= 0 then
            return false
        end

        return true
    end

    local function can_fire(local_player, weapon, weapon_info)
        local current_time = globals.curtime
        local next_primary_attack = weapon.m_flNextPrimaryAttack or 0

        if weapon_info ~= nil and weapon_info.is_revolver == true then
            return current_time >= next_primary_attack
        end

        local next_attack = local_player.m_flNextAttack or 0

        if current_time < next_attack then
            return false
        end

        if current_time < next_primary_attack then
            return false
        end

        return true
    end

    local function get_min_damage(target)
        local min_damage = math.max(0, get_menu_number(nl.rage.selection.minimum_damage, 0))

        if min_damage > 100 then
            min_damage = (target.m_iHealth or 100) + min_damage - 100
        end

        if min_damage < 1 then
            return 1
        end

        return min_damage
    end

    local function get_point_scale(template)
        local point_scale = 0

        if template.hitbox == "Head" then
            if ref.head_scale ~= nil then
                point_scale = ref.head_scale:get()
            end
        elseif ref.body_scale ~= nil then
            point_scale = ref.body_scale:get()
        end

        if point_scale == 0 then
            return template.scale
        end

        return template.scale * point_scale * 0.01
    end

    local function build_points(eye_position, center, scale)
        local angle = eye_position:to(center):angles()
        local side_yaw = math.rad(angle.y + 90)
        local side = vector(math.cos(side_yaw), math.sin(side_yaw), 0) * scale

        return {
            {
                vec = center,
            },
            {
                vec = center + side,
            },
            {
                vec = center - side,
            },
        }
    end

    local function trace_point(local_player, eye_position, point, target)
        local damage, trace = utils.trace_bullet(local_player, eye_position, point, function(trace_entity)
            return trace_entity == target
        end)

        if trace ~= nil then
            local hit_entity = trace.entity
            if hit_entity == nil then
                return 0, trace
            end

            if hit_entity:is_player() and not hit_entity:is_enemy() then
                return 0, trace
            end
        end

        return damage, trace
    end

    local function limit_movement(cmd, max_speed)
        local move_speed = math.sqrt(cmd.forwardmove * cmd.forwardmove + cmd.sidemove * cmd.sidemove)

        if max_speed <= 0 or move_speed <= 0 then
            return
        end

        if cmd.in_duck == 1 then
            max_speed = max_speed * 2.94117647
        end

        if move_speed <= max_speed then
            return
        end

        local scale = max_speed / move_speed
        cmd.forwardmove = cmd.forwardmove * scale
        cmd.sidemove = cmd.sidemove * scale
    end

    local function find_candidate(local_player, eye_position)
        local selected_hitboxes = ref.hitbox:get()
        local required_accuracy = ref.accuracy:get()
        local selected_count = selected_hitboxes ~= nil and #selected_hitboxes or 0
        local candidate = nil

        entity.get_players(true, true, function(target)
            if candidate ~= nil then
                return
            end

            if target == nil or not target:is_alive() or not target:is_dormant() then
                return
            end

            if target:is_visible() then
                return
            end

            if target:get_network_state() == 5 then
                return
            end

            local bbox = target:get_bbox()
            if bbox == nil then
                return
            end

            local alpha = bbox.alpha or 0
            local confidence = math.floor(alpha * 100) + 5
            if alpha == 0 or confidence <= required_accuracy then
                return
            end

            local origin = target:get_origin()
            if origin == nil then
                return
            end

            local min_damage = get_min_damage(target)
            for index = 1, #constants.point_templates do
                local template = constants.point_templates[index]
                if selected_count == 0 or has_hitbox_selection(selected_hitboxes, template.hitbox) then
                    local center = origin + template.offset
                    local points = build_points(eye_position, center, get_point_scale(template))

                    for point_index = 1, #points do
                        local point_data = points[point_index]
                        local damage = trace_point(local_player, eye_position, point_data.vec, target)

                        if damage ~= 0 and min_damage < damage then
                            candidate = {
                                point = point_data.vec,
                            }

                            return
                        end
                    end
                end
            end
        end)

        return candidate
    end

    local function reset_native_dormant_aimbot()
        if ref.native_ref ~= nil then
            ref.native_ref:override()
        end
    end

    local function on_createmove(cmd)
        local local_player = entity.get_local_player()
        if local_player == nil or not local_player:is_alive() then
            return
        end

        local weapon = local_player:get_player_weapon()
        if weapon == nil then
            return
        end

        local weapon_info = weapon:get_weapon_info()
        if not is_supported_weapon(weapon, weapon_info) then
            return
        end

        if not can_fire(local_player, weapon, weapon_info) then
            return
        end

        local on_ground = bit.band(local_player.m_fFlags or 0, constants.on_ground) ~= 0
        if (cmd.in_jump == 1 or cmd.in_jump == true) and not on_ground then
            return
        end

        local eye_position = local_player:get_eye_position()
        if eye_position == nil then
            return
        end

        local candidate = find_candidate(local_player, eye_position)
        if candidate == nil then
            return
        end

        local scoped = local_player.m_bIsScoped or local_player.m_bResumeZoom
        local max_speed = scoped and weapon_info.max_player_speed_alt or weapon_info.max_player_speed
        if max_speed ~= nil then
            limit_movement(cmd, max_speed * 0.33)
        end

        if not scoped and weapon_info.weapon_type == 5 and on_ground then
            cmd.in_attack2 = true
        end

        if weapon:get_inaccuracy() >= constants.attack_inaccuracy then
            return
        end

        local angle = eye_position:to(candidate.point):angles()
        cmd.view_angles.x = angle.x
        cmd.view_angles.y = angle.y
        cmd.in_attack = true
    end

    local function on_toggle(item)
        local enabled = item ~= nil and item:get() == true
        if enabled == callbacks_registered then
            return
        end

        if enabled then
            if ref.native_ref ~= nil then
                ref.native_ref:override(false)
            end

            events.createmove(on_createmove, true)
            callbacks_registered = true
            return
        end

        events.createmove(on_createmove, false)
        reset_native_dormant_aimbot()
        callbacks_registered = false
    end

    if ref.enabled ~= nil then
        ref.enabled:set_callback(on_toggle, true)
    end

    events.shutdown(reset_native_dormant_aimbot, true)
end

do
    local ON_GROUND_FLAG = 1
    local sv_maxunlag = cvar.sv_maxunlag
    local stored_maxunlag = nil

    local function is_revolver_weapon(weapon)
        if weapon == nil then
            return false
        end

        local weapon_info = weapon:get_weapon_info()
        if weapon_info == nil then
            return false
        end

        return weapon_info.is_revolver == true
    end

    local function reset_fix_recharge_delay()
        local override_state = angles_builder.fake_lag_limit_override_state
        if override_state ~= nil then
            override_state.fix_recharge_delay = nil
        end

        if angles_builder.apply_fake_lag_limit_override ~= nil then
            angles_builder.apply_fake_lag_limit_override()
        end
    end

    local function get_exploit_charge()
        if rage == nil or rage.exploit == nil then
            return nil
        end

        local ok_charge, charge = pcall(rage.exploit.get, rage.exploit)
        if not ok_charge or type(charge) ~= "number" then
            return nil
        end

        return charge
    end

    local function on_fix_recharge_delay_createmove()
        local override_state = angles_builder.fake_lag_limit_override_state
        if override_state == nil or angles_builder.apply_fake_lag_limit_override == nil then
            return
        end

        local local_player = entity.get_local_player()
        if local_player == nil or local_player:is_alive() ~= true then
            reset_fix_recharge_delay()
            return
        end

        local weapon = local_player:get_player_weapon()
        if is_revolver_weapon(weapon) then
            reset_fix_recharge_delay()
            return
        end

        local flags = local_player.m_fFlags
        if type(flags) ~= "number" or bit.band(flags, ON_GROUND_FLAG) ~= 0 then
            reset_fix_recharge_delay()
            return
        end

        local double_tap_ref = nl.rage and nl.rage.main and nl.rage.main.double_tap
        local hide_shots_ref = nl.rage and nl.rage.main and nl.rage.main.hide_shots
        local is_double_tap = double_tap_ref ~= nil and double_tap_ref:get() == true
        local is_hide_shots = hide_shots_ref ~= nil and hide_shots_ref:get() == true
        if not is_double_tap and not is_hide_shots then
            reset_fix_recharge_delay()
            return
        end

        local fake_duck_ref = nl.aa and nl.aa.misc and nl.aa.misc.fake_duck
        if fake_duck_ref ~= nil and fake_duck_ref:get() == true then
            reset_fix_recharge_delay()
            return
        end

        local exploit_charge = get_exploit_charge()
        if exploit_charge == nil or exploit_charge >= 1 then
            reset_fix_recharge_delay()
            return
        end

        override_state.fix_recharge_delay = 1
        angles_builder.apply_fake_lag_limit_override()
    end

    local function restore_unlock_ping_spike()
        if sv_maxunlag == nil or stored_maxunlag == nil then
            return
        end

        sv_maxunlag:float(stored_maxunlag, true)
        stored_maxunlag = nil
    end

    local function apply_unlock_ping_spike()
        if sv_maxunlag == nil then
            return
        end

        if stored_maxunlag == nil then
            stored_maxunlag = sv_maxunlag:float()
        end

        sv_maxunlag:float(0.400, true)
    end

    local function is_tweak_enabled(reference, value)
        if reference == nil or type(value) ~= "string" then
            return false
        end

        local ok_named, named = pcall(reference.get, reference, value)
        if ok_named and type(named) == "boolean" then
            return named
        end

        local ok_list, list = pcall(reference.get, reference)
        if not ok_list or type(list) ~= "table" then
            return false
        end

        for i = 1, #list do
            if list[i] == value then
                return true
            end
        end

        return false
    end

    if rage_ref.tweaks_selectable ~= nil then
        rage_ref.tweaks_selectable:set_callback(function(item)
            local fix_enabled = is_tweak_enabled(item, rage_tweaks_labels.fix_recharge_delay)
            events.createmove(on_fix_recharge_delay_createmove, fix_enabled)
            if fix_enabled ~= true then
                reset_fix_recharge_delay()
            end

            local unlock_enabled = is_tweak_enabled(item, rage_tweaks_labels.unlock_ping_spike)
            if unlock_enabled ~= true then
                restore_unlock_ping_spike()
                return
            end

            apply_unlock_ping_spike()
        end, true)
    end

    events.shutdown(reset_fix_recharge_delay, true)
    events.shutdown(restore_unlock_ping_spike, true)
end

do
    local WEAPONTYPE_PISTOL = 1
    local WEAPONTYPE_SUBMACHINEGUN = 2
    local WEAPONTYPE_RIFLE = 3
    local WEAPONTYPE_SNIPER_RIFLE = 5
    local auto_hide_shots_active = false
    local auto_hide_shots_dt_enabled = false
    local auto_hide_shots_previous_state = nil

    local function get_weapon_type(weapon)
        if weapon == nil then
            return nil
        end

        local weapon_info = weapon:get_weapon_info()
        if weapon_info == nil then
            return nil
        end

        local console_name = weapon_info.console_name
        if console_name == "weapon_ssg08" then
            return "Scout"
        end

        if console_name == "weapon_awp" then
            return "AWP"
        end

        if console_name == "weapon_scar20" or console_name == "weapon_g3sg1" then
            return "Auto Snipers"
        end

        if console_name == "weapon_deagle" then
            return "Desert Eagle"
        end

        if console_name == "weapon_revolver" then
            return "Revolver R8"
        end

        local weapon_type = weapon_info.weapon_type
        local weapon_index = weapon:get_weapon_index()

        if weapon_type == WEAPONTYPE_SUBMACHINEGUN then
            return "SMG"
        end

        if weapon_type == WEAPONTYPE_RIFLE then
            return "Rifles"
        end

        if weapon_type == WEAPONTYPE_PISTOL then
            if weapon_index == 1 then
                return "Desert Eagle"
            end

            if weapon_index == 64 then
                return "Revolver R8"
            end

            return "Pistols"
        end

        if weapon_type == WEAPONTYPE_SNIPER_RIFLE then
            if weapon_index == 40 then
                return "Scout"
            end

            if weapon_index == 9 then
                return "AWP"
            end

            return "Auto Snipers"
        end

        return nil
    end

    local function restore_auto_hide_shots_values()
        if nl.rage ~= nil and nl.rage.main ~= nil then
            if nl.rage.main.double_tap ~= nil then
                nl.rage.main.double_tap:override()
            end

            if nl.rage.main.hide_shots ~= nil then
                nl.rage.main.hide_shots:override()
            end
        end
    end

    local function apply_auto_hide_shots_values()
        if nl.rage ~= nil and nl.rage.main ~= nil then
            if nl.rage.main.double_tap ~= nil then
                nl.rage.main.double_tap:override(false)
            end

            if nl.rage.main.hide_shots ~= nil then
                nl.rage.main.hide_shots:override(true)
            end
        end
    end

    local function is_auto_hide_shots_landing_transition(previous_state, current_state)
        if previous_state ~= "Air-Crouch" then
            return false
        end

        return current_state == "Crouch" or current_state == "Move-Crouch"
    end

    local function should_apply_auto_hide_shots(state)
        local ref = rage_ref.auto_hide_shots
        if ref == nil or ref.weapons == nil then
            return false
        end

        local fake_duck_ref = nl.aa and nl.aa.misc and nl.aa.misc.fake_duck
        if fake_duck_ref ~= nil and fake_duck_ref:get() == true then
            return false
        end

        local peek_assist_ref = nl.rage and nl.rage.main and nl.rage.main.peek_assist
        if type(peek_assist_ref) == "table" and peek_assist_ref[1] ~= nil then
            if peek_assist_ref[1]:get() == true then
                return false
            end
        end

        local local_player = entity.get_local_player()
        if local_player == nil or local_player:is_alive() ~= true then
            return false
        end

        local anim_state = local_player:get_anim_state()
        if type(anim_state) == "table" and anim_state.landed_on_ground_this_frame == true then
            return false
        end

        local weapon = local_player:get_player_weapon()
        if weapon == nil then
            return false
        end

        local weapon_type = get_weapon_type(weapon)
        if weapon_type == nil then
            return false
        end

        local state_ref = ref.weapon_states[weapon_type]
        if state_ref == nil then
            return false
        end

        if type(state) ~= "string" then
            return false
        end

        if state_ref:get(state) ~= true then
            return false
        end

        return true
    end

    local function on_auto_hide_shots_shutdown()
        auto_hide_shots_active = false
        auto_hide_shots_previous_state = nil
        restore_auto_hide_shots_values()
    end

    local function on_auto_hide_shots_double_tap_change(item)
        auto_hide_shots_dt_enabled = item ~= nil and item:get() == true

        if auto_hide_shots_dt_enabled ~= true then
            auto_hide_shots_active = false
            auto_hide_shots_previous_state = nil
            restore_auto_hide_shots_values()
        end
    end

    local function on_auto_hide_shots_createmove(command)
        if auto_hide_shots_dt_enabled ~= true then
            auto_hide_shots_active = false
            auto_hide_shots_previous_state = nil
            restore_auto_hide_shots_values()
            return
        end

        local local_player = entity.get_local_player()
        local current_state = nil
        if local_player ~= nil and local_player:is_alive() == true then
            current_state = angles_builder.get_state(local_player, command)
        end

        local is_landing_transition = is_auto_hide_shots_landing_transition(
            auto_hide_shots_previous_state,
            current_state
        )

        auto_hide_shots_previous_state = current_state

        if is_landing_transition then
            auto_hide_shots_active = false
            restore_auto_hide_shots_values()
            return
        end

        if should_apply_auto_hide_shots(current_state) ~= true then
            auto_hide_shots_active = false
            restore_auto_hide_shots_values()
            return
        end

        auto_hide_shots_active = true
        apply_auto_hide_shots_values()
    end

    local function on_auto_hide_shots_enabled(item)
        local enabled = item ~= nil and item:get() == true

        events.shutdown(on_auto_hide_shots_shutdown, enabled)
        events.createmove(on_auto_hide_shots_createmove, enabled)

        if enabled ~= true then
            auto_hide_shots_active = false
            auto_hide_shots_previous_state = nil
            restore_auto_hide_shots_values()
        end
    end

    if rage_ref.auto_hide_shots ~= nil and rage_ref.auto_hide_shots.enabled ~= nil then
        rage_ref.auto_hide_shots.enabled:set_callback(on_auto_hide_shots_enabled, true)
    end

    local double_tap_ref = nl.rage and nl.rage.main and nl.rage.main.double_tap
    if double_tap_ref ~= nil then
        double_tap_ref:set_callback(on_auto_hide_shots_double_tap_change, true)
    end
end

do
    local COLOR_RESET = "\aF2F2F2FF"
    local MISS_HEX = color(214, 120, 120, 255):to_hex()
    local MUTED_HEX = color(255, 255, 255, 150):to_hex()
    local PURCHASE_ICON_NAME = "cart-shopping"
    local purchase_icon = ui.get_icon(PURCHASE_ICON_NAME)
    local hitgroup_names = {
        [0] = "generic",
        "head",
        "chest",
        "stomach",
        "left arm",
        "right arm",
        "left leg",
        "right leg",
        "neck",
        "generic",
        "gear",
    }

    if type(purchase_icon) ~= "string" or purchase_icon == "" then
        purchase_icon = "$"
    end

    local damage_dealt_enabled = false
    local purchase_enabled = false
    local accent_hex = color(221, 161, 94, 255):to_hex()
    local accent_dark_hex = color(221, 161, 94, 255):to_hex()

    local function colorize(hex, text)
        return "\a" .. hex .. text .. COLOR_RESET
    end

    local function accent(text)
        return colorize(accent_hex, text)
    end

    local function accent_dark(text)
        return colorize(accent_dark_hex, text)
    end

    local function muted(text)
        return colorize(MUTED_HEX, text)
    end

    local function miss_color(text)
        return colorize(MISS_HEX, text)
    end

    local function get_hitgroup_name(hitgroup)
        return hitgroup_names[hitgroup] or hitgroup_names[0]
    end

    local function title_case_word(word)
        if word == "" then
            return word
        end

        return word:sub(1, 1):upper() .. word:sub(2):lower()
    end

    local function write_log(tag, text)
        local console_message = text
        local event_icon = tag

        if tag == "purchase" then
            console_message = accent(purchase_icon) .. " " .. text
            event_icon = PURCHASE_ICON_NAME
        end

        print_raw(console_message)
        common.add_event(text, event_icon)
    end

    local function format_percent(value)
        if type(value) ~= "number" then
            return "?"
        end

        return string.format("%.0f%%", value)
    end

    local function format_ticks(value)
        if type(value) ~= "number" then
            return "?"
        end

        return string.format("%dt", value)
    end

    local function format_damage(value)
        if type(value) ~= "number" then
            return "?"
        end

        return tostring(value)
    end

    local function format_spread(value)
        if type(value) ~= "number" then
            return "?"
        end

        return string.format("%.2f", value)
    end

    local function format_pair(actual, wanted)
        if wanted == nil or wanted == "" then
            return actual
        end

        return actual .. muted("(") .. accent_dark(wanted) .. muted(")")
    end

    local function format_damage_pair(actual_damage, wanted_damage)
        local actual = format_damage(actual_damage)

        if type(actual_damage) == "number"
            and type(wanted_damage) == "number"
            and actual_damage >= wanted_damage then
            return actual
        end

        if type(wanted_damage) ~= "number" then
            return actual
        end

        return format_pair(actual, format_damage(wanted_damage))
    end

    local function format_hitgroup_pair(actual_hitgroup, wanted_hitgroup)
        local actual = get_hitgroup_name(actual_hitgroup)
        local wanted = get_hitgroup_name(wanted_hitgroup)

        if wanted == "generic" or actual == wanted then
            return accent(actual)
        end

        return accent(format_pair(actual, wanted))
    end

    local function format_metrics(hitchance, backtrack, spread)
        return " " .. muted(
            string.format("[hc: %s  /  bt: %s  /  sp: %s]", hitchance, backtrack, spread)
        )
    end

    local function get_item_name(raw_name)
        if type(raw_name) ~= "string" then
            return "Unknown"
        end

        local item_name = raw_name:lower()
        item_name = item_name:gsub("^weapon_", "")
        item_name = item_name:gsub("^item_", "")
        item_name = item_name:gsub("_", " ")
        item_name = item_name:gsub("%S+", title_case_word)

        return item_name
    end

    local function get_special_hurt_name(raw_name)
        if type(raw_name) ~= "string" then
            return nil
        end

        local weapon_name = raw_name:lower()
        if weapon_name == "inferno" then
            return "molotov"
        end

        if weapon_name == "hegrenade" then
            return "grenade"
        end

        if weapon_name:find("knife", 1, true) ~= nil
            or weapon_name:find("bayonet", 1, true) ~= nil then
            return "knife"
        end

        return nil
    end

    local on_rage_logs_aim_ack
    local on_rage_logs_player_hurt
    local on_rage_logs_item_purchase

    local function update_rage_logs_callbacks()
        events.aim_ack(on_rage_logs_aim_ack, damage_dealt_enabled)
        events.player_hurt(on_rage_logs_player_hurt, damage_dealt_enabled)
        events.item_purchase(on_rage_logs_item_purchase, purchase_enabled)
    end

    on_rage_logs_aim_ack = function(event)
        if damage_dealt_enabled ~= true or event == nil then
            return
        end

        local victim = event.target
        if victim == nil or victim:is_player() ~= true then
            return
        end

        local victim_name = accent(victim:get_name())
        local hitchance = format_percent(event.hitchance)
        local backtrack = format_ticks(event.backtrack)
        local spread = format_spread(event.spread)
        local metrics = format_metrics(hitchance, backtrack, spread)

        if event.state ~= nil then
            local wanted_hitgroup = get_hitgroup_name(event.wanted_hitgroup)

            if wanted_hitgroup == "generic" then
                write_log(
                    "xmark",
                    "Miss " .. victim_name
                        .. " due to " .. miss_color(event.state) .. " "
                        .. metrics
                )
                return
            end

            write_log(
                "xmark",
                "Miss " .. victim_name
                    .. " in " .. accent(wanted_hitgroup)
                    .. " due to " .. miss_color(event.state)  .. " "
                    .. metrics
            )
            return
        end

        local hitgroup = get_hitgroup_name(event.hitgroup)
        local wanted_hitgroup = get_hitgroup_name(event.wanted_hitgroup)
        local damage_text = format_damage_pair(event.damage, event.wanted_damage)

        if hitgroup == "generic" then
            write_log(
                "check",
                "Hit " .. victim_name
                    .. " for " .. accent(damage_text) .. " damage "
                    .. metrics
            )
            return
        end

        if wanted_hitgroup == "generic" then
            write_log(
                "check",
                "Hit " .. victim_name
                    .. " in " .. accent(hitgroup)
                    .. " for " .. accent(damage_text) .. " damage "
                    .. metrics
            )
            return
        end

        write_log(
            "check",
            "Hit " .. victim_name
                .. " in " .. format_hitgroup_pair(event.hitgroup, event.wanted_hitgroup)
                .. " for " .. accent(damage_text) .. " damage "
                .. metrics
        )
    end

    on_rage_logs_player_hurt = function(event)
        if damage_dealt_enabled ~= true or event == nil then
            return
        end

        if type(event.userid) ~= "number" or type(event.attacker) ~= "number" then
            return
        end

        local local_player = entity.get_local_player()
        if local_player == nil then
            return
        end

        local attacker = entity.get(event.attacker, true)
        if attacker ~= local_player then
            return
        end

        local victim = entity.get(event.userid, true)
        if victim == nil or victim == local_player or victim:is_player() ~= true then
            return
        end

        local hurt_name = get_special_hurt_name(event.weapon)
        if hurt_name == nil then
            return
        end

        local victim_name = accent(victim:get_name())
        local hitgroup = get_hitgroup_name(event.hitgroup)
        local damage = accent(format_damage(event.dmg_health))
        local weapon_text = accent(hurt_name)

        if hitgroup == "generic" then
            write_log(
                "check",
                "Hit " .. victim_name
                    .. " for " .. damage .. " damage "
                    .. " " .. muted("[") .. weapon_text .. muted("]")
            )
            return
        end

        write_log(
            "check",
            "Hit " .. victim_name
                .. " in " .. accent(hitgroup)
                .. " for " .. damage .. " damage "
                .. " " .. muted("[") .. weapon_text .. muted("]")
        )
    end

    on_rage_logs_item_purchase = function(event)
        if purchase_enabled ~= true then
            return
        end

        if type(event.userid) ~= "number" or type(event.weapon) ~= "string" then
            return
        end

        if event.weapon == "weapon_unknown" then
            return
        end

        local local_player = entity.get_local_player()
        if local_player == nil then
            return
        end

        local buyer = entity.get(event.userid, true)
        if buyer == nil or buyer:is_enemy() ~= true then
            return
        end

        write_log(
            "purchase",
            accent(buyer:get_name())
                .. " bought " .. accent(get_item_name(event.weapon))
        )
    end

    local function on_rage_logs_change(item)
        if item == nil then
            damage_dealt_enabled = false
            purchase_enabled = false
            update_rage_logs_callbacks()
            return
        end

        damage_dealt_enabled = item:get(1) == true
        purchase_enabled = item:get(2) == true

        update_rage_logs_callbacks()
    end

    local function on_rage_logs_accent_change(item)
        if item == nil then
            return
        end

        local accent_color = item:get()
        if accent_color == nil then
            return
        end

        accent_hex = accent_color:to_hex()
        accent_dark_hex = color(
            math.max(math.floor(accent_color.r * 0.78), 0),
            math.max(math.floor(accent_color.g * 0.78), 0),
            math.max(math.floor(accent_color.b * 0.78), 0),
            accent_color.a
        ):to_hex()
    end

    if rage_ref.logs ~= nil then
        rage_ref.logs:set_callback(on_rage_logs_change, true)
    end

    if rage_ref.logs_accent ~= nil then
        rage_ref.logs_accent:set_callback(on_rage_logs_accent_change, true)
    end

    events.shutdown(function()
        damage_dealt_enabled = false
        purchase_enabled = false
        update_rage_logs_callbacks()
    end, true)
end

local hit_chance_indicator_state
do
    hit_chance_indicator_state = {
        active = false,
        bind_active = false,
        override_active = false,
        updated_at = 0,
    }
end

local rage_hitchance_override
do
    rage_hitchance_override = {
    }

    local ref = rage_hitchance_override_ref
    local DISTANCE_INCHES_PER_METER = 39.37
    local DISTANCE_INFINITY_VALUE = 201

    local native = {
        global_hit_chance = nl.rage.selection.hit_chance,
        hit_chance = {
            auto_snipers = ui.find("Aimbot", "Ragebot", "Selection", "AutoSnipers", "Hit Chance"),
            ssg08 = ui.find("Aimbot", "Ragebot", "Selection", "SSG-08", "Hit Chance"),
            awp = ui.find("Aimbot", "Ragebot", "Selection", "AWP", "Hit Chance"),
            r8_revolver = ui.find("Aimbot", "Ragebot", "Selection", "R8 Revolver", "Hit Chance"),
        },
        auto_stop = {
            auto_snipers = ui.find("Aimbot", "Ragebot", "Accuracy", "AutoSnipers", "Auto Stop", "Options"),
            ssg08 = ui.find("Aimbot", "Ragebot", "Accuracy", "SSG-08", "Auto Stop", "Options"),
            awp = ui.find("Aimbot", "Ragebot", "Accuracy", "AWP", "Auto Stop", "Options"),
        },
        auto_scope = {
            auto_snipers = ui.find("Aimbot", "Ragebot", "Accuracy", "AutoSnipers", "Auto Scope"),
            ssg08 = ui.find("Aimbot", "Ragebot", "Accuracy", "SSG-08", "Auto Scope"),
            awp = ui.find("Aimbot", "Ragebot", "Accuracy", "AWP", "Auto Scope"),
        },
    }

    local active_hit_chance_ref = nil
    local active_hit_chance_value = nil
    local active_auto_stop_ref = nil
    local active_auto_scope_ref = nil
    local active_auto_stop_values = {
    }
    local hit_chance_state = {
        baseline_global = nil,
        baseline_weapon = {
        },
        external_until_tick = 0,
    }
    local runtime_state = {
        active = false,
    }
    local hit_chance_reference_ids = {
    }

    local on_createmove
    local on_shutdown
    local update_callback_state

    local function is_on_ground(flags)
        if type(flags) ~= "number" then
            return false
        end

        if bit ~= nil and bit.band ~= nil then
            return bit.band(flags, 1) == 1
        end

        return flags % 2 == 1
    end

    local function clear_hit_chance_override()
        runtime_state.active = false

        if active_hit_chance_ref == nil then
            active_hit_chance_value = nil
            return
        end

        active_hit_chance_ref:override()
        active_hit_chance_ref = nil
        active_hit_chance_value = nil
    end

    local function clear_auto_stop_override()
        for i = #active_auto_stop_values, 1, -1 do
            active_auto_stop_values[i] = nil
        end

        if active_auto_stop_ref == nil then
            return
        end

        active_auto_stop_ref:override()
        active_auto_stop_ref = nil
    end

    local function clear_auto_scope_override()
        if active_auto_scope_ref == nil then
            return
        end

        active_auto_scope_ref:override()
        active_auto_scope_ref = nil
    end

    local function clear_overrides()
        clear_hit_chance_override()
        clear_auto_stop_override()
        clear_auto_scope_override()
    end

    local function get_reference_value(reference)
        if reference == nil then
            return nil
        end

        local ok_value, value = pcall(reference.get, reference)
        if not ok_value then
            return nil
        end

        return value
    end

    local function get_reference_override(reference)
        if reference == nil then
            return nil
        end

        local ok_value, value = pcall(reference.get_override, reference)
        if not ok_value then
            return nil
        end

        return value
    end

    local function update_hit_chance_baseline(weapon_key, global_value, weapon_value)
        if type(global_value) == "number" then
            hit_chance_state.baseline_global = global_value
        end

        if type(weapon_key) == "string" and type(weapon_value) == "number" then
            hit_chance_state.baseline_weapon[weapon_key] = weapon_value
        end
    end

    local function get_hit_chance_baseline(weapon_key, current_global, current_weapon)
        local baseline_global = hit_chance_state.baseline_global
        if type(baseline_global) ~= "number" and type(current_global) == "number" then
            baseline_global = current_global
            hit_chance_state.baseline_global = current_global
        end

        local baseline_weapon = hit_chance_state.baseline_weapon[weapon_key]
        if type(baseline_weapon) ~= "number" and type(current_weapon) == "number" then
            baseline_weapon = current_weapon
            hit_chance_state.baseline_weapon[weapon_key] = current_weapon
        end

        return baseline_global, baseline_weapon
    end

    local function is_external_hit_chance_state_active(weapon_key, current_global, current_weapon)
        local baseline_global, baseline_weapon = get_hit_chance_baseline(
            weapon_key,
            current_global,
            current_weapon
        )
        local reasons = {
        }

        if get_reference_override(native.global_hit_chance) == nil
            and type(baseline_global) == "number"
            and type(current_global) == "number"
            and current_global ~= baseline_global then
            reasons[#reasons + 1] = string.format(
                "global get changed %s->%s",
                tostring(baseline_global),
                tostring(current_global)
            )
        end

        local weapon_reference = native.hit_chance[weapon_key]
        if get_reference_override(weapon_reference) == nil
            and type(baseline_weapon) == "number"
            and type(current_weapon) == "number"
            and current_weapon ~= baseline_weapon then
            reasons[#reasons + 1] = string.format(
                "%s get changed %s->%s",
                weapon_key,
                tostring(baseline_weapon),
                tostring(current_weapon)
            )
        end

        if #reasons == 0 then
            return false, nil
        end

        return true, table.concat(reasons, " | ")
    end

    local function cache_selectable_values(reference, store)
        if type(store) ~= "table" then
            return
        end

        for i = #store, 1, -1 do
            store[i] = nil
        end

        if reference == nil then
            return
        end

        local values = reference:get()
        if type(values) ~= "table" then
            return
        end

        local listed = reference:list()
        if type(listed) ~= "table" then
            listed = nil
        end

        for i = 1, #values do
            local value = values[i]
            if type(value) == "string" then
                store[#store + 1] = value
            elseif type(value) == "number" and listed ~= nil then
                local option = listed[value]
                if type(option) ~= "string" then
                    option = listed[value + 1]
                end

                if type(option) == "string" then
                    store[#store + 1] = option
                end
            end
        end
    end

    local function are_same_selectable_values(first, second)
        if type(first) ~= "table" or type(second) ~= "table" then
            return false
        end

        if #first ~= #second then
            return false
        end

        for i = 1, #first do
            if first[i] ~= second[i] then
                return false
            end
        end

        return true
    end

    local function copy_selectable_values(store, values)
        for i = #store, 1, -1 do
            store[i] = nil
        end

        if type(values) ~= "table" then
            return
        end

        for i = 1, #values do
            store[i] = values[i]
        end
    end

    local function has_any_override()
        for i = 1, #ref.order do
            local weapon_key = ref.order[i]
            local weapon = ref.weapons[weapon_key]

            if weapon_key ~= "auto_snipers" and weapon.jumping ~= nil and weapon.jumping:get() > 0 then
                return true
            end

            if weapon_key ~= "r8_revolver" and weapon.noscope ~= nil and weapon.noscope:get() > 0 then
                return true
            end
        end

        return false
    end

    local function get_weapon_key(local_player)
        if local_player == nil then
            return nil
        end

        local weapon = local_player:get_player_weapon()
        if weapon == nil then
            return nil
        end

        local weapon_info = weapon:get_weapon_info()
        if weapon_info == nil then
            return nil
        end

        local console_name = weapon_info.console_name
        if type(console_name) ~= "string" then
            return nil
        end

        for i = 1, #ref.order do
            local weapon_key = ref.order[i]
            if ref.weapons[weapon_key].console_names[console_name] == true then
                return weapon_key
            end
        end

        return nil
    end

    local function get_no_scope_distance_limit(reference)
        if reference == nil then
            return nil
        end

        local value = reference:get()
        if type(value) ~= "number" then
            return nil
        end

        if value == DISTANCE_INFINITY_VALUE then
            return math.huge
        end

        return value * 0.1 * DISTANCE_INCHES_PER_METER
    end

    local function is_no_scope_distance_valid(local_player, limit)
        if local_player == nil or type(limit) ~= "number" then
            return false
        end

        if limit == math.huge then
            return true
        end

        local local_origin = local_player:get_origin()
        if local_origin == nil then
            return false
        end

        local target_player = entity.get_threat()
        if target_player ~= nil and target_player:is_alive() then
            local target_origin = target_player:get_origin()
            if target_origin ~= nil and local_origin:dist2d(target_origin) <= limit then
                return true
            end
        end

        local is_valid = false
        entity.get_players(true, false, function(enemy_player)
            if is_valid or enemy_player == nil or not enemy_player:is_alive() then
                return
            end

            local enemy_origin = enemy_player:get_origin()
            if enemy_origin == nil then
                return
            end

            if local_origin:dist2d(enemy_origin) <= limit then
                is_valid = true
            end
        end)

        return is_valid
    end

    local function apply_hit_chance_override(reference, value)
        if reference == nil or type(value) ~= "number" or value <= 0 then
            clear_hit_chance_override()
            return
        end

        local current_override = get_reference_override(reference)
        if active_hit_chance_ref == reference
            and active_hit_chance_value == value
            and runtime_state.active == true
            and type(current_override) == "number"
            and current_override == value then
            return
        end

        if active_hit_chance_ref ~= nil and active_hit_chance_ref ~= reference then
            active_hit_chance_ref:override()
        end

        active_hit_chance_ref = reference
        active_hit_chance_value = value
        runtime_state.active = true
        reference:override(value)
    end

    local function apply_auto_stop_override(reference, values)
        if reference == nil or type(values) ~= "table" or #values == 0 then
            clear_auto_stop_override()
            return
        end

        if active_auto_stop_ref == reference and are_same_selectable_values(active_auto_stop_values, values) then
            return
        end

        if active_auto_stop_ref ~= nil and active_auto_stop_ref ~= reference then
            active_auto_stop_ref:override()
        end

        active_auto_stop_ref = reference
        copy_selectable_values(active_auto_stop_values, values)
        reference:override(values)
    end

    local function apply_auto_scope_override(reference, value)
        if reference == nil or type(value) ~= "boolean" then
            clear_auto_scope_override()
            return
        end

        if active_auto_scope_ref ~= nil and active_auto_scope_ref ~= reference then
            active_auto_scope_ref:override()
        end

        active_auto_scope_ref = reference
        reference:override(value)
    end

    local function get_reference_id(reference)
        if reference == nil then
            return nil
        end

        local ok_id, reference_id = pcall(reference.id, reference)
        if not ok_id or type(reference_id) ~= "number" then
            return nil
        end

        return reference_id
    end

    local function is_hit_chance_bind_name(bind_name)
        if type(bind_name) ~= "string" then
            return false
        end

        return string.find(bind_name, "Hit Chance", 1, true) ~= nil
            or string.find(bind_name, "Hit chance", 1, true) ~= nil
            or string.find(bind_name, "Hitchance", 1, true) ~= nil
            or string.find(bind_name, "Minimum Hitchance", 1, true) ~= nil
    end

    local function read_bind_field(bind_data, field_name)
        local ok_field, field_value = pcall(function()
            return bind_data[field_name]
        end)
        if not ok_field then
            return nil
        end

        if type(field_value) == "function" then
            local ok_call, call_value = pcall(field_value, bind_data)
            if ok_call then
                return call_value
            end
        end

        return field_value
    end

    local function read_bind_field_any(bind_data, field_names)
        for i = 1, #field_names do
            local field_value = read_bind_field(bind_data, field_names[i])
            if field_value ~= nil then
                return field_value
            end
        end

        return nil
    end

    local function get_bind_name(bind_data)
        local bind_name = read_bind_field_any(bind_data, {
            "name",
            "label",
            "title",
        })
        if type(bind_name) == "string" and bind_name ~= "" then
            return bind_name
        end

        local bind_text = tostring(bind_data)
        if type(bind_text) ~= "string" then
            return nil
        end

        local parsed_name = bind_text:match("^bind%((.*)%)$")
        if type(parsed_name) == "string" and parsed_name ~= "" then
            return parsed_name
        end

        return bind_text
    end

    local function get_bind_active(bind_data)
        local active = read_bind_field_any(bind_data, {
            "active",
            "is_active",
            "enabled",
            "state",
            "get",
        })
        if active == true or active == 1 then
            return true
        end

        if active == false or active == 0 then
            return false
        end

        local state_value = read_bind_field(bind_data, "state")
        if state_value == true or state_value == 1 then
            return true
        end

        return false
    end

    local function get_bind_reference(bind_data)
        return read_bind_field_any(bind_data, {
            "reference",
            "ref",
            "item",
            "menu_item",
            "get_reference",
        })
    end

    local function scan_hit_chance_binds(binds, source_name)
        if type(binds) ~= "table" then
            return false, source_name .. ": invalid binds table"
        end

        local active_binds = {
        }

        for _, bind_data in pairs(binds) do
            if type(bind_data) == "table" and get_bind_active(bind_data) then
                local bind_name = get_bind_name(bind_data)
                if type(bind_name) ~= "string" or bind_name == "" then
                    bind_name = "<unknown>"
                end

                active_binds[#active_binds + 1] = bind_name

                local bind_reference = get_bind_reference(bind_data)
                local bind_reference_id = get_reference_id(bind_reference)
                if bind_reference_id ~= nil and hit_chance_reference_ids[bind_reference_id] == true then
                    return true, source_name .. ": matched reference: " .. bind_name
                end

                if is_hit_chance_bind_name(bind_name) then
                    return true, source_name .. ": matched name: " .. bind_name
                end
            end
        end

        if #active_binds == 0 then
            return false, source_name .. ": no active binds"
        end

        return false, source_name .. ": active binds: " .. table.concat(active_binds, ", ")
    end

    local function is_hit_chance_bind_active()
        local ok_binds, binds = pcall(ui.get_binds)
        if ok_binds and type(binds) == "table" then
            local is_active, reason = scan_hit_chance_binds(binds, "ui.get_binds()")
            if is_active then
                return true, reason
            end

            local ok_all_binds, all_binds = pcall(ui.get_binds, true)
            if ok_all_binds and type(all_binds) == "table" then
                local is_active_all, reason_all = scan_hit_chance_binds(all_binds, "ui.get_binds(true)")
                if is_active_all then
                    return true, reason_all
                end

                return false, reason .. " | " .. reason_all
            end

            return false, reason .. " | ui.get_binds(true): failed"
        end

        local ok_all_binds, all_binds = pcall(ui.get_binds, true)
        if ok_all_binds and type(all_binds) == "table" then
            local is_active, reason = scan_hit_chance_binds(all_binds, "ui.get_binds(true)")
            if is_active then
                return true, reason
            end

            return false, "ui.get_binds(): failed | " .. reason
        end

        return false, "ui.get_binds(): failed | ui.get_binds(true): failed"
    end

    function on_createmove()
        local local_player = entity.get_local_player()
        if local_player == nil or not local_player:is_alive() then
            clear_overrides()
            return
        end

        local weapon_key = get_weapon_key(local_player)
        if weapon_key == nil then
            clear_overrides()
            return
        end

        local weapon = ref.weapons[weapon_key]
        local hit_chance_ref = native.hit_chance[weapon_key]
        local auto_stop_ref = native.auto_stop[weapon_key]
        local auto_scope_ref = native.auto_scope[weapon_key]
        local jumping_value = 0
        local noscope_value = 0
        local in_air = not is_on_ground(local_player.m_fFlags)
        local is_scoped = local_player.m_bIsScoped == true

        if weapon.jumping ~= nil then
            jumping_value = weapon.jumping:get()
        end

        if weapon.noscope ~= nil then
            noscope_value = weapon.noscope:get()
        end

        local is_bind_active = is_hit_chance_bind_active()
        local current_global_hit_chance = get_reference_value(native.global_hit_chance)
        local current_weapon_hit_chance = get_reference_value(hit_chance_ref)
        local has_external_hit_chance_state = is_external_hit_chance_state_active(
            weapon_key,
            current_global_hit_chance,
            current_weapon_hit_chance
        )
        local indicator_hit_chance_bind_active = hit_chance_indicator_state ~= nil
            and hit_chance_indicator_state.bind_active == true
            and type(hit_chance_indicator_state.updated_at) == "number"
            and globals.realtime - hit_chance_indicator_state.updated_at <= 0.25
        if is_bind_active then
            clear_overrides()
            return
        end

        if indicator_hit_chance_bind_active then
            clear_overrides()
            return
        end

        if has_external_hit_chance_state then
            hit_chance_state.external_until_tick = globals.tickcount + 12
            clear_overrides()
            return
        end

        if globals.tickcount <= hit_chance_state.external_until_tick then
            clear_overrides()
            return
        end

        if weapon_key ~= "auto_snipers" and jumping_value > 0 and in_air then
            apply_hit_chance_override(hit_chance_ref, jumping_value)
            clear_auto_stop_override()
            clear_auto_scope_override()
            return
        end

        if weapon_key ~= "r8_revolver" and noscope_value > 0 and not is_scoped then
            local distance_limit = get_no_scope_distance_limit(weapon.noscope_distance)
            if is_no_scope_distance_valid(local_player, distance_limit) then
                apply_hit_chance_override(hit_chance_ref, noscope_value)
                apply_auto_stop_override(auto_stop_ref, weapon.cached_auto_stop)
                apply_auto_scope_override(auto_scope_ref, false)
                return
            end
        end

        update_hit_chance_baseline(
            weapon_key,
            current_global_hit_chance,
            current_weapon_hit_chance
        )
        clear_overrides()
    end

    function on_shutdown()
        clear_overrides()
    end

    function update_callback_state()
        local enabled = has_any_override()
        if not enabled then
            clear_overrides()
        end

        events.createmove(on_createmove, enabled)
        events.shutdown(on_shutdown, enabled)
    end

    function rage_hitchance_override.is_active()
        return runtime_state.active == true
    end

    do
        local references = {
            native.global_hit_chance,
            native.hit_chance.auto_snipers,
            native.hit_chance.ssg08,
            native.hit_chance.awp,
            native.hit_chance.r8_revolver,
        }

        for i = 1, #references do
            local reference_id = get_reference_id(references[i])
            if reference_id ~= nil then
                hit_chance_reference_ids[reference_id] = true
            end
        end
    end

    for i = 1, #ref.order do
        local weapon_key = ref.order[i]
        local weapon = ref.weapons[weapon_key]

        if weapon.jumping ~= nil then
            weapon.jumping:set_callback(update_callback_state, true)
        end

        if weapon.noscope ~= nil then
            weapon.noscope:set_callback(update_callback_state, true)
        end

        if weapon.noscope_auto_stop ~= nil then
            weapon.noscope_auto_stop:set_callback(function(item)
                cache_selectable_values(item, weapon.cached_auto_stop)
            end, true)
        end
    end
end

