        )
        local smoothy do
            smoothy = {
            }

            local function to_smoothy_number(value)
                if type(value) == "boolean" then
                    return value and 1.0 or 0.0
                end

                return value or 0.0
            end

            local function linear_easing(time, begin_value, change_value, duration)
                if duration <= 0.0 then
                    return begin_value + change_value
                end

                return begin_value + change_value * (time / duration)
            end

            local function get_smoothy_dt()
                local dt = globals.frametime
                if type(dt) ~= "number" or dt <= 0.0 then
                    return 0.0
                end

                local timescale = native_get_timescale()
                if type(timescale) == "number" and timescale > 0.0 then
                    dt = dt / timescale
                end

                return dt
            end

            function smoothy.new(default_value, easing_fn)
                local initial_value = to_smoothy_number(default_value)
                local mt = {
                }
                local mt_data = {
                    value = initial_value,
                    start_value = initial_value,
                    target_value = initial_value,
                    elapsed = 0.0,
                    duration = 0.0,
                    easing = easing_fn or linear_easing,
                }

                function mt.update(self, duration, value, easing)
                    local target_value = to_smoothy_number(value)
                    local target_duration = duration or 0.0

                    if target_duration <= 0.0 then
                        self.value = target_value
                        self.start_value = target_value
                        self.target_value = target_value
                        self.elapsed = 0.0
                        self.duration = 0.0
                        return self.value
                    end

                    if self.target_value ~= target_value then
                        self.start_value = self.value
                        self.target_value = target_value
                        self.elapsed = 0.0
                    end

                    self.duration = target_duration

                    if self.value == self.target_value then
                        return self.value
                    end

                    local dt = get_smoothy_dt()
                    if dt <= 0.0 then
                        return self.value
                    end

                    self.elapsed = self.elapsed + dt

                    local easing_fn = easing or self.easing
                    local sample_time = math.min(self.elapsed, self.duration)
                    self.value = easing_fn(
                        sample_time,
                        self.start_value,
                        self.target_value - self.start_value,
                        self.duration
                    )

                    if sample_time >= self.duration then
                        self.value = self.target_value
                        self.start_value = self.target_value
                        self.elapsed = 0.0
                    end

                    return self.value
                end

                return setmetatable(mt, {
                    __metatable = false,
                    __call = mt.update,
                    __index = mt_data,
                })
            end
        end

