        local function clamp_number(value, min_value, max_value)
            if value < min_value then
                return min_value
            end

            if value > max_value then
                return max_value
            end

            return value
        end

        local function set_zone_offset(value)
            if type(value) ~= "number" then
                indicator_state.zone_offset = DEFAULT_ZONE_OFFSET
                return
