        local function invalidate_drag_bounds()
            indicator_state.drag_has_bounds = false
            indicator_state.drag_bounds_min_x = 0
            indicator_state.drag_bounds_min_y = 0
            indicator_state.drag_bounds_max_x = 0
            indicator_state.drag_bounds_max_y = 0
            indicator_state.drag_base_y = 0
            indicator_state.drag_top_offset = 0
            indicator_state.drag_bottom_offset = 0

            if indicator_state.dragging ~= true then
                indicator_state.drag_hovered = false
            end
        end

        local function stop_drag(sync_position)
            indicator_state.dragging = false
            indicator_state.drag_hovered = false
            indicator_state.drag_was_left_down = false

            if sync_position == true then
                sync_position_ref()
            end
        end

        local function update_drag_bounds(min_y, max_y, max_width, base_y)
            if type(min_y) ~= "number"
                or type(max_y) ~= "number"
                or type(max_width) ~= "number"
                or type(base_y) ~= "number" then
                invalidate_drag_bounds()
                return
            end

            indicator_state.drag_has_bounds = true
            indicator_state.drag_bounds_min_x = HORIZONTAL_OFFSET
            indicator_state.drag_bounds_min_y = min_y
            indicator_state.drag_bounds_max_x = HORIZONTAL_OFFSET + math.max(1, max_width)
            indicator_state.drag_bounds_max_y = max_y
            indicator_state.drag_base_y = base_y
            indicator_state.drag_top_offset = math.max(0, base_y - min_y)
            indicator_state.drag_bottom_offset = math.max(0, max_y - base_y)
        end

        local function is_mouse_inside_indicator_bounds(mouse)
            if indicator_state.drag_has_bounds ~= true or mouse == nil then
                return false
            end

            if mouse.x < indicator_state.drag_bounds_min_x then
                return false
            end

            if mouse.x > indicator_state.drag_bounds_max_x then
                return false
            end

            if mouse.y < indicator_state.drag_bounds_min_y then
                return false
            end

            if mouse.y > indicator_state.drag_bounds_max_y then
                return false
            end

            return true
        end

        local function is_mouse_inside_menu_bounds(mouse)
            if mouse == nil then
                return false
            end

            local menu_position = ui.get_position()
            local menu_size = ui.get_size()
            if menu_position == nil or menu_size == nil then
                return false
            end

            if mouse.x < menu_position.x then
                return false
            end

            if mouse.x > menu_position.x + menu_size.x then
                return false
            end

            if mouse.y < menu_position.y then
                return false
            end

            if mouse.y > menu_position.y + menu_size.y then
                return false
            end

            return true
        end

        local function update_customize_controls_visibility()
