        local function has_feature_selected(name)
            if ref.gamesense_side_list == nil then
                return true
            end

            local named_value = ref.gamesense_side_list:get(name)
            if type(named_value) == "boolean" then
                return named_value
            end

            local list_value = ref.gamesense_side_list:get()
            if type(list_value) ~= "table" then
                return true
            end

            for i = 1, #list_value do
                if list_value[i] == name then
                    return true
                end
            end

            return false
        end

        get_hitchance_indicator_label = function()
            local label = visuals_state.gamesense_side_hitchance_label
            if type(label) ~= "string" or label == "" then
                return "HC"
