                and has_feature_selected("Minimum Hitchance")

            if ref.gamesense_side_hitchance_text ~= nil then
                ref.gamesense_side_hitchance_text:visibility(is_visible)
            end

            if ref.gamesense_side_hitchance_apply ~= nil then
                ref.gamesense_side_hitchance_apply:visibility(is_visible)
            end
        end

        local function clear_animation_entries()
            local animation_entries = indicator_state.animation_entries
            local animation_draw_list = indicator_state.animation_draw_list
            local animation_remove_keys = indicator_state.animation_remove_keys

            for key in pairs(animation_entries) do
                animation_entries[key] = nil
            end

            for i = 1, #animation_draw_list do
                animation_draw_list[i] = nil
            end

            for i = 1, #animation_remove_keys do
                animation_remove_keys[i] = nil
            end
        end

        local function purge_text_cache()
            return
        end

        local function clear_queue()
            for i = 1, label_count do
                labels[i] = nil
                colors[i] = nil
                offsets[i] = nil
                widths[i] = nil
                heights[i] = nil
                icons[i] = nil
                progresses[i] = nil
                keys[i] = nil
            end

            label_count = 0
        end

        local function measure_indicator_layout_text(text)
            return indicator_text_renderer:measure_layout(text)
        end

        local function measure_indicator_draw_text(text)
            return indicator_text_renderer:measure_draw(text)
        end

        local function draw_indicator_text(position, clr, text, scale)
            indicator_text_renderer:draw_text(position, clr, text, scale)
        end

        local function add_indicator(label, clr, options)
            local icon = nil
            local progress = nil
            local key = label
            if type(options) == "table" then
                icon = options.icon
                if type(options.progress) == "number" then
                    progress = math.clamp(options.progress, 0, 1)
                end

                if type(options.key) == "string" and options.key ~= "" then
                    key = options.key
                end
            end

            local text_size = measure_indicator_layout_text(label)
            local box_width = text_size.x + 50
            local box_height = text_size.y + VERTICAL_PADDING * 2

            if icon ~= nil then
                box_width = box_width + BOMB_ICON_SIZE.x + 5
            end

            if progress ~= nil then
                box_width = box_width + 30
            end

            local screen_size = render.screen_size()
            local offset = screen_size.y - indicator_state.zone_offset
            if label_count > 0 then
                offset = offsets[label_count] - SPACING - box_height
            end

            label_count = label_count + 1
            labels[label_count] = label
            colors[label_count] = clr
            offsets[label_count] = offset
            widths[label_count] = box_width
            heights[label_count] = box_height
            icons[label_count] = icon
            progresses[label_count] = progress
            keys[label_count] = key
        end

        local function alpha_scale_color(base_color, alpha_scale)
            if alpha_scale >= 0.999 then
                return base_color
            end

            return color(
                base_color.r or 255,
                base_color.g or 255,
                base_color.b or 255,
                math.floor((base_color.a or 255) * alpha_scale + 0.5)
            )
        end

        local function lerp_number(from_value, to_value, t)
            return from_value + (to_value - from_value) * t
        end

        local function sync_indicator_animations()
            local animation_entries = indicator_state.animation_entries
            local frame_id = indicator_state.frame_id

            for i = 1, label_count do
                local key = keys[i]
                if type(key) ~= "string" or key == "" then
                    key = labels[i]
                end

                local entry = animation_entries[key]
                if entry == nil then
                    entry = {
                        move = smoothy.new(1.0),
                        start_y = offsets[i],
                        target_y = offsets[i],
                        size = smoothy.new(1.0),
                        start_width = widths[i],
                        target_width = widths[i],
                        start_height = heights[i],
                        target_height = heights[i],
                        alpha = smoothy.new(0.0),
                        target_alpha = 1.0,
                        scale = smoothy.new(0.0),
                        target_scale = 1.0,
                        label = labels[i],
                        color = colors[i],
                        icon = icons[i],
                        progress = progresses[i],
                        draw_y = offsets[i],
                        draw_width = widths[i],
                        draw_height = heights[i],
                        draw_alpha = 0.0,
                        draw_scale = ANIMATION_MIN_VISIBILITY_SCALE,
                        sort_index = i,
                        seen_frame = frame_id,
                    }
                    animation_entries[key] = entry
                else
                    if entry.target_y ~= offsets[i] then
                        if indicator_state.dragging == true then
                            entry.move = smoothy.new(1.0)
                            entry.start_y = offsets[i]
                            entry.draw_y = offsets[i]
                        else
                            entry.move = smoothy.new(0.0)
                            entry.start_y = entry.draw_y
                        end
                        entry.target_y = offsets[i]
                    end

                    if entry.target_width ~= widths[i] or entry.target_height ~= heights[i] then
                        entry.size = smoothy.new(0.0)
                        entry.start_width = entry.draw_width
                        entry.target_width = widths[i]
                        entry.start_height = entry.draw_height
                        entry.target_height = heights[i]
                    end

                    entry.target_alpha = 1.0
                    entry.target_scale = 1.0
                    entry.label = labels[i]
                    entry.color = colors[i]
                    entry.icon = icons[i]
                    entry.progress = progresses[i]
                    entry.sort_index = i
                    entry.seen_frame = frame_id
                end
            end

            for _, entry in pairs(animation_entries) do
                if entry.seen_frame ~= frame_id then
                    entry.move = smoothy.new(1.0)
                    entry.start_y = entry.draw_y
                    entry.target_y = entry.draw_y
                    entry.size = smoothy.new(1.0)
                    entry.start_width = entry.draw_width
                    entry.target_width = entry.draw_width
                    entry.start_height = entry.draw_height
                    entry.target_height = entry.draw_height
                    entry.target_alpha = 0.0
                    entry.target_scale = ANIMATION_MIN_VISIBILITY_SCALE
                end
            end
        end

        local function sort_animation_draw_list(a, b)
            if a.draw_y == b.draw_y then
                return (a.sort_index or 0) < (b.sort_index or 0)
            end

            return a.draw_y < b.draw_y
        end

        local function build_animation_draw_list()
            local animation_entries = indicator_state.animation_entries
            local animation_draw_list = indicator_state.animation_draw_list
            local animation_remove_keys = indicator_state.animation_remove_keys
            local draw_count = 0
            local remove_count = 0

            for key, entry in pairs(animation_entries) do
                local move_t = entry.move(ANIMATION_MOVE_DURATION, 1.0)
                local size_t = entry.size(ANIMATION_SIZE_DURATION, 1.0)
                local scale_target = entry.target_scale <= ANIMATION_MIN_VISIBILITY_SCALE and 0.0 or 1.0

                entry.draw_y = lerp_number(entry.start_y, entry.target_y, move_t)
                entry.draw_width = lerp_number(entry.start_width, entry.target_width, size_t)
                entry.draw_height = lerp_number(entry.start_height, entry.target_height, size_t)
                entry.draw_alpha = math.clamp(
                    entry.alpha(ANIMATION_ALPHA_DURATION, entry.target_alpha),
                    0.0,
                    1.0
                )
                entry.draw_scale = ANIMATION_MIN_VISIBILITY_SCALE
                    + (1.0 - ANIMATION_MIN_VISIBILITY_SCALE) * math.clamp(
                        entry.scale(ANIMATION_SCALE_DURATION, scale_target),
                        0.0,
                        1.0
                    )

                if entry.target_alpha <= ANIMATION_EPSILON and entry.draw_alpha <= ANIMATION_EPSILON then
                    remove_count = remove_count + 1
                    animation_remove_keys[remove_count] = key
                else
                    draw_count = draw_count + 1
                    animation_draw_list[draw_count] = entry
                end
            end

            for i = draw_count + 1, #animation_draw_list do
                animation_draw_list[i] = nil
            end

            for i = 1, remove_count do
                animation_entries[animation_remove_keys[i]] = nil
                animation_remove_keys[i] = nil
            end

            for i = remove_count + 1, #animation_remove_keys do
                animation_remove_keys[i] = nil
            end

            if draw_count > 1 then
                table.sort(animation_draw_list, sort_animation_draw_list)
            end

            return draw_count
        end

        local function reset_bind_state(entry)
            entry.active = false
            entry.value = nil
            entry.by_id = false
            entry.by_name = false
            entry.inferred = false
            entry.mode = nil
        end

        local function get_reference_id(reference)
            if reference == nil then
                return nil
            end

            return reference:id()
        end

        local function is_bind_name_match(bind_name, bind_type)
            if type(bind_name) ~= "string" then
                return false
            end

            if bind_type == "min_damage" then
                return string.find(bind_name, "Min. Damage", 1, true) ~= nil
                    or string.find(bind_name, "Min Damage", 1, true) ~= nil
                    or string.find(bind_name, "Minimum Damage", 1, true) ~= nil
            end

            if bind_type == "hit_chance" then
                return string.find(bind_name, "Hit Chance", 1, true) ~= nil
                    or string.find(bind_name, "Hit chance", 1, true) ~= nil
                    or string.find(bind_name, "Hitchance", 1, true) ~= nil
                    or string.find(bind_name, "Minimum Hitchance", 1, true) ~= nil
            end

            return false
        end

        local function read_bind_field(bind_data, field_name)
            local ok_field, field_value = pcall(function()
                return bind_data[field_name]
            end)
            if not ok_field then
                return nil
            end

            if type(field_value) == "function" then
                local ok_call, call_value = pcall(field_value, bind_data)
                if ok_call then
                    return call_value
                end
            end

            return field_value
        end

        local function read_bind_field_any(bind_data, field_names)
            for i = 1, #field_names do
                local field_value = read_bind_field(bind_data, field_names[i])
                if field_value ~= nil then
                    return field_value
                end
            end

            return nil
        end

        local function get_bind_name(bind_data)
            local bind_name = read_bind_field_any(bind_data, {
                "name",
                "label",
                "title",
            })
            if type(bind_name) == "string" and bind_name ~= "" then
                return bind_name
            end

            local bind_text = tostring(bind_data)
            if type(bind_text) ~= "string" then
                return nil
            end

            local parsed_name = bind_text:match("^bind%((.*)%)$")
            if type(parsed_name) == "string" and parsed_name ~= "" then
                return parsed_name
            end

            return bind_text
        end

        local function get_bind_active(bind_data)
            local active = read_bind_field_any(bind_data, {
                "active",
                "is_active",
                "enabled",
                "state",
                "get",
            })
            if active == true or active == 1 then
                return true
            end

            if active == false or active == 0 then
                return false
            end

            local state_value = read_bind_field(bind_data, "state")
            if state_value == true or state_value == 1 then
                return true
            end

            return false
        end

        local function get_bind_value(bind_data)
            return read_bind_field_any(bind_data, {
                "value",
                "val",
                "bind_value",
                "get_value",
            })
        end

        local function get_bind_mode(bind_data)
            return read_bind_field_any(bind_data, {
                "mode",
                "bind_mode",
                "type",
                "get_mode",
            })
        end

        local function get_bind_reference(bind_data)
            return read_bind_field_any(bind_data, {
                "reference",
                "ref",
                "item",
                "menu_item",
                "get_reference",
            })
        end

        local function apply_bind_data(entry, bind_data, bind_type, reference_id)
            local match_by_id = false
            local match_by_name = false

            local bind_reference = get_bind_reference(bind_data)
            if bind_reference ~= nil and reference_id ~= nil then
                local bind_id = get_reference_id(bind_reference)
                match_by_id = bind_id ~= nil and bind_id == reference_id
            end

            local bind_name = get_bind_name(bind_data)
            if is_bind_name_match(bind_name, bind_type) then
                match_by_name = true
            end

            if not match_by_id and not match_by_name then
                return
            end

            entry.by_id = entry.by_id or match_by_id
            entry.by_name = entry.by_name or match_by_name

            if entry.value == nil then
                entry.value = get_bind_value(bind_data)
            end

            local bind_mode = get_bind_mode(bind_data)
            local bind_value = get_bind_value(bind_data)
            if entry.mode == nil and bind_mode ~= nil then
                entry.mode = bind_mode
            end

            local active = get_bind_active(bind_data)
            if active then
                entry.active = true
                entry.inferred = false
                entry.value = bind_value
                return
            end

            if entry.active then
                return
            end

            entry.value = bind_value
        end

        local function scan_binds_list(binds, md_reference_id, hc_reference_id)
            if type(binds) ~= "table" then
                return
            end

            for i = 1, #binds do
                local bind_data = binds[i]
                apply_bind_data(
                    bind_state.min_damage,
                    bind_data,
                    "min_damage",
                    md_reference_id
                )
                apply_bind_data(
                    bind_state.hit_chance,
                    bind_data,
                    "hit_chance",
                    hc_reference_id
                )
            end
        end

        local function update_bind_state()
            reset_bind_state(bind_state.min_damage)
            reset_bind_state(bind_state.hit_chance)

            local md_reference_id = get_reference_id(ref_min_damage)
            local hc_reference_id = get_reference_id(ref_hit_chance)

            scan_binds_list(
                ui.get_binds(),
                md_reference_id,
                hc_reference_id
            )
        end

        local function is_bind_active(bind_type)
            local entry = bind_state[bind_type]
            return type(entry) == "table" and entry.active == true
        end

        local function has_active_override(reference)
            if reference == nil then
                return false
            end

            local override = reference:get_override()
            if override == nil then
                return false
            end

            return override ~= reference:get()
        end

        local function update_shared_hit_chance_state()
            if hit_chance_indicator_state == nil then
                return
            end

            local bind_active = is_bind_active("hit_chance")
            local override_active = has_active_override(ref_hit_chance)

            hit_chance_indicator_state.bind_active = bind_active
            hit_chance_indicator_state.override_active = override_active
            hit_chance_indicator_state.active = bind_active or override_active
            hit_chance_indicator_state.updated_at = globals.realtime
        end

        local function unpack_u32_rgba(value)
            local r = value % 256
            local g = math.floor(value / 256) % 256
            local b = math.floor(value / 65536) % 256
            local a = math.floor(value / 16777216) % 256
            return r, g, b, a
        end

        local function pack_u32_rgba(r, g, b, a)
            return r + g * 256 + b * 65536 + a * 16777216
        end

        local function to_u8(value)
            if value ~= value or value < 0 then
                return 0
            end

            if value > 255 then
                return 255
            end

            return math.floor(value)
        end

        local function rgb_u32_to_hsv(value)
            local r8, g8, b8 = unpack_u32_rgba(value)
            local r = r8 / 255.0
            local g = g8 / 255.0
            local b = b8 / 255.0
            local min_channel = math.min(r, g, b)
            local max_channel = math.max(r, g, b)
            local delta = max_channel - min_channel
            local h = 0.0
            local s = 0.0
            local v = max_channel

            if delta < 0.00001 then
                return h, s, v
            end

            if max_channel > 0.0 then
                s = delta / max_channel
            else
                return 0 / 0, s, v
            end

            if r >= max_channel then
                h = (g - b) / delta
            elseif g >= max_channel then
                h = (b - r) / delta + 2.0
            else
                h = (r - g) / delta + 4.0
            end

            h = h * 60.0
            if h < 0.0 then
                h = h + 360.0
            end

            return h, s, v
        end

        local function hsv_to_u32_color(h, s, v)
            local r = v
            local g = v
            local b = v

            if s > 0.0 then
                if h >= 360.0 then
                    h = 0.0
                end

                h = h / 60.0

                local i = math.floor(h)
                local f = h - i
                local p = v * (1.0 - s)
                local q = v * (1.0 - s * f)
                local t = v * (1.0 - s * (1.0 - f))

                if i == 0 then
                    r = v
                    g = t
                    b = p
                elseif i == 1 then
                    r = q
                    g = v
                    b = p
                elseif i == 2 then
                    r = p
                    g = v
                    b = t
                elseif i == 3 then
                    r = p
                    g = q
                    b = v
                elseif i == 4 then
                    r = t
                    g = p
                    b = v
                else
                    r = v
                    g = p
                    b = q
                end
            end

            return pack_u32_rgba(
                to_u8(r * 255.0),
                to_u8(g * 255.0),
                to_u8(b * 255.0),
                255
            )
        end

        local function color_lerp_rgba_native(base_u32, ratio, target_u32)
            if ratio <= 0.0 then
                return base_u32
            end

            if ratio >= 1.0 then
                return target_u32
            end

            local h1, s1, v1 = rgb_u32_to_hsv(base_u32)
            local h2, s2, v2 = rgb_u32_to_hsv(target_u32)
            return hsv_to_u32_color(
                (h2 - h1) * ratio + h1,
                (s2 - s1) * ratio + s1,
                (v2 - v1) * ratio + v1
            )
        end

        local function get_ping_color(fake_latency_value)
            if type(fake_latency_value) ~= "number" or fake_latency_value <= 0 then
                return nil
            end

            local net = utils.net_channel()
            if net == nil or net.latency == nil then
                return nil
            end

            local latency_sum = (net.latency[0] or 0) + (net.latency[1] or 0)
            local denominator = math.clamp(fake_latency_value * 0.001, 0.001, 0.2)
            local ratio = math.clamp(latency_sum / denominator, 0.0, 1.0)
            local packed = color_lerp_rgba_native(PING_COLOR_BASE_U32, ratio, PING_COLOR_TARGET_U32)
            local r, g, b, a = unpack_u32_rgba(packed)
            return color(r, g, b, a)
        end

        local function get_csgo_damage(damage, armor_value)
            local armor_ratio = 0.5
            local armor_bonus = 0.5

            if armor_value > 0 then
                local new_damage = damage * armor_ratio
                local armor_damage = (damage - new_damage) * armor_bonus

                if armor_damage > armor_value then
                    armor_damage = armor_value * (1.0 / armor_bonus)
                    new_damage = damage - armor_damage
                end

                damage = new_damage
            end

            return damage
        end

        local function get_bomb_damage(local_player, c4)
            local damage = 500
            local bomb_radius = damage * 3.5
            local distance = local_player:get_eye_position():dist(c4:get_origin())
            local sigma = bomb_radius / 3.0
            local falloff = math.exp(-distance * distance / (2.0 * sigma * sigma))
            return get_csgo_damage(damage * falloff, local_player.m_ArmorValue or 0)
        end

        local function update_bomb_indicators(local_player)
            local game_rules = entity.get_game_rules()
            if game_rules == nil then
                return
            end

            local player_resource = entity.get_player_resource()
            if player_resource == nil then
                return
            end

            if has_feature_selected("Bomb Information") then
                local player_c4 = player_resource.m_iPlayerC4
                if type(player_c4) == "number" and player_c4 > 0 then
                    local carrier = entity.get(player_c4)
                    if carrier ~= nil then
                        local weapon = carrier:get_player_weapon()
                        if weapon ~= nil and weapon.m_bStartedArming == true and type(weapon.m_fArmedTime) == "number" then
                            local planting_time = weapon.m_fArmedTime - globals.curtime
                            if planting_time > 0 then
                                local bombsite = "A"
                                local carrier_origin = carrier:get_origin()
                                local bombsite_a = player_resource.m_bombsiteCenterA
                                local bombsite_b = player_resource.m_bombsiteCenterB

                                if carrier_origin ~= nil and bombsite_a ~= nil and bombsite_b ~= nil then
                                    local dist_a = carrier_origin:distsqr(bombsite_a)
                                    local dist_b = carrier_origin:distsqr(bombsite_b)
                                    bombsite = dist_a < dist_b and "A" or "B"
                                end

                                add_indicator(
                                    string.format("%s - %.1fs", bombsite, planting_time),
                                    color(252, 243, 105, 255),
                                    {
                                        icon = bomb_icon,
                                        key = "bomb_arming_timer",
                                        progress = 1 - math.clamp(planting_time / 3.0, 0, 1),
                                    }
                                )
                            end
                        end
                    end
                end
            end

            local planted_list = entity.get_entities("CPlantedC4", true)
            if type(planted_list) ~= "table" or #planted_list == 0 then
                return
            end

            local planted_c4 = planted_list[1]
            if planted_c4 == nil or planted_c4.m_bBombDefused == true or planted_c4.m_bBombTicking ~= true then
                return
            end

            local curtime = globals.curtime
            local blow_time = planted_c4.m_flC4Blow
            if type(blow_time) ~= "number" then
                return
            end

            local remaining_time = blow_time - curtime
            if remaining_time < 0 then
                return
            end

            if has_feature_selected("Bomb Information") then
                local bombsite = planted_c4.m_nBombSite == 1 and "B" or "A"
                add_indicator(
                    string.format("%s - %.1fs", bombsite, remaining_time),
                    color(255, 255, 255, 200),
                    {
                        icon = bomb_icon,
                        key = "bomb_planted_timer",
                    }
                )

                local bomb_damage = math.floor(get_bomb_damage(local_player, planted_c4))
                if bomb_damage >= 1 then
                    local health = local_player.m_iHealth or 0
                    if bomb_damage < health then
                        add_indicator(
                            string.format("-%d HP", bomb_damage),
                            color(252, 243, 105, 255),
                            {
                                key = "bomb_damage",
                            }
                        )
                    else
                        add_indicator(
                            "FATAL",
                            color(255, 0, 50, 255),
                            {
                                key = "bomb_damage",
                            }
                        )
                    end
                end
            end

            if has_feature_selected("Bomb Information") and planted_c4.m_hBombDefuser ~= nil then
                local defuse_countdown = planted_c4.m_flDefuseCountDown
                if type(defuse_countdown) == "number" then
                    local defuse_time = defuse_countdown - curtime
                    if defuse_time > 0 then
                        local progress_percent = math.clamp(defuse_time / 10, 0, 1)
                        if progress_percent > 0 and progress_percent < 1 then
                            local screen_size = render.screen_size()
                            local bar_color = blow_time < defuse_countdown
                                and color(235, 50, 75, 125)
                                or color(50, 235, 75, 125)
                            local bar_height = (screen_size.y - 2) * progress_percent

                            render.rect(vector(0, 0, 0), vector(20, screen_size.y, 0), color(0, 0, 0, 115))
                            render.rect(
                                vector(1, 1 + bar_height, 0),
                                vector(19, screen_size.y - 1, 0),
                                bar_color
                            )
                        end

                        local defuse_color = defuse_countdown > blow_time
                            and color(255, 0, 0, 255)
                            or color(252, 243, 105, 255)

                        add_indicator(
                            string.format("DEF - %.1fs", defuse_time),
                            defuse_color,
                            {
                                icon = bomb_icon,
                                key = "bomb_defuse_timer",
                                progress = 1 - progress_percent,
                            }
                        )
                    end
                end
            end
        end

        local function update_indicators(local_player)
            local is_fake_duck = get_value(ref_fake_duck) == true
            local is_double_tap = get_value(ref_double_tap) == true and not is_fake_duck
            local is_hide_shots = get_value(ref_hide_shots) == true and not is_fake_duck and not is_double_tap
            local is_dormant_aimbot = get_value(ref_dormant_aimbot) == true
            local is_body_aim = get_value(ref_body_aim) == "Force"
            local is_safe_points = get_value(ref_safe_points) == "Force"
            local is_freestanding = get_value(ref_freestanding) == true
            local is_min_damage = is_bind_active("min_damage") or has_active_override(ref_min_damage)
            local is_custom_hitchance_override = rage_hitchance_override ~= nil
                and type(rage_hitchance_override.is_active) == "function"
                and rage_hitchance_override.is_active()
            local is_hit_chance = not is_custom_hitchance_override
                and (is_bind_active("hit_chance") or has_active_override(ref_hit_chance))
            local fake_latency_value = get_value(ref_fake_latency)
            local is_fake_latency = type(fake_latency_value) == "number" and fake_latency_value > 0

            if is_fake_latency and has_feature_selected("Fake Latency") then
                local ping_indicator_color = get_ping_color(fake_latency_value)
                if ping_indicator_color ~= nil then
                    add_indicator("PING", ping_indicator_color, {
                        key = "fake_latency",
                    })
                end
            end

            if is_hide_shots and has_feature_selected("Hide Shots") then
                add_indicator("OSAA", color(255, 255, 255, 200), {
                    key = "hide_shots",
                })
            end

            if is_double_tap and has_feature_selected("Double Tap") then
                local dt_color = color(255, 0, 50, 255)
                if rage.exploit:get() == 1 then
                    dt_color = color(255, 255, 255, 200)
                end

                add_indicator("DT", dt_color, {
                    key = "double_tap",
                })
            end

            if is_dormant_aimbot and has_feature_selected("Dormant Aimbot") then
                add_indicator("DA", color(255, 255, 255, 200), {
                    key = "dormant_aimbot",
                })
            end

            if is_fake_duck and has_feature_selected("Fake Duck") then
                add_indicator("DUCK", color(255, 255, 255, 200), {
                    key = "fake_duck",
                })
            end

            if is_safe_points and has_feature_selected("Force Safe Point") then
                add_indicator("SAFE", color(255, 255, 255, 200), {
                    key = "force_safe_point",
                })
            end

            if is_body_aim and has_feature_selected("Force Body Aim") then
                add_indicator("BODY", color(255, 255, 255, 200), {
                    key = "force_body_aim",
                })
            end

            if is_min_damage and has_feature_selected("Minimum Damage") then
                add_indicator("MD", color(255, 255, 255, 200), {
                    key = "minimum_damage",
                })
            end

            if is_hit_chance and has_feature_selected("Minimum Hitchance") then
                add_indicator(get_hitchance_indicator_label(), color(255, 255, 255, 200), {
                    key = "minimum_hitchance",
                })
            end

            if is_freestanding and has_feature_selected("Freestanding") then
                add_indicator("FS", color(255, 255, 255, 200), {
                    key = "freestanding",
                })
            end
        end

        local function draw_shadow(pos_a, pos_b, alpha_scale)
            alpha_scale = alpha_scale or 1.0
            if alpha_scale <= 0.0 then
                return
            end

            local adjusted_pos_b = vector(
                pos_b.x,
                math.max(pos_a.y + 1, pos_b.y - GRADIENT_HEIGHT_OFFSET),
                0
            )
            local center = (pos_a + adjusted_pos_b) / 2
            local start_color = color(0, 0, 0, 0)
            local end_color = color(
                0,
                0,
                0,
                math.floor(indicator_state.shadow_alpha * alpha_scale + 0.5)
            )

            render.gradient(
                pos_a,
                vector(center.x, adjusted_pos_b.y, 0),
                start_color,
                end_color,
                start_color,
                end_color
            )
            render.gradient(
                adjusted_pos_b,
                vector(center.x, pos_a.y, 0),
                start_color,
                end_color,
                start_color,
                end_color
            )
        end

        local function draw_progress_circle(position, clr, radius, percentage, thickness, alpha_scale)
            alpha_scale = alpha_scale or 1.0
            render.circle_outline(
                position,
                color(0, 0, 0, math.floor(255 * alpha_scale + 0.5)),
                radius,
                0,
                1.0,
                thickness
            )
            render.circle_outline(position, clr, radius - 1, 0, percentage, thickness - 2)
        end

        local function draw_indicator_entry(offset_y, label, clr, box_width, box_height, icon, progress, alpha_scale, visibility_scale)
            local pos = vector(HORIZONTAL_OFFSET, offset_y, 0)
            local layout_size = measure_indicator_layout_text(label)
            local draw_size = measure_indicator_draw_text(label)
            local box_size = vector(box_width, box_height, 0)
            local final_alpha_scale = clamp_number(
                (alpha_scale or 1.0) * indicator_state.global_alpha_scale,
                0.0,
                1.0
            )
            visibility_scale = visibility_scale or 1.0
            local draw_color = final_alpha_scale < 0.999
                and alpha_scale_color(clr, final_alpha_scale)
                or clr
            local text_pos = vector(
                pos.x + TEXT_OFFSET,
                pos.y + (box_size.y - draw_size.y) * 0.5 + TEXT_Y_OFFSET,
                0
            )

            draw_shadow(pos, pos + box_size, final_alpha_scale)

            if icon ~= nil then
                local icon_size = vector(
                    math.max(1, BOMB_ICON_SIZE.x * visibility_scale),
                    math.max(1, BOMB_ICON_SIZE.y * visibility_scale),
                    0
                )
                local icon_pos = pos + vector(
                    TEXT_OFFSET + (BOMB_ICON_SIZE.x - icon_size.x) * 0.5,
                    (box_size.y - BOMB_ICON_SIZE.y) * 0.5 + (BOMB_ICON_SIZE.y - icon_size.y) * 0.5,
                    0
                )

                render.texture(icon, icon_pos, icon_size, draw_color, "f")
                text_pos.x = text_pos.x + BOMB_ICON_SIZE.x + 5
            end

            draw_indicator_text(text_pos, draw_color, label, visibility_scale)

            if progress ~= nil then
                local radius = 10 * visibility_scale
                local circle_pos = vector(
                    text_pos.x + layout_size.x * visibility_scale + 12 + radius * 0.5,
                    pos.y + box_size.y * 0.5,
                    0
                )

                draw_progress_circle(
                    circle_pos,
                    color(255, 255, 255, math.floor(200 * final_alpha_scale + 0.5)),
                    radius,
                    progress,
                    math.max(2, 5 * visibility_scale),
                    final_alpha_scale
                )
            end
        end

        local function draw_indicators()
            if indicator_state.animate_enabled then
                sync_indicator_animations()

                local draw_count = build_animation_draw_list()
                if draw_count <= 0 then
                    invalidate_drag_bounds()
                    return
                end

                local animation_draw_list = indicator_state.animation_draw_list
                local min_y = animation_draw_list[1].draw_y
                local max_y = animation_draw_list[1].draw_y + animation_draw_list[1].draw_height
                local max_width = animation_draw_list[1].draw_width
                local base_y = animation_draw_list[1].draw_y
                for i = 1, draw_count do
                    local entry = animation_draw_list[i]
                    local bottom_y = entry.draw_y + entry.draw_height
                    if bottom_y > max_y then
                        max_y = bottom_y
                    end

                    if entry.draw_width > max_width then
                        max_width = entry.draw_width
                    end

                    if entry.draw_y > base_y then
                        base_y = entry.draw_y
                    end

                    draw_indicator_entry(
                        entry.draw_y,
                        entry.label,
                        entry.color,
                        entry.draw_width,
                        entry.draw_height,
                        entry.icon,
                        entry.progress,
                        entry.draw_alpha,
                        entry.draw_scale
                    )
                end

                update_drag_bounds(min_y, max_y, max_width, base_y)
                return
            end

            if label_count <= 0 then
                invalidate_drag_bounds()
                return
            end

            local min_y = offsets[1]
            local max_y = offsets[1] + heights[1]
            local max_width = widths[1]
            local base_y = offsets[1]
            for i = 1, label_count do
                local bottom_y = offsets[i] + heights[i]
                if offsets[i] < min_y then
                    min_y = offsets[i]
                end

                if bottom_y > max_y then
                    max_y = bottom_y
                end

                if widths[i] > max_width then
                    max_width = widths[i]
                end

                draw_indicator_entry(
                    offsets[i],
                    labels[i],
                    colors[i],
                    widths[i],
                    heights[i],
                    icons[i],
                    progresses[i],
                    1.0,
                    1.0
                )
            end

            update_drag_bounds(min_y, max_y, max_width, base_y)
        end

        on_mouse_input = function()
            if indicator_state.enabled ~= true or indicator_state.customize_enabled ~= true then
                if indicator_state.dragging == true then
                    stop_drag(true)
                end
                return
            end

            if ui.get_alpha() <= 0 then
                if indicator_state.dragging == true then
                    stop_drag(true)
                end

                indicator_state.drag_hovered = false
                indicator_state.drag_was_left_down = false
                return
            end

            local mouse = ui.get_mouse_position()
            if mouse == nil then
                return
            end

            local left_down = common.is_button_down(VK_LBUTTON) == true
            if is_mouse_inside_menu_bounds(mouse) then
                indicator_state.drag_hovered = false

                if indicator_state.dragging == true and left_down ~= true then
                    stop_drag(true)
                end

                indicator_state.drag_was_left_down = left_down
                return
            end

            local is_hovered = is_mouse_inside_indicator_bounds(mouse)
            indicator_state.drag_hovered = is_hovered

            if left_down and indicator_state.drag_was_left_down ~= true then
                if is_hovered and indicator_state.drag_has_bounds == true then
                    indicator_state.dragging = true
                    indicator_state.drag_offset_y = mouse.y - indicator_state.drag_base_y
                end
            end

            if indicator_state.dragging == true then
                if left_down == true then
                    local screen = render.screen_size()
                    local next_base_y = mouse.y - indicator_state.drag_offset_y
                    next_base_y = clamp_number(
                        next_base_y,
                        indicator_state.drag_top_offset,
                        screen.y - indicator_state.drag_bottom_offset
                    )
                    set_zone_offset(screen.y - next_base_y)
                else
                    stop_drag(true)
                end
            end

            indicator_state.drag_was_left_down = left_down

            if indicator_state.drag_hovered == true or indicator_state.dragging == true then
                return false
            end
        end

        local function on_render()
            indicator_state.frame_id = indicator_state.frame_id + 1
            indicator_text_renderer:set_frame_id(indicator_state.frame_id)
            if not indicator_state.enabled then
                clear_queue()
                invalidate_drag_bounds()
                purge_text_cache()
                return
            end

            update_bind_state()
            update_shared_hit_chance_state()

            local local_player = entity.get_local_player()
            if local_player == nil or local_player:is_alive() ~= true then
                draw_indicators()
                clear_queue()
                purge_text_cache()
                return
            end

            update_indicators(local_player)
            update_bomb_indicators(local_player)
            draw_indicators()
            clear_queue()
            purge_text_cache()
        end

        local callbacks
        do
            local function on_position_state_change()
                if indicator_state.customize_enabled ~= true then
                    set_zone_offset(DEFAULT_ZONE_OFFSET)
                    return
                end

                local value = get_value(ref.gamesense_side_position)
                if type(value) ~= "number" then
                    value = DEFAULT_ZONE_OFFSET
                end

                set_zone_offset(value)
            end

            local function on_alpha_state_change()
                if indicator_state.customize_enabled ~= true then
                    indicator_state.global_alpha_scale = DEFAULT_GLOBAL_ALPHA * 0.01
                    return
                end

                local value = get_value(ref.gamesense_side_alpha)
                if type(value) ~= "number" then
                    value = DEFAULT_GLOBAL_ALPHA
                end

                indicator_state.global_alpha_scale = clamp_number(value, 0, 100) * 0.01
            end

            local function on_shadow_alpha_state_change()
                if indicator_state.customize_enabled ~= true then
                    indicator_state.shadow_alpha = DEFAULT_SHADOW_GRADIENT_ALPHA
                    return
                end

                local value = get_value(ref.gamesense_side_shadow_alpha)
                if type(value) ~= "number" then
                    value = DEFAULT_SHADOW_GRADIENT_ALPHA
                end

                indicator_state.shadow_alpha = clamp_number(
                    math.floor(value + 0.5),
                    0,
                    255
                )
            end

            local function on_state_change()
                local enabled = is_enabled(ref.gamesense_side)
                indicator_state.enabled = enabled
                events.render(on_render, enabled)
                update_hitchance_input_visibility()
                update_mouse_input_callback_state()

                if not enabled then
                    if hit_chance_indicator_state ~= nil then
                        hit_chance_indicator_state.active = false
                        hit_chance_indicator_state.bind_active = false
                        hit_chance_indicator_state.override_active = false
                        hit_chance_indicator_state.updated_at = globals.realtime
                    end

                    stop_drag(false)
                    clear_animation_entries()
                    clear_queue()
                    invalidate_drag_bounds()
                end
            end

            local function on_animation_state_change()
                indicator_state.animate_enabled = indicator_state.customize_enabled == true
                    and is_enabled(ref.gamesense_side_animate)
                clear_animation_entries()
            end

            local function reset_customize_refs()
                set_zone_offset(DEFAULT_ZONE_OFFSET)
                indicator_state.global_alpha_scale = DEFAULT_GLOBAL_ALPHA * 0.01
                indicator_state.shadow_alpha = DEFAULT_SHADOW_GRADIENT_ALPHA

                if ref.gamesense_side_position ~= nil then
                    ref.gamesense_side_position:set(DEFAULT_ZONE_OFFSET)
                end

                if ref.gamesense_side_animate ~= nil then
                    ref.gamesense_side_animate:set(DEFAULT_ANIMATE_ENABLED)
                end
            end

            local function sync_customize_refs()
                on_position_state_change()
                on_alpha_state_change()
                on_shadow_alpha_state_change()
            end

            local function on_customize_state_change()
                indicator_state.customize_enabled = is_enabled(ref.gamesense_side_customize)
                update_customize_controls_visibility()

                if indicator_state.customize_enabled == true then
                    sync_customize_refs()
                else
                    stop_drag(false)
                    reset_customize_refs()
                    invalidate_drag_bounds()
                end

                on_animation_state_change()
                update_mouse_input_callback_state()
            end

            if ref.gamesense_side_position ~= nil then
                ref.gamesense_side_position:set_callback(on_position_state_change, true)
            end

            if ref.gamesense_side_alpha ~= nil then
                ref.gamesense_side_alpha:set_callback(on_alpha_state_change, true)
            end

            if ref.gamesense_side_shadow_alpha ~= nil then
                ref.gamesense_side_shadow_alpha:set_callback(on_shadow_alpha_state_change, true)
            end

            if ref.gamesense_side_animate ~= nil then
                ref.gamesense_side_animate:set_callback(on_animation_state_change, true)
            end

            if ref.gamesense_side_customize ~= nil then
                ref.gamesense_side_customize:set_callback(on_customize_state_change, true)
            end

            if ref.gamesense_side ~= nil then
                ref.gamesense_side:set_callback(on_state_change, true)
            end

            if ref.gamesense_side_list ~= nil then
                ref.gamesense_side_list:set_callback(function()
                    clear_queue()
                    update_hitchance_input_visibility()
                end, true)
            end
        end
    end
end

local visuals_min_damage_indicator
do

    do
        local ref = {
            enabled = visuals_ref.min_damage_indicator_enabled,
            font = visuals_ref.min_damage_indicator_font,
            color = visuals_ref.min_damage_indicator_color,
            offset = visuals_ref.min_damage_indicator_offset,
        }

        local FONT_IDS = {
            Default = 1,
            Small = 2,
            Bold = 4,
        }
        local DEFAULT_FONT_NAME = "Default"
        local DEFAULT_ACTIVE_COLOR = color(255, 255, 255, 255)
        local DEFAULT_INACTIVE_COLOR = color(255, 255, 255, 150)
        local DEFAULT_TEXT = "0"
        local DEFAULT_OFFSET = 8

        local ref_min_damage = ui.find("Aimbot", "Ragebot", "Selection", "Min. Damage")

        local state = {
            enabled = false,
            active = false,
            text = DEFAULT_TEXT,
            font_name = DEFAULT_FONT_NAME,
            offset = DEFAULT_OFFSET,
            active_color = DEFAULT_ACTIVE_COLOR,
            inactive_color = DEFAULT_INACTIVE_COLOR,
        }

        local function is_enabled(item)
            if item == nil then
                return false
            end

            return item:get() == true
        end

        local function get_reference_id(reference)
            if reference == nil then
                return nil
            end

            local ok_id, reference_id = pcall(reference.id, reference)
            if not ok_id or type(reference_id) ~= "number" then
                return nil
            end

            return reference_id
        end

        local function read_bind_field(bind_data, field_name)
            local ok_field, field_value = pcall(function()
                return bind_data[field_name]
            end)
            if not ok_field then
                return nil
            end

            if type(field_value) == "function" then
                local ok_call, call_value = pcall(field_value, bind_data)
                if ok_call then
                    return call_value
                end
            end

            return field_value
        end

        local function read_bind_field_any(bind_data, field_names)
            for i = 1, #field_names do
                local value = read_bind_field(bind_data, field_names[i])
                if value ~= nil then
                    return value
                end
            end

            return nil
        end

        local function get_bind_name(bind_data)
            local bind_name = read_bind_field_any(bind_data, {
                "name",
                "label",
                "title",
            })
            if type(bind_name) == "string" and bind_name ~= "" then
                return bind_name
            end

            local bind_text = tostring(bind_data)
            if type(bind_text) ~= "string" then
                return nil
            end

            local parsed_name = bind_text:match("^bind%((.*)%)$")
            if type(parsed_name) == "string" and parsed_name ~= "" then
                return parsed_name
            end

            return bind_text
        end

        local function get_bind_active(bind_data)
            local active = read_bind_field_any(bind_data, {
                "active",
                "is_active",
                "enabled",
                "state",
                "get",
            })
            if active == true or active == 1 then
                return true
            end

            if active == false or active == 0 then
                return false
            end

            local state_value = read_bind_field(bind_data, "state")
            if state_value == true or state_value == 1 then
                return true
            end

            return false
        end

        local function get_bind_reference(bind_data)
            return read_bind_field_any(bind_data, {
                "reference",
                "ref",
                "item",
                "menu_item",
                "get_reference",
            })
        end

        local function is_min_damage_bind_name(bind_name)
            if type(bind_name) ~= "string" then
                return false
            end

            return string.find(bind_name, "Min. Damage", 1, true) ~= nil
                or string.find(bind_name, "Min Damage", 1, true) ~= nil
                or string.find(bind_name, "Minimum Damage", 1, true) ~= nil
        end

        local function is_bind_active()
            local ok_binds, binds = pcall(ui.get_binds)
            if not ok_binds or type(binds) ~= "table" then
                return false
            end

            local reference_id = get_reference_id(ref_min_damage)
            for _, bind_data in pairs(binds) do
                if bind_data ~= nil and get_bind_active(bind_data) then
                    local bind_reference = get_bind_reference(bind_data)
                    if bind_reference ~= nil and reference_id ~= nil then
                        local bind_reference_id = get_reference_id(bind_reference)
                        if bind_reference_id ~= nil and bind_reference_id == reference_id then
                            return true
                        end
                    end

                    if is_min_damage_bind_name(get_bind_name(bind_data)) then
                        return true
                    end
                end
            end

            return false
        end

        local function has_active_override()
            if ref_min_damage == nil then
                return false
            end

            return ref_min_damage:get_override() ~= nil
        end

        local function get_effective_value()
            if ref_min_damage == nil then
                return 0
            end

            local override = ref_min_damage:get_override()
            if override ~= nil then
                return override
            end

            return ref_min_damage:get()
        end

        local function update_text_state()
            local value = get_effective_value()
            if type(value) == "number" then
                state.text = string.format("%d", math.floor(value + 0.5))
                return
            end

            state.text = tostring(value or DEFAULT_TEXT)
        end

        local function read_palette_color(key, fallback)
            if ref.color == nil then
                return fallback
            end

            local ok_value, value = pcall(ref.color.get, ref.color, key)
            if ok_value and type(value) == "table" and value[1] ~= nil then
                return value[1]
            end

            return fallback
        end

        local function update_font_state()
            local font_name = DEFAULT_FONT_NAME
            if ref.font ~= nil then
                local value = ref.font:get()
                if FONT_IDS[value] ~= nil then
                    font_name = value
                end
            end

            state.font_name = font_name
        end

        local function update_color_state()
            state.active_color = read_palette_color("Active", DEFAULT_ACTIVE_COLOR)
            state.inactive_color = read_palette_color("Inactive", DEFAULT_INACTIVE_COLOR)
        end

        local function update_offset_state()
            local offset = DEFAULT_OFFSET
            if ref.offset ~= nil then
                local value = ref.offset:get()
                if type(value) == "number" then
                    offset = value
                end
            end

            state.offset = offset
        end

        local function on_createmove()
            update_text_state()

            local local_player = entity.get_local_player()
            if local_player == nil or local_player:is_alive() ~= true then
                state.active = false
                return
            end

            state.active = is_bind_active() or has_active_override()
        end

        local function on_render()
            local local_player = entity.get_local_player()
            local menu_open = ui.get_alpha() > 0
            if not menu_open and (local_player == nil or local_player:is_alive() ~= true) then
                return
            end

            local font = FONT_IDS[state.font_name] or FONT_IDS[DEFAULT_FONT_NAME]
            local text = state.text
            if type(text) ~= "string" or text == "" then
                text = DEFAULT_TEXT
            end

            local screen = render.screen_size()
            local text_size = render.measure_text(font, nil, text)
            local position = screen * 0.5
            local offset = state.offset
            local draw_color = state.active and state.active_color or state.inactive_color

            position.x = position.x + offset
            position.y = position.y - offset - text_size.y

            render.text(
                font,
                position,
                draw_color,
                "",
                text
            )
        end

        local callbacks
        do
            local function bind_item_callback(item, callback, enabled)
                if item == nil then
                    return
                end

                if enabled then
                    item:set_callback(callback, true)
                    return
                end

                item:unset_callback(callback)
            end

            local function on_state_change()
                local enabled = is_enabled(ref.enabled)
                state.enabled = enabled
                if not enabled then
                    state.active = false
                end

                bind_item_callback(ref.font, update_font_state, enabled)
                bind_item_callback(ref.color, update_color_state, enabled)
                bind_item_callback(ref.offset, update_offset_state, enabled)
                bind_item_callback(ref_min_damage, update_text_state, enabled)

                if enabled then
                    update_font_state()
                    update_color_state()
                    update_offset_state()
                    update_text_state()
                end

                events.render(on_render, enabled)
                events.createmove(on_createmove, enabled)
            end

            if ref.enabled ~= nil then
                ref.enabled:set_callback(on_state_change, true)
            end
        end
    end
end

local visuals_esp_slowed_flag
do
    local DEFAULT_LOW_COLOR = color(255, 220, 120, 255)
    local DEFAULT_FULL_COLOR = color(255, 80, 80, 255)
    local VELOCITY_RECOVERY_RATE = 1 / 2.5
    local MIN_VISIBLE_SLOWED = 0.04
    local FULL_SLOWED_COLOR_AMOUNT = 0.2
    local FL_ONGROUND = 1
    local bit_band = bit.band

    local slowed_states = {
    }
    local low_color_ref = nil
    local full_color_ref = nil

    local function estimate_initial_slowed_amount(event)
        local damage = tonumber(event.dmg_health) or 0
        if damage < 0 then
            damage = 0
        end

        local slowed_amount = 0.06 + math.min(0.4, damage * 0.0065)
        local hitgroup = tonumber(event.hitgroup) or 0
        if hitgroup == 1 then
            slowed_amount = slowed_amount + 0.06
        end

        if slowed_amount > 0.7 then
            slowed_amount = 0.7
        end

        return slowed_amount
    end

    local function is_player_on_ground(player)
        if player == nil then
            return false
        end

        local flags = player.m_fFlags
        if type(flags) ~= "number" then
            return false
        end

        return bit_band(flags, FL_ONGROUND) ~= 0
    end

    local function get_current_slowed_amount(player, now)
        if player == nil then
            return 0
        end

        local entity_index = player:get_index()
        if type(entity_index) ~= "number" then
            return 0
        end

        local state = slowed_states[entity_index]
        if state == nil then
            return 0
        end

        local slowed_amount = state.value
        if type(slowed_amount) ~= "number" then
            slowed_states[entity_index] = nil
            return 0
        end

        local last_time = state.last_time
        if type(last_time) ~= "number" then
            last_time = now
        end

        if is_player_on_ground(player) then
            local delta_time = now - last_time
            if delta_time > 0 then
                slowed_amount = slowed_amount - delta_time * VELOCITY_RECOVERY_RATE
            end
        end

        if slowed_amount <= 0 then
            slowed_states[entity_index] = nil
            return 0
        end

        state.value = slowed_amount
        state.last_time = now

        return slowed_amount
    end

    local function on_player_hurt(event)
        local victim = entity.get(event.userid, true)
        if victim == nil or victim:is_enemy() ~= true or victim:is_alive() ~= true then
            return
        end

        local victim_index = victim:get_index()
        if type(victim_index) ~= "number" then
            return
        end

        local now = globals.curtime
        local current_slowed = get_current_slowed_amount(victim, now)
        local next_slowed = estimate_initial_slowed_amount(event)
        if current_slowed > next_slowed then
            next_slowed = current_slowed
        end

        slowed_states[victim_index] = {
            value = next_slowed,
            last_time = now,
        }
    end

    local function on_player_death(event)
        local victim = entity.get(event.userid, true)
        if victim == nil then
            return
        end

        local victim_index = victim:get_index()
        if type(victim_index) ~= "number" then
            return
        end

        slowed_states[victim_index] = nil
    end

    local function on_round_start()
        slowed_states = {
        }
    end

    if esp ~= nil and esp.enemy ~= nil and esp.enemy.new_text ~= nil then
        local slowed_flag_ref = esp.enemy:new_text(
            "Slowed",
            "SLOWED",
            function(player)
                if player == nil or player:is_alive() ~= true then
                    return nil
                end

                local slowed_amount = get_current_slowed_amount(player, globals.curtime)
                if slowed_amount < MIN_VISIBLE_SLOWED then
                    return nil
                end

                local low_color = DEFAULT_LOW_COLOR
                if low_color_ref ~= nil then
                    local value = low_color_ref:get()
                    if value ~= nil then
                        low_color = value
                    end
                end

                local full_color = DEFAULT_FULL_COLOR
                if full_color_ref ~= nil then
                    local value = full_color_ref:get()
                    if value ~= nil then
                        full_color = value
                    end
                end

                local color_factor = slowed_amount / FULL_SLOWED_COLOR_AMOUNT
                if color_factor < 0 then
                    color_factor = 0
                elseif color_factor > 1 then
                    color_factor = 1
                end

                local lerped_color = full_color:lerp(low_color, color_factor)
                return "\a" .. lerped_color:to_hex() .. "Slowed\aDEFAULT"
            end
        )

        if slowed_flag_ref ~= nil then
            local slowed_flag_group = slowed_flag_ref:create()
            if slowed_flag_group ~= nil then
                low_color_ref = config.push(
                    slowed_flag_group:color_picker("Low", DEFAULT_LOW_COLOR),
                    "main_visuals_esp_slowed_low_color"
                )
                full_color_ref = config.push(
                    slowed_flag_group:color_picker("Full", DEFAULT_FULL_COLOR),
                    "main_visuals_esp_slowed_full_color"
                )
            end
        end
    end

    events.player_hurt(on_player_hurt, true)
    events.player_death(on_player_death, true)
    events.round_start(on_round_start, true)
end

local visuals_grenade_prediction
do
    local LINE_OFFSET = vector(-1, 0)
    local IMPACT_COLOR = color(255, 0, 40)
    local IMPACT_HIT_COLOR = color(0, 255, 40)
    local DANGER_TEXT_COLOR = color(150, 200, 59, 220)
    local COLLISION_COLOR = color(255, 160)
    local COLLISION_BG_COLOR = color(0, 60)

    local enabled = false
    local prediction_data = nil
    local trail_color = color(255)
    local trail_hit_color = color(255)
    local prediction_ref = visuals_ref.grenade_prediction_enabled
    local prediction_color_ref = nl.visuals.world.other.grenade_prediction.color
    local hit_ref = nl.visuals.world.other.grenade_prediction.color_hit[1]
    local hit_color_ref = nl.visuals.world.other.grenade_prediction.color_hit[2]

    if not prediction_ref or not prediction_color_ref or not hit_ref or not hit_color_ref then
        return
    end

    local function update_colors()
        trail_color = prediction_color_ref:get()
        trail_hit_color = hit_ref:get() and hit_color_ref:get() or trail_color
    end

    local function on_grenade_prediction(ctx)
        prediction_data = {
            tick = globals.tickcount,
            type = ctx.type,
            damage = ctx.damage,
            fatal = ctx.fatal,
            path = ctx.path,
            collisions = ctx.collisions,
        }
        return false
    end

    local function on_render()
        local local_player = entity.get_local_player()
        local data = prediction_data
        if not local_player or not local_player:is_alive() or not data then
            return
        end
        if data.tick ~= globals.tickcount or not data.path or not data.collisions or #data.path == 0 then
            prediction_data = nil
            return
        end
        local path = data.path
        local damage = data.damage
        local line_color = damage >= 1 and trail_hit_color or trail_color
        local line_fade_color = line_color:clone():alpha_modulate(line_color.a * 0.65)
        local gradient_steps = math.min(#path - 1, 10)
        for i = 2, #path do
            local from = path[i - 1]:to_screen()
            local to = path[i]:to_screen()
            if from and to then
                local alpha_scale = 1
                if i <= gradient_steps + 1 then
                    alpha_scale = 0.1 + (i - 2) / math.max(1, gradient_steps) * 0.9
                end
                if math.floor(from.x - to.x) == 0 then
                    local segment_color = alpha_scale == 1 and line_fade_color or
                        line_fade_color:clone():alpha_modulate(line_fade_color.a * alpha_scale)
                    render.line(from - LINE_OFFSET, to - LINE_OFFSET, segment_color)
                    render.line(from, to, segment_color)
                else
                    render.line(from - LINE_OFFSET, to - LINE_OFFSET,
                        alpha_scale == 1 and line_color or line_color:clone():alpha_modulate(line_color.a * alpha_scale))
                end
            end
        end
        local hit_position
        if #path > 1 and #data.collisions > 0 then
            for i = 1, #data.collisions do
                local is_last_collision = i == #data.collisions
                local screen = (is_last_collision and path[#path] or data.collisions[i]):to_screen()
                if screen then
                    if is_last_collision then
                        hit_position = screen
                    end
                    local marker = screen + LINE_OFFSET
                    render.rect(marker - 1, marker + 5, COLLISION_BG_COLOR, 6)
                    render.rect(marker, marker + 4,
                        is_last_collision and (damage >= 1 and IMPACT_HIT_COLOR or IMPACT_COLOR) or COLLISION_COLOR, 6)
                end
            end
        end
        if damage < 1 then
            return
        end
        local text, text_color = nil, color(255, 200)
        if data.type == "Frag" then
            text = string.format("%d dmg", damage)
            if data.fatal or damage > 50 then
                text_color = DANGER_TEXT_COLOR
            end
        elseif data.type == "Molly" then
            text = string.format("%.1f m", damage * 0.01905)
            if damage / 12 < 12.5 then
                text_color = DANGER_TEXT_COLOR
            end
        elseif data.type == "Flash" then
            text = string.format("%d%%", damage)
        end
        if not text then
            return
        end
        local text_y_offset = render.measure_text(1, "d", text).y - 2
        local text_position = hit_position
        if text_position then
            local screen_size = render.screen_size()
            if text_position.x < 0 or text_position.y < 0 or text_position.x > screen_size.x or text_position.y > screen_size.y then
                text_position = nil
            else
                text_position = text_position - vector(0, text_y_offset)
            end
        end
        if not text_position then
            text_position = path[1] and path[1]:to_screen()
            if text_position then
                text_position = text_position - vector(0, text_y_offset + 8)
            end
        end
        if text_position then
            render.text(1, text_position, text_color, "c", text)
        end
    end

    local function set_enabled(state)
        if state == enabled then
            return
        end
        enabled = state
        events.render(on_render, state)
        events.grenade_prediction(on_grenade_prediction, state)
        if state then
            update_colors()
            return
        end
        prediction_data = nil
    end

    prediction_ref:set_callback(function()
        set_enabled(prediction_ref:get())
    end, true)
    prediction_color_ref:set_callback(update_colors, true)
    hit_ref:set_callback(update_colors, true)
    hit_color_ref:set_callback(update_colors, true)
end

local visuals_hit_marker
do
    local ref = {
        enabled = visuals_ref.hit_marker_enabled,
        damage_enabled = visuals_ref.hit_marker_damage_enabled,
        damage_speed = visuals_ref.hit_marker_damage_speed,
        damage_duration = visuals_ref.hit_marker_damage_duration,
        damage_color = visuals_ref.hit_marker_damage_color,
        screen_enabled = visuals_ref.hit_marker_screen_enabled,
        screen_color = visuals_ref.hit_marker_screen_color,
        world_enabled = visuals_ref.hit_marker_world_enabled,
        world_mode = visuals_ref.hit_marker_world_mode,
        world_gap = visuals_ref.hit_marker_world_gap,
        world_size = visuals_ref.hit_marker_world_size,
        world_color = visuals_ref.hit_marker_world_color,
    }

    local STATE_BODY = 0
    local STATE_HEAD = 1
    local STATE_MISMATCH = 2
    local WORLD_MODE_DEFAULT = 1
    local WORLD_MODE_DIAGONAL = 2

    local enabled = false

    local damage_state = {
        enabled = false,
        speed = 58,
        duration = 4.0,
        list = {
        },
        colors = {
            Body = color(255, 255, 255, 255),
            Head = color(150, 185, 5, 255),
            Mismatch = color(255, 0, 0, 255),
        },
    }

    local screen_state = {
        enabled = false,
        hurt_time = 0.0,
        color = color(255, 255, 255, 255),
    }

    local world_state = {
        enabled = false,
        mode = WORLD_MODE_DEFAULT,
        gap = 1,
        size = 4,
        thickness = 1,
        list = {
        },
        colors = {
            Vertical = color(0, 255, 0, 255),
            Horizontal = color(0, 255, 255, 255),
        },
    }

    local function is_enabled(item)
        if item == nil then
            return false
        end

        local ok_value, value = pcall(item.get, item)
        return ok_value and value == true
    end

    local function get_number(item, fallback)
        if item == nil then
            return fallback
        end

        local ok_value, value = pcall(item.get, item)
        if ok_value and type(value) == "number" then
            return value
        end

        return fallback
    end

    local function get_color(item, fallback)
        if item == nil then
            return fallback
        end

        local ok_value, value = pcall(item.get, item)
        if ok_value and value ~= nil then
            return value
        end

        return fallback
    end

    local function get_world_mode(item, fallback)
        if item == nil then
            return fallback
        end

        local ok_value, value = pcall(item.get, item)
        if not ok_value then
            return fallback
        end

        if value == "Diagonal" or value == WORLD_MODE_DIAGONAL then
            return WORLD_MODE_DIAGONAL
        end

        return WORLD_MODE_DEFAULT
    end

    local function get_palette_color(item, key, fallback)
        if item == nil then
            return fallback
        end

        local ok_value, value = pcall(item.get, item, key)
        if not ok_value or value == nil then
            return fallback
        end

        if type(value) == "table" then
            return value[1] or fallback
        end

        return value
    end

    local function refresh_damage_palette()
        damage_state.colors.Body = get_palette_color(
            ref.damage_color,
            "Body",
            damage_state.colors.Body
        )
        damage_state.colors.Head = get_palette_color(
            ref.damage_color,
            "Head",
            damage_state.colors.Head
        )
        damage_state.colors.Mismatch = get_palette_color(
            ref.damage_color,
            "Mismatch",
            damage_state.colors.Mismatch
        )
    end

    local function refresh_world_palette()
        world_state.colors.Vertical = get_palette_color(
            ref.world_color,
            "Vertical",
            world_state.colors.Vertical
        )
        world_state.colors.Horizontal = get_palette_color(
            ref.world_color,
            "Horizontal",
            world_state.colors.Horizontal
        )
    end

    local function get_damage_color(state)
        if state == STATE_HEAD then
            return damage_state.colors.Head
        end

        if state == STATE_MISMATCH then
            return damage_state.colors.Mismatch
        end

        return damage_state.colors.Body
    end

    local function on_damage_render()
        if not globals.is_in_game then
            return
        end

        local dt = globals.frametime
        local time = globals.realtime
        local list = damage_state.list

        for i = #list, 1, -1 do
            local data = list[i]

            if time > data.remaining then
                table.remove(list, i)
            else
                data.pos.z = data.pos.z + damage_state.speed * dt
            end
        end

        for i = 1, #list do
            local data = list[i]
            local screen = render.world_to_screen(data.pos)
            if screen ~= nil then
                local alpha = 1.0
                local life_remaining = data.remaining - time
                if life_remaining < 0.7 then
                    alpha = life_remaining / 0.7
                end

                local text_color = get_damage_color(data.state):clone()
                text_color.a = text_color.a * alpha

                render.text(
                    1,
                    screen,
                    text_color,
                    "c",
                    tostring(data.damage)
                )
            end
        end
    end

    local function on_damage_aim_ack(event)
        local data = damage_state.list[#damage_state.list]
        if data == nil then
            return
        end

        local wanted_damage = event.wanted_damage
        if type(wanted_damage) ~= "number" then
            return
        end

        if data.damage < wanted_damage then
            data.state = STATE_MISMATCH
        end
    end

    local function on_damage_player_hurt(event)
        local local_player = entity.get_local_player()
        if local_player == nil then
            return
        end

        local victim = entity.get(event.userid, true)
        local attacker = entity.get(event.attacker, true)
        if victim == nil or attacker == nil then
            return
        end

        if victim == local_player or attacker ~= local_player then
            return
        end

        local position = victim:get_eye_position()
        if position == nil then
            return
        end

        local damage = event.dmg_health
        if type(damage) ~= "number" then
            return
        end

        local state = STATE_BODY
        if event.hitgroup == 1 then
            state = STATE_HEAD
        end

        table.insert(damage_state.list, {
            pos = position,
            state = state,
            damage = damage,
            remaining = globals.realtime + damage_state.duration,
        })
    end

    local function render_screen_fade_line(outer_pos, inner_pos, line_color)
        local step_count = 5

        for i = 1, step_count do
            local from_pos = outer_pos:lerp(inner_pos, (i - 1) / step_count)
            local to_pos = outer_pos:lerp(inner_pos, i / step_count)
            local alpha_scale = 0.15 + (i / step_count) * 0.85
            local segment_color = line_color

            if i ~= step_count then
                segment_color = line_color:clone():alpha_modulate(line_color.a * alpha_scale)
            end

            render.line(from_pos, to_pos, segment_color)
        end
    end

    local function snap_screen_vector(pos)
        return vector(
            math.floor(pos.x + 0.5),
            math.floor(pos.y + 0.5)
        )
    end

    local function render_world_fade_line(outer_pos, inner_pos, line_color, thickness)
        local step_count = 5
        local line_dx = inner_pos.x - outer_pos.x
        local line_dy = inner_pos.y - outer_pos.y
        local line_length = math.sqrt(line_dx * line_dx + line_dy * line_dy)

        if line_length <= 0 then
            return
        end

        local normal_x = -line_dy / line_length
        local normal_y = line_dx / line_length
        local line_thickness = math.max(1, math.floor(thickness + 0.5))
        local start_offset = -(line_thickness - 1) * 0.5

        for thickness_index = 1, line_thickness do
            local offset = start_offset + thickness_index - 1
            local offset_vector = vector(normal_x * offset, normal_y * offset)

            for i = 1, step_count do
                local from_pos = snap_screen_vector(
                    outer_pos:lerp(inner_pos, (i - 1) / step_count) + offset_vector
                )
                local to_pos = snap_screen_vector(
                    outer_pos:lerp(inner_pos, i / step_count) + offset_vector
                )
                local alpha_scale = 0.15 + (i / step_count) * 0.85
                local segment_color = line_color

                if i ~= step_count then
                    segment_color = line_color:clone():alpha_modulate(line_color.a * alpha_scale)
                end

                render.line(from_pos, to_pos, segment_color)
            end
        end
    end

    local function render_world_axis_fade_line(center_pos, is_horizontal, direction, line_color, gap, size, thickness)
        local arm_gap = math.max(0, math.floor(gap + 0.5))
        local arm_size = math.max(1, math.floor(size + arm_gap + 0.5))
        local line_thickness = math.max(1, math.floor(thickness + 0.5))
        local center_x = math.floor(center_pos.x + 0.5)
        local center_y = math.floor(center_pos.y + 0.5)
        local inner_color = line_color
        local outer_color = line_color:clone():alpha_modulate(line_color.a * 0.15)

        if is_horizontal then
            local top = math.floor(center_y - line_thickness * 0.5 + 0.5)
            local bottom = top + line_thickness

            if direction < 0 then
                local outer_x = center_x - arm_gap - arm_size + 1
                local inner_x = center_x - arm_gap + 1

                render.gradient(
                    vector(outer_x, top),
                    vector(inner_x, bottom),
                    outer_color,
                    inner_color,
                    outer_color,
                    inner_color
                )
                return
            end

            local inner_x = center_x + arm_gap
            local outer_x = center_x + arm_gap + arm_size

            render.gradient(
                vector(inner_x, top),
                vector(outer_x, bottom),
                inner_color,
                outer_color,
                inner_color,
                outer_color
            )
            return
        end

        local left = math.floor(center_x - line_thickness * 0.5 + 0.5)
        local right = left + line_thickness

        if direction < 0 then
            local outer_y = center_y - arm_gap - arm_size + 1
            local inner_y = center_y - arm_gap + 1

            render.gradient(
                vector(left, outer_y),
                vector(right, inner_y),
                outer_color,
                outer_color,
                inner_color,
                inner_color
            )
            return
        end

        local inner_y = center_y + arm_gap
        local outer_y = center_y + arm_gap + arm_size

        render.gradient(
            vector(left, inner_y),
            vector(right, outer_y),
            inner_color,
            inner_color,
            outer_color,
            outer_color
        )
    end

    local function on_screen_render()
        if not globals.is_in_game or screen_state.hurt_time <= 0 then
            return
        end

        local alpha = 1.0
        if screen_state.hurt_time < 0.25 then
            alpha = screen_state.hurt_time / 0.25
        end

        local draw_color = screen_state.color:clone()
        draw_color.a = draw_color.a * alpha

        local center = render.screen_size() * 0.5

        render_screen_fade_line(
            vector(center.x - 10, center.y - 10),
            vector(center.x - 5, center.y - 5),
            draw_color
        )
        render_screen_fade_line(
            vector(center.x + 10, center.y - 10),
            vector(center.x + 5, center.y - 5),
            draw_color
        )
        render_screen_fade_line(
            vector(center.x + 10, center.y + 10),
            vector(center.x + 5, center.y + 5),
            draw_color
        )
        render_screen_fade_line(
            vector(center.x - 10, center.y + 10),
            vector(center.x - 5, center.y + 5),
            draw_color
        )

        screen_state.hurt_time = math.max(
            screen_state.hurt_time - globals.frametime,
            0.0
        )
    end

    local function on_screen_player_hurt(event)
        local local_player = entity.get_local_player()
        if local_player == nil then
            return
        end

        local victim = entity.get(event.userid, true)
        local attacker = entity.get(event.attacker, true)
        if victim == nil or attacker == nil then
            return
        end

        if victim == local_player or attacker ~= local_player then
            return
        end

        screen_state.hurt_time = 0.5
    end

    local function on_world_render()
        if not globals.is_in_game then
            return
        end

        local time = globals.realtime
        local list = world_state.list

        for i = #list, 1, -1 do
            if time > list[i].time then
                table.remove(list, i)
            end
        end

        for i = 1, #list do
            local data = list[i]
            local screen = render.world_to_screen(data.point)
            if screen ~= nil then
                screen = snap_screen_vector(screen)

                local alpha = 1.0
                local life_remaining = data.time - time
                if life_remaining < 0.7 then
                    alpha = life_remaining / 0.7
                end

                local half_thickness = world_state.thickness * 0.5
                local center_gap = math.max(0, world_state.gap)
                local base_marker_size = world_state.size + half_thickness

                local color_vertical = world_state.colors.Vertical:clone()
                local color_horizontal = world_state.colors.Horizontal:clone()

                color_vertical.a = color_vertical.a * alpha
                color_horizontal.a = color_horizontal.a * alpha

                if world_state.mode == WORLD_MODE_DIAGONAL then
                    local marker_size = base_marker_size
                    local inner_offset = half_thickness

                    render_world_fade_line(
                        vector(screen.x - marker_size, screen.y - marker_size),
                        vector(screen.x - inner_offset, screen.y - inner_offset),
                        color_vertical,
                        world_state.thickness
                    )
                    render_world_fade_line(
                        vector(screen.x + marker_size, screen.y - marker_size),
                        vector(screen.x + inner_offset, screen.y - inner_offset),
                        color_horizontal,
                        world_state.thickness
                    )
                    render_world_fade_line(
                        vector(screen.x + marker_size, screen.y + marker_size),
                        vector(screen.x + inner_offset, screen.y + inner_offset),
                        color_vertical,
                        world_state.thickness
                    )
                    render_world_fade_line(
                        vector(screen.x - marker_size, screen.y + marker_size),
                        vector(screen.x - inner_offset, screen.y + inner_offset),
                        color_horizontal,
                        world_state.thickness
                    )
                else
                    render_world_axis_fade_line(
                        screen,
                        true,
                        -1,
                        color_horizontal,
                        center_gap,
                        world_state.size,
                        world_state.thickness
                    )
                    render_world_axis_fade_line(
                        screen,
                        true,
                        1,
                        color_horizontal,
                        center_gap,
                        world_state.size,
                        world_state.thickness
                    )
                    render_world_axis_fade_line(
                        screen,
                        false,
                        -1,
                        color_vertical,
                        center_gap,
                        world_state.size,
                        world_state.thickness
                    )
                    render_world_axis_fade_line(
                        screen,
                        false,
                        1,
                        color_vertical,
                        center_gap,
                        world_state.size,
                        world_state.thickness
                    )
                end
            end
        end
    end

    local function on_world_aim_ack(event)
        if event.aim == nil then
            return
        end

        table.insert(world_state.list, {
            time = globals.realtime + 3.0,
            point = event.aim,
        })
    end

    local function bind_damage_callbacks()
        local state = enabled and damage_state.enabled

        if not state then
            damage_state.list = {
            }
        end

        events.render(on_damage_render, state)
        events.aim_ack(on_damage_aim_ack, state)
        events.player_hurt(on_damage_player_hurt, state)
    end

    local function bind_screen_callbacks()
        local state = enabled and screen_state.enabled

        if not state then
            screen_state.hurt_time = 0.0
        end

        events.render(on_screen_render, state)
        events.player_hurt(on_screen_player_hurt, state)
    end

    local function bind_world_callbacks()
        local state = enabled and world_state.enabled

        if not state then
            world_state.list = {
            }
        end

        events.render(on_world_render, state)
        events.aim_ack(on_world_aim_ack, state)
    end

    if ref.damage_speed ~= nil then
        ref.damage_speed:set_callback(function(item)
            damage_state.speed = get_number(item, 58)
        end, true)
    end

    if ref.damage_duration ~= nil then
        ref.damage_duration:set_callback(function(item)
            damage_state.duration = get_number(item, 4.0)
        end, true)
    end

    if ref.damage_color ~= nil then
        ref.damage_color:set_callback(
            refresh_damage_palette,
            true
        )
    end

    if ref.damage_enabled ~= nil then
        ref.damage_enabled:set_callback(function(item)
            damage_state.enabled = is_enabled(item)
            bind_damage_callbacks()
        end, true)
    end

    if ref.screen_color ~= nil then
        ref.screen_color:set_callback(function(item)
            screen_state.color = get_color(
                item,
                screen_state.color
            )
        end, true)
    end

    if ref.screen_enabled ~= nil then
        ref.screen_enabled:set_callback(function(item)
            screen_state.enabled = is_enabled(item)
            bind_screen_callbacks()
        end, true)
    end

    if ref.world_size ~= nil then
        ref.world_size:set_callback(function(item)
            world_state.size = get_number(item, 4)
        end, true)
    end

    if ref.world_mode ~= nil then
        ref.world_mode:set_callback(function(item)
            world_state.mode = get_world_mode(item, WORLD_MODE_DEFAULT)
        end, true)
    end

    if ref.world_gap ~= nil then
        ref.world_gap:set_callback(function(item)
            world_state.gap = get_number(item, 1)
        end, true)
    end

    if ref.world_color ~= nil then
        ref.world_color:set_callback(
            refresh_world_palette,
            true
        )
    end

    if ref.world_enabled ~= nil then
        ref.world_enabled:set_callback(function(item)
            world_state.enabled = is_enabled(item)
            bind_world_callbacks()
        end, true)
    end

    if ref.enabled ~= nil then
        ref.enabled:set_callback(function(item)
            enabled = is_enabled(item)

            bind_damage_callbacks()
            bind_screen_callbacks()
            bind_world_callbacks()
        end, true)
    end
end

local visuals_aspect_ratio
do
    local ref = {
        enabled = visuals_ref.aspect_ratio_enabled,
        proportion = visuals_ref.aspect_ratio_proportion,
    }

    local r_aspectratio = cvar.r_aspectratio

    local function unset_ratio()
        if r_aspectratio == nil then
            return
        end

        local value = tonumber(r_aspectratio:string())
        if type(value) ~= "number" then
            value = 0
        end

        r_aspectratio:float(value, true)
    end

    local function set_ratio(value)
        if r_aspectratio == nil then
            return
        end

        r_aspectratio:float(value, true)
    end

    local function on_shutdown()
        unset_ratio()
    end

    local callbacks
    do
        local function on_proportion(item)
            if item == nil then
                return
            end

            local ok_value, value = pcall(item.get, item)
            if not ok_value or type(value) ~= "number" then
                return
            end

            set_ratio(value * 0.01)
        end

        local function on_enabled(item)
            local enabled = false
            if item ~= nil then
                local ok_enabled, value = pcall(item.get, item)
                enabled = ok_enabled and value == true
            end

            if ref.proportion ~= nil then
                if enabled then
                    ref.proportion:set_callback(on_proportion, true)
                else
                    ref.proportion:unset_callback(on_proportion)
                    unset_ratio()
                end
            elseif not enabled then
                unset_ratio()
            end

            events.shutdown(on_shutdown, enabled)
        end

        if ref.enabled ~= nil then
            ref.enabled:set_callback(on_enabled, true)
        end
    end
end

local visuals_viewmodel
do
    local ref = {
        enabled = visuals_ref.viewmodel_enabled,
        fov = visuals_ref.viewmodel_fov,
        offset_x = visuals_ref.viewmodel_offset_x,
        offset_y = visuals_ref.viewmodel_offset_y,
        offset_z = visuals_ref.viewmodel_offset_z,
        options = visuals_ref.viewmodel_options,
    }

    local WEAPONTYPE_KNIFE = 0

    local cl_bobup = cvar.cl_bobup
    local cl_bobamt_lat = cvar.cl_bobamt_lat
    local cl_bobamt_vert = cvar.cl_bobamt_vert

    local cl_righthand = cvar.cl_righthand
    local viewmodel_fov = cvar.viewmodel_fov
    local viewmodel_offset_x = cvar.viewmodel_offset_x
    local viewmodel_offset_y = cvar.viewmodel_offset_y
    local viewmodel_offset_z = cvar.viewmodel_offset_z

    local ref_force_viewmodel = ui.find(
        "Visuals",
        "World",
        "Main",
        "Override Zoom",
        "Force Viewmodel"
    )

    local old_weapon_index = 0
    local scope_value = 0.0

    local function get_option_state(item, name)
        if item == nil then
            return false
        end

        local ok_named, named_value = pcall(item.get, item, name)
        if ok_named and type(named_value) == "boolean" then
            return named_value
        end

        local ok_values, values = pcall(item.get, item)
        if not ok_values or type(values) ~= "table" then
            return false
        end

        local option_names = nil
        local ok_options, listed = pcall(item.list, item)
        if ok_options and type(listed) == "table" then
            option_names = listed
        end

        for i = 1, #values do
            local value = values[i]
            if value == name then
                return true
            end

            if type(value) == "number" and option_names ~= nil then
                if option_names[value] == name then
                    return true
                end
            end
        end

        return false
    end

    local function get_slider_value(item, fallback)
        if item == nil then
            return fallback
        end

        local ok_value, value = pcall(item.get, item)
        if not ok_value or type(value) ~= "number" then
            return fallback
        end

        return value
    end

    local function get_original(convar, fallback)
        if convar == nil then
            return fallback
        end

        local value = tonumber(convar:string())
        if type(value) ~= "number" then
            return fallback
        end

        return value
    end

    local function lerp(a, b, t)
        return a + (b - a) * t
    end

    local function update_knife_hand(is_knife)
        if cl_righthand == nil then
            return
        end

        local is_right = cl_righthand:string() == "1"
        if is_right then
            cl_righthand:int(is_knife and 0 or 1, true)
        else
            cl_righthand:int(is_knife and 1 or 0, true)
        end
    end

    local function shutdown_viewmodel()
        if ref_force_viewmodel ~= nil then
            ref_force_viewmodel:override()
        end

        if cl_bobup ~= nil then
            cl_bobup:float(get_original(cl_bobup, 0), false)
        end

        if cl_bobamt_lat ~= nil then
            cl_bobamt_lat:float(get_original(cl_bobamt_lat, 0), false)
        end

        if cl_bobamt_vert ~= nil then
            cl_bobamt_vert:float(get_original(cl_bobamt_vert, 0), false)
        end

        if viewmodel_fov ~= nil then
            viewmodel_fov:float(get_original(viewmodel_fov, 68), false)
        end

        if viewmodel_offset_x ~= nil then
            viewmodel_offset_x:float(get_original(viewmodel_offset_x, 0), false)
        end

        if viewmodel_offset_y ~= nil then
            viewmodel_offset_y:float(get_original(viewmodel_offset_y, 0), false)
        end

        if viewmodel_offset_z ~= nil then
            viewmodel_offset_z:float(get_original(viewmodel_offset_z, 0), false)
        end

        if cl_righthand ~= nil then
            cl_righthand:int(cl_righthand:string() == "1" and 1 or 0, false)
        end

        scope_value = 0.0
    end

    local function get_viewmodel_offset()
        local local_player = entity.get_local_player()
        if local_player == nil or not local_player:is_alive() then
            return nil, nil, nil
        end

        local weapon = local_player:get_player_weapon()
        if weapon == nil then
            return nil, nil, nil
        end

        local x = get_slider_value(ref.offset_x, 25) * 0.1
        local y = get_slider_value(ref.offset_y, 25) * 0.1
        local z = get_slider_value(ref.offset_z, 25) * 0.1
        local scope_down_sight = get_option_state(ref.options, "Scope down sight")

        if get_option_state(ref.options, "Legacy animation") then
            local velocity = local_player.m_vecVelocity
            local velocity_length = 0
            if velocity ~= nil then
                velocity_length = velocity:length()
            end

            local modifier = math.min(1.0, velocity_length / 300)

            if cl_bobup ~= nil then
                cl_bobup:int(0, true)
            end

            if cl_bobamt_lat ~= nil then
                cl_bobamt_lat:float(0, true)
            end

            if cl_bobamt_vert ~= nil then
                cl_bobamt_vert:float(0, true)
            end

            if viewmodel_offset_y ~= nil then
                viewmodel_offset_y:float(y, true)
            end

            if viewmodel_offset_z ~= nil then
                viewmodel_offset_z:float(z, true)
            end

            y = y + math.sin(globals.realtime * 6) * modifier * 0.8
            z = z + math.sin(globals.realtime * 3) * modifier * 0.2
        end

        if scope_down_sight then
            local target_value = local_player.m_bIsScoped == true and 1 or 0
            scope_value = scope_value + (target_value - scope_value) * 0.05

            x = lerp(x, -4.75, scope_value)
            y = lerp(y, -5, scope_value)
            z = lerp(z, -2, scope_value)
        else
            scope_value = 0.0
        end

        if ref_force_viewmodel ~= nil then
            if scope_down_sight then
                ref_force_viewmodel:override(true)
            else
                ref_force_viewmodel:override()
            end
        end

        return x, y, z
    end

    local function on_shutdown()
        shutdown_viewmodel()
    end

    local function on_pre_render()
        local x, y, z = get_viewmodel_offset()
        if x == nil or y == nil or z == nil then
            return
        end

        if viewmodel_offset_x ~= nil then
            viewmodel_offset_x:float(x, true)
        end

        if viewmodel_offset_y ~= nil then
            viewmodel_offset_y:float(y, true)
        end

        if viewmodel_offset_z ~= nil then
            viewmodel_offset_z:float(z, true)
        end
    end

    local function on_pre_render_knife()
        local local_player = entity.get_local_player()
        if local_player == nil then
            return
        end

        local weapon = local_player:get_player_weapon()
        if weapon == nil then
            return
        end

        local weapon_info = weapon:get_weapon_info()
        if weapon_info == nil then
            return
        end

        local weapon_index = weapon:get_weapon_index()
        if weapon_index == nil then
            return
        end

        if old_weapon_index ~= weapon_index then
            old_weapon_index = weapon_index
            update_knife_hand(weapon_info.weapon_type == WEAPONTYPE_KNIFE)
        end
    end

    local function update_event_callbacks(enabled)
        if not enabled then
            shutdown_viewmodel()
            events.pre_render(on_pre_render_knife, false)
        end

        events.shutdown(on_shutdown, enabled)
        events.pre_render(on_pre_render, enabled)
    end

    local callbacks
    do
        local function on_fov(item)
            if item == nil or viewmodel_fov == nil then
                return
            end

            local ok_value, value = pcall(item.get, item)
            if not ok_value or type(value) ~= "number" then
                return
            end

            viewmodel_fov:float(value * 0.1, true)
        end

        local function on_options(item)
            local opposite_knife_hand = get_option_state(item, "Opposite knife hand")
            if not opposite_knife_hand and cl_righthand ~= nil then
                local is_righthand = cl_righthand:string() == "1"
                cl_righthand:int(is_righthand and 1 or 0, false)
            end

            old_weapon_index = 0
            events.pre_render(on_pre_render_knife, opposite_knife_hand)
        end

        local function on_enabled(item)
            local enabled = false
            if item ~= nil then
                local ok_enabled, value = pcall(item.get, item)
                enabled = ok_enabled and value == true
            end

            if enabled then
                if ref.fov ~= nil then
                    ref.fov:set_callback(on_fov, true)
                end

                if ref.options ~= nil then
                    ref.options:set_callback(on_options, true)
                end
            else
                if ref.fov ~= nil then
                    ref.fov:unset_callback(on_fov)
                end

                if ref.options ~= nil then
                    ref.options:unset_callback(on_options)
                end
            end

            update_event_callbacks(enabled)
        end

        if ref.enabled ~= nil then
            ref.enabled:set_callback(on_enabled, true)
        end
    end
end

local visuals_scope_overlay
do
    local ref = {
        enabled = visuals_ref.scope_overlay_enabled,
        color = visuals_ref.scope_overlay_color,
        position = visuals_ref.scope_overlay_position,
        offset = visuals_ref.scope_overlay_offset,
        start_fade = visuals_ref.scope_overlay_start_fade,
    }

    local ANIMATION_SPEED = 40
    local RESOLUTION = 1 / 1080

    local math_floor = math.floor
    local math_clamp = math.clamp
    local alpha = 0.0

    local remove_scope_overlay_ref = ui.find(
        "Visuals",
        "World",
        "Main",
        "Override Zoom",
        "Scope Overlay"
    )

    local function get_ref_number(reference, fallback)
        if reference == nil then
            return fallback
        end

        local ok_value, value = pcall(reference.get, reference)
        if ok_value and type(value) == "number" then
            return value
        end

        return fallback
    end

    local function update_scope_overlay_override(state)
        if remove_scope_overlay_ref == nil then
            return
        end

        if state == true then
            remove_scope_overlay_ref:override("Remove All")
            return
        end

        remove_scope_overlay_ref:override()
    end

    local function draw_linear_gradient(x1, y1, x2, y2, color_from, color_to, horizontal)
        if horizontal then
            if x2 < x1 then
                local temp = x1
                x1 = x2
                x2 = temp

                temp = color_from
                color_from = color_to
                color_to = temp
            end

            render.gradient(
                vector(x1, y1),
                vector(x2, y2),
                color_from,
                color_to,
                color_from,
                color_to
            )
            return
        end

        if y2 < y1 then
            local temp = y1
            y1 = y2
            y2 = temp

            temp = color_from
            color_from = color_to
            color_to = temp
        end

        render.gradient(
            vector(x1, y1),
            vector(x2, y2),
            color_from,
            color_from,
            color_to,
            color_to
        )
    end

    local function draw_new_gradient(x, y, w, h, color_a, color_b, horizontal, fade)
        if horizontal then
            local middle_x = x + w * fade * 0.5
            local end_x = x + w

            draw_linear_gradient(x, y, middle_x, y + h, color_b, color_a, true)
            draw_linear_gradient(middle_x, y, end_x, y + h, color_a, color_b, true)
            return
        end

        local middle_y = y + h * fade * 0.5
        local end_y = y + h

        draw_linear_gradient(x, y, x + w, middle_y, color_b, color_a, false)
        draw_linear_gradient(x, middle_y, x + w, end_y, color_a, color_b, false)
    end

    local function ease_smoothstep(value)
        value = math_clamp(value, 0, 1)
        return value * value * (3 - value * 2)
    end

    local function scale_distance(value, scale)
        local scaled = math_floor(value * scale + 0.5)
        if scaled < 0 then
            return 0
        end

        return scaled
    end

    local function draw_scope_segments(
        center_x,
        center_y,
        vertical_inner,
        vertical_outer,
        horizontal_inner,
        horizontal_outer,
        color_a,
        color_b,
        fade
    )
        local vertical_delta = vertical_outer - vertical_inner
        if vertical_delta > 0 then
            draw_new_gradient(
                center_x,
                center_y - vertical_inner + 1,
                1,
                -vertical_delta,
                color_a,
                color_b,
                false,
                fade
            )
            draw_new_gradient(
                center_x,
                center_y + vertical_inner,
                1,
                vertical_delta,
                color_a,
                color_b,
                false,
                fade
            )
        end

        local horizontal_delta = horizontal_outer - horizontal_inner
        if horizontal_delta > 0 then
            draw_new_gradient(
                center_x - horizontal_inner + 1,
                center_y,
                -horizontal_delta,
                1,
                color_a,
                color_b,
                true,
                fade
            )
            draw_new_gradient(
                center_x + horizontal_inner,
                center_y,
                horizontal_delta,
                1,
                color_a,
                color_b,
                true,
                fade
            )
        end
    end

    local function on_render()
        local local_player = entity.get_local_player()
        if local_player == nil or not local_player:is_alive() then
            alpha = 0.0
            return
        end

        local is_scoped = local_player.m_bIsScoped == true
        alpha = alpha + ((is_scoped and 1 or 0) - alpha) * (1 / ANIMATION_SPEED)
        alpha = math_clamp(alpha, 0, 1)
        if alpha <= 0.001 then
            alpha = 0.0
            return
        end

        local screen_size = render.screen_size()
        if screen_size == nil then
            return
        end

        local center = screen_size * 0.5
        local center_x = math_floor(center.x + 0.5)
        local center_y = math_floor(center.y + 0.5)

        local offset = get_ref_number(ref.offset, 10) * screen_size.y * RESOLUTION
        local position = get_ref_number(ref.position, 105) * screen_size.y * RESOLUTION

        offset = math_floor(offset)
        position = math_floor(position)
        if position < offset + 1 then
            position = offset + 1
        end

        if position - offset <= 0 then
            return
        end

        local vertical_progress = ease_smoothstep(math_clamp(alpha * 1.12, 0, 1))
        local horizontal_progress = ease_smoothstep(math_clamp((alpha - 0.14) / 0.86, 0, 1))
        local animation_progress = vertical_progress
        if horizontal_progress > animation_progress then
            animation_progress = horizontal_progress
        end

        local vertical_inner_scale = 0.10 + vertical_progress * 0.90
        local vertical_outer_scale = vertical_inner_scale
        local horizontal_inner_scale = 0.10 + horizontal_progress * 0.90
        local horizontal_outer_scale = horizontal_inner_scale

        local vertical_inner = scale_distance(offset, vertical_inner_scale)
        local vertical_outer = scale_distance(position, vertical_outer_scale)
        if vertical_outer < vertical_inner + 1 then
            vertical_outer = vertical_inner + 1
        end

        local horizontal_inner = scale_distance(offset, horizontal_inner_scale)
        local horizontal_outer = scale_distance(position, horizontal_outer_scale)
        if horizontal_outer < horizontal_inner + 1 then
            horizontal_outer = horizontal_inner + 1
        end

        local fade = get_ref_number(ref.start_fade, 50) * 0.01 * 2
        fade = math_clamp(fade, 0.0, 1.0)

        local base_color = color(255, 255, 255, 200)
        if ref.color ~= nil then
            local ok_color, value = pcall(ref.color.get, ref.color)
            if ok_color and value ~= nil then
                base_color = value
            end
        end

        local color_a = base_color:clone()
        local color_b = base_color:clone()
        local alpha_scale = animation_progress
        color_a.a = color_a.a * alpha_scale
        color_b.a = 0

        draw_scope_segments(
            center_x,
            center_y,
            vertical_inner,
            vertical_outer,
            horizontal_inner,
            horizontal_outer,
            color_a,
            color_b,
            fade
        )
    end

    local function on_shutdown()
        alpha = 0.0
        update_scope_overlay_override(false)
    end

    local function on_enabled(item)
        local enabled = false
        if item ~= nil then
            local ok_enabled, value = pcall(item.get, item)
            enabled = ok_enabled and value == true
        end

        if enabled ~= true then
            alpha = 0.0
        end

        update_scope_overlay_override(enabled)
        events.render(on_render, enabled)
        events.shutdown(on_shutdown, enabled)
    end

    if ref.enabled ~= nil then
        ref.enabled:set_callback(on_enabled, true)
    end
end

local visuals_local_transparency
do
    local ref = {
        features = visuals_ref.other_features,
        scoped_chams_alpha = visuals_ref.other_features_scoped_chams_alpha,
    }

    local KEEP_LOCAL_TRANSPARENCY = "Keep Local Transparency"
    local SCOPED_CHAMS_FADE = "Scoped Chams Fade"
    local REMOVE_SLEEVES = "Remove Sleeves"
    local REMOVE_ARMS = "Remove Arms"
    local BASE_RESUME_ALPHA = 59
    local MAX_BLEND_TIME = 0.065
    local FULL_BLEND_DELTA = 196
    local SCOPED_CHAMS_BLEND_TIME = 0.22
    local MATERIAL_SCAN_PATH = "models/weapons"
    local VIEWMODEL_MARKER = "v_models"
    local SLEEVE_MARKER = "sleeve"
    local GLOVE_MARKER = "glove"
    local ARMS_MARKER = "arms"
    local HAND_MARKER = "hand"
    local MATERIAL_CHAMS_STYLE = "Material"
    local FIRST_PERSON_PERSPECTIVE = "First Person"
    local SCOPED_WEAPON_COLOR = color(255, 255, 255, 255)

    local transparency_ref = ui.find(
        "Visuals",
        "Players",
        "Self",
        "Chams",
        "Model",
        "Transparency"
    )
    local scoped_chams_ref = {
        weapon_enabled = ui.find(
            "Visuals",
            "Players",
            "Self",
            "Chams",
            "Weapon"
        ),
        weapon_style = ui.find(
            "Visuals",
            "Players",
            "Self",
            "Chams",
            "Weapon",
            "Style"
        ),
        weapon_perspective = ui.find(
            "Visuals",
            "Players",
            "Self",
            "Chams",
            "Weapon",
            "Perspective"
        ),
        weapon_color = ui.find(
            "Visuals",
            "Players",
            "Self",
            "Chams",
            "Weapon",
            "Color"
        ),
        viewmodel_enabled = ui.find(
            "Visuals",
            "Players",
            "Self",
            "Chams",
            "Viewmodel"
        ),
        viewmodel_style = ui.find(
            "Visuals",
            "Players",
            "Self",
            "Chams",
            "Viewmodel",
            "Style"
        ),
        viewmodel_color = ui.find(
            "Visuals",
            "Players",
            "Self",
            "Chams",
            "Viewmodel",
            "Color"
        ),
    }

    local feature_sync = false
    local hidden_materials = {
    }

    local feature_state = {
        remove_sleeves = false,
        remove_arms = false,
    }

    local transparency_state = {
        current_alpha = nil,
        start_alpha = 255,
        target_alpha = 255,
        start_time = 0.0,
        end_time = 0.0,
        thirdperson = false,
    }
    local scoped_chams_state = {
        current_weight = 0.0,
        start_weight = 0.0,
        target_weight = 0.0,
        start_time = 0.0,
        end_time = 0.0,
        applied = false,
    }
    local hidden_materials_applied = false

    local function get_feature_enabled(name)
        if ref.features == nil then
            return false
        end

        local ok_named, named_value = pcall(ref.features.get, ref.features, name)
        if ok_named and type(named_value) == "boolean" then
            return named_value
        end

        local ok_values, values = pcall(ref.features.get, ref.features)
        if not ok_values or type(values) ~= "table" then
            return false
        end

        local options = nil
        local ok_options, option_values = pcall(ref.features.list, ref.features)
        if ok_options and type(option_values) == "table" then
            options = option_values
        end

        for i = 1, #values do
            local value = values[i]
            if value == name then
                return true
            end

            if type(value) == "number" and options ~= nil and options[value] == name then
                return true
            end
        end

        return false
    end

    local function get_feature_options()
        if ref.features == nil then
            return nil
        end

        local ok_options, options = pcall(ref.features.list, ref.features)
        if not ok_options or type(options) ~= "table" then
            return nil
        end

        return options
    end

    local function get_feature_index(name)
        local options = get_feature_options()
        if options == nil then
            return nil
        end

        for index = 1, #options do
            if options[index] == name then
                return index
            end
        end

        return nil
    end

    local function to_index_set(values)
        local selected = {
        }
        local options = get_feature_options()

        if type(values) ~= "table" then
            return selected
        end

        for i = 1, #values do
            local value = values[i]
            if type(value) == "number" then
                selected[value] = true
            elseif type(value) == "string" and options ~= nil then
                for option_index = 1, #options do
                    if options[option_index] == value then
                        selected[option_index] = true
                        break
                    end
                end
            end
        end

        return selected
    end

    local function to_index_array(selected)
        local values = {
        }
        local options = get_feature_options()

        if options == nil then
            return values
        end

        for index = 1, #options do
            if selected[index] == true then
                values[#values + 1] = options[index]
            end
        end

        return values
    end

    local function normalize_feature_selection(values)
        local selected = to_index_set(values)
        local remove_sleeves_index = get_feature_index(REMOVE_SLEEVES)
        local remove_arms_index = get_feature_index(REMOVE_ARMS)

        if remove_sleeves_index == nil or remove_arms_index == nil then
            return selected
        end

        local remove_sleeves_enabled = selected[remove_sleeves_index] == true
        local remove_arms_enabled = selected[remove_arms_index] == true

        if remove_sleeves_enabled and remove_arms_enabled then
            local sleeves_changed = feature_state.remove_sleeves ~= true
            local arms_changed = feature_state.remove_arms ~= true

            if sleeves_changed and not arms_changed then
                selected[remove_arms_index] = nil
            else
                selected[remove_sleeves_index] = nil
            end
        end

        feature_state.remove_sleeves = selected[remove_sleeves_index] == true
        feature_state.remove_arms = selected[remove_arms_index] == true

        return selected
    end

    local function sync_feature_selection()
        if ref.features == nil or feature_sync then
            return
        end

        local normalized = normalize_feature_selection(ref.features:get())

        feature_sync = true
        ref.features:set(to_index_array(normalized))
        feature_sync = false
    end

    local function reset_state(alpha, thirdperson)
        local value = type(alpha) == "number" and alpha or 255
        transparency_state.current_alpha = value
        transparency_state.start_alpha = value
        transparency_state.target_alpha = value
        transparency_state.start_time = 0.0
        transparency_state.end_time = 0.0
        transparency_state.thirdperson = thirdperson == true
    end

    local function reset_scoped_chams_state(weight)
        local value = type(weight) == "number" and weight or 0.0
        scoped_chams_state.current_weight = value
        scoped_chams_state.start_weight = value
        scoped_chams_state.target_weight = value
        scoped_chams_state.start_time = 0.0
        scoped_chams_state.end_time = 0.0
    end

    local function get_in_scope_transparency_enabled()
        if transparency_ref == nil then
            return false
        end

        local ok_value, value = pcall(transparency_ref.get, transparency_ref, "In Scope")
        return ok_value and value == true
    end

    local function get_target_alpha(default_alpha)
        local value = type(default_alpha) == "number" and default_alpha or 255
        local local_player = entity.get_local_player()
        if local_player == nil or not local_player:is_alive() then
            return nil
        end

        if local_player.m_bResumeZoom == true and get_in_scope_transparency_enabled() == true then
            return BASE_RESUME_ALPHA
        end

        return value
    end

    local function get_blended_alpha(now)
        local current_alpha = transparency_state.current_alpha
        if type(current_alpha) ~= "number" then
            return transparency_state.target_alpha
        end

        if now >= transparency_state.end_time then
            transparency_state.current_alpha = transparency_state.target_alpha
            return transparency_state.target_alpha
        end

        local duration = transparency_state.end_time - transparency_state.start_time
        if duration <= 0.0 then
            transparency_state.current_alpha = transparency_state.target_alpha
            return transparency_state.target_alpha
        end

        local t = math.clamp((now - transparency_state.start_time) / duration, 0.0, 1.0)
        local value = transparency_state.start_alpha
            + (transparency_state.target_alpha - transparency_state.start_alpha) * t
        transparency_state.current_alpha = value
        return value
    end

    local function on_localplayer_transparency(default_alpha)
        local local_player = entity.get_local_player()
        if local_player == nil or not local_player:is_alive() then
            return
        end

        local now = globals.curtime
        if type(now) ~= "number" then
            return default_alpha
        end

        local thirdperson = common.is_in_thirdperson() == true
        local target_alpha = get_target_alpha(default_alpha)
        if type(target_alpha) ~= "number" then
            return
        end

        local current_alpha = type(default_alpha) == "number" and default_alpha or 255
        if transparency_state.current_alpha == nil then
            reset_state(current_alpha, thirdperson)
            return current_alpha
        end

        if thirdperson ~= transparency_state.thirdperson
            or now - transparency_state.end_time > 1.0 then
            reset_state(target_alpha, thirdperson)
            return target_alpha
        end

        if target_alpha ~= transparency_state.target_alpha then
            local start_alpha = get_blended_alpha(now)
            local duration = math.map(
                math.abs(target_alpha - start_alpha),
                0,
                FULL_BLEND_DELTA,
                0,
                MAX_BLEND_TIME,
                true
            )

            transparency_state.start_alpha = start_alpha
            transparency_state.target_alpha = target_alpha
            transparency_state.start_time = now
            transparency_state.end_time = now + duration
        end

        return get_blended_alpha(now)
    end

    local function get_scoped_chams_weight(now)
        local current_weight = scoped_chams_state.current_weight
        if type(current_weight) ~= "number" then
            return scoped_chams_state.target_weight
        end

        if now >= scoped_chams_state.end_time then
            scoped_chams_state.current_weight = scoped_chams_state.target_weight
            return scoped_chams_state.target_weight
        end

        local duration = scoped_chams_state.end_time - scoped_chams_state.start_time
        if duration <= 0.0 then
            scoped_chams_state.current_weight = scoped_chams_state.target_weight
            return scoped_chams_state.target_weight
        end

        local t = math.clamp((now - scoped_chams_state.start_time) / duration, 0.0, 1.0)
        t = t * t * (3.0 - 2.0 * t)
        local value = scoped_chams_state.start_weight
            + (scoped_chams_state.target_weight - scoped_chams_state.start_weight) * t
        scoped_chams_state.current_weight = value
        return value
    end

    local function get_scoped_chams_alpha_scale()
        local item = ref.scoped_chams_alpha
        if item == nil then
            return 0.27
        end

        local ok_value, value = pcall(item.get, item)
        if not ok_value or type(value) ~= "number" then
            return 0.27
        end

        return math.clamp(value / 100, 0.0, 1.0)
    end

    local function get_color_alpha(color_value, fallback)
        if color_value == nil then
            return fallback
        end

        local ok_unpack, _, _, _, alpha = pcall(color_value.unpack, color_value)
        if ok_unpack and type(alpha) == "number" then
            return alpha
        end

        local direct_alpha = color_value.a
        if type(direct_alpha) == "number" then
            return direct_alpha
        end

        return fallback
    end

    local function get_faded_color(color_value, weight, fallback_alpha)
        local alpha = math.floor(get_color_alpha(color_value, fallback_alpha) * weight + 0.5)
        alpha = math.clamp(alpha, 0, 255)

        if color_value ~= nil then
            local ok_color, faded_color = pcall(
                color_value.alpha_modulate,
                color_value,
                alpha
            )
            if ok_color and faded_color ~= nil then
                return faded_color
            end
        end

        return color(255, 255, 255, alpha)
    end

    local function get_menu_color(item, fallback)
        if item == nil then
            return fallback
        end

        local ok_color, color_value = pcall(item.get, item)
        if not ok_color or color_value == nil then
            return fallback
        end

        return color_value
    end

    local function clear_scoped_chams_overrides()
        if scoped_chams_state.applied ~= true then
            return
        end

        if scoped_chams_ref.weapon_enabled ~= nil then
            scoped_chams_ref.weapon_enabled:override()
        end

        if scoped_chams_ref.weapon_style ~= nil then
            scoped_chams_ref.weapon_style:override()
        end

        if scoped_chams_ref.weapon_perspective ~= nil then
            scoped_chams_ref.weapon_perspective:override()
        end

        if scoped_chams_ref.weapon_color ~= nil then
            scoped_chams_ref.weapon_color:override()
        end

        if scoped_chams_ref.viewmodel_enabled ~= nil then
            scoped_chams_ref.viewmodel_enabled:override()
        end

        if scoped_chams_ref.viewmodel_style ~= nil then
            scoped_chams_ref.viewmodel_style:override()
        end

        if scoped_chams_ref.viewmodel_color ~= nil then
            scoped_chams_ref.viewmodel_color:override()
        end

        scoped_chams_state.applied = false
    end

    local function apply_scoped_chams(weight)
        local alpha_scale = get_scoped_chams_alpha_scale()
        local total_weight = weight * alpha_scale
        local weapon_color = get_faded_color(SCOPED_WEAPON_COLOR, total_weight, 255)
        local viewmodel_color = get_faded_color(
            get_menu_color(scoped_chams_ref.viewmodel_color, nil),
            total_weight,
            255
        )

        if scoped_chams_ref.weapon_enabled ~= nil then
            scoped_chams_ref.weapon_enabled:override(true)
        end

        if scoped_chams_ref.weapon_style ~= nil then
            scoped_chams_ref.weapon_style:override(MATERIAL_CHAMS_STYLE)
        end

        if scoped_chams_ref.weapon_perspective ~= nil then
            scoped_chams_ref.weapon_perspective:override(FIRST_PERSON_PERSPECTIVE)
        end

        if scoped_chams_ref.weapon_color ~= nil then
            scoped_chams_ref.weapon_color:override(weapon_color)
        end

        if scoped_chams_ref.viewmodel_enabled ~= nil then
            scoped_chams_ref.viewmodel_enabled:override(true)
        end

        if scoped_chams_ref.viewmodel_style ~= nil then
            scoped_chams_ref.viewmodel_style:override(MATERIAL_CHAMS_STYLE)
        end

        if scoped_chams_ref.viewmodel_color ~= nil then
            scoped_chams_ref.viewmodel_color:override(viewmodel_color)
        end

        scoped_chams_state.applied = true
    end

    local function on_scoped_chams_pre_render()
        local now = globals.curtime
        if type(now) ~= "number" then
            clear_scoped_chams_overrides()
            reset_scoped_chams_state(0.0)
            return
        end

        local local_player = entity.get_local_player()
        if local_player == nil or not local_player:is_alive() then
            clear_scoped_chams_overrides()
            reset_scoped_chams_state(0.0)
            return
        end

        local target_weight = local_player.m_bIsScoped == true and 1.0 or 0.0
        if target_weight ~= scoped_chams_state.target_weight then
            local start_weight = get_scoped_chams_weight(now)
            scoped_chams_state.start_weight = start_weight
            scoped_chams_state.target_weight = target_weight
            scoped_chams_state.start_time = now
            scoped_chams_state.end_time = now
                + SCOPED_CHAMS_BLEND_TIME * math.abs(target_weight - start_weight)
        elseif now - scoped_chams_state.end_time > 1.0 then
            reset_scoped_chams_state(target_weight)
        end

        local weight = get_scoped_chams_weight(now)
        if weight <= 0.001 then
            clear_scoped_chams_overrides()
            return
        end

        apply_scoped_chams(weight)
    end

    local function clear_hidden_materials()
        if hidden_materials_applied ~= true and #hidden_materials == 0 then
            return
        end

        for i = 1, #hidden_materials do
            local material = hidden_materials[i]
            if material ~= nil and material:is_valid() then
                material:reset()
            end
        end

        hidden_materials = {
        }
        hidden_materials_applied = false
    end

    local function should_hide_arms_material(material)
        if material == nil or not material:is_valid() then
            return false
        end

        local name = material:get_name()
        if type(name) ~= "string" then
            return false
        end

        if name:find(GLOVE_MARKER, 1, true) ~= nil then
            return false
        end

        if name:find(ARMS_MARKER, 1, true) ~= nil then
            return true
        end

        return name:find(HAND_MARKER, 1, true) ~= nil
    end

    local function apply_hidden_arms_materials()
        clear_hidden_materials()

        materials.get_materials(MATERIAL_SCAN_PATH, true, function(material)
            if not should_hide_arms_material(material) then
                return
            end

            material:alpha_modulate(0)
            hidden_materials[#hidden_materials + 1] = material
        end)

        hidden_materials_applied = true
    end

    local function on_remove_arms_level_init()
        apply_hidden_arms_materials()
    end

    local function on_remove_arms_pre_render()
        local local_player = entity.get_local_player()
        if local_player == nil or not local_player:is_alive() then
            clear_hidden_materials()
            return
        end

        local thirdperson = common.is_in_thirdperson ~= nil
            and common.is_in_thirdperson() == true

        if thirdperson then
            clear_hidden_materials()
            return
        end

        if hidden_materials_applied ~= true then
            apply_hidden_arms_materials()
        end
    end

    local function should_hide_sleeves(ctx)
        if ctx == nil then
            return false
        end

        local name = ctx.name
        if type(name) ~= "string" then
            return false
        end

        if name:find(VIEWMODEL_MARKER, 1, true) == nil then
            return false
        end

        return name:find(SLEEVE_MARKER, 1, true) ~= nil
    end

    local function on_remove_sleeves_draw_model(ctx)
        local local_player = entity.get_local_player()
        if local_player == nil or not local_player:is_alive() then
            return
        end

        if should_hide_sleeves(ctx) then
            return false
        end
    end

    local function on_shutdown()
        clear_scoped_chams_overrides()
        clear_hidden_materials()
    end

    local function update_remove_arms(enabled)
        if enabled ~= true then
            clear_hidden_materials()
        end

        events.level_init(on_remove_arms_level_init, enabled)
        events.pre_render(on_remove_arms_pre_render, enabled)

        if enabled == true then
            on_remove_arms_pre_render()
        end
    end

    local function update_remove_sleeves(enabled)
        events.draw_model(on_remove_sleeves_draw_model, enabled)
    end

    local function update_scoped_chams(enabled)
        if enabled ~= true then
            events.pre_render(on_scoped_chams_pre_render, false)
            clear_scoped_chams_overrides()
            reset_scoped_chams_state(0.0)
            return
        end

        events.pre_render(on_scoped_chams_pre_render, true)
        on_scoped_chams_pre_render()
    end

    local function on_enabled()
        if feature_sync then
            return
        end

        sync_feature_selection()

        local keep_local_transparency_enabled = get_feature_enabled(KEEP_LOCAL_TRANSPARENCY)
        if keep_local_transparency_enabled ~= true then
            reset_state(255, false)
        end

        if events.localplayer_transparency ~= nil then
            events.localplayer_transparency(
                on_localplayer_transparency,
                keep_local_transparency_enabled
            )
        end

        local scoped_chams_enabled = get_feature_enabled(SCOPED_CHAMS_FADE)
        local remove_arms_enabled = get_feature_enabled(REMOVE_ARMS)
        local remove_sleeves_enabled = get_feature_enabled(REMOVE_SLEEVES)

        update_scoped_chams(scoped_chams_enabled)
        update_remove_arms(remove_arms_enabled)
        update_remove_sleeves(remove_sleeves_enabled)
        events.shutdown(
            on_shutdown,
            scoped_chams_enabled or remove_arms_enabled or remove_sleeves_enabled
        )
    end

    if ref.features ~= nil then
        ref.features:set_callback(on_enabled, true)
    end
end

local visuals_model_changer
do
    local ref = {
        enabled = visuals_ref.ct_agent_enabled,
        model = visuals_ref.ct_agent_model,
    }

    local ffi_ok, ffi = pcall(require, "ffi")
    local ffi_ready = ffi_ok and ffi ~= nil

    local find_string_table = nil
    local add_string = nil
    local find_or_load_model = nil
    local get_model_index = nil
    local set_model_index = nil

    if ffi_ready then
        local ok_find_string_table, find_string_table_vfunc = pcall(
            utils.get_vfunc,
            "engine.dll",
            "VEngineClientStringTable001",
            3,
            "void*(__thiscall*)(void*, const char*)"
        )
        if ok_find_string_table then
            find_string_table = find_string_table_vfunc
        end

        local ok_add_string, add_string_vfunc = pcall(
            utils.get_vfunc,
            8,
            "int(__thiscall*)(void*, bool, const char*, int, const void*)"
        )
        if ok_add_string then
            add_string = add_string_vfunc
        end

        local ok_find_or_load_model, find_or_load_model_vfunc = pcall(
            utils.get_vfunc,
            "engine.dll",
            "VModelInfoClient004",
            39,
            "void*(__thiscall*)(void*, const char*)"
        )
        if ok_find_or_load_model then
            find_or_load_model = find_or_load_model_vfunc
        end

        local ok_get_model_index, get_model_index_vfunc = pcall(
            utils.get_vfunc,
            "engine.dll",
            "VModelInfoClient004",
            2,
            "int(__thiscall*)(void*, const char*)"
        )
        if ok_get_model_index then
            get_model_index = get_model_index_vfunc
        end

        local ok_set_model_index, set_model_index_vfunc = pcall(
            utils.get_vfunc,
            75,
            "void(__thiscall*)(void*, int)"
        )
        if ok_set_model_index then
            set_model_index = set_model_index_vfunc
        end
    end

    local cl_ragdoll_physics_enable = cvar.cl_ragdoll_physics_enable
    local FULL_UPDATE_DELAY = 1.00

    local model_applied = false
    local ragdoll_overridden = false
    local ragdoll_restore_value = nil
    local last_model_selection = nil
    local delayed_full_update_at = nil
    local on_delayed_full_update_render = nil

    local function get_selected_agent()
        if ref.model == nil then
            return nil
        end

        local selected_index = ref.model:get()
        if type(selected_index) ~= "number" then
            return nil
        end

        return model_changer_data.ct_agents[selected_index]
    end

    local function restore_ragdoll_physics()
        if not ragdoll_overridden or cl_ragdoll_physics_enable == nil then
            return
        end

        local restore_value = ragdoll_restore_value
        if type(restore_value) ~= "number" then
            restore_value = 1
        end

        cl_ragdoll_physics_enable:int(restore_value)
        ragdoll_restore_value = nil
        ragdoll_overridden = false
    end

    local function clear_delayed_full_update()
        delayed_full_update_at = nil
        events.render(on_delayed_full_update_render, false)
    end

    local function schedule_delayed_full_update()
        local now = globals.realtime
        if type(now) ~= "number" then
            now = 0
        end

        delayed_full_update_at = now + FULL_UPDATE_DELAY
        events.render(on_delayed_full_update_render, true)
    end

    on_delayed_full_update_render = function()
        if type(delayed_full_update_at) ~= "number" then
            events.render(on_delayed_full_update_render, false)
            return
        end

        local now = globals.realtime
        if type(now) ~= "number" or now < delayed_full_update_at then
            return
        end

        delayed_full_update_at = nil
        events.render(on_delayed_full_update_render, false)

        if ref.enabled == nil or ref.enabled:get() ~= true then
            return
        end

        local local_player = entity.get_local_player()
        if local_player == nil or local_player.m_iTeamNum ~= 3 then
            return
        end

        local selected_agent = get_selected_agent()
        if selected_agent == nil then
            return
        end

        common.force_full_update()
    end

    local function disable_ragdoll_physics()
        if cl_ragdoll_physics_enable == nil then
            return
        end

        if not ragdoll_overridden then
            local current_value = cl_ragdoll_physics_enable:int()
            if type(current_value) == "number" then
                ragdoll_restore_value = current_value
            end
        end

        cl_ragdoll_physics_enable:int(0)
        ragdoll_overridden = true
    end

    local function resolve_model_index(model_path)
        if not ffi_ready or get_model_index == nil then
            return nil
        end

        if type(model_path) ~= "string" or model_path == "" then
            return nil
        end

        local ok_index, model_index = pcall(get_model_index, model_path)
        if ok_index and type(model_index) == "number" and model_index ~= -1 then
            return model_index
        end

        if find_string_table == nil or add_string == nil or find_or_load_model == nil then
            return nil
        end

        local ok_table, modelprecache = pcall(find_string_table, "modelprecache")
        if not ok_table or modelprecache == nil then
            return nil
        end

        local modelprecache_ptr = ffi.cast("void***", modelprecache)
        if modelprecache_ptr == nil then
            return nil
        end

        pcall(find_or_load_model, model_path)

        local ok_add = pcall(
            add_string,
            modelprecache_ptr,
            false,
            model_path,
            -1,
            nil
        )
        if not ok_add then
            return nil
        end

        ok_index, model_index = pcall(get_model_index, model_path)
        if not ok_index or type(model_index) ~= "number" or model_index == -1 then
            return nil
        end

        return model_index
    end

    local function reset_model(force_full_update)
        restore_ragdoll_physics()
        clear_delayed_full_update()

        if force_full_update and model_applied then
            common.force_full_update()
        end

        model_applied = false
    end

    local function on_net_update_end()
        local local_player = entity.get_local_player()
        if local_player == nil then
            restore_ragdoll_physics()
            model_applied = false
            return
        end

        if local_player.m_iTeamNum ~= 3 then
            reset_model(model_applied)
            return
        end

        local selected_agent = get_selected_agent()
        if selected_agent == nil then
            reset_model(model_applied)
            return
        end

        local model_index = resolve_model_index(selected_agent.path)
        if type(model_index) ~= "number" then
            return
        end

        if local_player.m_nModelIndex ~= model_index then
            if set_model_index ~= nil then
                local ok_set_model = pcall(set_model_index, local_player[0], model_index)
                if ok_set_model ~= true then
                    local_player.m_nModelIndex = model_index
                end
            else
                local_player.m_nModelIndex = model_index
            end
        end

        disable_ragdoll_physics()
        model_applied = true
    end

    local function on_shutdown()
        reset_model(true)
    end

    local function on_enabled(item)
        local enabled = item ~= nil and item:get() == true
        if not enabled then
            reset_model(true)
        end

        events.net_update_end(on_net_update_end, enabled)
        events.shutdown(on_shutdown, enabled)

        if enabled ~= true then
            return
        end

        model_applied = false

        local local_player = entity.get_local_player()
        if local_player == nil or local_player.m_iTeamNum ~= 3 then
            return
        end

        local selected_agent = get_selected_agent()
        if selected_agent == nil then
            return
        end

        schedule_delayed_full_update()
    end

    if ref.enabled ~= nil then
        ref.enabled:set_callback(on_enabled, true)
    end

    if ref.model ~= nil then
        ref.model:set_callback(function(item)
            if item == nil then
                return
            end

            local selected_index = item:get()
            if type(selected_index) ~= "number" then
                return
            end

            if last_model_selection == nil then
                last_model_selection = selected_index
                return
            end

            if last_model_selection == selected_index then
                return
            end

            last_model_selection = selected_index
            model_applied = false

            if ref.enabled == nil or ref.enabled:get() ~= true then
                return
            end

            local local_player = entity.get_local_player()
            if local_player == nil or local_player.m_iTeamNum ~= 3 then
                return
            end

            schedule_delayed_full_update()
        end, true)
    end
end

local game_focus
do
    local ref = misc_ref.game_focus_enabled

    local MMQUEUE_RESERVED = "reserved"
    local POLL_INTERVAL = 1.0

    local ffi_ok, ffi = pcall(require, "ffi")
    local ffi_ready = ffi_ok and ffi ~= nil
    local winapi_ready = false

    if ffi_ready then
        pcall(ffi.cdef, [[
      void* GetForegroundWindow();
      void* SetForegroundWindow(void* window);
      void* SetFocus(void* window);
      bool ShowWindow(void* window, int state);
    ]])

        local ok_get_foreground = pcall(function()
            return ffi.C.GetForegroundWindow
        end)

        local ok_set_foreground = pcall(function()
            return ffi.C.SetForegroundWindow
        end)

        local ok_set_focus = pcall(function()
            return ffi.C.SetFocus
        end)

        local ok_show_window = pcall(function()
            return ffi.C.ShowWindow
        end)

        winapi_ready = (
            ok_get_foreground
            and ok_set_foreground
            and ok_set_focus
            and ok_show_window
        )
    end

    local check_console_visible = nil
    if ffi_ready then
        local ok_console, console_vfunc = pcall(
            utils.get_vfunc,
            "engine.dll",
            "VEngineClient014",
            11,
            "bool(__thiscall*)(void*)"
        )

        if ok_console then
            check_console_visible = console_vfunc
        end
    end

    local hwnd_ptr = nil
    local last_mmqueue_state = nil
    local next_poll_time = 0

    local function is_console_open()
        if check_console_visible == nil then
            return false
        end

        local ok_visible, is_visible = pcall(check_console_visible)
        return ok_visible and is_visible == true
    end

    local function get_mmqueue_state()
        local party_api = panorama.PartyListAPI
        if party_api == nil then
            return nil
        end

        local ok_state, state = pcall(
            party_api.GetPartySessionSetting,
            "game/mmqueue"
        )
        if not ok_state then
            return nil
        end

        if type(state) ~= "string" then
            return nil
        end

        return state
    end

    local function resolve_game_hwnd()
        if not ffi_ready or not winapi_ready then
            return nil
        end

        if hwnd_ptr ~= nil then
            local ok_hwnd, hwnd = pcall(function()
                return hwnd_ptr[0]
            end)

            if ok_hwnd and hwnd ~= nil then
                return hwnd
            end

            hwnd_ptr = nil
        end

        local signature = utils.opcode_scan(
            "engine.dll",
            "8B 0D ? ? ? ? 85 C9 74 16 8B 01 8B",
            2
        )
        if signature == nil then
            return nil
        end

        local ok_ptr, ptr = pcall(function()
            local engine_client = ffi.cast("void***", signature)
            if engine_client == nil then
                return nil
            end

            local first_level = engine_client[0]
            if first_level == nil then
                return nil
            end

            local engine_base = first_level[0]
            if engine_base == nil then
                return nil
            end

            return ffi.cast(
                "void**",
                ffi.cast("char*", engine_base) + 8
            )
        end)

        if not ok_ptr or ptr == nil then
            return nil
        end

        hwnd_ptr = ptr
        return hwnd_ptr[0]
    end

    local function focus_game_window()
        if not ffi_ready or not winapi_ready then
            return false
        end

        local hwnd = resolve_game_hwnd()
        if hwnd == nil then
            return false
        end

        local ok_foreground, foreground = pcall(ffi.C.GetForegroundWindow)
        if not ok_foreground or foreground == nil then
            return false
        end

        if foreground == hwnd then
            return false
        end

        pcall(ffi.C.ShowWindow, hwnd, 6)
        pcall(ffi.C.ShowWindow, hwnd, 9)
        pcall(ffi.C.SetForegroundWindow, hwnd)
        pcall(ffi.C.SetFocus, hwnd)

        if is_console_open() and cvar.toggleconsole ~= nil then
            cvar.toggleconsole:call()
        end

        return true
    end

    local function on_render()
        if globals.realtime < next_poll_time then
            return
        end

        next_poll_time = globals.realtime + POLL_INTERVAL

        local mmqueue_state = get_mmqueue_state()
        if mmqueue_state == nil then
            return
        end

        if mmqueue_state ~= last_mmqueue_state then
            if mmqueue_state == MMQUEUE_RESERVED then
                focus_game_window()
            end

            last_mmqueue_state = mmqueue_state
        end
    end

    local function on_round_start()
        local local_player = entity.get_local_player()
        if local_player == nil then
            return
        end

        local game_rules = entity.get_game_rules()
        if game_rules == nil then
            return
        end

        if game_rules.m_bWarmupPeriod == true then
            return
        end

        local team = local_player.m_iTeamNum
        if team ~= 2 and team ~= 3 then
            return
        end

        focus_game_window()
    end

    local callbacks
    do
        local function on_enabled(item)
            local enabled = false
            if item ~= nil then
                local ok_enabled, value = pcall(item.get, item)
                enabled = ok_enabled and value == true
            end

            next_poll_time = 0
            last_mmqueue_state = nil

            events.render(on_render, enabled)
            events.round_start(on_round_start, enabled)
        end

        if ref ~= nil then
            ref:set_callback(on_enabled, true)
        end
    end
end

local weapons
do
    local ref = {
        super_toss_enabled = weapons_ref.super_toss_enabled,
        better_interactions_enabled = weapons_ref.better_interactions_enabled,
        quick_switch_enabled = weapons_ref.quick_switch_enabled,
        grenade_release_enabled = weapons_ref.grenade_release_enabled,
        grenade_release_he_damage = weapons_ref.grenade_release_he_damage,
        grenade_release_molotov_range = weapons_ref.grenade_release_molotov_range,
        grenade_release_predict_molotov = weapons_ref.grenade_release_predict_molotov,
    }

    local grenade_release = { unlock_tick = 0 }
    local super_toss = {}
    local better_interactions = {
        bombsite_use_suppressed = false,
        hostage_use_ticks = 0,
        is_use_aa_overridden = false,
    }
    local quick_switch = {}
    local on_grenade_override_view = nil

    local function is_enabled(item)
        if item == nil then
            return false
        end

        local ok_enabled, value = pcall(item.get, item)
        return ok_enabled and value == true
    end

    local function get_slider_value(item, fallback)
        if item == nil then
            return fallback
        end

        local ok_value, value = pcall(item.get, item)
        if not ok_value or type(value) ~= 'number' then
            return fallback
        end

        return value
    end

    local function get_predict_molotov_enabled()
        if ref.grenade_release_predict_molotov == nil then
            return true
        end

        local ok_enabled, enabled = pcall(
            ref.grenade_release_predict_molotov.get,
            ref.grenade_release_predict_molotov
        )

        if not ok_enabled then
            return true
        end

        return enabled == true
    end

    local menu = {
        enabled_item = {
            get = function()
                return is_enabled(ref.grenade_release_enabled)
            end,
        },
        he_damage_item = {
            get = function()
                return get_slider_value(ref.grenade_release_he_damage, 25)
            end,
        },
        molotov_range_item = {
            get = function()
                return get_slider_value(ref.grenade_release_molotov_range, 10)
            end,
        },
        pin_pulled_only_item = {
            get = function()
                return true
            end,
        },
        predict_molotov_item = {
            get = function()
                return get_predict_molotov_enabled()
            end,
        },
        super_toss_item = {
            get = function()
                return is_enabled(ref.super_toss_enabled)
            end,
        },
        quick_switch_item = {
            get = function()
                return is_enabled(ref.quick_switch_enabled)
            end,
        },
        better_interactions_item = {
            get = function()
                return is_enabled(ref.better_interactions_enabled)
            end,
        },
    }
    local neverlose = {}
    do
        neverlose = {
            air_strafe = ui.find('Miscellaneous', 'Main', 'Movement', 'Air Strafe'),
            air_duck = ui.find('Miscellaneous', 'Main', 'Movement', 'Air Duck'),
            quick_stop = ui.find('Miscellaneous', 'Main', 'Movement', 'Quick Stop'),
            strafe_assist = ui.find('Miscellaneous', 'Main', 'Movement', 'Strafe Assist'),
            slow_walk = ui.find('Aimbot', 'Anti Aim', 'Misc', 'Slow Walk'),
        }
    end

    local debug_render = {}
    do
        local is_debug_enabled = false
        local render_enabled = false

        debug_render.list = {}

        function debug_render.add_line(vector1, vector2, line_color)
            if is_debug_enabled ~= true then
                return
            end

            debug_render.list[#debug_render.list + 1] = {
                type = 'line',
                vector1 = vector1:clone(),
                vector2 = vector2:clone(),
                color = line_color:clone(),
                add_time = globals.realtime,
            }
        end

        function debug_render.add_radius(position, radius, line_color)
            if is_debug_enabled ~= true then
                return
            end

            debug_render.list[#debug_render.list + 1] = {
                type = 'radius',
                vector1 = position:clone(),
                radius = radius,
                color = line_color:clone(),
                add_time = globals.realtime,
            }
        end

        local function on_render()
            if is_debug_enabled ~= true then
                return
            end

            for i = #debug_render.list, 1, -1 do
                local item = debug_render.list[i]

                if globals.realtime - item.add_time > globals.frametime then
                    table.remove(debug_render.list, i)
                    goto continue
                end

                if item.type == 'line' then
                    render.line(render.world_to_screen(item.vector1), render.world_to_screen(item.vector2), item.color)
                elseif item.type == 'radius' then
                    render.circle_3d_outline(item.vector1, item.color, item.radius, 0, 1)
                end

                ::continue::
            end
        end

        local function set_render_callback(state)
            local enabled = state == true
            if render_enabled == enabled then
                return
            end

            events.render(on_render, enabled)
            render_enabled = enabled
        end

        function debug_render.set_enabled(state)
            is_debug_enabled = state == true

            if is_debug_enabled ~= true then
                debug_render.list = {}
            end

            set_render_callback(is_debug_enabled)
        end

        debug_render.set_enabled(is_debug_enabled)

        function debug_render.print(...)
            if is_debug_enabled ~= true then
                return
            end

            print_dev(...)
        end
    end

    do
        local FL_ONGROUND = 1
        local bit_band = bit.band
        local HOSTAGE_PICKUP_DISTANCE = 80

        local function is_button_down(value)
            if value == true then
                return true
            end

            return type(value) == 'number' and value ~= 0
        end

        local function can_force_bomb_plant(command, local_player)
            if local_player.m_bInBombZone ~= true then
                return false
            end

            local flags = local_player.m_fFlags
            if type(flags) ~= 'number' then
                return false
            end

            if bit_band(flags, FL_ONGROUND) == 0 then
                return false
            end

            if is_button_down(command.in_jump) then
                return false
            end

            local anim_state = local_player:get_anim_state()
            if anim_state ~= nil and anim_state.landed_on_ground_this_frame == true then
                return false
            end

            return true
        end

        local function has_c4_in_inventory(local_player)
            local resource = entity.get_player_resource()
            if resource == nil then
                return false
            end

            local carrier_index = resource.m_iPlayerC4
            if type(carrier_index) ~= 'number' then
                return false
            end

            if carrier_index == 0 then
                return false
            end

            local local_index = local_player:get_index()
            if carrier_index == local_index then
                return true
            end

            local carrier = entity.get(carrier_index)
            if carrier == nil then
                return false
            end

            return carrier:get_index() == local_index
        end

        local function set_use_aa_override(state)
            local should_override = state == true
            is_bombsite_efix_aa_override_active = should_override
            if should_override == better_interactions.is_use_aa_overridden then
                return
            end

            if should_override then
                nl.aa.angles.pitch:override("Disabled")
                nl.aa.angles.yaw:override("Disabled")
                nl.aa.angles.body_yaw:override(true)
                nl.aa.angles.left_limit:override(0)
                nl.aa.angles.right_limit:override(0)
            else
                nl.aa.angles.pitch:override()
                nl.aa.angles.yaw:override()
                nl.aa.angles.body_yaw:override()
                nl.aa.angles.left_limit:override()
                nl.aa.angles.right_limit:override()
            end

            better_interactions.is_use_aa_overridden = should_override
        end

        local function apply_bombsite_efix(command, local_player, weapon)
            local team = local_player.m_iTeamNum
            if team ~= 2 then
                better_interactions.bombsite_use_suppressed = false
                return false
            end

            local is_use_pressed = is_button_down(command.in_use)
            local is_attack_pressed = is_button_down(command.in_attack)
            if is_use_pressed ~= true and is_attack_pressed ~= true then
                better_interactions.bombsite_use_suppressed = false
                return false
            end

            if local_player.m_bInBombZone ~= true then
                better_interactions.bombsite_use_suppressed = false
                return false
            end

            if better_interactions.bombsite_use_suppressed == true
                and is_attack_pressed ~= true then
                command.in_use = false
                command.in_attack = false
                return true
            end

            if weapon:get_classname() ~= 'CC4' then
                if is_use_pressed == true and has_c4_in_inventory(local_player) == true then
                    better_interactions.bombsite_use_suppressed = true
                    command.in_use = false
                    return true
                end

                better_interactions.bombsite_use_suppressed = false
                return false
            end

            if better_interactions.bombsite_use_suppressed == true
                and is_attack_pressed ~= true then
                command.in_use = false
                command.in_attack = false
                return true
            end

            better_interactions.bombsite_use_suppressed = false
            local should_plant = can_force_bomb_plant(command, local_player)
            command.in_use = should_plant
            command.in_attack = should_plant
            return false
        end

        local function get_nearest_hostage_angles(local_player)
            if local_player.m_iTeamNum ~= 3 then
                return nil
            end

            if local_player.m_hCarriedHostage ~= nil then
                return nil
            end

            local eye_position = local_player:get_eye_position()
            if eye_position == nil then
                return nil
            end

            local nearest_hostage = nil
            local nearest_distance = HOSTAGE_PICKUP_DISTANCE

            entity.get_entities('CHostage', false, function(hostage)
                if hostage == nil then
                    return
                end

                local hostage_origin = hostage:get_origin()
                if hostage_origin == nil then
                    return
                end

                local distance = eye_position:dist(hostage_origin)
                if distance > nearest_distance then
                    return
                end

                nearest_distance = distance
                nearest_hostage = hostage
            end)

            if nearest_hostage == nil then
                return nil
            end

            local hostage_origin = nearest_hostage:get_origin()
            if hostage_origin == nil then
                return nil
            end

            return eye_position:to(hostage_origin):angles()
        end

        local function apply_hostage_assist(command, local_player)
            if is_button_down(command.in_use) ~= true then
                better_interactions.hostage_use_ticks = 0
                return
            end

            local hostage_angles = get_nearest_hostage_angles(local_player)
            if hostage_angles == nil then
                better_interactions.hostage_use_ticks = 0
                return
            end

            better_interactions.hostage_use_ticks = better_interactions.hostage_use_ticks + 1

            command.view_angles = hostage_angles

            if better_interactions.hostage_use_ticks == 1 then
                command.in_use = false
                return
            end

            command.in_use = true
        end

        function better_interactions.on_createmove(command)
            local local_player = entity.get_local_player()
            if local_player == nil then
                set_use_aa_override(false)
                better_interactions.bombsite_use_suppressed = false
                better_interactions.hostage_use_ticks = 0
                return
            end

            if local_player:is_alive() ~= true then
                set_use_aa_override(false)
                better_interactions.bombsite_use_suppressed = false
                better_interactions.hostage_use_ticks = 0
                return
            end

            local weapon = local_player:get_player_weapon()
            if weapon == nil then
                set_use_aa_override(false)
                better_interactions.bombsite_use_suppressed = false
                better_interactions.hostage_use_ticks = 0
                return
            end

            local is_use_suppressed = apply_bombsite_efix(command, local_player, weapon)
            set_use_aa_override(is_use_suppressed)
            apply_hostage_assist(command, local_player)
        end

        function better_interactions.reset_state()
            set_use_aa_override(false)
            better_interactions.bombsite_use_suppressed = false
            better_interactions.hostage_use_ticks = 0
        end
    end

    do
        local weapon_actions = nl.misc.main.other.weapon_actions
        local quick_switch_index = nil
        local is_updating = false
        local callback_set = false
        local on_weapon_actions = nil

        local function find_quick_switch_index()
            if weapon_actions == nil then
                return nil
            end

            local list = weapon_actions:list()
            if list == nil then
                return nil
            end

            for i = 1, #list do
                if list[i] == 'Quick Switch' then
                    return i
                end
            end

            return nil
        end

        local function is_me(userid)
            local me = entity.get_local_player()
            if me == nil then
                return false
            end

            local player = entity.get(userid, true)
            if player == nil then
                return false
            end

            return player == me
        end

        local function switch_back()
            utils.console_exec('slot3; slot2; slot1')
        end

        local function apply_weapon_actions_override(enabled)
            if weapon_actions == nil then
                return
            end

            if enabled ~= true then
                weapon_actions:override()
                return
            end

            local item_type = weapon_actions:type()
            if item_type ~= 'listable' and item_type ~= 'selectable' then
                weapon_actions:override()
                return
            end

            local value = weapon_actions:get()
            if type(value) ~= 'table' then
                weapon_actions:override()
                return
            end

            if #value == 0 then
                weapon_actions:override({})
                return
            end

            local filtered = {}
            local count = 0

            if type(value[1]) == 'string' then
                for i = 1, #value do
                    local v = value[i]
                    if v == 'Quick Switch' then
                        goto continue
                    end

                    count = count + 1
                    filtered[count] = v

                    ::continue::
                end

                weapon_actions:override(filtered)
                return
            end

            local index = quick_switch_index
            if index == nil then
                index = find_quick_switch_index()
                quick_switch_index = index
            end

            if index == nil then
                weapon_actions:override()
                return
            end

            for i = 1, #value do
                local v = value[i]
                if v == index then
                    goto continue
                end

                count = count + 1
                filtered[count] = v

                ::continue::
            end

            weapon_actions:override(filtered)
        end

        on_weapon_actions = function()
            if menu.quick_switch_item:get() ~= true then
                return
            end

            if is_updating == true then
                return
            end

            is_updating = true
            apply_weapon_actions_override(true)
            is_updating = false
        end

        local function set_weapon_actions_callback(enabled)
            if weapon_actions == nil then
                callback_set = false
                return
            end

            if enabled == callback_set then
                return
            end

            if enabled then
                weapon_actions:set_callback(on_weapon_actions)
            else
                weapon_actions:unset_callback(on_weapon_actions)
            end

            callback_set = enabled
        end

        function quick_switch.on_grenade_thrown(e)
            if menu.quick_switch_item:get() ~= true then
                return
            end

            if e == nil or is_me(e.userid) ~= true then
                return
            end

            utils.execute_after(globals.tickinterval, switch_back)
        end

        function quick_switch.on_weapon_fire(e)
            if menu.quick_switch_item:get() ~= true then
                return
            end

            if e == nil or is_me(e.userid) ~= true then
                return
            end

            local weapon = e.weapon
            if weapon ~= 'weapon_taser' and weapon ~= 'taser' then
                return
            end

            if cvar.sv_infinite_ammo ~= nil and cvar.sv_infinite_ammo:int() == 1 then
                return
            end

            switch_back()
        end

        function quick_switch.on_shutdown()
            apply_weapon_actions_override(false)
        end

        function quick_switch.set_enabled(enabled)
            apply_weapon_actions_override(enabled)
            set_weapon_actions_callback(enabled)
        end

        function quick_switch.reset_state()
            set_weapon_actions_callback(false)
            apply_weapon_actions_override(false)
        end
    end

    do
        super_toss.is_enabled = false

        local ui_air_strafe = neverlose.air_strafe
        local ui_strafe_assist = neverlose.strafe_assist
        local is_ui_overridden = false

        local function restore_movement_overrides()
            if ui_air_strafe ~= nil then
                ui_air_strafe:override()
            end

            if ui_strafe_assist ~= nil then
                ui_strafe_assist:override()
            end

            is_ui_overridden = false
            grenade_throw_state.set_super_toss_active(false)
        end

        local function disable_movement_overrides()
            if ui_air_strafe ~= nil then
                ui_air_strafe:override(false)
            end

            if ui_strafe_assist ~= nil then
                ui_strafe_assist:override(false)
            end

            is_ui_overridden = true
            grenade_throw_state.set_super_toss_active(true)
        end

        local function resolve_grenade_throw(target_angles, base_velocity, power, current_velocity)
            local dir = vector():angles(target_angles)
            local player_vel = current_velocity * 1.25

            local throw_vel = math.clamp(base_velocity * 0.9, 15, 750)
            local power_scale = math.clamp(power, 0, 1) * 0.7 + 0.3
            local speed = throw_vel * power_scale

            local perp = player_vel - dir * dir:dot(player_vel)
            local perp_len2 = perp:lengthsqr()

            if perp_len2 < speed * speed then
                local forward = dir * math.sqrt(speed * speed - perp_len2) - perp
                return forward:normalized():angles()
            end


            local forward = (dir * 0.001 - perp):normalized()
            local t = 1 - (speed * speed) / perp_len2
            forward = forward:lerp(dir, t)
            return forward:normalized():angles()
        end
        super_toss.resolve_grenade_throw = resolve_grenade_throw

        on_grenade_override_view = function(grenade)
            if super_toss.is_enabled ~= true then
                return
            end

            local local_player = entity.get_local_player()
            if local_player == nil then
                return
            end

            local weapon = local_player:get_player_weapon()
            if weapon == nil then
                return
            end

            local weapon_info = weapon:get_weapon_info()
            if weapon_info == nil then
                return
            end

            grenade.angles = resolve_grenade_throw(grenade.angles, weapon_info.throw_velocity, weapon.m_flThrowStrength,
                grenade.velocity)
        end

        function super_toss.on_createmove(command)
            if is_ui_overridden == true then
                restore_movement_overrides()
            end

            if super_toss.is_enabled ~= true then
                return
            end

            local local_player = entity.get_local_player()
            if local_player == nil then
                return
            end
            if local_player:is_alive() ~= true then
                return
            end

            local weapon = local_player:get_player_weapon()
            if weapon == nil then
                return
            end

            local weapon_info = weapon:get_weapon_info()
            if weapon_info == nil then
                return
            end
            if weapon_info.weapon_type ~= 9 then
                return
            end

            local throw_time_threshold = 0.1 * rage.exploit:get()
            local throw_time = weapon.m_fThrowTime
            local is_throw_window = (
                throw_time > 0
                and throw_time - throw_time_threshold <= globals.curtime
            )

            if grenade_release.unlock_tick <= globals.tickcount then
                if command.jitter_move ~= true then
                    return
                end
            end

            if is_throw_window ~= true then
                return
            end

            disable_movement_overrides()

            local simulated_local_player = local_player:simulate_movement()
            simulated_local_player:think()

            local simulated_velocity = simulated_local_player.velocity
            if local_player.m_MoveType == 9 then
                command.in_moveleft = 0
                command.in_moveright = 0
                command.in_forward = 0
                command.in_back = 0
                simulated_velocity = vector(0, 0, 0)
            end

            command.view_angles = resolve_grenade_throw(command.view_angles, weapon_info.throw_velocity,
                weapon.m_flThrowStrength, simulated_velocity)
        end

        function super_toss.reset_state()
            super_toss.is_enabled = false

            if is_ui_overridden ~= true then
                grenade_throw_state.set_super_toss_active(false)
                return
            end

            restore_movement_overrides()
        end
    end

    do
        grenade_release.is_ui_locked = false
        grenade_release.locked_command = {}
        grenade_release.unlock_tick = 0
        grenade_throw_state.set_grenade_release_active(false)

        function grenade_release.lock_command(command, extrapolation_amount)
            neverlose.air_strafe:override(false)
            neverlose.air_duck:override(false)
            neverlose.quick_stop:override(false)
            neverlose.strafe_assist:override(false)
            neverlose.slow_walk:override(false)
            grenade_throw_state.set_grenade_release_active(true)

            grenade_release.is_ui_locked = true

            command.jitter_move = false
            command.in_attack = false
            command.in_attack2 = false
            command.in_moveleft = false
            command.in_moveright = false
            command.in_forward = false
            command.in_back = false

            local locked_command = grenade_release.locked_command
            locked_command.view_angles = command.view_angles:clone()
            locked_command.move_yaw = command.move_yaw
            locked_command.forwardmove = command.forwardmove
            locked_command.sidemove = command.sidemove
            locked_command.upmove = command.upmove
            locked_command.in_jump = command.in_jump
            locked_command.in_duck = command.in_duck
            locked_command.in_walk = command.in_walk
            locked_command.in_speed = command.in_speed
            locked_command.in_left = command.in_left
            locked_command.in_right = command.in_right
            locked_command.in_bullrush = command.in_bullrush

            local lock_ticks = math.clamp(extrapolation_amount, 1, 2)
            grenade_release.unlock_tick = globals.tickcount + lock_ticks
        end

        function grenade_release.handle_command_lock(command)
            if grenade_release.unlock_tick <= globals.tickcount then
                if grenade_release.is_ui_locked == true then
                    neverlose.air_strafe:override()
                    neverlose.air_duck:override()
                    neverlose.quick_stop:override()
                    neverlose.strafe_assist:override()
                    neverlose.slow_walk:override()
                    grenade_throw_state.set_grenade_release_active(false)

                    grenade_release.is_ui_locked = false
                end

                return
            end

            neverlose.air_strafe:override(false)
            neverlose.air_duck:override(false)
            neverlose.quick_stop:override(false)
            neverlose.strafe_assist:override(false)
            neverlose.slow_walk:override(false)
            grenade_throw_state.set_grenade_release_active(true)

            local locked_command = grenade_release.locked_command
            command.jitter_move = false
            command.view_angles = locked_command.view_angles:clone()
            command.move_yaw = locked_command.move_yaw
            command.forwardmove = locked_command.forwardmove
            command.sidemove = locked_command.sidemove
            command.upmove = locked_command.upmove
            command.in_attack = false
            command.in_attack2 = false
            command.in_jump = locked_command.in_jump
            command.in_duck = locked_command.in_duck
            command.in_walk = locked_command.in_walk
            command.in_speed = locked_command.in_speed
            command.in_moveleft = false
            command.in_moveright = false
            command.in_forward = false
            command.in_back = false
            command.in_left = locked_command.in_left
            command.in_right = locked_command.in_right
            command.in_bullrush = locked_command.in_bullrush
        end

        grenade_release.is_weapon_allowed = {
            [44] = function()
                return menu.he_damage_item:get() > 0
            end,
            [45] = function()
                return menu.predict_molotov_item:get() == true
            end,
            [46] = function()
                return menu.molotov_range_item:get() > 0
            end,
        }

        local TRACE_MASK = 0x208400B
        local SMOKE_RADIUS_SQR = 44100
        local SMOKE_LIFETIME_TICKS = 1112
        local SMOKE_HEIGHT_MIN = -64
        local SMOKE_HEIGHT_MAX = 120
        local SMOKE_BASE_RADIUS = 22500
        local SMOKE_HEIGHT_UPPER = 72
        local SMOKE_HEIGHT_LOWER = 18
        local SMOKE_UPPER_COEF = 5.42534722222
        local SMOKE_LOWER_COEF = 0.90957763236
        local SMOKE_DETONATE_TIME_FALLBACK = 1.5
        local SMOKE_DETONATE_CHECK = 0.2
        local SMOKE_EXTINGUISH_RADIUS = 512
        local SMOKE_EXTINGUISH_RADIUS_SQR = SMOKE_EXTINGUISH_RADIUS * SMOKE_EXTINGUISH_RADIUS
        local SMOKE_GRENADE_RADIUS = 166
        local SMOKE_GRENADE_RADIUS_SQR = SMOKE_GRENADE_RADIUS * SMOKE_GRENADE_RADIUS
        local SMOKE_GRENADE_RADIUS_RANGE_SQR = (SMOKE_GRENADE_RADIUS * 4) ^ 2
        local SMOKE_DROP_DISTANCE = SMOKE_GRENADE_RADIUS
        local FIRE_HALF_WIDTH = 30
        local FIRE_FULL_HEIGHT = 80
        local FIRE_CENTER_OFFSET = FIRE_FULL_HEIGHT * 0.5
        local FIRE_UP_TO_SMOKE_HEIGHT = 2 * FIRE_HALF_WIDTH + 4
        local FIRE_EXTINGUISH_RADIUS = FIRE_HALF_WIDTH * 2
        local FIRE_EXTINGUISH_RADIUS_SQR = FIRE_EXTINGUISH_RADIUS * FIRE_EXTINGUISH_RADIUS
        local SMOKE_AFFECT_Z = 120
        local SMOKE_XY_TOP = 100
        local SMOKE_XY_EQUATOR = 150
        local SMOKE_XY_BOTTOM = 128
        local SMOKE_FULL_SAFETY_MARGIN = 0
        local SMOKE_INFERNO_MARGIN = 16
        local SMOKE_WARNING_MARGIN = 20
        local MOLOTOV_PREDICT_MIN_SPEED_SQR = 1
        local MOLLY_TARGET_RADIUS = 90
        local MOLLY_TARGET_RADIUS_SQR = MOLLY_TARGET_RADIUS * MOLLY_TARGET_RADIUS
        local MOLLY_TARGET_Z_MIN = -60
        local MOLLY_TARGET_Z_MAX = 120
        local INFERNO_LIFETIME_FALLBACK = 7
        local function trace_filter(ent)
            return not ent:is_player()
        end

        local cache = {
            tick = -1,
            infernos = nil,
            smokes = nil,
            inferno_points = nil,
        }

        local molotov_prediction = {
            tick = -1,
            origins = {},
            history = {},
        }
        local molotov_warning = { list = {} }

        local function reset_cache()
            cache.tick = globals.tickcount
            cache.infernos = nil
            cache.smokes = nil
            cache.inferno_points = nil
        end

        local function ensure_cache()
            if cache.tick == globals.tickcount then
                return
            end

            reset_cache()
        end

        local function on_level_init()
            grenade_release.unlock_tick = 0
            reset_cache()
            molotov_prediction.tick = -1
            molotov_prediction.origins = {}
            molotov_prediction.history = {}
            molotov_warning.list = {}
        end

        local function get_infernos()
            ensure_cache()

            if cache.infernos == nil then
                cache.infernos = entity.get_entities('CInferno')
            end

            return cache.infernos
        end

        local function build_inferno_points(inferno)
            local origin = inferno.m_vecOrigin
            if origin == nil then
                return {}
            end

            local fire_count = inferno.m_fireCount
            local fire_x_delta = inferno.m_fireXDelta
            local fire_y_delta = inferno.m_fireYDelta
            local fire_z_delta = inferno.m_fireZDelta
            local fire_burning = inferno.m_bFireIsBurning

            if type(fire_count) ~= 'number' or fire_count <= 0 then
                return { origin }
            end

            local has_deltas = fire_x_delta ~= nil and fire_y_delta ~= nil and fire_z_delta ~= nil
            if has_deltas ~= true then
                return { origin }
            end

            local points = {}
            for i = 0, fire_count - 1 do
                local is_burning = true
                if fire_burning ~= nil then
                    local ok, result = pcall(function()
                        return fire_burning[i]
                    end)
                    if ok and result == false then
                        is_burning = false
                    end
                end

                if is_burning == true then
                    local value_x, value_y, value_z = nil, nil, nil
                    local ok_x, result_x = pcall(function()
                        return fire_x_delta[i]
                    end)
                    local ok_y, result_y = pcall(function()
                        return fire_y_delta[i]
                    end)
                    local ok_z, result_z = pcall(function()
                        return fire_z_delta[i]
                    end)

                    if ok_x and ok_y and ok_z then
                        value_x = result_x
                        value_y = result_y
                        value_z = result_z
                    end

                    if type(value_x) == 'number' and type(value_y) == 'number' and type(value_z) == 'number' then
                        points[#points + 1] = origin + vector(value_x, value_y, value_z)
                    end
                end
            end

            if #points == 0 then
                points[1] = origin
            end

            return points
        end

        local function get_inferno_points()
            ensure_cache()

            if cache.inferno_points ~= nil then
                return cache.inferno_points
            end

            local infernos = get_infernos()
            local points_list = {}
            for i = 1, #infernos do
                points_list[i] = build_inferno_points(infernos[i])
            end

            cache.inferno_points = points_list

            return points_list
        end

        local function get_smokes()
            ensure_cache()

            if cache.smokes == nil then
                local smokes = {}

                entity.get_entities('CSmokeGrenadeProjectile', true, function(smoke)
                    local effect_tick = smoke.m_nSmokeEffectTickBegin
                    if effect_tick ~= nil and effect_tick > 0 then
                        smokes[#smokes + 1] = smoke
                    end
                end)

                cache.smokes = smokes
            end

            return cache.smokes
        end

        local function get_predicted_server_tick()
            return math.floor(globals.client_tick + globals.clock_offset + 0.5)
        end

        local function predict_molotov_position(origin, velocity)
            local gravity = cvar['sv_gravity']:float() * 0.4
            local max_flight_time = cvar['molotov_throw_detonate_time']:float()
            local max_detonate_slope = math.cos(math.rad(cvar['weapon_molotov_maxdetonateslope']:float()))

            local position = origin:clone()
            local vel = velocity:clone()

            local tickinterval = globals.tickinterval
            local max_ticks = math.min(256, math.floor(max_flight_time / tickinterval + 1.5))

            for _ = 1, max_ticks do
                local move = vel * tickinterval

                local new_velocity_z = vel.z - gravity * tickinterval
                move.z = (vel.z + new_velocity_z) / 2 * tickinterval
                vel.z = new_velocity_z

                local new_position = position + move

                local trace = utils.trace_hull(position, new_position, vector(-2, -2, -2), vector(2, 2, 2), trace_filter,
                    TRACE_MASK)

                if trace.fraction < 1 then
                    local plane_normal = trace.plane.normal

                    if plane_normal.z > max_detonate_slope then
                        position:init(trace.end_pos:unpack())
                        break
                    end

                    vel = vel - plane_normal * vel:dot(plane_normal) * 2

                    if math.abs(vel.x) < 0.1 then
                        vel.x = 0
                    end
                    if math.abs(vel.y) < 0.1 then
                        vel.y = 0
                    end
                    if math.abs(vel.z) < 0.1 then
                        vel.z = 0
                    end

                    vel = vel * 0.45

                    local speed = vel:lengthsqr()

                    if plane_normal.z > 0.7 and speed > 96000 then
                        local deduct = vel:normalized():dot(plane_normal)

                        if deduct > 0.5 then
                            vel = vel * (1.5 - deduct)
                        end
                    end

                    if speed < 400 then
                        vel = vector(0, 0, 0)
                    end

                    trace = utils.trace_hull(trace.end_pos, trace.end_pos + vel * (1 - trace.fraction) * tickinterval,
                        vector(-2, -2, -2), vector(2, 2, 2), trace_filter, TRACE_MASK)
                    new_position = trace.end_pos
                end

                position:init(new_position:unpack())
            end

            local teleport_trace = utils.trace_line(position,
                position - vector(0, 0, grenade_release.teleport_distance[46]), trace_filter, TRACE_MASK)
            if teleport_trace.fraction < 1 then
                position:init(teleport_trace.end_pos:unpack())
            end

            return position
        end

        local function get_predicted_molotov_origins()
            if molotov_prediction.tick == globals.tickcount then
                return molotov_prediction.origins
            end

            molotov_prediction.tick = globals.tickcount
            molotov_prediction.origins = {}

            local molotovs = entity.get_entities('CMolotovProjectile', true)
            if molotovs == nil or #molotovs == 0 then
                return molotov_prediction.origins
            end

            local now = globals.curtime
            for i = 1, #molotovs do
                local molotov = molotovs[i]
                local origin = molotov:get_origin()
                if origin == nil then
                    goto continue
                end

                local index = molotov:get_index()
                local last = molotov_prediction.history[index]
                local velocity = nil
                if last ~= nil then
                    local dt = now - last.time
                    if dt > 0 then
                        velocity = (origin - last.origin) / dt
                    end
                end

                molotov_prediction.history[index] = {
                    origin = origin:clone(),
                    time = now,
                }

                if velocity == nil or velocity:lengthsqr() < MOLOTOV_PREDICT_MIN_SPEED_SQR then
                    goto continue
                end

                molotov_prediction.origins[#molotov_prediction.origins + 1] = predict_molotov_position(origin, velocity)

                ::continue::
            end

            return molotov_prediction.origins
        end

        local function on_grenade_warning(event)
            if menu.predict_molotov_item:get() ~= true then
                return
            end

            if event == nil then
                return
            end

            if event.type ~= 'Molly' then
                return
            end

            local warning_position = event.closest_point
            if warning_position == nil and event.path ~= nil then
                warning_position = event.path[#event.path]
            end
            if warning_position == nil then
                return
            end

            local key = #molotov_warning.list + 1
            local entity = event.entity
            if entity ~= nil then
                key = entity:get_index()
            end

            molotov_warning.list[key] = {
                position = warning_position:clone(),
                expire_time = event.expire_time or 0,
            }
        end

        local function get_grenade_warning_positions()
            local list = molotov_warning.list
            if list == nil then
                return {}
            end

            local now = globals.curtime
            local has_inferno = false
            local infernos = get_infernos()
            if infernos ~= nil and #infernos > 0 then
                has_inferno = true
            end
            local has_molotov = false
            local molotovs = entity.get_entities('CMolotovProjectile', true)
            if molotovs ~= nil and #molotovs > 0 then
                has_molotov = true
            end
            for key, item in pairs(list) do
                if item == nil then
                    list[key] = nil
                    goto continue
                end

                if item.expire_time ~= nil and item.expire_time > 0 and item.expire_time < now then
                    list[key] = nil
                end
                if has_inferno ~= true and has_molotov ~= true then
                    list[key] = nil
                end

                ::continue::
            end

            return list
        end

        local function approach_number(current_value, target_value, step)
            if current_value < target_value then
                return math.min(current_value + step, target_value)
            end

            if current_value > target_value then
                return math.max(current_value - step, target_value)
            end

            return current_value
        end

        local function get_release_throw_strength(weapon, release_ticks)
            local current_strength = math.clamp(weapon.m_flThrowStrength or 0, 0, 1)
            local ticks = math.max(1, release_ticks or 1)
            local step = globals.tickinterval * 1.3 * ticks

            return approach_number(current_strength, 0.5, step)
        end

        local function get_extrapolation_amount(command)
            local ticks = 1

            if command ~= nil
                and type(command.choked_commands) == 'number'
                and command.choked_commands > 0 then
                ticks = ticks + math.min(command.choked_commands, 2)
            end

            if rage ~= nil and rage.exploit ~= nil and rage.exploit:get() == 1 then
                ticks = ticks + 1
            end

            return math.clamp(ticks, 1, 3)
        end

        local function is_smoke_active(smoke, predicted_tick)
            local effect_tick = smoke.m_nSmokeEffectTickBegin
            if effect_tick == nil or effect_tick <= 0 then
                return false
            end

            if predicted_tick < effect_tick then
                return false
            end

            if predicted_tick - effect_tick >= SMOKE_LIFETIME_TICKS then
                return false
            end

            return true
        end

        local function get_smoke_detonate_time()
            local detonate_cvar = cvar['weapon_smokegrenade_detonate_time']
            if detonate_cvar ~= nil then
                local value = detonate_cvar:float()
                if value ~= nil and value > 0 then
                    return value
                end
            end

            return SMOKE_DETONATE_TIME_FALLBACK
        end

        local function get_smoke_radius(height_difference)
            local radius = SMOKE_BASE_RADIUS
            if height_difference > SMOKE_HEIGHT_UPPER then
                radius = radius - SMOKE_UPPER_COEF * (height_difference - SMOKE_HEIGHT_UPPER) ^ 2
            elseif height_difference < SMOKE_HEIGHT_LOWER then
                radius = radius - SMOKE_LOWER_COEF * (SMOKE_HEIGHT_LOWER - height_difference) ^ 2
            end

            return radius
        end

        local function is_in_smoke_radius(center_position, target_position)
            local height_difference = target_position.z - center_position.z
            if height_difference <= SMOKE_HEIGHT_MIN or height_difference >= SMOKE_HEIGHT_MAX then
                return false
            end

            local radius = get_smoke_radius(height_difference)
            return center_position:dist2dsqr(target_position) <= radius
        end

        local function remap_clamped(value, a, b, c, d)
            if a == b then
                return c
            end

            local t = (value - a) / (b - a)
            t = math.clamp(t, 0, 1)

            return c + (d - c) * t
        end

        local function get_fire_point_smoke_info(fire_point, smoke_origin)
            local fire_above_smoke = fire_point.z - smoke_origin.z
            local dist2d_sqr = smoke_origin:dist2dsqr(fire_point)
            if fire_above_smoke < -FIRE_UP_TO_SMOKE_HEIGHT then
                return false, fire_above_smoke, 0, dist2d_sqr
            end
            if fire_above_smoke > SMOKE_AFFECT_Z then
                return false, fire_above_smoke, 0, dist2d_sqr
            end

            local radius_sqr = SMOKE_XY_EQUATOR * SMOKE_XY_EQUATOR
            if fire_above_smoke > SMOKE_AFFECT_Z * 0.6 then
                local pct = remap_clamped(fire_above_smoke, SMOKE_AFFECT_Z * 0.6, SMOKE_AFFECT_Z, 0, 1)
                pct = pct * pct
                radius_sqr = remap_clamped(pct, 0, 1, radius_sqr, SMOKE_XY_TOP * SMOKE_XY_TOP)
            elseif fire_above_smoke < SMOKE_AFFECT_Z * 0.15 then
                local pct = remap_clamped(fire_above_smoke, SMOKE_AFFECT_Z * 0.1, -FIRE_UP_TO_SMOKE_HEIGHT, 0, 1)
                pct = pct * pct
                radius_sqr = remap_clamped(pct, 0, 1, radius_sqr, SMOKE_XY_BOTTOM * SMOKE_XY_BOTTOM)
            end

            return dist2d_sqr <= radius_sqr, fire_above_smoke, radius_sqr, dist2d_sqr
        end

        local function is_fire_point_in_smoke_full(fire_point, smoke_origin, margin_override)
            local is_full, fire_above_smoke, radius_sqr, dist2d_sqr = get_fire_point_smoke_info(fire_point, smoke_origin)
            if is_full ~= true then
                return false, fire_above_smoke, radius_sqr, dist2d_sqr
            end

            local margin = SMOKE_FULL_SAFETY_MARGIN
            if type(margin_override) == 'number' then
                margin = margin_override
            end

            if margin <= 0 then
                return true, fire_above_smoke, radius_sqr, dist2d_sqr
            end

            local radius = math.sqrt(radius_sqr) - margin
            if radius <= 0 then
                return false, fire_above_smoke, radius_sqr, dist2d_sqr
            end

            return dist2d_sqr <= radius * radius, fire_above_smoke, radius_sqr, dist2d_sqr
        end

        local function can_fully_extinguish_inferno(smoke_origin, inferno_origin, margin_override)
            if inferno_origin == nil then
                return false, 0, 0, 0
            end

            local is_full, fire_above_smoke, radius_sqr, dist2d_sqr = is_fire_point_in_smoke_full(inferno_origin,
                smoke_origin, margin_override)
            if smoke_origin:distsqr(inferno_origin) > SMOKE_GRENADE_RADIUS_RANGE_SQR then
                return false, fire_above_smoke, radius_sqr, dist2d_sqr
            end

            return is_full, fire_above_smoke, radius_sqr, dist2d_sqr
        end

        local function get_inferno_remaining_time(inferno)
            if inferno == nil then
                return nil
            end

            local spawn_time = inferno.m_flSpawnTime
            if type(spawn_time) ~= 'number' then
                return nil
            end

            local lifetime = INFERNO_LIFETIME_FALLBACK
            local lifetime_cvar = cvar['inferno_flame_lifetime']
            if lifetime_cvar ~= nil then
                local value = lifetime_cvar:float()
                if value ~= nil and value > 0 then
                    lifetime = value
                end
            end

            return spawn_time + lifetime - globals.curtime
        end

        local function is_smoke_full_extinguish(smoke_origin, inferno, inferno_points, time_to_detonate)
            if smoke_origin == nil or inferno == nil then
                return false
            end

            local origin = inferno.m_vecOrigin
            if origin == nil then
                return false
            end

            if time_to_detonate ~= nil then
                local remaining_time = get_inferno_remaining_time(inferno)
                if remaining_time ~= nil and remaining_time <= time_to_detonate then
                    return false
                end
            end

            if smoke_origin:distsqr(origin) > SMOKE_GRENADE_RADIUS_RANGE_SQR then
                return false
            end

            if is_fire_point_in_smoke_full(origin, smoke_origin, SMOKE_INFERNO_MARGIN) ~= true then
                return false
            end

            return true
        end

        local function get_smoke_drop_position(position)
            local trace_down = utils.trace_line(position, position - vector(0, 0, SMOKE_DROP_DISTANCE), trace_filter,
                TRACE_MASK)
            if trace_down.fraction >= 1 then
                return nil
            end

            if trace_down.fraction > 0.001 then
                return trace_down.end_pos
            end

            return position
        end

        local function check_smoke_bounce_extinguish(bounce_position, infernos, inferno_points)
            local drop_position = get_smoke_drop_position(bounce_position)
            if drop_position == nil then
                return false, nil
            end

            for i = 1, #infernos do
                local inferno = infernos[i]
                if inferno == nil then
                    goto continue
                end

                local inferno_origin = inferno.m_vecOrigin
                if inferno_origin ~= nil and bounce_position:distsqr(inferno_origin) > SMOKE_EXTINGUISH_RADIUS_SQR then
                    goto continue
                end

                local points = inferno_points[i]
                if points ~= nil then
                    local has_touch = false
                    for p = 1, #points do
                        local fire_point = points[p]
                        local fire_center = fire_point + vector(0, 0, FIRE_CENTER_OFFSET)

                        if drop_position:distsqr(fire_center) <= FIRE_EXTINGUISH_RADIUS_SQR then
                            has_touch = true
                            local trace_from_top = utils.trace_line(fire_center + vector(0, 0, FIRE_HALF_WIDTH),
                                drop_position, trace_filter, TRACE_MASK)
                            local has_line_of_sight = trace_from_top.fraction == 1

                            if has_line_of_sight ~= true then
                                local trace_from_center = utils.trace_line(fire_center, drop_position, trace_filter,
                                    TRACE_MASK)
                                has_line_of_sight = trace_from_center.fraction == 1
                            end

                            if has_line_of_sight == true then
                                return true, drop_position, inferno_origin, i
                            end
                        end
                    end
                end

                ::continue::
            end

            return false, drop_position
        end

        function grenade_release.simulate_throw(view_angles, local_player, extrapolation_amount, weapon, weapon_info)
            local simulated_local_player = local_player:simulate_movement()
            if local_player.m_MoveType ~= 9 then
                simulated_local_player:think(extrapolation_amount)
            end

            local simulated_position = simulated_local_player.origin
            local simulated_velocity = simulated_local_player.velocity
            if local_player.m_MoveType == 9 then
                simulated_position = local_player.m_vecOrigin
                simulated_velocity = vector(0, 0, 0)
            end

            debug_render.add_line(local_player.m_vecOrigin, simulated_position, color(255, 255, 255, 255))
            debug_render.add_radius(simulated_position, 4, color(255, 255, 255, 255))
            debug_render.add_line(simulated_position,
                simulated_position + vector(0, 0, simulated_local_player.view_offset), color(255, 255, 255, 255))
            debug_render.add_radius(simulated_position + vector(0, 0, simulated_local_player.view_offset), 4,
                color(255, 255, 255, 255))

            local throw_strength = get_release_throw_strength(weapon, extrapolation_amount)

            if super_toss.is_enabled == true then
                view_angles = super_toss.resolve_grenade_throw(view_angles, weapon_info.throw_velocity, throw_strength,
                    simulated_velocity)
            end

            local view_forward = vector():angles(vector(view_angles.x - (90 - math.abs(view_angles.x)) / 9, view_angles
                .y))

            local position = simulated_position
            position.z = position.z + simulated_local_player.view_offset - 12 * (1 - throw_strength)
            position = utils.trace_hull(position, position + view_forward * 22, vector(-2, -2, -2), vector(2, 2, 2),
                trace_filter, TRACE_MASK).end_pos - (view_forward * 6)

            local velocity = view_forward * math.clamp(weapon_info.throw_velocity * 0.9, 15, 750) *
                (throw_strength * 0.7 + 0.3) + simulated_velocity * 1.25

            debug_render.add_line(position + vector(0, 0, 2), position - vector(0, 0, 2), color(255, 0, 0, 255))
            debug_render.add_line(position + vector(0, 2, 0), position - vector(0, 2, 0), color(255, 0, 0, 255))
            debug_render.add_line(position + vector(2, 0, 0), position - vector(2, 0, 0), color(255, 0, 0, 255))

            return position, velocity
        end

        grenade_release.check_flight_duration = {
            [44] = function(flight_duration)
                return (flight_duration - 1) * globals.tickinterval > 1.5 and
                    flight_duration % math.floor(0.2 / globals.tickinterval + 0.5) == 0
            end,
            [45] = function()
                return false
            end,
            [46] = function(flight_duration, molotov_max_flight_duration)
                return (flight_duration - 1) * globals.tickinterval > molotov_max_flight_duration
            end,
        }

        grenade_release.teleport_distance = {
            [44] = 24,
            [45] = 0,
            [46] = 128,
        }

        function grenade_release.simulate_projectile(position, velocity, weapon_definition_index)
            local gravity = cvar['sv_gravity']:float() * 0.4
            local molotov_max_flight_duration = cvar['molotov_throw_detonate_time']:float()
            local molotov_max_detonate_slope = math.cos(math.rad(cvar['weapon_molotov_maxdetonateslope']:float()))

            local has_exploded = false
            if weapon_definition_index ~= 46 then
                has_exploded = true
            end

            local is_smoke_hit_molotov = false

            local infernos = nil
            local inferno_points = nil
            if weapon_definition_index == 45 then
                infernos = get_infernos()
                inferno_points = get_inferno_points()
            end

            local detonate_tick = nil
            local detonate_check_interval = nil
            local detonation_position = nil
            local last_bounce_tick = nil

            local flight_duration = 0
            local tickinterval = globals.tickinterval
            local max_ticks = 256
            if weapon_definition_index == 46 then
                max_ticks = math.min(256, math.floor(molotov_max_flight_duration / tickinterval + 1.5))
            elseif weapon_definition_index == 45 then
                local detonate_time = get_smoke_detonate_time()
                detonate_tick = math.max(1, math.floor(detonate_time / tickinterval + 0.5))
                detonate_check_interval = math.max(1, math.floor(SMOKE_DETONATE_CHECK / tickinterval + 0.5))
            end

            for tick = 1, max_ticks do
                local move = velocity * tickinterval

                local new_velocity_z = velocity.z - gravity * tickinterval
                move.z = (velocity.z + new_velocity_z) / 2 * tickinterval
                velocity.z = new_velocity_z

                local new_position = position + move

                local trace = utils.trace_hull(position, new_position, vector(-2, -2, -2), vector(2, 2, 2), trace_filter,
                    TRACE_MASK)

                if trace.fraction < 1 then
                    if weapon_definition_index == 45 and infernos ~= nil and inferno_points ~= nil then
                        if last_bounce_tick == nil or tick - last_bounce_tick > 3 then
                            last_bounce_tick = tick

                            local bounce_position = trace.end_pos
                            debug_render.add_radius(bounce_position, 3, color(255, 127, 0, 255))

                            local can_extinguish, drop_position, inferno_origin, inferno_index =
                                check_smoke_bounce_extinguish(bounce_position, infernos, inferno_points)
                            if drop_position ~= nil then
                                debug_render.add_radius(drop_position, 4, color(255, 200, 0, 255))
                            end

                            if can_extinguish == true then
                                if drop_position ~= nil then
                                    position:init(drop_position:unpack())
                                else
                                    position:init(bounce_position:unpack())
                                end

                                if drop_position ~= nil then
                                    local is_full = false
                                    if inferno_index ~= nil then
                                        local time_to_detonate = tick * tickinterval
                                        is_full = is_smoke_full_extinguish(drop_position, infernos[inferno_index],
                                            inferno_points[inferno_index], time_to_detonate)
                                    elseif inferno_origin ~= nil then
                                        is_full = can_fully_extinguish_inferno(drop_position, inferno_origin,
                                            SMOKE_INFERNO_MARGIN)
                                    end

                                    if is_full == true then
                                        is_smoke_hit_molotov = true
                                    end
                                end
                                flight_duration = tick
                                goto finish_simulation
                            end
                        end
                    elseif weapon_definition_index == 45 then
                        debug_render.add_radius(trace.end_pos, 3, color(255, 127, 0, 255))
                    end

                    local plane_normal = trace.plane.normal

                    if weapon_definition_index == 46 and plane_normal.z > molotov_max_detonate_slope then
                        position:init(trace.end_pos:unpack())

                        return true, tick, false
                    end

                    velocity = velocity - plane_normal * velocity:dot(plane_normal) * 2

                    if math.abs(velocity.x) < 0.1 then
                        velocity.x = 0
                    end
                    if math.abs(velocity.y) < 0.1 then
                        velocity.y = 0
                    end
                    if math.abs(velocity.z) < 0.1 then
                        velocity.z = 0
                    end

                    velocity = velocity * 0.45

                    local speed = velocity:lengthsqr()

                    if plane_normal.z > 0.7 and speed > 96000 then
                        local deduct = velocity:normalized():dot(plane_normal)

                        if deduct > 0.5 then
                            velocity = velocity * (1.5 - deduct)
                        end
                    end

                    if speed < 400 then
                        velocity = vector(0, 0, 0)
                    end

                    trace = utils.trace_hull(trace.end_pos,
                        trace.end_pos + velocity * (1 - trace.fraction) * tickinterval, vector(-2, -2, -2),
                        vector(2, 2, 2), trace_filter, TRACE_MASK)

                    new_position = trace.end_pos
                end

                debug_render.add_line(position, new_position, color(0, 255, 0, 255))

                position:init(new_position:unpack())

                if detonate_tick ~= nil and tick >= detonate_tick then
                    if velocity:lengthsqr() <= 0.01 then
                        detonation_position = position:clone()
                        flight_duration = tick
                        break
                    end

                    if detonate_check_interval ~= nil and (tick - detonate_tick) % detonate_check_interval == 0 then
                        flight_duration = tick
                    end
                end

                if grenade_release.check_flight_duration[weapon_definition_index](tick, molotov_max_flight_duration) == true then
                    flight_duration = tick

                    break
                end

                if tick == max_ticks then
                    flight_duration = tick
                end
            end

            if detonation_position ~= nil then
                position:init(detonation_position:unpack())
            end

            if weapon_definition_index == 45 and infernos ~= nil then
                local time_to_detonate = flight_duration * tickinterval
                for i = 1, #infernos do
                    local is_full = is_smoke_full_extinguish(position, infernos[i], inferno_points[i], time_to_detonate)
                    if is_full == true then
                        is_smoke_hit_molotov = true
                        break
                    end
                end
            end

            ::finish_simulation::

            local teleport_trace = utils.trace_line(position,
                position - vector(0, 0, grenade_release.teleport_distance[weapon_definition_index]), trace_filter,
                TRACE_MASK)

            if teleport_trace.fraction < 1 then
                debug_render.add_line(position, teleport_trace.end_pos, color(0, 255, 0, 255))

                position:init(teleport_trace.end_pos:unpack())

                has_exploded = true
            end

            return has_exploded, flight_duration, is_smoke_hit_molotov
        end

        grenade_release.check_network_state = {
            [0] = true,
            [1] = true,
            [2] = true,
            [3] = true,
            [4] = true,
        }

        grenade_release.simulate_impact = {
            [44] = function(position)
                position.z = position.z + 1

                local base_min_damage = menu.he_damage_item:get()

                local players_resource = entity.get_player_resource()
                local players = entity.get_players(true, true)
                for i = 1, #players do
                    local player = players[i]

                    if players_resource.m_bConnected[player:get_index()] ~= true then
                        goto continue
                    end
                    if player:is_alive() ~= true then
                        goto continue
                    end
                    if grenade_release.check_network_state[player:get_network_state()] ~= true then
                        goto continue
                    end
                    if player:get_bbox().alpha <= 0 then
                        goto continue
                    end

                    local min_damage = base_min_damage
                    local health = player.m_iHealth

                    if health ~= nil and health > 0 and health < min_damage then
                        min_damage = health
                    end

                    local distance = position:dist(player:get_origin() + player.m_vecViewOffset)
                    if distance > 350 then
                        goto continue
                    end

                    local player_position = player:get_origin()
                    local head_position = player_position + vector(0, 0, 71)
                    local chest_position = player_position + player.m_vecViewOffset

                    local position_offset = vector():angles(vector(0, player.m_angEyeAngles.y + 90)) * 16

                    local left_position = chest_position - position_offset
                    local right_position = chest_position + position_offset

                    debug_render.add_line(player_position, head_position, color(127, 127, 255, 255))
                    debug_render.add_line(left_position, right_position, color(127, 127, 255, 255))

                    local percentages = { 0.2, 0.4, 0.1, 0.1, 0.2 }
                    local points = { head_position, chest_position, left_position, right_position, player_position }

                    local damage_multiplier = 0
                    for j = 1, #points do
                        local point = points[j]

                        local trace = utils.trace_line(position, point, trace_filter, 0x46004003)

                        if trace.fraction == 1 then
                            debug_render.add_line(position, point, color(255, 127, 127, 255))

                            damage_multiplier = damage_multiplier + percentages[j]
                        end
                    end

                    if damage_multiplier > 0 then
                        local damage = math.exp(-distance * distance / 27222.2222222) * 99 * damage_multiplier

                        local armor = player.m_ArmorValue

                        if armor > 0 then
                            local new_damage = damage * 0.6
                            local new_armor = (damage - new_damage) * 0.5

                            if new_armor > armor then
                                new_damage = damage - armor * 2
                            end

                            damage = new_damage
                        end

                        debug_render.print('damage: ', damage)

                        if damage >= min_damage then
                            return true
                        end
                    end

                    ::continue::
                end
            end,
            [45] = function()
                return false
            end,
            [46] = function(position, flight_duration)
                local predicted_tick = get_predicted_server_tick() + flight_duration
                local smokes = get_smokes()

                for i = 1, #smokes do
                    local smoke = smokes[i]
                    if is_smoke_active(smoke, predicted_tick) ~= true then
                        goto continue
                    end

                    local smoke_position = smoke.m_vecOrigin
                    if position:distsqr(smoke_position) > SMOKE_RADIUS_SQR then
                        goto continue
                    end

                    local height_difference = position.z - smoke_position.z

                    if height_difference > SMOKE_HEIGHT_MIN and height_difference < SMOKE_HEIGHT_MAX then
                        local radius = get_smoke_radius(height_difference)

                        if position:dist2dsqr(smoke_position) <= radius then
                            debug_render.add_radius(smoke_position + vector(0, 0, height_difference), math.sqrt(radius),
                                color(127, 127, 255, 255))

                            return
                        end
                    end

                    ::continue::
                end

                debug_render.add_radius(position, 60, color(255, 127, 127, 255))

                local max_range = (menu.molotov_range_item:get() / 10 * 50.85) ^ 2

                local players_resource = entity.get_player_resource()

                local players = {}
                entity.get_players(true, true, function(player)
                    if players_resource.m_bConnected[player:get_index()] == true and player:is_alive() == true and grenade_release.check_network_state[player:get_network_state()] == true and player:get_bbox().alpha > 0 and position:distsqr(player:get_origin()) <= 14400 then
                        players[#players + 1] = player
                    end
                end)

                for j = 1, #players do
                    local player_position = players[j]:get_origin()

                    local distance = position:dist2dsqr(player_position)

                    if distance <= MOLLY_TARGET_RADIUS_SQR and player_position.z - position.z <= MOLLY_TARGET_Z_MAX and player_position.z - position.z >= MOLLY_TARGET_Z_MIN then
                        debug_render.print('distance: ', string.format('%.2f', math.sqrt(distance) / 50.85))

                        if distance <= max_range then
                            return true
                        end
                    end
                end

                local cells = {}
                local random_rotation = utils.random_float(0, 0.785)
                for k = random_rotation, 5.495 + random_rotation, 0.785 do
                    local cell_position = position + vector(math.cos(k), math.sin(k), 0) * 60
                    cell_position.z = utils.trace_line(cell_position + vector(0, 0, 50),
                        cell_position - vector(0, 0, 200), trace_filter, 0x4003).end_pos.z

                    local is_in_smoke = false
                    for v = 1, #smokes do
                        local smoke = smokes[v]
                        if is_smoke_active(smoke, predicted_tick) ~= true then
                            goto continue_smoke
                        end

                        local smoke_position = smoke.m_vecOrigin

                        local height_difference = cell_position.z - smoke_position.z

                        if height_difference > SMOKE_HEIGHT_MIN and height_difference < SMOKE_HEIGHT_MAX then
                            local radius = get_smoke_radius(height_difference)

                            if cell_position:dist2dsqr(smoke_position) <= radius then
                                debug_render.add_radius(smoke_position + vector(0, 0, height_difference),
                                    math.sqrt(radius), color(127, 127, 255, 255))

                                is_in_smoke = true

                                break
                            end
                        end

                        ::continue_smoke::
                    end

                    if is_in_smoke ~= true and utils.trace_line(position + vector(0, 0, 30), cell_position + vector(0, 0, 30), trace_filter, 0x2004003).fraction == 1 then
                        debug_render.add_radius(cell_position, 60, color(255, 127, 127, 255))

                        cells[#cells + 1] = cell_position
                    end
                end

                for p = 1, #players do
                    local player_position = players[p]:get_origin()

                    for q = 1, #cells do
                        local cell_position = cells[q]

                        local distance = cell_position:dist2dsqr(player_position)

                        if distance <= MOLLY_TARGET_RADIUS_SQR and player_position.z - cell_position.z <= MOLLY_TARGET_Z_MAX and player_position.z - cell_position.z >= MOLLY_TARGET_Z_MIN then
                            debug_render.print('distance: ',
                                string.format('%.2f', position:dist2d(player_position) / 50.85))

                            if position:dist2dsqr(player_position) <= max_range then
                                return true
                            end
                        end
                    end
                end
            end,
        }

        function grenade_release.on_createmove(command)
            grenade_release.handle_command_lock(command)

            if menu.enabled_item:get() ~= true then
                grenade_throw_state.set_grenade_release_active(false)
                return
            end

            if command.jitter_move ~= true then
                return
            end

            local local_player = entity.get_local_player()
            if local_player == nil then
                return
            end
            if local_player:is_alive() ~= true then
                return
            end

            local weapon = local_player:get_player_weapon()
            if weapon == nil then
                return
            end
            if weapon.m_bPinPulled ~= true then
                return
            end
            if command.in_attack ~= true and command.in_attack2 ~= true then
                return
            end

            local weapon_definition_index = weapon.m_iItemDefinitionIndex
            if weapon_definition_index == 48 then
                weapon_definition_index = 46
            end

            if grenade_release.is_weapon_allowed[weapon_definition_index] == nil then
                return
            end
            if grenade_release.is_weapon_allowed[weapon_definition_index]() ~= true then
                return
            end

            local weapon_info = weapon:get_weapon_info()
            if weapon_info == nil then
                return
            end
            if weapon_info.weapon_type ~= 9 then
                return
            end

            local extrapolation_amount = get_extrapolation_amount(command)

            command.jitter_move = false
            neverlose.air_strafe:override(false)
            neverlose.air_duck:override(false)
            neverlose.quick_stop:override(false)
            neverlose.strafe_assist:override(false)
            neverlose.slow_walk:override(false)
            grenade_throw_state.set_grenade_release_active(true)

            local position, velocity = grenade_release.simulate_throw(command.view_angles, local_player,
                extrapolation_amount, weapon, weapon_info)

            command.jitter_move = true
            neverlose.air_strafe:override()
            neverlose.air_duck:override()
            neverlose.quick_stop:override()
            neverlose.strafe_assist:override()
            neverlose.slow_walk:override()
            grenade_throw_state.set_grenade_release_active(false)

            local has_exploded, flight_duration, is_smoke_hit_molotov = grenade_release.simulate_projectile(position,
                velocity, weapon_definition_index)
            if has_exploded == false and is_smoke_hit_molotov == false then
                return
            end

            if weapon_definition_index ~= 45 then
                debug_render.add_radius(position, 4, color(255, 0, 0, 255))
                debug_render.add_radius(position, 5, color(255, 0, 0, 255))
                debug_render.add_radius(position, 6, color(255, 0, 0, 255))
            end

            if grenade_release.simulate_impact[weapon_definition_index](position, extrapolation_amount + flight_duration) ~= true and is_smoke_hit_molotov ~= true then
                return
            end

            grenade_release.lock_command(command, extrapolation_amount)
        end

        local function reset_grenade_release_state()
            neverlose.air_strafe:override()
            neverlose.air_duck:override()
            neverlose.quick_stop:override()
            neverlose.strafe_assist:override()
            neverlose.slow_walk:override()
            grenade_throw_state.set_grenade_release_active(false)

            grenade_release.is_ui_locked = false
            grenade_release.unlock_tick = 0

            reset_cache()
            molotov_prediction.tick = -1
            molotov_prediction.origins = {}
            molotov_prediction.history = {}
            molotov_warning.list = {}
        end

        local callbacks
        do
            local function on_state_change()
                local super_toss_enabled = menu.super_toss_item:get()
                local better_interactions_enabled = menu.better_interactions_item:get()
                local quick_switch_enabled = menu.quick_switch_item:get()
                local grenade_release_enabled = menu.enabled_item:get()
                local predict_molotov_enabled = menu.predict_molotov_item:get()

                super_toss.is_enabled = super_toss_enabled

                events.createmove(better_interactions.on_createmove, better_interactions_enabled)
                events.grenade_thrown(quick_switch.on_grenade_thrown, quick_switch_enabled)
                events.weapon_fire(quick_switch.on_weapon_fire, quick_switch_enabled)
                events.shutdown(quick_switch.on_shutdown, quick_switch_enabled)
                events.createmove(grenade_release.on_createmove, false)
                events.createmove(super_toss.on_createmove, false)
                if grenade_release_enabled == true then
                    events.createmove(grenade_release.on_createmove, true)
                end
                if super_toss_enabled == true then
                    events.createmove(super_toss.on_createmove, true)
                end
                events.level_init(on_level_init, grenade_release_enabled)
                events.grenade_warning(
                    on_grenade_warning,
                    grenade_release_enabled and predict_molotov_enabled
                )
                events.grenade_override_view(on_grenade_override_view, false)
                if super_toss_enabled == true then
                    events.grenade_override_view(on_grenade_override_view, true)
                end
                quick_switch.set_enabled(quick_switch_enabled)

                if grenade_release_enabled ~= true then
                    reset_grenade_release_state()
                end

                if super_toss_enabled ~= true then
                    super_toss.reset_state()
                end

                if better_interactions_enabled ~= true then
                    better_interactions.reset_state()
                end

                if quick_switch_enabled ~= true then
                    quick_switch.reset_state()
                end
            end

            if ref.super_toss_enabled ~= nil then
                ref.super_toss_enabled:set_callback(on_state_change, true)
            end

            if ref.better_interactions_enabled ~= nil then
                ref.better_interactions_enabled:set_callback(on_state_change, true)
            end

            if ref.quick_switch_enabled ~= nil then
                ref.quick_switch_enabled:set_callback(on_state_change, true)
            end

            if ref.grenade_release_enabled ~= nil then
                ref.grenade_release_enabled:set_callback(on_state_change, true)
            end

            if ref.grenade_release_predict_molotov ~= nil then
                ref.grenade_release_predict_molotov:set_callback(on_state_change)
            end
        end
    end
end

local fps_optimize
do
    local ref = {
        enabled = fps_optimize_ref.enabled,
        select = fps_optimize_ref.select,
    }

    local tree = {
    }

    local function wrap(convar, value)
        return {
            convar = convar,
            old_value = nil,
            new_value = value,
        }
    end

    tree["Fog"] = {
        wrap(cvar.fog_enable, 0),
        wrap(cvar.fog_enable_water_fog, 0),
    }

    tree["Blood"] = {
        wrap(cvar.violence_hblood, 0),
    }

    tree["Bloom"] = {
        wrap(cvar.mat_disable_bloom, 1),
    }

    tree["Decals"] = {
        wrap(cvar.r_drawdecals, 0),
    }

    tree["Shadows"] = {
        wrap(cvar.r_shadows, 0),
        wrap(cvar.cl_csm_static_prop_shadows, 0),
        wrap(cvar.cl_csm_shadows, 0),
        wrap(cvar.cl_csm_world_shadows, 0),
        wrap(cvar.cl_foot_contact_shadows, 0),
        wrap(cvar.cl_csm_viewmodel_shadows, 0),
        wrap(cvar.cl_csm_rope_shadows, 0),
        wrap(cvar.cl_csm_sprite_shadows, 0),
        wrap(cvar.cl_csm_translucent_shadows, 0),
        wrap(cvar.cl_csm_entity_shadows, 0),
        wrap(cvar.cl_csm_world_shadows_in_viewmodelcascad, 0),
    }

    tree["Sprites"] = {
        wrap(cvar.r_drawsprites, 0),
    }

    tree["Particles (Molotov and etc)"] = {
        wrap(cvar.r_drawparticles, 0),
    }

    tree["Ropes"] = {
        wrap(cvar.r_drawropes, 0),
    }

    tree["Dynamic lights"] = {
        wrap(cvar.mat_disable_fancy_blending, 1),
    }

    tree["Map details"] = {
        wrap(cvar.func_break_max_pieces, 0),
        wrap(cvar.props_break_max_pieces, 0),
    }

    tree["Weapon effects"] = {
        wrap(cvar.muzzleflash_light, 0),
        wrap(cvar.r_drawtracers_firstperson, 0),
    }

    local selected_lookup = {
    }

    local function clear_selected_lookup()
        for key in pairs(selected_lookup) do
            selected_lookup[key] = nil
        end
    end

    local function is_active()
        if ref.enabled == nil then
            return false
        end

        local ok_enabled, enabled_value = pcall(ref.enabled.get, ref.enabled)
        if not ok_enabled or enabled_value ~= true then
            return false
        end

        return true
    end

    local function restore_convars()
        for _, items in pairs(tree) do
            for i = 1, #items do
                local item = items[i]
                local convar = item.convar
                local old_value = item.old_value

                if convar ~= nil and old_value ~= nil then
                    convar:int(old_value)
                end

                item.old_value = nil
            end
        end
    end

    local function apply_convars()
        if ref.select == nil then
            return
        end

        local ok_values, values = pcall(ref.select.get, ref.select)
        if not ok_values or type(values) ~= "table" then
            values = {
            }
        end

        local options = nil
        local ok_options, option_values = pcall(ref.select.list, ref.select)
        if ok_options and type(option_values) == "table" then
            options = option_values
        end

        clear_selected_lookup()

        for i = 1, #values do
            local value = values[i]
            if type(value) == "string" then
                selected_lookup[value] = true
            elseif type(value) == "number" then
                if options ~= nil then
                    local option_name = options[value]
                    if type(option_name) == "string" then
                        selected_lookup[option_name] = true
                    end
                end
            end
        end

        for name, items in pairs(tree) do
            local should_apply = selected_lookup[name] == true

            for i = 1, #items do
                local item = items[i]
                local convar = item.convar

                if convar == nil then
                    goto continue
                end

                if should_apply then
                    if item.old_value == nil then
                        item.old_value = convar:int()
                    end

                    convar:int(item.new_value)
                elseif item.old_value ~= nil then
                    convar:int(item.old_value)
                    item.old_value = nil
                end

                ::continue::
            end
        end
    end

    local function update_state()
        if not is_active() then
            restore_convars()
            return
        end

        apply_convars()
    end

    local function on_shutdown()
        restore_convars()
    end

    local callbacks
    do
        local function on_value_change()
            update_state()
        end

        local function on_enabled(item)
            local enabled = false
            if item ~= nil then
                local ok_enabled, value = pcall(item.get, item)
                enabled = ok_enabled and value == true
            end

            if ref.select ~= nil then
                if enabled then
                    ref.select:set_callback(on_value_change, true)
                else
                    ref.select:unset_callback(on_value_change)
                end
            end

            if not enabled then
                restore_convars()
            end

            events.shutdown(on_shutdown, enabled)
        end

        if ref.enabled ~= nil then
            ref.enabled:set_callback(on_enabled, true)
        end
    end
end

local clantag
do
    local MODE_ORIGINAL = "Original"
    local MODE_CUSTOM = "Custom"
    local MODE_REVERSE = "Reverse"
    local MODE_STEALER = "Stealer"

    local CUSTOM_TYPE_ANIMATED = "Animated"
    local CUSTOM_TYPE_STATIC = "Static"

    local UPDATE_SPEED = 3.0
    local CUSTOM_SYNC_DEFAULT_TEXT = "aesthetic"
    local STEALER_REFRESH_DELAY = 1.0
    local SCROLL_LEFT_PADDING = "               "
    local SCROLL_RIGHT_PADDING = "                      "
    local SCROLL_VISIBLE_START = 2
    local SCROLL_VISIBLE_END = 16
    local SCROLL_LENGTH_OFFSET = 13
    local SCROLL_MID_HOLD_FRAMES = 8

    local ORIGINAL_ANIMATION = {
        "",
        "a",
        "ae",
        "aes",
        "aest",
        "aesth",
        "aesthe",
        "/aesthetic",
        "aesthetic",
        "aesthetic_",
        "aesthetic-",
        "a3sthetic",
        "ae5thetic",
        "aesthet1c",
        "aesthetic#",
        "aesthetic$",
        "aesthetic",
        "aestheti",
        "aesthet",
        "aesth",
        "aest",
        "aes",
        "ae",
        "a",
        "\\"
    }

    local ref = {
        enabled = clantag_ref.enabled,
        mode = clantag_ref.mode,
        custom_type = clantag_ref.custom_type,
        custom_text = clantag_ref.custom_text,
        stealer_target = clantag_ref.stealer_target,
        native = nl.misc.main.in_game.clan_tag,
    }

    local cl_clanid = cvar.cl_clanid
    local get_net_channel_info = utils.get_vfunc(
        "engine.dll",
        "VEngineClient014",
        78,
        "void*(__thiscall*)(void*)"
    )
    local get_channel_latency = utils.get_vfunc(
        10,
        "float(__thiscall*)(void*, int)"
    )
    local last_text = nil
    local next_stealer_refresh = 0
    local was_enabled = false
    local animated_sync_state = {
        source_text = nil,
        source = "",
        scroll_length = 0,
        last_frame = "",
        offsets = {
        },
    }
    local get_custom_text

    local function normalize_mode(value)
        if value == MODE_ORIGINAL or value == 1 then
            return MODE_ORIGINAL
        end

        if value == MODE_CUSTOM or value == 2 then
            return MODE_CUSTOM
        end

        if value == MODE_REVERSE or value == 3 then
            return MODE_REVERSE
        end

        if value == MODE_STEALER or value == 4 then
            return MODE_STEALER
        end

        return MODE_ORIGINAL
    end

    local function normalize_custom_type(value)
        if value == CUSTOM_TYPE_STATIC or value == 2 then
            return CUSTOM_TYPE_STATIC
        end

        return CUSTOM_TYPE_ANIMATED
    end

    local function sanitize_text(value)
        if type(value) ~= "string" then
            return ""
        end

        value = value:gsub("%z", "")
        return value
    end

    local function set_tag(text)
        text = sanitize_text(text)
        if text == last_text then
            return
        end

        last_text = text
        common.set_clan_tag(text)
    end

    local function restore_tag()
        last_text = nil
        animated_sync_state.source_text = nil
        animated_sync_state.source = ""
        animated_sync_state.scroll_length = 0
        animated_sync_state.last_frame = ""
        for i = 1, #animated_sync_state.offsets do
            animated_sync_state.offsets[i] = nil
        end
        common.set_clan_tag("")

        if ref.native ~= nil then
            ref.native:override()
        end

        if cl_clanid ~= nil then
            cl_clanid:call(cl_clanid:string())
        end
    end

    local function get_original_text(reverse)
        local time = math.floor(globals.curtime * UPDATE_SPEED)
        local count = #ORIGINAL_ANIMATION
        local index = (time % count) + 1

        if reverse then
            index = count - (index - 1)
        end

        return ORIGINAL_ANIMATION[index]
    end

    local function seconds_to_ticks(value)
        local tickinterval = globals.tickinterval
        if type(tickinterval) ~= "number" or tickinterval <= 0 then
            return 1
        end

        return math.floor(value / tickinterval + 0.5)
    end

    local function refresh_custom_sync_state()
        local text = get_custom_text()
        local length = #text
        if length == 0 then
            text = CUSTOM_SYNC_DEFAULT_TEXT
            length = #text
        end

        animated_sync_state.source_text = text
        animated_sync_state.source = SCROLL_LEFT_PADDING .. text .. SCROLL_RIGHT_PADDING
        animated_sync_state.scroll_length = length + SCROLL_LENGTH_OFFSET
        animated_sync_state.last_frame = ""

        local offsets = animated_sync_state.offsets
        for i = 1, #offsets do
            offsets[i] = nil
        end

        local hold_offset = math.floor(animated_sync_state.scroll_length * 0.5)
        for offset = 0, animated_sync_state.scroll_length do
            if offset == hold_offset then
                for _ = 1, SCROLL_MID_HOLD_FRAMES do
                    offsets[#offsets + 1] = offset
                end
            else
                offsets[#offsets + 1] = offset
            end
        end
    end

    local function get_synced_scroll_text(text)
        return sanitize_text(text)
    end

    local function read_clan_from_resource(resource, player_index)
        if type(player_index) ~= "number" then
            return ""
        end

        if player_index < 0 or player_index > 128 then
            return ""
        end

        if resource == nil then
            return ""
        end

        local ok_clans, clans = pcall(function()
            return resource.m_szClan
        end)
        if not ok_clans then
            return ""
        end

        if clans == nil then
            return ""
        end

        local ok_value, value = pcall(function()
            return clans[player_index]
        end)
        if type(value) ~= "string" and player_index > 0 then
            ok_value, value = pcall(function()
                return clans[player_index - 1]
            end)
        end

        if not ok_value or type(value) ~= "string" then
            return ""
        end

        value = sanitize_text(value)
        value = value:gsub("^%s+", "")
        value = value:gsub("%s+$", "")

        return value
    end

    local function get_stolen_tag()
        if ref.stealer_target == nil then
            return ""
        end

        local selected = ref.stealer_target:get()
        if type(selected) ~= "number" then
            return ""
        end

        local player_index = clantag_ref.target_indices[selected]
        if type(player_index) ~= "number" or player_index <= 0 then
            player_index = clantag_ref.selected_player_index
        end

        if type(player_index) ~= "number" or player_index <= 0 then
            return ""
        end

        clantag_ref.selected_player_index = player_index

        local local_player = entity.get_local_player()
        if local_player == nil then
            return ""
        end

        local target = entity.get(player_index)
        local target_is_player = false
        if target ~= nil then
            local ok_target_is_player, is_player = pcall(target.is_player, target)
            target_is_player = ok_target_is_player and is_player == true
        end

        if target ~= nil and target_is_player then
            local from_target_resource = read_clan_from_resource(
                target:get_resource(),
                player_index
            )

            if from_target_resource ~= "" then
                clantag_ref.cached_player_tags[player_index] = from_target_resource
                return from_target_resource
            end
        end

        local from_player_resource = read_clan_from_resource(
            entity.get_player_resource(),
            player_index
        )
        if from_player_resource ~= "" then
            clantag_ref.cached_player_tags[player_index] = from_player_resource
            return from_player_resource
        end

        local cached_tag = clantag_ref.cached_player_tags[player_index]
        if type(cached_tag) == "string" and cached_tag ~= "" then
            return cached_tag
        end

        return ""
    end

    local function get_mode()
        if ref.mode == nil then
            return MODE_ORIGINAL
        end

        local ok_mode, value = pcall(ref.mode.get, ref.mode)
        if not ok_mode then
            return MODE_ORIGINAL
        end

        return normalize_mode(value)
    end

    local function get_custom_type()
        if ref.custom_type == nil then
            return CUSTOM_TYPE_ANIMATED
        end

        local ok_type, value = pcall(ref.custom_type.get, ref.custom_type)
        if not ok_type then
            return CUSTOM_TYPE_ANIMATED
        end

        return normalize_custom_type(value)
    end

    get_custom_text = function()
        if ref.custom_text == nil then
            return ""
        end

        local ok_text, value = pcall(ref.custom_text.get, ref.custom_text)
        if not ok_text then
            return ""
        end

        return sanitize_text(value)
    end

    local function apply_synced_custom_tag()
        local custom_text = get_custom_text()
        if custom_text == "" then
            custom_text = CUSTOM_SYNC_DEFAULT_TEXT
        end

        if animated_sync_state.source_text ~= custom_text then
            refresh_custom_sync_state()
        end

        local game_rules = entity.get_game_rules()
        if game_rules == nil then
            return
        end

        if ref.native ~= nil then
            ref.native:override(false)
        end

        local source = animated_sync_state.source
        local scroll_length = animated_sync_state.scroll_length
        if type(source) ~= "string" or source == "" or scroll_length <= 0 then
            return set_tag(custom_text)
        end

        local time_until_next_phase = game_rules.m_timeUntilNextPhaseStarts
        if type(time_until_next_phase) == "number" and time_until_next_phase > 0 then
            local offset = math.floor(scroll_length * 0.5) + 1
            local frame = source:sub(
                offset + SCROLL_VISIBLE_START,
                offset + SCROLL_VISIBLE_END
            )

            common.set_clan_tag(frame)
            animated_sync_state.last_frame = frame
            return
        end

        local net_channel = nil
        if get_net_channel_info ~= nil then
            local ok_channel, channel = pcall(get_net_channel_info)
            if ok_channel then
                net_channel = channel
            end
        end

        if net_channel == nil or get_channel_latency == nil then
            return
        end

        local ok_latency, latency = pcall(get_channel_latency, net_channel, 0)
        if not ok_latency or type(latency) ~= "number" then
            return
        end

        local tickcount = globals.tickcount
        if type(tickcount) ~= "number" then
            return
        end

        local offsets = animated_sync_state.offsets
        local step_ticks = seconds_to_ticks(0.3)
        local phase = (tickcount + seconds_to_ticks(latency)) / step_ticks
        local offset = (offsets[math.floor(phase % #offsets) + 1] or 0) + 1
        local frame = source:sub(
            offset + SCROLL_VISIBLE_START,
            offset + SCROLL_VISIBLE_END
        )

        if frame ~= animated_sync_state.last_frame then
            common.set_clan_tag(frame)
        end

        animated_sync_state.last_frame = frame
    end

    local function build_tag()
        local mode = get_mode()

        if mode == MODE_ORIGINAL then
            return get_original_text(false)
        end

        if mode == MODE_REVERSE then
            return "\u{202E}"
        end

        if mode == MODE_CUSTOM then
            local custom_text = get_custom_text()
            if get_custom_type() == CUSTOM_TYPE_STATIC then
                return custom_text
            end

            return get_synced_scroll_text(custom_text)
        end

        if mode == MODE_STEALER then
            if entity.get_local_player() == nil then
                return ""
            end

            if clantag_ref.refresh_targets ~= nil and globals.realtime >= next_stealer_refresh then
                clantag_ref.refresh_targets()
                next_stealer_refresh = globals.realtime + STEALER_REFRESH_DELAY
            end

            return get_stolen_tag()
        end

        return ""
    end

    local function on_net_update_end()
        if get_mode() == MODE_CUSTOM and get_custom_type() == CUSTOM_TYPE_ANIMATED then
            apply_synced_custom_tag()
            return
        end

        if animated_sync_state.source_text ~= nil then
            animated_sync_state.source_text = nil
            animated_sync_state.source = ""
            animated_sync_state.scroll_length = 0
            animated_sync_state.last_frame = ""
            for i = 1, #animated_sync_state.offsets do
                animated_sync_state.offsets[i] = nil
            end
        end

        if ref.native ~= nil then
            ref.native:override(false)
        end

        set_tag(build_tag())
    end

    local callbacks
    do
        local function on_enabled(item)
            local enabled = false
            if item ~= nil then
                local ok_enabled, value = pcall(item.get, item)
                enabled = ok_enabled and value == true
            end

            if enabled and clantag_ref.refresh_targets ~= nil and get_mode() == MODE_STEALER then
                clantag_ref.refresh_targets()
                next_stealer_refresh = globals.realtime + STEALER_REFRESH_DELAY
            end

            if enabled and ref.native ~= nil then
                ref.native:override(false)
            end

            events.net_update_end(on_net_update_end, enabled)
            events.shutdown(restore_tag, enabled)

            if not enabled and was_enabled then
                restore_tag()
            end

            was_enabled = enabled
        end

        if ref.enabled ~= nil then
            ref.enabled:set_callback(on_enabled, true)
        end

        if ref.custom_text ~= nil then
            ref.custom_text:set_callback(refresh_custom_sync_state, true)
        end
    end
end

local shared_logo
do
    local ref = misc_ref.shared_logo_enabled

    local HEARTBEAT_INTERVAL = 1.0
    local STALE_TIMEOUT = 2.0
    local PAYLOAD_ID = 0x3576975
    local PAYLOAD_ROLE_CLEAR = 0
    local PAYLOAD_ROLE_USER = 1
    local PAYLOAD_ROLE_ADMIN = 2
    local PAYLOAD_KEY = 0x697509
    local SECURITY_KEY = ".aesthetic|shared_logo"
    local USER_ICON_URL = "https://github.com/h3xcolor/icons/blob/main/user.png?raw=true"
    local ADMIN_ICON_URL = "https://github.com/h3xcolor/icons/blob/main/admin.png?raw=true"
    local ADMIN_USERNAMES = {
        epicgamer69 = true,
        shamelessl = true,
        h3xc0l0r = true,
    }

    local enabled = false
    local last_broadcast_time = 0
    local logo_user_data = {
    }

    local function is_admin_username()
        local username = common.get_username()
        if type(username) ~= "string" or username == "" then
            return false
        end

        return ADMIN_USERNAMES[username:lower()] == true
    end

    local function get_payload_role(is_admin)
        if is_admin == true then
            return PAYLOAD_ROLE_ADMIN
        end

        return PAYLOAD_ROLE_USER
    end

    local function get_role_icon(role)
        if role == PAYLOAD_ROLE_ADMIN then
            return ADMIN_ICON_URL
        end

        if role == PAYLOAD_ROLE_USER then
            return USER_ICON_URL
        end

        return nil
    end

    local function calculate_token(server_tick, role)
        local token = bit.bxor(server_tick, PAYLOAD_KEY)
        token = bit.bxor(token, PAYLOAD_ID)
        token = token + role * 131
        return bit.band(token, 0x7FFFFFFF)
    end

    local function seconds_to_ticks(seconds)
        local tickinterval = globals.tickinterval
        if type(tickinterval) ~= "number" or tickinterval <= 0 then
            return 1
        end

        return math.max(1, math.floor(seconds / tickinterval + 0.5))
    end

    local function normalize_xuid(xuid)
        if xuid == nil then
            return nil
        end

        xuid = tostring(xuid)
        if xuid == "" then
            return nil
        end

        return xuid
    end

    local function clear_applied_icons()
        local local_player = entity.get_local_player()
        local local_xuid = nil
        if local_player ~= nil then
            local_xuid = normalize_xuid(local_player:get_xuid())
            local_player:set_icon()
        end

        entity.get_players(false, true, function(player)
            local xuid = normalize_xuid(player:get_xuid())
            if xuid == nil then
                return
            end

            if logo_user_data[xuid] ~= nil or xuid == local_xuid then
                player:set_icon()
            end

            logo_user_data[xuid] = nil
        end)

        for xuid in pairs(logo_user_data) do
            logo_user_data[xuid] = nil
        end

        last_broadcast_time = 0
    end

    local function refresh_icons_after_clear()
        if entity.get_local_player() == nil then
            return
        end

        common.force_full_update()
    end

    local function schedule_disable_clear_retry()
        utils.execute_after(0, function()
            if enabled == true then
                return
            end

            clear_applied_icons()
            refresh_icons_after_clear()
        end)

        utils.execute_after(0.15, function()
            if enabled == true then
                return
            end

            clear_applied_icons()
            refresh_icons_after_clear()
        end)
    end

    local function broadcast_role(role)
        local server_tick = globals.server_tick
        if type(server_tick) ~= "number" then
            return
        end

        events.voice_message:call(function(buffer)
            buffer:write_bits(server_tick, 32)
            buffer:write_bits(calculate_token(server_tick, role), 32)
            buffer:write_bits(PAYLOAD_ID, 32)
            buffer:write_bits(role, 4)
            buffer:crypt(SECURITY_KEY)
        end)
    end

    local function on_voice_message(ctx)
        if type(ctx) ~= "userdata" or ctx.entity == nil or ctx.buffer == nil then
            return
        end

        local sender = ctx.entity
        local local_player = entity.get_local_player()
        local local_xuid = nil
        if local_player ~= nil then
            local_xuid = normalize_xuid(local_player:get_xuid())
        end

        local sender_xuid = normalize_xuid(sender:get_xuid())
        if sender_xuid == nil then
            return
        end

        if local_xuid ~= nil and sender_xuid == local_xuid then
            return
        end

        local buffer = ctx.buffer
        buffer:crypt(SECURITY_KEY)

        local server_tick = buffer:read_bits(32)
        local token = buffer:read_bits(32)
        local payload_id = buffer:read_bits(32)
        local role = buffer:read_bits(4)
        local is_admin = role == PAYLOAD_ROLE_ADMIN

        if payload_id ~= PAYLOAD_ID then
            return
        end

        if role ~= PAYLOAD_ROLE_CLEAR
            and role ~= PAYLOAD_ROLE_USER
            and role ~= PAYLOAD_ROLE_ADMIN then
            return
        end

        if type(server_tick) ~= "number" or token ~= calculate_token(server_tick, role) then
            return
        end

        local current_tick = globals.server_tick
        if type(current_tick) ~= "number" then
            return
        end

        local stale_ticks = seconds_to_ticks(STALE_TIMEOUT)
        if math.abs(current_tick - server_tick) > stale_ticks then
            return
        end

        if role == PAYLOAD_ROLE_CLEAR then
            logo_user_data[sender_xuid] = nil
            sender:set_icon()
            return
        end

        logo_user_data[sender_xuid] = {
            role = role,
            heartbeat = current_tick,
        }
    end

    local function on_net_update_end()
        local local_player = entity.get_local_player()
        if local_player == nil then
            return
        end

        local current_tick = globals.server_tick
        local current_realtime = globals.realtime
        if type(current_tick) ~= "number" then
            return
        end

        local local_xuid = normalize_xuid(local_player:get_xuid())
        if type(current_realtime) == "number"
            and local_xuid ~= nil
            and math.abs(current_realtime - last_broadcast_time) > HEARTBEAT_INTERVAL then
            local role = get_payload_role(is_admin_username())
            last_broadcast_time = current_realtime
            logo_user_data[local_xuid] = {
                role = role,
                heartbeat = current_tick,
            }
            broadcast_role(role)
        end

        local stale_ticks = seconds_to_ticks(STALE_TIMEOUT)
        local players_this_tick = {
        }

        entity.get_players(false, true, function(player)
            local xuid = normalize_xuid(player:get_xuid())
            if xuid == nil then
                return
            end

            players_this_tick[xuid] = true

            local data = logo_user_data[xuid]
            if data ~= nil or xuid == local_xuid then
                if data ~= nil and math.abs(current_tick - data.heartbeat) > stale_ticks then
                    logo_user_data[xuid] = nil
                    player:set_icon()
                    return
                end

                local role = data ~= nil and data.role or get_payload_role(is_admin_username())
                local icon = get_role_icon(role)
                if icon ~= nil then
                    player:set_icon(icon)
                else
                    player:set_icon()
                end
                return
            end
        end)

        for xuid in pairs(logo_user_data) do
            if players_this_tick[xuid] ~= true then
                logo_user_data[xuid] = nil
            end
        end
    end

    local function on_shutdown()
        if enabled == true then
            broadcast_role(PAYLOAD_ROLE_CLEAR)
        end

        clear_applied_icons()
        refresh_icons_after_clear()
    end

    local function on_enabled(item)
        local new_enabled = item ~= nil and item:get() == true
        local was_enabled = enabled

        events.voice_message(on_voice_message, new_enabled)
        events.net_update_end(on_net_update_end, new_enabled)
        events.shutdown(on_shutdown, new_enabled)

        if new_enabled ~= true and was_enabled == true then
            broadcast_role(PAYLOAD_ROLE_CLEAR)
        end

        enabled = new_enabled

        if new_enabled ~= true and was_enabled == true then
            clear_applied_icons()
            refresh_icons_after_clear()
            schedule_disable_clear_retry()
        end
    end

    if ref ~= nil then
        ref:set_callback(on_enabled, true)
    end
end

local trash_talk
do
    local ref = misc_ref.trash_talk_enabled

    local MISCLICK_CHANCE = 10
    local SEND_DELAY = 0.35

    local MISCLICK_MESSAGES = {
        "e1",
        "\u{0443}1",
    }

    local revenge_target = nil
    local next_send_time = 0
    local queue = {
    }

    local function reset_state()
        revenge_target = nil
        next_send_time = 0

        for i = 1, #queue do
            queue[i] = nil
        end
    end

    local function build_message()
        if utils.random_int(1, 100) <= MISCLICK_CHANCE then
            local index = utils.random_int(1, #MISCLICK_MESSAGES)
            return MISCLICK_MESSAGES[index]
        end

        return "1"
    end

    local function enqueue_message()
        queue[#queue + 1] = build_message()
    end

    local function on_round_start()
        revenge_target = nil
    end

    local function on_player_death(e)
        if e == nil then
            return
        end

        if type(e.userid) ~= "number" then
            return
        end

        if type(e.attacker) ~= "number" then
            return
        end

        local local_player = entity.get_local_player()
        if local_player == nil then
            return
        end

        local victim = entity.get(e.userid, true)
        if victim == nil then
            return
        end

        local attacker = entity.get(e.attacker, true)

        local local_index = local_player:get_index()
        local victim_index = victim:get_index()

        local attacker_index = 0
        if attacker ~= nil then
            attacker_index = attacker:get_index()
        end

        if attacker_index == local_index and victim_index ~= local_index then
            enqueue_message()

            if revenge_target ~= nil and victim_index == revenge_target then
                revenge_target = nil
            end

            return
        end

        if victim_index == local_index then
            if attacker_index > 0 and attacker_index ~= local_index then
                revenge_target = attacker_index
            else
                revenge_target = nil
            end
            return
        end

        if revenge_target ~= nil and victim_index == revenge_target then
            local killed_by_other = (
                attacker_index > 0
                and attacker_index ~= local_index
                and attacker_index ~= victim_index
            )

            if killed_by_other then
                enqueue_message()
            end

            revenge_target = nil
        end
    end

    local function on_net_update_start()
        local text = queue[1]
        if type(text) ~= "string" then
            return
        end

        if globals.realtime < next_send_time then
            return
        end

        utils.console_exec("say " .. text)
        table.remove(queue, 1)

        next_send_time = globals.realtime + SEND_DELAY
    end

    local callbacks
    do
        local function on_enabled(item)
            local enabled = false
            if item ~= nil then
                local ok_enabled, value = pcall(item.get, item)
                enabled = ok_enabled and value == true
            end

            if not enabled then
                reset_state()
            end

            events.round_start(on_round_start, enabled)
            events.player_death(on_player_death, enabled)
            events.net_update_start(on_net_update_start, enabled)
        end

        if ref ~= nil then
            ref:set_callback(on_enabled, true)
        end
    end
end

local no_fall_damage
do
    local MODE_DISABLED = "Disabled"
    local MODE_DEFAULT = "Default"
    local MODE_GAMESENSE = "Game\a95B806FFSense\aDEFAULT"

    local MIN_VELOCITY_Z = -500
    local TRACE_SHORT_LENGTH = 15
    local TRACE_LONG_LENGTH = 75
    local TRACE_RADIUS = 10
    local TRACE_POINTS = 8
    local MATH_TAU = math.pi * 2.0
    local TRACE_STEP = MATH_TAU / TRACE_POINTS

    local math_sin = math.sin
    local math_cos = math.cos

    local MOVETYPE_WALK = 2
    local FL_ONGROUND = 1
    local FL_DUCKING = 2
    local TRACE_DISTANCE = 1000
    local TRACE_MASK = 1
    local TRACE_OFFSET_Z = 9
    local LAND_DISTANCE_MIN = 9
    local LAND_DISTANCE_MAX = 11
    local DAMAGE_VELOCITY_Z = -580
    local WALKABLE_NORMAL_Z = 0.7
    local MAX_SIM_STEPS = 256

    local trace_down = vector(0, 0, TRACE_DISTANCE)
    local fallback_mins = vector(-16, -16, 0)
    local fallback_maxs = vector(16, 16, 54)
    local bit_band = bit.band
    local gravity = cvar.sv_gravity

    local no_fall_damage = {
        state = false,
    }

    local function normalize_mode(value)
        if value == MODE_DISABLED then
            return MODE_DISABLED
        end

        if value == 1 then
            return MODE_DISABLED
        end

        if value == MODE_DEFAULT then
            return MODE_DEFAULT
        end

        if value == 2 then
            return MODE_DEFAULT
        end

        if value == MODE_GAMESENSE then
            return MODE_GAMESENSE
        end

        if value == 3 then
            return MODE_GAMESENSE
        end

        if value == true then
            return MODE_DEFAULT
        end

        return MODE_DISABLED
    end

    local function get_mode()
        local mode_item = misc_ref.no_fall_damage_mode
        if mode_item == nil then
            return MODE_DISABLED
        end

        local ok_mode, mode_value = pcall(mode_item.get, mode_item)
        if not ok_mode then
            return MODE_DISABLED
        end

        return normalize_mode(mode_value)
    end

    function no_fall_damage:trace_fall(local_player, length)
        if local_player == nil then
            return false
        end

        local origin = local_player:get_origin()
        if origin == nil then
            return false
        end

        for angle = 0, MATH_TAU, TRACE_STEP do
            local sin_value = math_sin(angle)
            local cos_value = math_cos(angle)

            local x = origin.x + cos_value * TRACE_RADIUS
            local y = origin.y + sin_value * TRACE_RADIUS

            local start_pos = vector(x, y, origin.z)
            local end_pos = vector(x, y, origin.z - length)

            local trace = utils.trace_line(start_pos, end_pos, local_player)
            if trace ~= nil and trace.fraction ~= 1 then
                return true
            end
        end

        return false
    end

    local function is_valid_land_trace(trace)
        if trace == nil then
            return false
        end

        if trace.fraction == nil or trace.fraction >= 1 then
            return false
        end

        if trace.start_solid or trace.all_solid then
            return false
        end

        local plane = trace.plane
        if plane == nil then
            return false
        end

        local normal = plane.normal
        if normal == nil then
            return false
        end

        if type(normal.z) ~= "number" then
            return false
        end

        return normal.z >= WALKABLE_NORMAL_Z
    end

    local function get_land_trace(local_player, origin, flags)
        local trace_origin = vector(origin.x, origin.y, origin.z)
        if bit_band(flags, FL_DUCKING) == 0 then
            trace_origin.z = trace_origin.z + TRACE_OFFSET_Z
        end

        local mins = local_player.m_vecMins
        local maxs = local_player.m_vecMaxs
        if mins == nil or maxs == nil then
            mins = fallback_mins
            maxs = fallback_maxs
        end

        local trace = utils.trace_hull(
            trace_origin,
            trace_origin - trace_down,
            mins,
            maxs,
            local_player,
            TRACE_MASK
        )

        if not is_valid_land_trace(trace) then
            return nil
        end

        return trace
    end

    local function will_take_fall_damage(distance_to_ground, velocity_z)
        local tick_interval = globals.tickinterval
        local gravity_step = gravity:float() * tick_interval * 0.5
        local remaining_distance = distance_to_ground
        local simulated_velocity = velocity_z
        local step = 0

        while remaining_distance > LAND_DISTANCE_MAX do
            local velocity_half = simulated_velocity - gravity_step
            remaining_distance = remaining_distance + tick_interval * velocity_half
            simulated_velocity = velocity_half - gravity_step

            step = step + 1
            if step > MAX_SIM_STEPS then
                return false
            end
        end

        return simulated_velocity <= DAMAGE_VELOCITY_Z and remaining_distance >= LAND_DISTANCE_MIN
    end

    function no_fall_damage:update_default(cmd, local_player, velocity_z)
        if velocity_z >= MIN_VELOCITY_Z then
            self.state = false
            return
        end

        if self:trace_fall(local_player, TRACE_SHORT_LENGTH) then
            self.state = false
        elseif self:trace_fall(local_player, TRACE_LONG_LENGTH) then
            self.state = true
        end

        cmd.in_duck = self.state and 1 or 0
    end

    function no_fall_damage:update_gamesense(cmd, local_player, velocity_z)
        if local_player.m_MoveType ~= MOVETYPE_WALK then
            return
        end

        local flags = local_player.m_fFlags
        if type(flags) ~= "number" then
            return
        end

        if bit_band(flags, FL_ONGROUND) ~= 0 then
            return
        end

        local origin = local_player:get_origin()
        if origin == nil then
            return
        end

        local land_trace = get_land_trace(local_player, origin, flags)
        if land_trace == nil then
            return
        end

        local distance_to_ground = land_trace.fraction * TRACE_DISTANCE

        if velocity_z >= 0 or distance_to_ground >= LAND_DISTANCE_MAX then
            if not will_take_fall_damage(distance_to_ground, velocity_z) then
                return
            end

            cmd.in_duck = 1
            cmd.in_jump = 0
            return
        end

        if velocity_z < DAMAGE_VELOCITY_Z and distance_to_ground > LAND_DISTANCE_MIN then
            cmd.in_jump = 1
            cmd.in_duck = 0
        end
    end

    function no_fall_damage:update(cmd)
        local mode = get_mode()
        if mode == MODE_DISABLED then
            self.state = false
            return
        end

        if cmd == nil then
            self.state = false
            return
        end

        local local_player = entity.get_local_player()
        if local_player == nil or not local_player:is_alive() then
            self.state = false
            return
        end

        if grenade_throw_state.is_active() == true then
            self.state = false
            return
        end

        local velocity = local_player.m_vecVelocity
        if velocity == nil then
            self.state = false
            return
        end

        local velocity_z = velocity.z
        if type(velocity_z) ~= "number" then
            self.state = false
            return
        end

        if mode == MODE_DEFAULT then
            self:update_default(cmd, local_player, velocity_z)
            return
        end

        self.state = false
        self:update_gamesense(cmd, local_player, velocity_z)
    end

    local callback_enabled = false

    local function on_createmove(cmd)
        no_fall_damage:update(cmd)
    end

    local function set_callback_state(state)
        local enabled = state == true
        if callback_enabled == enabled then
            return
        end

        events.createmove(on_createmove, enabled)
        callback_enabled = enabled

        if not enabled then
            no_fall_damage.state = false
        end
    end

    local function sync_callback_state()
        local mode = get_mode()
        if mode == MODE_DISABLED then
            set_callback_state(false)
            return
        end

        set_callback_state(true)
    end

    local function on_mode_change()
        sync_callback_state()
    end

    if misc_ref.no_fall_damage_mode ~= nil then
        misc_ref.no_fall_damage_mode:set_callback(on_mode_change, true)
    end
end

local fast_ladder_move
do
    local MOVETYPE_LADDER = 9
    local WEAPON_TYPE_GRENADE = 9
    local MASK_PLAYERSOLID = 0x200400B
    local CONTENTS_LADDER = 0x20000000
    local LADDER_DISTANCE = 2
    local LADDER_LEAVE_PREDICT_TICKS = 4
    local LADDER_POST_EXIT_SHIFT_TIME = 0.1
    local DEFAULT_LADDER_POST_EXIT_SHIFT_TICKS = 3
    local LADDER_ASCEND_MIN_VELOCITY = 15
    local LADDER_EXIT_MIN_Z_DELTA = 1.5
    local LADDER_EXIT_COMMAND_GRACE = 2
    local LADDER_EXIT_MAX_CHOKE_PREDICT_BONUS = 6
    local LADDER_EXIT_SPEED_PREDICT_DIVISOR = 120
    local LADDER_EXIT_MAX_SPEED_PREDICT_BONUS = 4
    local LADDER_EXIT_MAX_PREDICT_TICKS = 14
    local LADDER_POST_EXIT_MAX_PREDICT_BONUS = 8
    local LADDER_EXIT_JUMP_SUPPRESS_TICKS = 2
    local LADDER_EXIT_STOP_TICK = 2
    local LADDER_PRE_EXIT_SPEED_TICK = 1
    local LADDER_PRE_EXIT_DISABLE_FAST_MOVE_TICKS = 2
    local LADDER_PRE_EXIT_BRAKE_TRIGGER_TICK = 2
    local LADDER_PRE_EXIT_BRAKE_HOLD_COMMANDS = 4
    local LADDER_PRE_EXIT_BRAKE_CHOKE_GRACE = 14
    local LADDER_POST_EXIT_STOP_TICKS = 2
    local LADDER_TOP_EXIT_MIN_Z_DELTA = 24
    local LADDER_TOP_EXIT_MAX_ABS_VELOCITY_Z = 45
    local LADDER_DEBUG = false

    local bit_band = bit.band
    local math_abs = math.abs
    local math_floor = math.floor
    local math_clamp = math.clamp
    local math_max = math.max
    local math_normalize_yaw = math.normalize_yaw
    local math_sqrt = math.sqrt
    local string_format = string.format
    local post_exit_shift_ticks = 0
    local post_exit_jump_suppress_ticks = 0
    local post_exit_stop_ticks = 0
    local pre_exit_brake_expire_command_number = 0
    local shift_hold_armed = false
    local shift_hold_exit_tick = 0
    local shift_hold_predict_ticks = 0
    local shift_hold_expire_command_number = 0
    local ladder_lowest_origin_z = nil
    local run_was_on_ladder = false
    local cached_ladder_view_pitch = nil
    local cached_ladder_view_yaw = nil
    local ladder_jump_fix_enabled = true
    local ladder_debug_state = {
        was_armed = false,
        arm_command_number = 0,
        brake_command_number = 0,
        exit_command_number = 0,
        post_exit_command_number = 0,
    }

    local function get_flag_number(value)
        if value == true or value == 1 then
            return 1
        end

        return 0
    end

    local function get_command_number(cmd)
        if cmd == nil then
            return 0
        end

        local command_number = cmd.command_number
        if type(command_number) ~= "number" then
            return 0
        end

        return command_number
    end

    local function log_ladder_debug(text, ...)
        if LADDER_DEBUG ~= true then
            return
        end

        local message = string_format("[ladder dbg] " .. text, ...)
        print(message)
    end

    local function reset_jump_fix_state()
        post_exit_shift_ticks = 0
        post_exit_jump_suppress_ticks = 0
        post_exit_stop_ticks = 0
        pre_exit_brake_expire_command_number = 0
        shift_hold_armed = false
        shift_hold_exit_tick = 0
        shift_hold_predict_ticks = 0
        shift_hold_expire_command_number = 0
        ladder_lowest_origin_z = nil
        run_was_on_ladder = false
        cached_ladder_view_pitch = nil
        cached_ladder_view_yaw = nil
        ladder_debug_state.was_armed = false
        ladder_debug_state.arm_command_number = 0
        ladder_debug_state.brake_command_number = 0
        ladder_debug_state.exit_command_number = 0
        ladder_debug_state.post_exit_command_number = 0
    end

    local function is_throwing_grenade(weapon)
        if weapon == nil then
            return false
        end

        local weapon_info = weapon:get_weapon_info()
        if weapon_info == nil or weapon_info.weapon_type ~= WEAPON_TYPE_GRENADE then
            return false
        end

        local throw_time = weapon.m_fThrowTime
        if throw_time == nil or throw_time == 0 then
            return false
        end

        return true
    end

    local function is_pressed(value)
        if value == true then
            return true
        end

        if type(value) == "number" and value ~= 0 then
            return true
        end

        return false
    end

    local function get_axis_value(positive_pressed, negative_pressed, analog_value)
        if type(analog_value) == "number" and analog_value ~= 0 then
            return analog_value
        end

        if positive_pressed and not negative_pressed then
            return 1
        end

        if negative_pressed and not positive_pressed then
            return -1
        end

        return 0
    end

    local function cache_ladder_view_angles(cmd)
        if cmd == nil or cmd.view_angles == nil then
            return
        end

        if type(cmd.view_angles.x) ~= "number" or type(cmd.view_angles.y) ~= "number" then
            return
        end

        cached_ladder_view_pitch = cmd.view_angles.x
        cached_ladder_view_yaw = cmd.view_angles.y
    end

    local function apply_cached_ladder_view_angles(cmd)
        if cmd == nil or cmd.view_angles == nil then
            return
        end

        if type(cached_ladder_view_pitch) ~= "number" or type(cached_ladder_view_yaw) ~= "number" then
            return
        end

        cmd.view_angles.x = cached_ladder_view_pitch
        cmd.view_angles.y = cached_ladder_view_yaw
    end

    local function update_ladder_movement(cmd, local_player)
        if cmd.view_angles ~= nil then
            cmd.view_angles.y = math_floor(0.5 + cmd.view_angles.y)
        end

        local ladder_normal = local_player.m_vecLadderNormal
        if ladder_normal == nil or ladder_normal:lengthsqr() == 0 then
            return
        end

        local camera_angles = render.camera_angles()
        if camera_angles == nil then
            return
        end

        local ladder_angles = ladder_normal:angles()
        local delta_yaw = math_normalize_yaw(ladder_angles.y - camera_angles.y + 180)
        local delta_pitch = math_clamp(ladder_angles.x - camera_angles.x, -89, 89)

        local abs_yaw = math_abs(delta_yaw)

        local pitch = 89
        local yaw_offset = -90

        local is_looking_down = delta_pitch < -45
        local is_looking_to_right = delta_yaw > 0

        local forward_axis = get_axis_value(
            is_pressed(cmd.in_forward),
            is_pressed(cmd.in_back),
            cmd.forwardmove
        )
        local side_axis = get_axis_value(
            is_pressed(cmd.in_moveright),
            is_pressed(cmd.in_moveleft),
            cmd.sidemove
        )
        if forward_axis == 0 and side_axis == 0 then
            return
        end

        local use_side_mode = abs_yaw > 70 and abs_yaw < 135
        if use_side_mode then
            if forward_axis ~= 0 or side_axis == 0 then
                return
            end

            local is_sidemove = side_axis > 0
            if not is_looking_to_right then
                yaw_offset = -yaw_offset
            end

            if is_looking_to_right then
                is_sidemove = not is_sidemove
            end

            cmd.in_back = is_sidemove and 1 or 0
            cmd.in_forward = is_sidemove and 0 or 1

            if is_looking_to_right then
                is_sidemove = not is_sidemove
            end

            cmd.in_moveleft = is_sidemove and 1 or 0
            cmd.in_moveright = is_sidemove and 0 or 1

            cmd.view_angles.x = pitch
            cmd.view_angles.y = math_normalize_yaw(ladder_angles.y + yaw_offset)
            cache_ladder_view_angles(cmd)
            return
        end

        if side_axis ~= 0 or forward_axis == 0 then
            return
        end

        local is_forwardmove = forward_axis > 0
        if not is_looking_to_right then
            yaw_offset = -yaw_offset
        end

        if not is_looking_down then
            is_forwardmove = not is_forwardmove
        end

        cmd.in_back = is_forwardmove and 0 or 1
        cmd.in_forward = is_forwardmove and 1 or 0

        if not is_looking_to_right then
            is_forwardmove = not is_forwardmove
        end

        cmd.in_moveleft = is_forwardmove and 1 or 0
        cmd.in_moveright = is_forwardmove and 0 or 1

        cmd.view_angles.x = pitch
        cmd.view_angles.y = math_normalize_yaw(ladder_angles.y + yaw_offset)
        cache_ladder_view_angles(cmd)
    end

    local function is_exploit_active()
        if rage == nil or rage.exploit == nil then
            return false
        end

        local ok_exploit, exploit_value = pcall(rage.exploit.get, rage.exploit)
        if not ok_exploit or type(exploit_value) ~= "number" then
            return false
        end

        return exploit_value > 0
    end

    local function get_choked_commands(cmd)
        if cmd == nil then
            return 0
        end

        local choked_commands = cmd.choked_commands
        if type(choked_commands) ~= "number" then
            return 0
        end

        return math_clamp(choked_commands, 0, 62)
    end

    local function get_velocity_speed(velocity)
        if velocity == nil then
            return 0
        end

        local speed_sqr = velocity:lengthsqr()
        if type(speed_sqr) ~= "number" or speed_sqr <= 0 then
            return 0
        end

        return math_sqrt(speed_sqr)
    end

    local function get_ladder_exit_predict_ticks(cmd, velocity)
        local predict_ticks = LADDER_LEAVE_PREDICT_TICKS
        if not is_exploit_active() then
            predict_ticks = predict_ticks + math_clamp(
                get_choked_commands(cmd),
                0,
                LADDER_EXIT_MAX_CHOKE_PREDICT_BONUS
            )
            predict_ticks = predict_ticks + math_clamp(
                math_floor(get_velocity_speed(velocity) / LADDER_EXIT_SPEED_PREDICT_DIVISOR),
                0,
                LADDER_EXIT_MAX_SPEED_PREDICT_BONUS
            )
        end

        return math_clamp(predict_ticks, 1, LADDER_EXIT_MAX_PREDICT_TICKS)
    end

    local function get_post_exit_shift_ticks()
        local tick_interval = globals.tickinterval
        if type(tick_interval) ~= "number" or tick_interval <= 0 then
            return DEFAULT_LADDER_POST_EXIT_SHIFT_TICKS
        end

        local tick_count = math_floor(LADDER_POST_EXIT_SHIFT_TIME / tick_interval + 0.5)
        if not is_exploit_active() then
            tick_count = tick_count + math_clamp(
                shift_hold_predict_ticks - LADDER_LEAVE_PREDICT_TICKS + 1,
                1,
                LADDER_POST_EXIT_MAX_PREDICT_BONUS
            )
        end

        return math_clamp(tick_count, 1, 32)
    end

    local function get_player_bounds(player, simulation_ctx)
        if simulation_ctx ~= nil then
            local mins = simulation_ctx.obb_mins
            local maxs = simulation_ctx.obb_maxs
            if mins ~= nil and maxs ~= nil then
                return mins, maxs
            end
        end

        local mins = player.m_vecMins
        local maxs = player.m_vecMaxs
        if mins == nil or maxs == nil then
            return nil, nil
        end

        return mins, maxs
    end

    local function has_ladder_contact(player, origin, simulation_ctx, ladder_normal)
        if player == nil or origin == nil or ladder_normal == nil then
            return false
        end

        if ladder_normal:lengthsqr() == 0 then
            return false
        end

        local mins, maxs = get_player_bounds(player, simulation_ctx)
        if mins == nil or maxs == nil then
            return false
        end

        local ladder_trace = utils.trace_hull(
            origin,
            origin - ladder_normal * LADDER_DISTANCE,
            mins,
            maxs,
            player,
            MASK_PLAYERSOLID
        )
        if ladder_trace == nil then
            return false
        end

        local contents = ladder_trace.contents
        if type(contents) ~= "number" then
            return false
        end

        return bit_band(contents, CONTENTS_LADDER) ~= 0
    end

    local function will_leave_ladder_soon(player, cmd)
        if player == nil then
            return false, 0, 0
        end

        local velocity = player.m_vecVelocity
        if velocity == nil then
            return false, 0, 0
        end

        local velocity_z = velocity.z
        if type(velocity_z) ~= "number" or velocity_z <= LADDER_ASCEND_MIN_VELOCITY then
            return false, 0, 0
        end

        local predict_ticks = get_ladder_exit_predict_ticks(cmd, velocity)

        local ladder_normal = player.m_vecLadderNormal
        if ladder_normal == nil or ladder_normal:lengthsqr() == 0 then
            return false, predict_ticks, 0
        end

        local current_origin = player:get_origin()
        if current_origin == nil then
            return false, predict_ticks, 0
        end

        local current_z = current_origin.z
        if type(current_z) ~= "number" then
            return false, predict_ticks, 0
        end

        if not has_ladder_contact(player, current_origin, nil, ladder_normal) then
            return true, predict_ticks, 1
        end

        local tick_interval = globals.tickinterval
        if type(tick_interval) ~= "number" or tick_interval <= 0 then
            tick_interval = 1 / 64
        end

        for predict_tick = 1, predict_ticks do
            local predict_origin = current_origin + velocity * (tick_interval * predict_tick)
            local predict_z = predict_origin.z
            if type(predict_z) == "number"
                and predict_z >= current_z + LADDER_EXIT_MIN_Z_DELTA
                and not has_ladder_contact(player, predict_origin, nil, ladder_normal) then
                return true, predict_ticks, predict_tick
            end
        end

        return false, predict_ticks, 0
    end

    local function apply_post_exit_shift(cmd)
        local had_post_exit = post_exit_shift_ticks > 0
        if post_exit_shift_ticks > 0 then
            post_exit_shift_ticks = post_exit_shift_ticks - 1
            cmd.in_speed = 1
        end



        if post_exit_jump_suppress_ticks > 0 then
            post_exit_jump_suppress_ticks = post_exit_jump_suppress_ticks - 1
            cmd.in_jump = 0
            cmd.upmove = 0
        end

        if post_exit_stop_ticks > 0 then
            post_exit_stop_ticks = post_exit_stop_ticks - 1
            cmd.forwardmove = 0
            cmd.sidemove = 0
            cmd.in_forward = 0
            cmd.in_back = 0
            cmd.in_moveleft = 0
            cmd.in_moveright = 0
        end

        if had_post_exit then
            local command_number = get_command_number(cmd)
            if ladder_debug_state.post_exit_command_number ~= command_number then
                log_ladder_debug(
                    "post cmd=%d shift_left=%d jump_suppress=%d stop_left=%d jump=%d up=%.1f fwd=%.1f side=%.1f block=%d",
                    command_number,
                    post_exit_shift_ticks,
                    post_exit_jump_suppress_ticks,
                    post_exit_stop_ticks,
                    get_flag_number(cmd.in_jump),
                    cmd.upmove or 0,
                    cmd.forwardmove or 0,
                    cmd.sidemove or 0,
                    cmd.block_movement or 0
                )
                ladder_debug_state.post_exit_command_number = command_number
            end
        end
    end

    local function apply_ladder_exit_brake(cmd)
        local exit_tick = shift_hold_exit_tick
        local command_number = get_command_number(cmd)
        if ladder_debug_state.brake_command_number ~= command_number then
            local jump_before = get_flag_number(cmd.in_jump)
            local velocity = nil
            local speed = 0
            local velocity_z = 0
            local local_player = entity.get_local_player()
            if local_player ~= nil then
                velocity = local_player.m_vecVelocity
                speed = get_velocity_speed(velocity)
                if velocity ~= nil and type(velocity.z) == "number" then
                    velocity_z = velocity.z
                end
            end

            log_ladder_debug(
                "brake cmd=%d exit_tick=%d predict=%d choke=%d latch=%d jump=%d up=%.1f speed=%.1f velz=%.1f fwd=%.1f side=%.1f",
                command_number,
                exit_tick,
                shift_hold_predict_ticks,
                get_choked_commands(cmd),
                math_max(pre_exit_brake_expire_command_number - command_number, 0),
                jump_before,
                cmd.upmove or 0,
                speed,
                velocity_z,
                cmd.forwardmove or 0,
                cmd.sidemove or 0
            )
            ladder_debug_state.brake_command_number = command_number
        end

        cmd.in_jump = 0
        cmd.upmove = 0
    end

    local function on_createmove_run(cmd)
        if ladder_jump_fix_enabled ~= true then
            run_was_on_ladder = false
            return
        end

        local local_player = entity.get_local_player()
        if local_player == nil or not local_player:is_alive() then
            reset_jump_fix_state()
            return
        end

        local is_on_ladder = local_player.m_MoveType == MOVETYPE_LADDER
        if run_was_on_ladder and not is_on_ladder then
            local is_matching_command = shift_hold_armed
            local command_number = get_command_number(cmd)
            local velocity = local_player.m_vecVelocity
            local velocity_z = 0
            if velocity ~= nil and type(velocity.z) == "number" then
                velocity_z = velocity.z
            end
            local origin = local_player:get_origin()
            local origin_z = nil
            if origin ~= nil and type(origin.z) == "number" then
                origin_z = origin.z
            end
            local climbed_z_delta = 0
            if type(origin_z) == "number" and type(ladder_lowest_origin_z) == "number" then
                climbed_z_delta = origin_z - ladder_lowest_origin_z
            end
            local is_top_exit = type(origin_z) == "number"
                and type(ladder_lowest_origin_z) == "number"
                and climbed_z_delta >= LADDER_TOP_EXIT_MIN_Z_DELTA
                and math_abs(velocity_z) <= LADDER_TOP_EXIT_MAX_ABS_VELOCITY_Z

            if command_number ~= 0 and shift_hold_expire_command_number ~= 0 then
                is_matching_command = command_number <= shift_hold_expire_command_number
            end

            local should_apply_exit_fix = is_matching_command and is_top_exit
            if should_apply_exit_fix then
                post_exit_shift_ticks = get_post_exit_shift_ticks()
                post_exit_jump_suppress_ticks = LADDER_EXIT_JUMP_SUPPRESS_TICKS
                if not is_exploit_active() then
                    post_exit_stop_ticks = LADDER_POST_EXIT_STOP_TICKS
                end
            end

            if ladder_debug_state.exit_command_number ~= command_number then
                log_ladder_debug(
                    "exit cmd=%d matched=%d post=%d jump_suppress=%d predict=%d exit_tick=%d speed=%.1f velz=%.1f top=%d dz=%.1f",
                    command_number,
                    get_flag_number(should_apply_exit_fix),
                    post_exit_shift_ticks,
                    post_exit_jump_suppress_ticks,
                    shift_hold_predict_ticks,
                    shift_hold_exit_tick,
                    get_velocity_speed(velocity),
                    velocity_z,
                    get_flag_number(is_top_exit),
                    climbed_z_delta
                )
                ladder_debug_state.exit_command_number = command_number
            end
        end

        run_was_on_ladder = is_on_ladder

        if not is_on_ladder then
            shift_hold_armed = false
            shift_hold_exit_tick = 0
            shift_hold_predict_ticks = 0
            shift_hold_expire_command_number = 0
            ladder_lowest_origin_z = nil
            pre_exit_brake_expire_command_number = 0
            ladder_debug_state.was_armed = false
        end
    end

    local function on_createmove(cmd)
        local local_player = entity.get_local_player()
        if local_player == nil or not local_player:is_alive() then
            reset_jump_fix_state()
            return
        end

        if grenade_throw_state.is_active() == true then
            return
        end

        local move_type = local_player.m_MoveType
        if move_type ~= MOVETYPE_LADDER then
            if ladder_jump_fix_enabled then
                apply_post_exit_shift(cmd)
                if post_exit_shift_ticks <= 0 then
                    cached_ladder_view_pitch = nil
                    cached_ladder_view_yaw = nil
                end
            else
                post_exit_shift_ticks = 0
                post_exit_jump_suppress_ticks = 0
                post_exit_stop_ticks = 0
                cached_ladder_view_pitch = nil
                cached_ladder_view_yaw = nil
            end
            pre_exit_brake_expire_command_number = 0
            return
        end

        run_was_on_ladder = true
        post_exit_shift_ticks = 0
        post_exit_jump_suppress_ticks = 0
        post_exit_stop_ticks = 0
        local origin = local_player:get_origin()
        if origin ~= nil and type(origin.z) == "number" then
            local origin_z = origin.z
            if type(ladder_lowest_origin_z) ~= "number" or origin_z < ladder_lowest_origin_z then
                ladder_lowest_origin_z = origin_z
            end
        end
        local command_number = get_command_number(cmd)
        if ladder_jump_fix_enabled then
            local predict_ticks = 0
            local exit_tick = 0
            local predicted_arm = false
            local keep_armed = command_number ~= 0
                and shift_hold_expire_command_number ~= 0
                and command_number <= shift_hold_expire_command_number
            local keep_brake_armed = command_number ~= 0
                and pre_exit_brake_expire_command_number ~= 0
                and command_number <= pre_exit_brake_expire_command_number

            predicted_arm, predict_ticks, exit_tick = will_leave_ladder_soon(local_player, cmd)
            if predicted_arm then
                shift_hold_armed = true
                shift_hold_exit_tick = exit_tick
                shift_hold_predict_ticks = predict_ticks
                if exit_tick > 0 and exit_tick <= LADDER_PRE_EXIT_BRAKE_TRIGGER_TICK then
                    pre_exit_brake_expire_command_number = math_max(
                        pre_exit_brake_expire_command_number,
                        command_number + math_max(
                            predict_ticks + LADDER_PRE_EXIT_BRAKE_CHOKE_GRACE,
                            LADDER_PRE_EXIT_BRAKE_HOLD_COMMANDS
                        )
                    )
                end
                if command_number ~= 0 then
                    shift_hold_expire_command_number = math_max(
                        shift_hold_expire_command_number,
                        command_number + predict_ticks + LADDER_EXIT_COMMAND_GRACE
                    )
                else
                    shift_hold_expire_command_number = 0
                end
            elseif keep_armed or keep_brake_armed then
                shift_hold_armed = true
                shift_hold_exit_tick = 0
            else
                shift_hold_exit_tick = 0
                shift_hold_armed = false
                shift_hold_predict_ticks = 0
                shift_hold_expire_command_number = 0
                pre_exit_brake_expire_command_number = 0
            end
        else
            shift_hold_armed = false
            shift_hold_exit_tick = 0
            shift_hold_predict_ticks = 0
            shift_hold_expire_command_number = 0
            pre_exit_brake_expire_command_number = 0
        end

        if shift_hold_armed then
            if ladder_debug_state.was_armed ~= true then
                local velocity = local_player.m_vecVelocity
                local velocity_z = 0
                if velocity ~= nil and type(velocity.z) == "number" then
                    velocity_z = velocity.z
                end

                log_ladder_debug(
                    "arm cmd=%d choke=%d predict=%d exit_tick=%d jump=%d speed=%.1f velz=%.1f fwd=%.1f side=%.1f",
                    command_number,
                    get_choked_commands(cmd),
                    shift_hold_predict_ticks,
                    shift_hold_exit_tick,
                    get_flag_number(cmd.in_jump),
                    get_velocity_speed(velocity),
                    velocity_z,
                    cmd.forwardmove or 0,
                    cmd.sidemove or 0
                )
                ladder_debug_state.arm_command_number = command_number
            end
        elseif ladder_debug_state.was_armed == true and ladder_debug_state.arm_command_number ~= command_number then
            log_ladder_debug(
                "disarm cmd=%d choke=%d jump=%d up=%.1f fwd=%.1f side=%.1f",
                command_number,
                get_choked_commands(cmd),
                get_flag_number(cmd.in_jump),
                cmd.upmove or 0,
                cmd.forwardmove or 0,
                cmd.sidemove or 0
            )
        end
        ladder_debug_state.was_armed = shift_hold_armed

        local is_pre_exit_brake_active = command_number ~= 0
            and pre_exit_brake_expire_command_number ~= 0
            and command_number <= pre_exit_brake_expire_command_number
        if not is_pre_exit_brake_active and command_number ~= 0 then
            pre_exit_brake_expire_command_number = 0
        end
        local should_apply_pre_exit_speed = is_pre_exit_brake_active
            or shift_hold_exit_tick > 0 and shift_hold_exit_tick <= LADDER_PRE_EXIT_SPEED_TICK

        local weapon = local_player:get_player_weapon()
        if weapon == nil then
            if should_apply_pre_exit_speed then
                cmd.in_speed = 1
            end
            return
        end

        if is_throwing_grenade(weapon) then
            if should_apply_pre_exit_speed then
                cmd.in_speed = 1
            end
            return
        end

        if should_apply_pre_exit_speed then
            cmd.in_speed = 1
        end

        update_ladder_movement(cmd, local_player)
    end

    local callbacks
    do
        local function on_jump_fix_enabled(item)
            local enabled = true
            if item ~= nil then
                local ok_enabled, value = pcall(item.get, item)
                enabled = ok_enabled and value == true
            end

            ladder_jump_fix_enabled = enabled
            if not enabled then
                reset_jump_fix_state()
            end
        end

        local function on_enabled(item)
            local enabled = false
            if item ~= nil then
                local ok_enabled, value = pcall(item.get, item)
                enabled = ok_enabled and value == true
            end

            events.createmove(on_createmove, enabled)
            events.createmove_run(on_createmove_run, enabled)

            if not enabled then
                reset_jump_fix_state()
            end
        end

        if misc_ref.fast_ladder_move ~= nil then
            misc_ref.fast_ladder_move:set_callback(on_enabled, true)
        end
        if misc_ref.fast_ladder_jump_fix ~= nil then
            misc_ref.fast_ladder_jump_fix:set_callback(on_jump_fix_enabled, true)
        end
    end
end

local duck_collision
do
    local FL_ONGROUND = 1
    local AIR_PREDICT_TICKS = 12
    local GROUND_PREDICT_TICKS = 16
    local MIN_HEIGHT_DELTA = 4
    local MIN_VERTICAL_VELOCITY_DELTA = 24
    local bit_band = bit.band

    local function is_button_down(value)
        if value == true then
            return true
        end

        return type(value) == "number" and value ~= 0
    end

    local function is_on_ground(flags)
        return type(flags) == "number" and bit_band(flags, FL_ONGROUND) ~= 0
    end

    local function create_simulation(local_player, cmd, should_duck)
        cmd.in_duck = should_duck
        return local_player:simulate_movement()
    end

    local function should_duck_for_spot(local_player, cmd, predict_ticks)
        local original_duck = cmd.in_duck
        local duck_sim = create_simulation(local_player, cmd, true)
        if duck_sim == nil then
            cmd.in_duck = original_duck
            return false
        end

        local stand_sim = create_simulation(local_player, cmd, false)
        if stand_sim == nil then
            cmd.in_duck = original_duck
            return false
        end

        local did_duck_hit_collision = false
        local did_stand_hit_collision = false
        local should_duck = false

        for _ = 1, predict_ticks do
            duck_sim:think(1)
            stand_sim:think(1)

            local duck_origin = duck_sim.origin
            local stand_origin = stand_sim.origin
            if duck_origin == nil or stand_origin == nil then
                cmd.in_duck = original_duck
                return false
            end

            local duck_flags = duck_sim.flags
            local stand_flags = stand_sim.flags
            local duck_on_ground = is_on_ground(duck_flags)
            local stand_on_ground = is_on_ground(stand_flags)
            local height_delta = duck_origin.z - stand_origin.z
            local did_duck_hit_air_collision = duck_on_ground ~= true and duck_sim.did_hit_collision == true
            local did_stand_hit_air_collision = stand_on_ground ~= true and stand_sim.did_hit_collision == true
            did_duck_hit_collision = did_duck_hit_collision or did_duck_hit_air_collision
            did_stand_hit_collision = did_stand_hit_collision or did_stand_hit_air_collision

            if did_stand_hit_collision then
                if did_duck_hit_collision ~= true then
                    should_duck = true
                    break
                end

                if height_delta >= MIN_HEIGHT_DELTA then
                    should_duck = true
                    break
                end

                local duck_velocity = duck_sim.velocity
                local stand_velocity = stand_sim.velocity
                if duck_velocity ~= nil and stand_velocity ~= nil then
                    if duck_velocity.z >= stand_velocity.z + MIN_VERTICAL_VELOCITY_DELTA then
                        should_duck = true
                        break
                    end
                end
            end

            if duck_on_ground and stand_on_ground then
                should_duck = height_delta >= MIN_HEIGHT_DELTA
                break
            end
        end

        cmd.in_duck = original_duck
        return should_duck
    end

    local function on_createmove(cmd)
        local local_player = entity.get_local_player()
        if local_player == nil or not local_player:is_alive() then
            return
        end

        if grenade_throw_state.is_active() == true then
            return
        end

        local flags = local_player.m_fFlags
        if type(flags) ~= "number" then
            return
        end

        local is_player_on_ground = is_on_ground(flags)
        local is_jump_down = is_button_down(cmd.in_jump)
        local is_duck_down = is_button_down(cmd.in_duck)

        if is_player_on_ground then
            if is_duck_down or is_jump_down ~= true then
                return
            end

            if should_duck_for_spot(local_player, cmd, GROUND_PREDICT_TICKS) then
                cmd.in_duck = true
            end
            return
        end

        if is_duck_down then
            return
        end

        local is_hit_wall_with_duck = false
        do
            local sim_ctx = local_player:simulate_movement()
            if sim_ctx ~= nil then
                cmd.in_duck = true
                sim_ctx:think(1)

                local sim_flags = sim_ctx.flags
                is_hit_wall_with_duck = (
                    type(sim_flags) == "number"
                    and bit_band(sim_flags, FL_ONGROUND) == 0
                    and sim_ctx.did_hit_collision == true
                )
            end
        end

        local is_hit_wall_without_duck = false
        do
            cmd.in_duck = false
            local sim_ctx = local_player:simulate_movement()
            if sim_ctx ~= nil then
                sim_ctx:think(1)

                local sim_flags = sim_ctx.flags
                is_hit_wall_without_duck = (
                    type(sim_flags) == "number"
                    and bit_band(sim_flags, FL_ONGROUND) == 0
                    and sim_ctx.did_hit_collision == true
                )
            end
        end

        if not is_hit_wall_with_duck and is_hit_wall_without_duck then
            cmd.in_duck = true
            return
        end

        if is_jump_down ~= true then
            return
        end

        if should_duck_for_spot(local_player, cmd, AIR_PREDICT_TICKS) then
            cmd.in_duck = true
        end
    end

    local callbacks
    do
        local function on_enabled(item)
            local enabled = false
            if item ~= nil then
                local ok_enabled, value = pcall(item.get, item)
                enabled = ok_enabled and value == true
            end

            events.createmove(on_createmove, enabled)
        end

        if misc_ref.duck_collision ~= nil then
            misc_ref.duck_collision:set_callback(on_enabled, true)
        end
    end
end

local edge_stop
do
    local function on_createmove(cmd)
        local local_player = entity.get_local_player()
        if local_player == nil or not local_player:is_alive() then
            return
        end

        if grenade_throw_state.is_active() == true then
            return
        end

        local simulation_ctx = local_player:simulate_movement()
        if simulation_ctx == nil then
            return
        end

        simulation_ctx:think(5)

        local velocity = simulation_ctx.velocity
        if velocity == nil then
            return
        end

        local velocity_z = velocity.z
        if type(velocity_z) ~= "number" then
            return
        end

        if velocity_z < 0 then
            cmd.block_movement = 2
        end
    end

    local callbacks
    do
        local function on_enabled(item)
            local enabled = false
            if item ~= nil then
                local ok_enabled, value = pcall(item.get, item)
                enabled = ok_enabled and value == true
            end

            events.createmove(on_createmove, enabled)
        end

        if misc_ref.edge_stop ~= nil then
            misc_ref.edge_stop:set_callback(on_enabled, true)
        end
    end
end

