    end

    local get_absolute_angles = nil
    local set_absolute_angles = nil
    local setup_bones = nil
    local setup_bones_attachment_helper = nil
    local invalidate_physics_recursive = nil
    local native_get_client_entity = nil
    local native_set_interpolation_amount = nil
    local studio_hdr_offset = nil
    local varmap_origin_offset = DEFAULT_ORIGIN_OFFSET

    if ffi_ready then
        local address = utils.opcode_scan("client.dll", "56 8B F1 E8 ? ? ? ? 8D 86 ? ? ? ? 5E C3 8B 41")
        if address ~= nil then
            get_absolute_angles = ffi.cast("float*(__thiscall*)(void*)", address)
        end

        address = utils.opcode_scan("client.dll",
            "55 8B EC 83 E4 ? 83 EC ? 53 56 57 8B F1 E8 ? ? ? ? 8B 7D ? F3 0F 10 07")
        if address ~= nil then
            set_absolute_angles = ffi.cast("void(__thiscall*)(void*, float*)", address)
        end

        address = utils.opcode_scan("client.dll", "55 8B EC 83 E4 ? B8 ? ? ? ? E8 ? ? ? ? 56 57 8B F9 8B 0D")
        if address ~= nil then
            setup_bones = ffi.cast("bool(__thiscall*)(void*, matrix3x4_t*, int, int, float)", address)
        end

        address = utils.opcode_scan("client.dll", "55 8B EC 83 EC 48 53 8B 5D 08 89 4D F4")
        if address ~= nil then
            setup_bones_attachment_helper = ffi.cast("void(__thiscall*)(void*, void*)", address)
        end

        address = utils.opcode_scan("client.dll", "55 8B EC 83 E4 F8 83 EC 0C 53 8B 5D 08 8B C3 56 83 E0 04")
        if address ~= nil then
            invalidate_physics_recursive = ffi.cast("void(__thiscall*)(void*, int)", address)
        end

        local ok_get_client_entity, get_client_entity_vfunc = pcall(
            utils.get_vfunc,
            "client.dll",
            "VClientEntityList003",
            3,
            "void*(__thiscall*)(void*, int)"
        )
        if ok_get_client_entity then
            native_get_client_entity = get_client_entity_vfunc
        end

        local ok_set_interpolation_amount, set_interpolation_amount_vfunc = pcall(
            utils.get_vfunc,
            2,
            "void(__thiscall*)(void*, float)"
        )
        if ok_set_interpolation_amount then
            native_set_interpolation_amount = set_interpolation_amount_vfunc
        end

        local ok_origin_offset, origin_offset = pcall(
            utils.get_netvar_offset,
            "DT_BaseEntity",
            "m_vecOrigin"
        )
        if ok_origin_offset and type(origin_offset) == "number" and origin_offset > 0 then
            varmap_origin_offset = origin_offset
        end

        address = utils.opcode_scan("client.dll", "8B B7 ? ? ? ? 89 74 24 20")
        if address ~= nil then
            local signature_pointer = ffi.cast("uintptr_t", address)
            studio_hdr_offset = ffi.cast("int*", signature_pointer + 2)[0] + 0x4
        end
    end

    local ATTACHMENT_MATRIX_SIZE = 0
    local ATTACHMENT_VECTOR3_SIZE = 0
    if ffi_ready then
        ATTACHMENT_MATRIX_SIZE = ffi.sizeof("matrix3x4_t")
        ATTACHMENT_VECTOR3_SIZE = ffi.sizeof("float[3]")
    end

    local crouch_jitter_state = {
        end_tick = 0,
        was_duck_input = false,
        leg_override_active = false,
    }
    local hide_defensive_aa_state = {
        ready = false,
        body_yaw_pose = 0.5,
        pitch_pose = 0.5,
    }

    local layer_interpolation = {
        state = {
            samples = {
            },
            write_index = 1,
            sample_count = 0,
            last_capture_time = -1.0,
        },
        last_choked_commands = 0,
        values = {
        },
