    local history_animation_layers = nil
    local has_history_animation_layers = false

    local exp_smoothness_pose_values = {
    }
    local exp_smoothness_layer_values = {
    }
    for index = 0, EXP_SMOOTHNESS_MAX do
        exp_smoothness_pose_values[index] = 0.0
        exp_smoothness_layer_values[index] = 0.0
    end

    for layer_index = 0, INTERPOLATION_LAYER_MAX do
        layer_interpolation.values[layer_index] = {
            active = false,
            cycle = 0.0,
            weight = 0.0,
        }
    end

    for sample_index = 1, INTERPOLATION_SAMPLE_LIMIT do
        local sample_layers = {
        }
        for layer_index = 0, INTERPOLATION_LAYER_MAX do
            sample_layers[layer_index] = {
                active = false,
                cycle = 0.0,
                weight = 0.0,
            }
        end

        layer_interpolation.state.samples[sample_index] = {
            time = 0.0,
            weapon_index = 0,
            layers = sample_layers,
        }
    end

    function layer_interpolation.get_sample(order)
        local state = layer_interpolation.state
        local index = state.write_index - state.sample_count + order - 1

        if index <= 0 then
            index = index + INTERPOLATION_SAMPLE_LIMIT
        end

        if index > INTERPOLATION_SAMPLE_LIMIT then
            index = index - INTERPOLATION_SAMPLE_LIMIT
        end

        return state.samples[index]
    end

    local attachment_cache_state = {
        entities = {
        },
        count = 0,
        dirty = true,
        owner_index = 0,
        weapon_index = 0,
    }
    local has_leg_override = false
    local attachment_count = 0
