    local status_has_bones = false

    local history_absolute_angles = nil
    local history_pose_parameters = nil
    local history_aim_angles = nil
    local history_feet_yaw = nil
    local hide_defensive_buffers = {
        absolute_angles = nil,
        render_angles = nil,
        pose_parameters = nil,
        aim_angles = nil,
        feet_yaw = nil,
    }
