        history_aim_angles = ffi.new("float[2]")
        history_feet_yaw = ffi.new("float[1]")
        hide_defensive_buffers.absolute_angles = ffi.new("float[3]")
        hide_defensive_buffers.render_angles = ffi.new("float[2]")
        hide_defensive_buffers.pose_parameters = ffi.new("float[24]")
        hide_defensive_buffers.aim_angles = ffi.new("float[2]")
        hide_defensive_buffers.feet_yaw = ffi.new("float[1]")
        backup_absolute_angles = ffi.new("float[3]")
        backup_render_angles = ffi.new("float[4]")
        backup_animation_layers = ffi.new("char[728]")
        backup_pose_parameters = ffi.new("float[24]")
        backup_feet_yaw = ffi.new("float[1]")
        absolute_angles = ffi.new("float[3]")
        bones = ffi.new("matrix3x4_t[256]")
        attachments = ffi.new("attachment_data_t[256]")
    end

    local animation_config = {
    }

    function animation_config.get_item_value(item)
        if item == nil then
            return nil
        end

        local ok_override, override = pcall(item.get_override, item)
        if ok_override and override ~= nil then
            return override
        end

        local ok_value, value = pcall(item.get, item)
        if not ok_value then
            return nil
        end

        return value
    end

    function animation_config.is_animation_selected(name)
        if ref.animation_list == nil then
            return false
        end

        local ok_named, named_value = pcall(
            ref.animation_list.get,
            ref.animation_list,
            name
        )
        if ok_named and type(named_value) == "boolean" then
            return named_value
        end

        local ok_values, values = pcall(ref.animation_list.get, ref.animation_list)
        if not ok_values or type(values) ~= "table" then
            return false
        end

        local options = nil
        local ok_options, option_values = pcall(ref.animation_list.list, ref.animation_list)
        if ok_options and type(option_values) == "table" then
            options = option_values
        end

        for i = 1, #values do
            local value = values[i]
            if value == name then
                return true
            end

            if type(value) == "number" and options ~= nil and options[value] == name then
                return true
            end
        end

        return false
    end

    function animation_config.resolve_mode_name(reference, value)
        if type(value) == "string" then
            return value
        end

        if type(value) ~= "number" or reference == nil then
            return nil
        end

        local ok_list, items = pcall(reference.list, reference)
        if not ok_list or type(items) ~= "table" then
            return nil
        end

        local direct = items[value]
        if type(direct) == "string" then
            return direct
        end

        local shifted = items[value + 1]
        if type(shifted) == "string" then
            return shifted
        end

        return nil
    end

    function animation_config.normalize_air_mode(value)
        local resolved = animation_config.resolve_mode_name(ref.air_mode, value)
        if resolved ~= nil then
            value = resolved
        end

        if value == "Static" or value == 2 then
            return "Static"
        end

        if value == "Kangaroo" or value == 3 then
            return "Kangaroo"
        end

        return "Disabled"
    end

    function animation_config.normalize_ground_mode(value)
        local resolved = animation_config.resolve_mode_name(ref.ground_mode, value)
        if resolved ~= nil then
            value = resolved
        end

        if value == "Jitter" or value == 2 then
            return "Jitter"
        end

        if value == "Kangaroo" or value == 3 then
            return "Kangaroo"
        end

        if value == "Pacan4ik" or value == 4 then
            return "Pacan4ik"
        end

        return "Disabled"
    end

