    end

    function animation_config.get_ground_jitter_offset_2()
        local value = animation_config.get_item_value(ref.ground_jitter_offset_2)
        if type(value) ~= "number" then
            return 100
        end

        return value
    end

    function animation_config.get_ground_jitter_time()
        local value = animation_config.get_item_value(ref.ground_jitter_time)
        if type(value) ~= "number" then
            return 2
