    local hide_defensive = {
    }

    function hide_defensive.is_selected()
        return animation_config.is_animation_selected("Hide Defensive AA")
    end

    function hide_defensive.is_active()
        if hide_defensive.is_selected() ~= true then
            return false
        end

        local hidden_state = angles_builder.hidden_defensive_state
        return type(hidden_state) == "table"
            and hidden_state.is_overriding == true
    end

    function hide_defensive.is_exploit_active()
        if rage == nil or rage.exploit == nil then
            return false
        end

        local ok_exploit, exploit_value = pcall(rage.exploit.get, rage.exploit)
        return ok_exploit
            and type(exploit_value) == "number"
            and exploit_value > 0
    end

    function hide_defensive.clear_state()
        hide_defensive_aa_state.ready = false
        hide_defensive_aa_state.body_yaw_pose = 0.5
        hide_defensive_aa_state.pitch_pose = 0.5
    end

    function hide_defensive.is_snapshot_ready()
        if ffi_ready ~= true then
            return false
        end

        if get_absolute_angles == nil or set_absolute_angles == nil then
            return false
        end

        if hide_defensive_buffers.absolute_angles == nil
            or hide_defensive_buffers.render_angles == nil
            or hide_defensive_buffers.pose_parameters == nil
            or hide_defensive_buffers.aim_angles == nil
            or hide_defensive_buffers.feet_yaw == nil then
            return false
        end

        return true
    end

    function hide_defensive.capture_visual_state(
        pointer_void,
        render_angles,
        pose_parameters,
        aim_angles,
        feet_yaw
    )
        if hide_defensive.is_selected() ~= true then
            hide_defensive.clear_state()
            return false
        end

        if hide_defensive.is_active() == true then
            return false
        end

        if hide_defensive.is_snapshot_ready() ~= true
            or pointer_void == nil
            or render_angles == nil
            or pose_parameters == nil
            or aim_angles == nil
            or feet_yaw == nil then
            return false
        end

        local absolute = get_absolute_angles(pointer_void)
        if absolute == nil or absolute == ffi.NULL then
            return false
        end

        ffi.copy(hide_defensive_buffers.absolute_angles, absolute, 12)
        ffi.copy(hide_defensive_buffers.render_angles, render_angles, 8)
        ffi.copy(hide_defensive_buffers.aim_angles, aim_angles, 8)
        ffi.copy(hide_defensive_buffers.feet_yaw, feet_yaw, 4)

        local body_yaw_pose = pose_parameters[BODY_YAW_POSE_INDEX]
        if type(body_yaw_pose) == "number" then
            hide_defensive_aa_state.body_yaw_pose = body_yaw_pose
        else
            hide_defensive_aa_state.body_yaw_pose = 0.5
        end

        local pitch_pose = pose_parameters[PITCH_POSE_INDEX]
        if type(pitch_pose) == "number" then
            hide_defensive_aa_state.pitch_pose = pitch_pose
        else
            hide_defensive_aa_state.pitch_pose = 0.5
        end

        hide_defensive_aa_state.ready = true
        return true
    end

    function hide_defensive.apply_visual_state(
        pointer_void,
        render_angles,
        pose_parameters,
        aim_angles,
        feet_yaw
    )
        if hide_defensive_aa_state.ready ~= true
            or hide_defensive.is_active() ~= true then
            return false
        end

        if hide_defensive.is_snapshot_ready() ~= true
            or pointer_void == nil
            or render_angles == nil
            or pose_parameters == nil
            or aim_angles == nil
            or feet_yaw == nil then
            return false
        end

        pcall(
            set_absolute_angles,
            pointer_void,
            hide_defensive_buffers.absolute_angles
        )
        ffi.copy(render_angles, hide_defensive_buffers.render_angles, 8)
        ffi.copy(aim_angles, hide_defensive_buffers.aim_angles, 8)
        ffi.copy(feet_yaw, hide_defensive_buffers.feet_yaw, 4)

        pose_parameters[BODY_YAW_POSE_INDEX] =
            hide_defensive_aa_state.body_yaw_pose
        pose_parameters[PITCH_POSE_INDEX] =
            hide_defensive_aa_state.pitch_pose

        return true
    end

    function hide_defensive.update_visual_state(
        pointer_void,
        render_angles,
        pose_parameters,
        aim_angles,
        feet_yaw
    )
        if hide_defensive.apply_visual_state(
                pointer_void,
                render_angles,
                pose_parameters,
                aim_angles,
                feet_yaw
            ) == true then
            return true
        end

        return hide_defensive.capture_visual_state(
            pointer_void,
            render_angles,
            pose_parameters,
            aim_angles,
            feet_yaw
        )
    end

    local function set_leg_override(value)
        if ref.leg_movement == nil then
            return
        end

        if value == nil then
            if has_leg_override then
                pcall(ref.leg_movement.override, ref.leg_movement)
                has_leg_override = false
            end
            return
        end

        local ok_override = pcall(ref.leg_movement.override, ref.leg_movement, value)
        has_leg_override = ok_override
    end

    local function clear_crouch_transition_state()
        if crouch_jitter_state.leg_override_active == true then
            set_leg_override(nil)
            crouch_jitter_state.leg_override_active = false
        end

        crouch_jitter_state.was_duck_input = false
        crouch_jitter_state.end_tick = 0
    end

    local function clear_exp_smoothness_state()
        for index = 0, EXP_SMOOTHNESS_MAX do
            exp_smoothness_pose_values[index] = 0.0
            exp_smoothness_layer_values[index] = 0.0
        end
    end

    function layer_interpolation.clear_state()
        local state = layer_interpolation.state
        state.write_index = 1
        state.sample_count = 0
        state.last_capture_time = -1.0

        for sample_index = 1, INTERPOLATION_SAMPLE_LIMIT do
            local sample = state.samples[sample_index]
            sample.time = 0.0
            sample.weapon_index = 0

            local layers = sample.layers
            for layer_index = 0, INTERPOLATION_LAYER_MAX do
                local layer = layers[layer_index]
                layer.active = false
                layer.cycle = 0.0
                layer.weight = 0.0
            end
        end

        for layer_index = 0, INTERPOLATION_LAYER_MAX do
            local value = layer_interpolation.values[layer_index]
            value.active = false
            value.cycle = 0.0
            value.weight = 0.0
        end
    end

    local function get_animation_layers_pointer(local_player)
        if ffi_ready ~= true then
            return nil
        end

        if local_player == nil then
            return nil
        end

        local pointer = ffi.cast("uintptr_t", local_player[0])
        if pointer == 0x0 then
            return nil
        end

        local animation_layers = ffi.cast("uintptr_t*", pointer + ANIMATION_LAYER_OFFSET)[0]
        if animation_layers == 0x0 then
            return nil
        end

        return ffi.cast("void*", animation_layers)
    end

    local function get_attachment_data(pointer)
        if ffi_ready ~= true then
            return nil, 0
        end

        local attachment_vector = ffi.cast("utl_vector_anim_t*", pointer + ATTACHMENT_VECTOR_OFFSET)
        if attachment_vector == nil then
            return nil, 0
        end

        local size = attachment_vector.size
        if size == nil then
            return nil, 0
        end

        if size <= 0 or size > ATTACHMENT_LIMIT then
            return nil, 0
        end

        local allocation_count = attachment_vector.allocation_count
        if allocation_count == nil then
            return nil, 0
        end

        if allocation_count < size or allocation_count > ATTACHMENT_LIMIT * 2 then
            return nil, 0
        end

        local memory = attachment_vector.memory
        if memory == nil or memory == ffi.NULL then
            return nil, 0
        end

        local elements = attachment_vector.elements
        if elements == nil or elements == ffi.NULL then
            return nil, 0
        end

        if elements ~= memory then
            return nil, 0
        end

        return ffi.cast("attachment_data_t*", memory), size
    end

    local function invalidate_entity_physics(ent)
        if ent == nil then
            return
        end

        if ffi_ready ~= true then
            return
        end

        local ok_pointer, ent_pointer = pcall(function()
            return ent[0]
        end)
        if ok_pointer ~= true or ent_pointer == nil then
            return
        end

        local pointer = ffi.cast("uintptr_t", ent_pointer)
        if pointer == 0x0 then
            return
        end

        if invalidate_physics_recursive ~= nil then
            pcall(invalidate_physics_recursive, ffi.cast("void*", pointer), PHYSICS_ANIMATION_CHANGED)
            return
        end

        local ok_flags, flags = pcall(function()
            return ent.m_iEFlags
        end)
        if ok_flags and type(flags) == "number" then
            pcall(function()
                ent.m_iEFlags = bit.bor(flags, ENTITY_DIRTY_EFLAGS)
            end)
            return
        end

        local eflags = ffi.cast("int*", pointer + ENTITY_EFLAGS_OFFSET)
        eflags[0] = bit.bor(eflags[0], ENTITY_DIRTY_EFLAGS)
    end

    local function mark_attachment_cache_dirty()
        if attachment_cache_state.dirty == true then
            return
        end

        local entities = attachment_cache_state.entities
        for i = 1, attachment_cache_state.count do
            entities[i] = nil
        end

        attachment_cache_state.count = 0
        attachment_cache_state.dirty = true
        attachment_cache_state.owner_index = 0
    end

    local function get_local_weapon_index(local_player)
        if local_player == nil then
            return 0
        end

        local weapon = local_player:get_player_weapon()
        if weapon == nil then
            return 0
        end

        local weapon_index = weapon:get_index()
        if type(weapon_index) ~= "number" then
            return 0
        end

        return weapon_index
    end

    local function entity_from_handle(value)
        if type(value) == "userdata" then
            return value
        end

        if type(value) ~= "number" then
            return nil
        end

        local index = bit.band(value, MOVE_PARENT_INDEX_MASK)
        if index <= 0 then
            return nil
        end

        return entity.get(index)
    end

    local function get_parent_entity(ent)
        local moveparent = ent["moveparent"]
        if moveparent == nil or moveparent == 0 then
            moveparent = ent.m_hMoveParent
        end

        return entity_from_handle(moveparent)
    end

    local function is_attached_to_local(ent, owner_index)
        local current = ent
        for _ = 1, 10 do
            current = get_parent_entity(current)
            if current == nil then
                return false
            end

            if current:get_index() == owner_index then
                return true
            end
        end

        return false
    end

    local function invalidate_weapon_world_models(local_player)
        local weapons = local_player:get_player_weapon(true)
        if type(weapons) ~= "table" then
            return
        end

        for i = 1, #weapons do
            local weapon = weapons[i]
            if weapon ~= nil then
                invalidate_entity_physics(weapon)

                local ok_world, world_model_handle = pcall(function()
                    return weapon.m_hWeaponWorldModel
                end)
                if ok_world then
                    local world_model = entity_from_handle(world_model_handle)
                    if world_model ~= nil then
                        invalidate_entity_physics(world_model)
                    end
                end
            end
        end
    end

    local function rebuild_attached_entities_cache(local_player, owner_index)
        local entities = attachment_cache_state.entities
        for i = 1, attachment_cache_state.count do
            entities[i] = nil
        end

        local count = 0
        local ok = pcall(entity.get_entities, nil, true, function(ent)
            if ent == nil or ent == local_player then
                return
            end

            if ent:is_player() == true then
                return
            end

            if is_attached_to_local(ent, owner_index) ~= true then
                return
            end

            count = count + 1
            entities[count] = ent
        end)

        if ok ~= true then
            attachment_cache_state.count = 0
            attachment_cache_state.dirty = true
            attachment_cache_state.owner_index = owner_index
            return
        end

        attachment_cache_state.count = count
        attachment_cache_state.dirty = false
        attachment_cache_state.owner_index = owner_index
    end

    local function update_following_attachment_entities(local_player)
        if local_player == nil then
            return
        end

        local owner_index = local_player:get_index()
        if type(owner_index) ~= "number" then
            return
        end

        if attachment_cache_state.dirty == true or attachment_cache_state.owner_index ~= owner_index then
            rebuild_attached_entities_cache(local_player, owner_index)
        end

        local entities = attachment_cache_state.entities
        for i = 1, attachment_cache_state.count do
            invalidate_entity_physics(entities[i])
        end

        invalidate_weapon_world_models(local_player)
    end

    rebuild_local_attachment_data = function(pointer)
        if setup_bones_attachment_helper == nil or studio_hdr_offset == nil then
            return false
        end

        local studio_hdr = ffi.cast("void**", pointer + studio_hdr_offset)[0]
        if studio_hdr == nil or studio_hdr == ffi.NULL then
            return false
        end

        pcall(setup_bones_attachment_helper, ffi.cast("void*", pointer), studio_hdr)
        return true
    end

    local function invalidate_local_player_attachments(local_player)
        if local_player == nil then
            return
        end

        if ffi_ready ~= true then
            return
        end

        local pointer = ffi.cast("uintptr_t", local_player[0])
        if pointer == 0x0 then
            return
        end

        if invalidate_physics_recursive ~= nil then
            pcall(invalidate_physics_recursive, ffi.cast("void*", pointer), PHYSICS_ANIMATION_CHANGED)
        end

        update_following_attachment_entities(local_player)
    end

    local function apply_onetap_interp(index, amount)
        if ffi_ready ~= true or native_get_client_entity == nil or native_set_interpolation_amount == nil then
            return
        end

        if type(index) ~= "number" or index <= 0 then
            return
        end

        local entity_ptr = native_get_client_entity(index)
        if entity_ptr == nil or entity_ptr == ffi.NULL then
            return
        end

        local entity_addr = ffi.cast("uintptr_t", entity_ptr)
        if entity_addr == 0x0 then
            return
        end

        local varmap = entity_addr + VARMAP_OFFSET
        local entries_ptr = ffi.cast("void**", varmap)[0]
        if entries_ptr == nil or entries_ptr == ffi.NULL then
            return
        end

        local interp_count = ffi.cast("int*", varmap + VARMAP_INTERPOLATED_COUNT_OFFSET)[0]
        if type(interp_count) ~= "number" or interp_count <= 0 or interp_count > VARMAP_ENTRY_LIMIT then
            return
        end

        local interpolation_amount = globals.tickinterval * amount
        if type(interpolation_amount) ~= "number" or interpolation_amount <= 0.0 then
            return
        end

        local entries = ffi.cast("varmap_entry_t*", entries_ptr)
        for i = 0, interp_count - 1 do
            local entry = entries[i]
            if entry.data ~= nil
                and entry.data ~= ffi.NULL
                and entry.watcher ~= nil
                and entry.watcher ~= ffi.NULL then
                local data_offset = ffi.cast("uintptr_t", entry.data) - entity_addr
                if data_offset == varmap_origin_offset then
                    native_set_interpolation_amount(entry.watcher, interpolation_amount)
                    return
                end
            end
        end
    end

    local function on_net_update_end()
        if animation_config.is_animation_selected("Onetap Interp") ~= true then
            return
        end

        local local_player = entity.get_local_player()
        if local_player == nil or not local_player:is_alive() then
            return
        end

        local amount = animation_config.get_onetap_interp_amount()
        entity.get_players(false, false, function(player)
            if player == nil or player == local_player then
                return
            end

            apply_onetap_interp(player:get_index(), amount)
        end)
    end

    local function is_full_smoothness_ready()
        if ffi_ready ~= true then
            return false
        end

        if get_absolute_angles == nil or set_absolute_angles == nil then
            return false
        end

        if setup_bones == nil then
            return false
        end

        if history_animation_layers == nil then
            return false
        end

        if history_absolute_angles == nil or history_pose_parameters == nil then
            return false
        end

        if backup_absolute_angles == nil or backup_render_angles == nil then
            return false
        end

        if bones == nil or attachments == nil then
            return false
        end

        return true
    end

    local function reset_runtime_state()
        status_frame_ready = false
        has_history_animation_layers = false
        layer_interpolation.last_choked_commands = 0
        status_has_bones = false
        attachment_count = 0
        hide_defensive.clear_state()
        clear_crouch_transition_state()
        clear_exp_smoothness_state()
        layer_interpolation.clear_state()
        mark_attachment_cache_dirty()
        attachment_cache_state.weapon_index = 0
        set_leg_override(nil)
    end

    local function is_player_ducking(local_player)
        if local_player == nil then
            return false
        end

        if local_player.m_bDucking == true then
            return true
        end

        if local_player.m_bDucked == true then
            return true
        end

        local duck_amount = local_player.m_flDuckAmount
        return type(duck_amount) == "number" and duck_amount > 0.35
    end

    local function is_command_ducking(cmd)
        if cmd == nil then
            return false
        end

        local in_duck = cmd.in_duck
        if in_duck == true then
            return true
        end

        if type(in_duck) == "number" and in_duck ~= 0 then
            return true
        end

        local buttons = cmd.buttons
        return type(buttons) == "number" and bit.band(buttons, 4) ~= 0
    end

    local function update_crouch_transition_state(local_player, cmd, ground_mode)
        local mode = ground_mode
        if mode == nil then
            mode = animation_config.get_ground_mode()
        end

        if mode ~= "Jitter" then
            clear_crouch_transition_state()
            return
        end

        local duck_input = is_command_ducking(cmd)
        if duck_input ~= true then
            duck_input = is_player_ducking(local_player)
        end

        if duck_input == true and crouch_jitter_state.was_duck_input ~= true then
            crouch_jitter_state.end_tick = globals.tickcount + CROUCH_JITTER_DURATION_TICKS
        end

        crouch_jitter_state.was_duck_input = duck_input
    end

    local function apply_crouch_transition_jitter(local_player, ground_mode)
        local mode = ground_mode
        if mode == nil then
            mode = animation_config.get_ground_mode()
        end

        if mode ~= "Jitter" then
            clear_crouch_transition_state()
            return
        end

        local flags = local_player.m_fFlags
        if type(flags) ~= "number" or bit.band(flags, FL_ONGROUND) == 0 then
            if crouch_jitter_state.leg_override_active == true then
                set_leg_override(nil)
                crouch_jitter_state.leg_override_active = false
            end

            return
        end

        local tickcount = globals.tickcount
        if tickcount > crouch_jitter_state.end_tick then
            if crouch_jitter_state.leg_override_active == true then
                set_leg_override(nil)
                crouch_jitter_state.leg_override_active = false
            end

            return
        end

        set_leg_override(tickcount % 3 == 0 and "Walking" or "Sliding")
        crouch_jitter_state.leg_override_active = true
        local_player.m_flPoseParameter[1] = tickcount % 4 > 1 and 0.0 or 1.0
    end

    local function apply_air_legs(local_player, air_mode)
        local mode = air_mode
        if mode == nil then
            mode = animation_config.get_air_mode()
        end

        if mode == "Disabled" then
            return
        end

        if mode == "Static" then
            local local_weight = animation_config.get_air_weight()
            local_player.m_flPoseParameter[6] = local_weight * 0.01
            return
        end

        if mode == "Kangaroo" then
            local_player.m_flPoseParameter[3] = math.random()
            local_player.m_flPoseParameter[7] = math.random()
            local_player.m_flPoseParameter[6] = math.random()
        end
    end

    local function apply_air_static_pose(local_player, air_mode)
        local mode = air_mode
        if mode == nil then
            mode = animation_config.get_air_mode()
        end

        if mode ~= "Static" then
            return
        end

        local flags = local_player.m_fFlags
        if type(flags) ~= "number" then
            return
        end

        if bit.band(flags, FL_ONGROUND) ~= 0 then
            return
        end

        local local_weight = animation_config.get_air_weight()
        local_player.m_flPoseParameter[6] = local_weight * 0.01
    end

    local function apply_ground_legs(local_player, ground_mode)
        local mode = ground_mode
        if mode == nil then
            mode = animation_config.get_ground_mode()
        end

        if mode == "Disabled" then
            set_leg_override(nil)
            return
        end

        if mode == "Jitter" then
            local tickcount = globals.tickcount
            local speed = animation_config.get_ground_jitter_time()
            local flip_state = tickcount % (speed * 2) >= speed
            local mul = 1.0 / (tickcount % (speed * 4) >= (speed * 2) and 200 or 400)
            local offset = flip_state
                and animation_config.get_ground_jitter_offset_1()
                or animation_config.get_ground_jitter_offset_2()

            local_player.m_flPoseParameter[0] = offset * mul
            set_leg_override(flip_state and "Sliding" or "Walking")
            return
        end

        if mode == "Kangaroo" then
            local_player.m_flPoseParameter[3] = math.random()
            local_player.m_flPoseParameter[7] = math.random()
            local_player.m_flPoseParameter[6] = math.random()
            set_leg_override(nil)
            return
        end

        if mode == "Pacan4ik" then
            local leg_movement_value = utils.random_int(0, 1) == 0
                and "Off" or "Sliding"

            local_player.m_flPoseParameter[0] = utils.random_float(
                animation_config.get_ground_pacan4ik_offset_1(),
                animation_config.get_ground_pacan4ik_offset_2()
            )
            set_leg_override(leg_movement_value)
            return
        end

        set_leg_override(nil)
    end

    local function lerp_number(from, to, t)
        return from + (to - from) * t
    end

    local function clamp_01(value)
        if value < 0.0 then
            return 0.0
        end

        if value > 1.0 then
            return 1.0
        end

        return value
    end

    local function normalize_cycle(value)
        if value >= 0.0 and value <= 1.0 then
            return value
        end

        return value - math.floor(value)
    end

    local function interpolate_cycle(from_cycle, to_cycle, t)
        local a = from_cycle
        local b = to_cycle
        local delta = b - a

        if math.abs(delta) > 0.5 then
            if delta > 0.0 then
                a = a + 1.0
            else
                b = b + 1.0
            end
        end

        return normalize_cycle(lerp_number(a, b, t))
    end

    function layer_interpolation.capture_sample(local_player, layer_interpolation_enabled, weapon_index)
        local state = layer_interpolation.state
        if layer_interpolation_enabled ~= true then
            if state.sample_count > 0 or state.last_capture_time ~= -1.0 then
                layer_interpolation.clear_state()
            end
            return
        end

        local now = globals.realtime
        if type(now) ~= "number" then
            return
        end

        if now <= state.last_capture_time then
            return
        end

        if type(weapon_index) ~= "number" then
            weapon_index = get_local_weapon_index(local_player)
            if type(weapon_index) ~= "number" then
                weapon_index = 0
            end
        end

        local sample = state.samples[state.write_index]
        sample.time = now
        sample.weapon_index = weapon_index
        local sample_layers = sample.layers

        for layer_index = 0, INTERPOLATION_LAYER_MAX do
            local sample_layer = sample_layers[layer_index]
            sample_layer.active = false

            local layer = local_player:get_anim_overlay(layer_index)
            if layer ~= nil then
                local cycle = layer.cycle
                local weight = layer.weight
                if type(cycle) == "number" and type(weight) == "number" then
                    sample_layer.active = true
                    sample_layer.cycle = cycle
                    sample_layer.weight = weight
                end
            end
        end

        state.last_capture_time = now

        state.write_index = state.write_index + 1
        if state.write_index > INTERPOLATION_SAMPLE_LIMIT then
            state.write_index = 1
        end

        if state.sample_count < INTERPOLATION_SAMPLE_LIMIT then
            state.sample_count = state.sample_count + 1
        end
    end

    function layer_interpolation.build(local_player, layer_interpolation_enabled)
        if layer_interpolation_enabled ~= true then
            return false
        end

        if rage ~= nil and rage.exploit ~= nil then
            local ok_exploit, exploit_value = pcall(rage.exploit.get, rage.exploit)
            if ok_exploit and type(exploit_value) == "number" and exploit_value > 0 then
                return false
            end
        end

        local sample_count = layer_interpolation.state.sample_count
        if sample_count < 2 then
            return false
        end

        local now = globals.realtime
        if type(now) ~= "number" then
            return false
        end

        local first = nil
        local second = nil
        for i = sample_count - 1, 1, -1 do
            local state_1 = layer_interpolation.get_sample(i)
            local state_2 = layer_interpolation.get_sample(i + 1)
            if now >= state_1.time and now <= state_2.time then
                first = state_1
                second = state_2
                break
            end
        end

        if first == nil or second == nil then
            first = layer_interpolation.get_sample(sample_count - 1)
            second = layer_interpolation.get_sample(sample_count)
        end

        local delta_time = second.time - first.time
        if delta_time <= 0.0 then
            return false
        end

        local t = clamp_01((now - first.time) / delta_time)
        local has_values = false

        for layer_index = 0, INTERPOLATION_LAYER_MAX do
            local from = first.layers[layer_index]
            local to = second.layers[layer_index]
            local value = layer_interpolation.values[layer_index]

            if from.active == true and to.active == true then
                value.active = true

                if (layer_index == 1 or layer_index == 2) and first.weapon_index ~= second.weapon_index then
                    value.cycle = to.cycle
                    value.weight = to.weight
                else
                    value.cycle = interpolate_cycle(from.cycle, to.cycle, t)
                    value.weight = lerp_number(from.weight, to.weight, t)
                end

                has_values = true
            else
                value.active = false
            end
        end

        return has_values
    end

    function layer_interpolation.get_choked_commands(cmd)
        local choked_commands = nil

        if cmd ~= nil then
            local ok_choked, cmd_choked = pcall(function()
                return cmd.choked_commands
            end)
            if ok_choked and type(cmd_choked) == "number" then
                choked_commands = cmd_choked
            end
        end

        if type(choked_commands) ~= "number" then
            local global_choked = globals.choked_commands
            if type(global_choked) == "number" then
                choked_commands = global_choked
            end
        end

        if type(choked_commands) ~= "number" then
            choked_commands = 0
        end

        return choked_commands
    end

    function layer_interpolation.apply_to_memory(local_player, layer_pointer, layer_interpolation_enabled)
        if layer_pointer == nil then
            return
        end

        if layer_interpolation.build(local_player, layer_interpolation_enabled) ~= true then
            return
        end

        local animlayers = ffi.cast("aesthetic_anim_layer_t*", layer_pointer)
        for layer_index = 0, INTERPOLATION_LAYER_MAX do
            local value = layer_interpolation.values[layer_index]
            if value.active == true then
                animlayers[layer_index].m_flCycle = value.cycle
                animlayers[layer_index].m_flWeight = value.weight
            end
        end
    end

    local function apply_move_lean(local_player)
        local move_lean_enabled = animation_config.is_animation_selected("Move Lean")
        if move_lean_enabled ~= true then
            return
        end

        local move_lean_value = animation_config.get_move_lean_value()
        if move_lean_value < 0 then
            return
        end

        local velocity = local_player.m_vecVelocity
        if velocity == nil then
            return
        end

        local vx = velocity.x
        local vy = velocity.y
        if type(vx) ~= "number" or type(vy) ~= "number" then
            return
        end

        if (vx * vx + vy * vy) <= 1.0 then
            return
        end

        if ffi_ready ~= true then
            return
        end

        local animation_layers = get_animation_layers_pointer(local_player)
        if animation_layers == nil then
            return
        end

        local animlayers = ffi.cast("aesthetic_anim_layer_t*", animation_layers)
        animlayers[12].m_flWeight = move_lean_value
        animlayers[12].m_flWeightDeltaRate = move_lean_value
    end

    local function apply_exp_smoothness(local_player, pose_parameters, layer_pointer)
        if animation_config.is_animation_selected("Smoothness") ~= true then
            return
        end

        if ffi_ready ~= true then
            return
        end

        local animation_layers = layer_pointer
        if animation_layers == nil then
            animation_layers = get_animation_layers_pointer(local_player)
        end

        if animation_layers == nil then
            return
        end

        local coefficient = globals.tickinterval * animation_config.get_smoothness_amount()
        if type(coefficient) ~= "number" then
            return
        end

        coefficient = math.clamp(coefficient, 0.0, 1.0)
        local inverse = 1.0 - coefficient

        local pose_values = pose_parameters
        if pose_values == nil then
            pose_values = local_player.m_flPoseParameter
        end

        if pose_values == nil then
            return
        end

        for pose_index = 0, EXP_SMOOTHNESS_MAX do
            local pose_value = pose_values[pose_index]
            if type(pose_value) == "number" then
                local smoothed_pose = coefficient * exp_smoothness_pose_values[pose_index] + inverse * pose_value
                exp_smoothness_pose_values[pose_index] = smoothed_pose
                pose_values[pose_index] = smoothed_pose
            end
        end

        local animlayers = ffi.cast("aesthetic_anim_layer_t*", animation_layers)
        for layer_index = 0, EXP_SMOOTHNESS_MAX do
            local layer = animlayers[layer_index]
            local weight = layer.m_flWeight
            if type(weight) == "number" then
                local smoothed_weight = coefficient * exp_smoothness_layer_values[layer_index] + inverse * weight
                exp_smoothness_layer_values[layer_index] = smoothed_weight
                layer.m_flWeight = smoothed_weight
            end
        end
    end

    local function apply_pose_parameters_simple(local_player, ground_mode, air_mode)
        local flags = local_player.m_fFlags
        if type(flags) ~= "number" then
            return
        end

        if bit.band(flags, FL_ONGROUND) ~= 0 then
            apply_ground_legs(local_player, ground_mode)
        else
            apply_air_legs(local_player, air_mode)
        end

        apply_crouch_transition_jitter(local_player, ground_mode)
    end

    local function on_createmove(cmd)
        local local_player = entity.get_local_player()
        if local_player == nil or not local_player:is_alive() then
            reset_runtime_state()
            return
        end

        local choked_commands = layer_interpolation.get_choked_commands(cmd)
        layer_interpolation.last_choked_commands = choked_commands

        local ground_mode = animation_config.get_ground_mode()
        local air_mode = animation_config.get_air_mode()
        local layer_interpolation_enabled = animation_config.is_animation_selected("Layer Interpolation")

        update_crouch_transition_state(local_player, cmd, ground_mode)

        local weapon_index = get_local_weapon_index(local_player)
        if weapon_index ~= attachment_cache_state.weapon_index then
            attachment_cache_state.weapon_index = weapon_index
            mark_attachment_cache_dirty()
        end

        layer_interpolation.capture_sample(local_player, layer_interpolation_enabled, weapon_index)

        if status_frame_ready ~= true then
            apply_pose_parameters_simple(local_player, ground_mode, air_mode)
            reset_runtime_state()
            return
        end

        if ffi_ready ~= true or is_full_smoothness_ready() ~= true then
            status_has_bones = false
            apply_pose_parameters_simple(local_player, ground_mode, air_mode)
            return
        end

        local pointer = ffi.cast("uintptr_t", local_player[0])
        if pointer == 0x0 then
            reset_runtime_state()
            status_has_bones = false
            apply_pose_parameters_simple(local_player, ground_mode, air_mode)
            return
        end

        local pointer_void = ffi.cast("void*", pointer)

        local animation_layers_raw = ffi.cast("uintptr_t*", pointer + ANIMATION_LAYER_OFFSET)[0]
        if animation_layers_raw == 0x0 then
            reset_runtime_state()
            status_has_bones = false
            apply_pose_parameters_simple(local_player, ground_mode, air_mode)
            return
        end
        local animation_layers = ffi.cast("void*", animation_layers_raw)

        local animation_state = ffi.cast("uintptr_t*", pointer + ANIMATION_STATE_OFFSET)[0]
        if animation_state == 0x0 then
            reset_runtime_state()
            status_has_bones = false
            apply_pose_parameters_simple(local_player, ground_mode, air_mode)
            return
        end

        local render_angles = ffi.cast("float*", pointer + RENDER_ANGLES_OFFSET)
        local pose_parameters = ffi.cast("float*", pointer + POSE_PARAMETERS_OFFSET)
        local aim_angles = ffi.cast("float*", animation_state + ANIM_STATE_AIM_ANGLES_OFFSET)
        local feet_yaw = ffi.cast("float*", animation_state + ANIM_STATE_FEET_YAW_OFFSET)
        local effects = ffi.cast("int*", pointer + ENTITY_EFFECTS_OFFSET)
        local hide_defensive_visual_locked =
            hide_defensive.is_active() == true
            and hide_defensive_aa_state.ready == true

        hide_defensive.capture_visual_state(
            pointer_void,
            render_angles,
            pose_parameters,
            aim_angles,
            feet_yaw
        )

        if type(choked_commands) == "number" and choked_commands == 0 then
            if hide_defensive_visual_locked ~= true then
                local absolute = get_absolute_angles(pointer_void)
                if absolute ~= nil and absolute ~= ffi.NULL then
                    ffi.copy(history_absolute_angles, absolute, 12)
                end

                ffi.copy(history_pose_parameters, pose_parameters, 96)
                ffi.copy(history_aim_angles, aim_angles, 8)
                ffi.copy(history_feet_yaw, feet_yaw, 4)
            end

            ffi.copy(history_animation_layers, animation_layers, ANIMATION_LAYER_MEMORY_SIZE)
            has_history_animation_layers = true
        end

        if has_history_animation_layers ~= true then
            status_has_bones = false
            apply_pose_parameters_simple(local_player, ground_mode, air_mode)
            return
        end

        local absolute = get_absolute_angles(pointer_void)
        if absolute == nil or absolute == ffi.NULL then
            status_has_bones = false
            apply_pose_parameters_simple(local_player, ground_mode, air_mode)
            return
        end
        ffi.copy(backup_absolute_angles, absolute, 12)

        ffi.copy(backup_render_angles, render_angles, 8)
        ffi.copy(ffi.cast("float*", backup_render_angles) + 2, aim_angles, 8)
        ffi.copy(backup_animation_layers, animation_layers, ANIMATION_LAYER_MEMORY_SIZE)
        ffi.copy(backup_pose_parameters, pose_parameters, 96)
        ffi.copy(backup_feet_yaw, feet_yaw, 4)

        ffi.copy(animation_layers, history_animation_layers, ANIMATION_LAYER_MEMORY_SIZE)
        if hide_defensive.apply_visual_state(
                pointer_void,
                render_angles,
                pose_parameters,
                aim_angles,
                feet_yaw
            ) ~= true then
            absolute_angles[1] = history_feet_yaw[0]
            pcall(set_absolute_angles, pointer_void, absolute_angles)

            render_angles[1] = history_aim_angles[0]
            ffi.copy(pose_parameters, history_pose_parameters, 96)
            ffi.copy(feet_yaw, history_feet_yaw, 4)
        end

        layer_interpolation.apply_to_memory(local_player, animation_layers, layer_interpolation_enabled)

        apply_pose_parameters_simple(local_player, ground_mode, air_mode)
        if type(choked_commands) == "number" and choked_commands > 0 then
            apply_exp_smoothness(local_player, pose_parameters, animation_layers)
        end

        local backup_effects = effects[0]
        effects[0] = bit.bor(effects[0], 0x8)

        local sim_time = local_player.m_flSimulationTime
        local ok_setup = false
        local setup_result = false
        if type(sim_time) == "number" then
            ok_setup, setup_result = pcall(
                setup_bones,
                ffi.cast("void*", pointer + 0x4),
                bones,
                MAX_BONES,
                0x7FF00,
                sim_time
            )
        end
        status_has_bones = ok_setup and setup_result == true

        effects[0] = backup_effects

        pcall(set_absolute_angles, pointer_void, backup_absolute_angles)
        ffi.copy(render_angles, backup_render_angles, 8)
        ffi.copy(aim_angles, ffi.cast("float*", backup_render_angles) + 2, 8)
        ffi.copy(animation_layers, backup_animation_layers, ANIMATION_LAYER_MEMORY_SIZE)
        ffi.copy(pose_parameters, backup_pose_parameters, 96)
        ffi.copy(feet_yaw, backup_feet_yaw, 4)

        attachment_count = 0
        if status_has_bones == true then
            local origin = local_player:get_origin()
            local ox = origin.x
            local oy = origin.y
            local oz = origin.z

            local bone_count = math.min(MAX_BONES, ffi.cast("int*", pointer + BONE_COUNT_OFFSET)[0])
            for i = 0, bone_count - 1 do
                local m = bones[i].m
                m[0][3] = m[0][3] - ox
                m[1][3] = m[1][3] - oy
                m[2][3] = m[2][3] - oz
            end

            local attachment_data, size = get_attachment_data(pointer)
            if attachment_data ~= nil and size > 0 then
                attachment_count = size
                for i = 0, size - 1 do
                    ffi.copy(attachments[i].attachment_to_world, attachment_data[i].attachment_to_world,
                        ATTACHMENT_MATRIX_SIZE)
                    ffi.copy(attachments[i].ang_rotation, attachment_data[i].ang_rotation, ATTACHMENT_VECTOR3_SIZE)
                    ffi.copy(attachments[i].origin_velocity, attachment_data[i].origin_velocity, ATTACHMENT_VECTOR3_SIZE)
                end
            end
        end

        apply_pose_parameters_simple(local_player, ground_mode, air_mode)
    end

    local has_move_lean_feature_enabled
    local has_full_animation_feature_enabled

    local function on_post_update_clientside_animation(player)
        local local_player = entity.get_local_player()
        if local_player == nil or not local_player:is_alive() then
            reset_runtime_state()
            return
        end

        if player ~= local_player then
            return
        end

        if has_full_animation_feature_enabled() ~= true then
            apply_move_lean(local_player)
            return
        end

        local exploit_active = hide_defensive.is_exploit_active()

        if ffi_ready ~= true then
            hide_defensive.clear_state()
            return
        end

        local pointer = ffi.cast("uintptr_t", local_player[0])
        if pointer == 0x0 then
            reset_runtime_state()
            return
        end

        local animation_state = ffi.cast("uintptr_t*", pointer + ANIMATION_STATE_OFFSET)[0]
        if animation_state == 0x0 then
            reset_runtime_state()
            return
        end

        local pointer_void = ffi.cast("void*", pointer)
        local render_angles = ffi.cast("float*", pointer + RENDER_ANGLES_OFFSET)
        local pose_parameters = ffi.cast("float*", pointer + POSE_PARAMETERS_OFFSET)
        local aim_angles = ffi.cast("float*", animation_state + ANIM_STATE_AIM_ANGLES_OFFSET)
        local feet_yaw = ffi.cast("float*", animation_state + ANIM_STATE_FEET_YAW_OFFSET)

        if is_full_smoothness_ready() ~= true then
            apply_exp_smoothness(local_player)
            hide_defensive.update_visual_state(
                pointer_void,
                render_angles,
                pose_parameters,
                aim_angles,
                feet_yaw
            )
            return
        end

        local ground_mode = animation_config.get_ground_mode()
        local air_mode = animation_config.get_air_mode()

        if exploit_active == true then
            apply_pose_parameters_simple(local_player, ground_mode, air_mode)
            apply_exp_smoothness(local_player)

            local flags = local_player.m_fFlags
            if ground_mode == "Jitter"
                and type(flags) == "number"
                and bit.band(flags, FL_ONGROUND) ~= 0 then
                apply_ground_legs(local_player, ground_mode)
            end

            hide_defensive.update_visual_state(
                pointer_void,
                render_angles,
                pose_parameters,
                aim_angles,
                feet_yaw
            )
            return
        end

        local choked_commands = globals.choked_commands
        if type(choked_commands) ~= "number" then
            choked_commands = layer_interpolation.last_choked_commands
        end

        apply_air_static_pose(local_player, air_mode)

        local flags = local_player.m_fFlags
        if type(flags) == "number" and bit.band(flags, FL_ONGROUND) ~= 0 then
            apply_ground_legs(local_player, ground_mode)
        end

        apply_move_lean(local_player)
        apply_crouch_transition_jitter(local_player, ground_mode)
        apply_exp_smoothness(local_player)

        if ground_mode == "Jitter"
            and type(flags) == "number"
            and bit.band(flags, FL_ONGROUND) ~= 0 then
            apply_ground_legs(local_player, ground_mode)
        end

        if type(choked_commands) ~= "number" or choked_commands == 0 then
            hide_defensive.update_visual_state(
                pointer_void,
                render_angles,
                pose_parameters,
                aim_angles,
                feet_yaw
            )
            return
        end

        if status_frame_ready ~= true or has_history_animation_layers ~= true or status_has_bones ~= true then
            hide_defensive.update_visual_state(
                pointer_void,
                render_angles,
                pose_parameters,
                aim_angles,
                feet_yaw
            )
            return
        end

        local bone_cache = ffi.cast("matrix3x4_t**", pointer + BONE_CACHE_OFFSET)[0]
        if bone_cache == nil or bone_cache == ffi.NULL then
            hide_defensive.update_visual_state(
                pointer_void,
                render_angles,
                pose_parameters,
                aim_angles,
                feet_yaw
            )
            return
        end

        local bone_count = math.min(MAX_BONES, ffi.cast("int*", pointer + BONE_COUNT_OFFSET)[0])
        if bone_count <= 0 then
            hide_defensive.update_visual_state(
                pointer_void,
                render_angles,
                pose_parameters,
                aim_angles,
                feet_yaw
            )
            return
        end

        ffi.copy(bone_cache, bones, bone_count * 48)

        local origin = local_player:get_origin()
        local ox = origin.x
        local oy = origin.y
        local oz = origin.z

        for i = 0, bone_count - 1 do
            local m = bone_cache[i].m
            m[0][3] = m[0][3] + ox
            m[1][3] = m[1][3] + oy
            m[2][3] = m[2][3] + oz
        end

        local attachments_rebuilt = rebuild_local_attachment_data(pointer)
        if attachments_rebuilt ~= true and attachment_count > 0 then
            local attachment_data, size = get_attachment_data(pointer)
            if attachment_data ~= nil and size > 0 then
                local copy_count = math.min(attachment_count, size)
                for i = 0, copy_count - 1 do
                    ffi.copy(attachment_data[i].attachment_to_world, attachments[i].attachment_to_world,
                        ATTACHMENT_MATRIX_SIZE)
                    ffi.copy(attachment_data[i].ang_rotation, attachments[i].ang_rotation, ATTACHMENT_VECTOR3_SIZE)
                    ffi.copy(attachment_data[i].origin_velocity, attachments[i].origin_velocity, ATTACHMENT_VECTOR3_SIZE)
                end
            end
        end

        invalidate_local_player_attachments(local_player)
        hide_defensive.update_visual_state(
            pointer_void,
            render_angles,
            pose_parameters,
            aim_angles,
            feet_yaw
        )
    end

    local function on_pre_render()
        local local_player = entity.get_local_player()
        if local_player == nil or not local_player:is_alive() then
            reset_runtime_state()
            return
        end

        status_frame_ready = true
    end

    has_move_lean_feature_enabled = function()
        return animation_config.is_animation_selected("Move Lean")
            and animation_config.get_move_lean_value() >= 0
    end

    has_full_animation_feature_enabled = function()
        if animation_config.get_air_mode() ~= "Disabled" then
            return true
        end

        if animation_config.get_ground_mode() ~= "Disabled" then
            return true
        end

        if animation_config.is_animation_selected("Layer Interpolation") then
            return true
        end

        if animation_config.is_animation_selected("Hide Defensive AA") then
            return true
        end

        if animation_config.is_animation_selected("Onetap Interp") then
            return true
        end

        if animation_config.is_animation_selected("Smoothness") then
            return true
        end

        return false
    end

    local function has_any_feature_enabled()
        return has_full_animation_feature_enabled() == true
            or has_move_lean_feature_enabled() == true
    end

    local function sync_callbacks()
        local full_enabled = has_full_animation_feature_enabled()
        local enabled = has_any_feature_enabled()
        events.createmove(on_createmove, full_enabled)
        events.pre_render(on_pre_render, full_enabled)
        events.post_update_clientside_animation(on_post_update_clientside_animation, enabled)
        events.net_update_end(
            on_net_update_end,
            animation_config.is_animation_selected("Onetap Interp")
        )

        if not full_enabled then
            reset_runtime_state()
        end
    end

    local callbacks
    do
        local function on_settings_change()
            sync_callbacks()
        end

        if ref.animation_list ~= nil then
            ref.animation_list:set_callback(on_settings_change, true)
        end

        if ref.smoothness_amount ~= nil then
            ref.smoothness_amount:set_callback(on_settings_change)
        end

        if ref.onetap_interp_amount ~= nil then
            ref.onetap_interp_amount:set_callback(on_settings_change)
        end

        if ref.move_lean ~= nil then
            ref.move_lean:set_callback(on_settings_change)
        end

        if ref.air_mode ~= nil then
            ref.air_mode:set_callback(on_settings_change)
        end

        if ref.air_weight ~= nil then
            ref.air_weight:set_callback(on_settings_change)
        end

        if ref.ground_mode ~= nil then
            ref.ground_mode:set_callback(on_settings_change)
        end

        if ref.ground_jitter_offset_1 ~= nil then
            ref.ground_jitter_offset_1:set_callback(on_settings_change)
        end

        if ref.ground_jitter_offset_2 ~= nil then
            ref.ground_jitter_offset_2:set_callback(on_settings_change)
        end

        if ref.ground_jitter_time ~= nil then
            ref.ground_jitter_time:set_callback(on_settings_change)
        end

        if ref.ground_pacan4ik_offset_1 ~= nil then
            ref.ground_pacan4ik_offset_1:set_callback(on_settings_change)
        end

        if ref.ground_pacan4ik_offset_2 ~= nil then
            ref.ground_pacan4ik_offset_2:set_callback(on_settings_change)
        end

        events.shutdown(reset_runtime_state, true)
    end
end
